VALUES ('doc-09-mitre-attack-p0-3436', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects exploitation attempts targeting vulnerable kernel drivers or OS components, often followed by unusual process or token behavior.", "external_references": [{"external_id": "AN1419", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0514#AN1419"}], "id": "x-mitre-analytic--b01d212c-112a-47fb-8883-78bb623ee34b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1419", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=6", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3551476e-14f5-4e48-a518-e82135329e03"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=4672", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Targeted BYOVD drivers may vary based on campaign and tooling.", "field": "DriverNamePattern"}, {"description": "Controls temporal linking of driver load → process spawn → privilege use.", "field": "TimeWindow"}, {"description": "Parent-child relationships vary by exploitation vector (e.g., LOLBin vs. dropper).", "field": "ParentProcessPath"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3436', 0, 116, '09-mitre-attack', 'retrieved', '5254664C5081E2715C357