VALUES ('doc-09-mitre-attack-p0-3437', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of modified boot-time configuration scripts that persist malicious CLI commands across reboots.", "external_references": [{"external_id": "AN0661", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0237#AN0661"}], "id": "x-mitre-analytic--b053dbd4-ad1e-45e1-a6b7-af2a5d931c82", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0661", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "startup-config", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "system boot logs", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Device type or OS determines specific init script location", "field": "firmware_family"}, {"description": "Regex or pattern matching approach to detect suspicious CLI", "field": "config_line_pattern"}, {"description": "Time window between config change and first boot post-modification", "field": "reboot_time_window"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3437', 0, 103, '09-mitre-attack', 'retrieved', 'D73DC21F5D8619D60B547230AA8CFD3E131DD5DDD528107978DBDD1D6DB43F36', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
