INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3438', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Virtual instances or workloads generating sustained outbound data rates, often to TOR, VPN, or proxy endpoints. Often coincides with unusual IAM usage or deployed scripts (e.g., cron jobs using proxy clients).", "external_references": [{"external_id": "AN0084", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0028#AN0084"}], "id": "x-mitre-analytic--b0d018e2-0384-4e27-92ed-c9b181999fa9", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0084", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "StartInstances", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--f8213cde-6b3a-420d-9ab7-41c9af1a919f"}, {"channel": "egress > 90th percentile or frequent connection reuse", "name": "AWS:VPCFlowLogs", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "High-throughput instance types are more likely to be targeted for hijacking.", "field": "InstanceType"}, {"description": "Customize detection thresholds based on cloud provider quotas or billing alerts.", "field": "TrafficEgressThreshold"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3438', 0, 117, '09-mitre-attack', 'retrieved', '485D9019F37F5DE62DD147826A6238D04150B3D81B0FD5DC728D0C86C191C10B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
