INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3440', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of scripts or binaries that check for virtualization indicators (e.g., system_profiler, ioreg -l, kextstat), combined with delay functions or anomalous launchd activity.", "external_references": [{"external_id": "AN0129", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0046#AN0129"}], "id": "x-mitre-analytic--b12639b9-5daa-46aa-a21f-521f6962f042", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0129", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execution of system_profiler, ioreg, kextstat with argument patterns related to VM/sandbox checks", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "dynamic loading of sleep-related functions or sandbox detection libraries", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detection regex or substring matching sandbox-related checks", "field": "ProcessCommandPattern"}, {"description": "Maximum duration of sleep execution before alert (e.g., > 5 minutes)", "field": "SleepThreshold"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3440', 0, 117, '09-mitre-attack', 'retrieved', '3982C4B6C1DAC1A16C7B64931FDB96441C817303CDA9A9E60C8C01D8CED09751', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
