VALUES ('doc-09-mitre-attack-p0-3441', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Correlation of Mail.app logs with Safari/Chrome activity. Suspicious behavior includes email links → Safari/Chrome accessing newly registered or lookalike domains → osascript or Terminal spawned unexpectedly.", "external_references": [{"external_id": "AN0300", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0107#AN0300"}], "id": "x-mitre-analytic--b18b93d1-3f63-4788-8e26-68db032995e0", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0300", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Received messages with embedded or shortened URLs", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Browser processes launching unexpected interpreters (osascript, bash)", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Connections to suspicious domains with mismatched certificate or unusual patterns", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Flag self-signed or mismatched TLS certificates from spearphishing domains.", "field": "CertificateAnomalies"}, {"description": "Suspicious delay between URL click and malicious process spawn.", "field": "ExecutionDelayThreshold"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3441', 0, 128, '09-mitre-attack', 'retrieved', 'F89DB652575D4E77BC364BD7239C0DC9196C894258ED878E3AAA776879C7BEE4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
