INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3442', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Defenders may observe unauthorized modifications to encryption-related configuration files, firmware, or crypto modules on network devices. Suspicious patterns include changes to cipher suite configurations, unexpected firmware updates affecting crypto libraries, disabling of hardware cryptographic accelerators, or reductions in key length policies. Correlating configuration changes with anomalies in encrypted traffic characteristics (e.g., weaker ciphers or sudden plaintext transmission) strengthens detection.", "external_references": [{"external_id": "AN0961", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0339#AN0961"}], "id": "x-mitre-analytic--b192336c-4a85-4322-9ae8-fd6eb6b7747b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0961", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Configuration change events referencing encryption, TLS/SSL, or IPSec settings", "name": "networkdevice:config", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "Traffic patterns showing downgrade from strong encryption (AES-256) to weaker or plaintext protocols", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "Status change in cryptographic hardware modules (enabled -> disabled)", "name": "snmp:status", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of approved encryption algorithms and key lengths; customizable to organizational policy.", "field": "CipherSuiteWhitelist"}, {"description": "Correlation period between configuration changes and abnormal traffic; adjustable to reduce false positives.", "field": "TimeWindow"}, {"description": "Known trusted sources of firmware updates; deviations indicate possible compromise.", "field": "AuthorizedFirmwareSources"}, {"description": "Baseline entropy measurements of encrypted traffic; deviations may reveal weakening of encryption.", "field": "TrafficEntropyThreshold"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3442', 0, 204, '09-mitre-attack', 'retrieved', '5E240DFE7978020C4367CB2D888D91A8B359269B87AAAC82CDBE13AF5616E1A5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
