VALUES ('doc-09-mitre-attack-p0-3443', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects adversary behavior deleting artifacts (e.g., dropped payloads, evidence files) using native or external utilities (e.g., del, erase, SDelete). Detects deletion events correlated with unusual process lineage or timing post-execution.", "external_references": [{"external_id": "AN0392", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0140#AN0392"}], "id": "x-mitre-analytic--b1ee9791-91f8-4788-9e08-c40eedbcf08b", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0392", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=23", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}, {"channel": "EventCode=4663, 4670, 4656", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines correlation window after suspicious binary execution or login session.", "field": "TimeWindow"}, {"description": "Focuses on deletion of temp files, malware staging dirs, or known indicators.", "field": "FilePathPattern"}, {"description": "Privilege level or impersonated user deleting sensitive files.", "field": "UserContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3443', 0, 131, '09-mitre-attack', 'retrieved', '0AAECC22079FF1EB448272E1040E35A9F7FBF4C5DC9F3D338CD44B82CE3AF348', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
