VALUES ('doc-09-mitre-attack-p0-3447', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Cloud API usage to create/import SSH keys or generate new access keys (CreateAccessKey, ImportKeyPair, CreateLoginProfile) from non-console access or unusual principals.", "external_references": [{"external_id": "AN1470", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0531#AN1470"}], "id": "x-mitre-analytic--b31afcb5-1690-43f1-acbb-3e2936e48616", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1470", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "CreateAccessKey, ImportKeyPair, CreateLoginProfile, CreateKeyPair", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--18b236d8-7224-488f-9d2f-50076a0f653a"}, {"channel": "iam.serviceAccounts.keys.create, os-login.sshPublicKeys.add", "name": "gcp:audit", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Track root, federated identities, and STS tokens separately.", "field": "CallerIdentityContext"}, {"description": "Time between key creation and first use (default: 5 min).", "field": "NewCredentialUsageWindow"}, {"description": "Expected services/accounts allowed to create keys.", "field": "IAMRoleBaseline"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3447', 0, 109, '09-mitre-attack', 'retrieved', '620A6B9F8349B12C97398BB3812AC10C9733608B4A47FFA91ED4CF1FCD8BE5A1', 'v1', '{"source_id": "09-m