VALUES ('doc-09-mitre-attack-p0-3450', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects suspicious execution of network monitoring tools (e.g., Wireshark, tshark, Microsoft Message Analyzer), driver loading indicative of promiscuous mode, or non-admin user privilege escalation to access NICs for capture.", "external_references": [{"external_id": "AN0875", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0314#AN0875"}], "id": "x-mitre-analytic--b3579b0f-7daf-40bd-af1c-f5cd020942e6", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0875", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7045", "name": "WinEventLog:System", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Adjust list of known sniffing tools based on environment and known administrator usage.", "field": "ToolNames"}, {"description": "Tune time of day or frequency of capture sessions to reduce false positives from authorized use.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3450', 0, 115, '09-mitre-attack', 'retrieved', 'BCDCD50472B90AC09025A159E94B2EEB9325C1FB5719817EC30308F092F2DDAC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_t