VALUES ('doc-09-mitre-attack-p0-3451', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of syslog configuration tampering using esxcli system syslog config set or reload. Defender correlates command execution with absence of syslog forwarding activity.", "external_references": [{"external_id": "AN0670", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0239#AN0670"}], "id": "x-mitre-analytic--b3828af6-912b-493b-b621-3448a8f07972", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0670", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "esxcli system syslog config set or reload", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Expected syslog destination servers for ESXi hosts.", "field": "SyslogServerBaseline"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3451', 0, 84, '09-mitre-attack', 'retrieved', '1836E9E427B5889E109270F17380930B559CF2A61BCE6211A460AC2862CB742C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
