VALUES ('doc-09-mitre-attack-p0-3452', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Cause→effect chain: (1) Browser/Office/reader process logs crash/segfault or abnormal sandbox message, (2) new executable/script/write occurs in $HOME (Downloads, ~/.cache, /tmp), (3) unexpected child like curl/wget/bash/python opens network connections soon after.", "external_references": [{"external_id": "AN0798", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0287#AN0798"}], "id": "x-mitre-analytic--b3b58ac5-6b60-4c34-9842-46f5ee517bcb", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0798", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "browser/office crash, segfault, abnormal termination", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "open", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "creat", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "rename,chmod", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "new outbound connections from exploited process tree", "name": "NetFlow:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "5–20m correlation window.", "field": "TimeWindow"}, {"description": "HOME write targets: ~/Downloads, ~/.config/autostart, ~/.local/share, /tmp.", "field": "UserPaths"}, {"description": "bash, sh, python, perl, node, curl, wget, socat, openssl, xxd.", "field": "HighRiskChildren"}, {"description": "Allow-list common updaters (snap, flatpak, packagekit) to reduce FP.", "field": "PackageUpdaters"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3452', 0, 156, '09-mitre-attack', 'retrieved', 'A7E460BC0D35F6856E5238485CA71C0CC43EA250C93E8DB92AADF52B36CA9441', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
