INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3454', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitors tampering with audit logs, volumes, or mounted storage often used for side-channel logging (e.g., /var/log inside containers) post-compromise.", "external_references": [{"external_id": "AN0523", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0184#AN0523"}], "id": "x-mitre-analytic--b3d533fc-010a-4ee8-b234-80f98e2443a0", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0523", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "container file operations", "name": "docker:daemon", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}, {"channel": "Unexpected container volume unmount + file deletion", "name": "ebpf:syscalls", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune based on how logs are exported (bind-mount, overlay)", "field": "LogMountPaths"}, {"description": "Limit detection to suspicious containers or runtime classes", "field": "ContainerLabelScope"}], "x_mitre_platforms": ["Containers"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3454', 0, 101, '09-mitre-attack', 'retrieved', 'E943693C4219060515B75A7A70A35CDABBDC32BDECB8AA1DF455FE641CDD2C08', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
