INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3457', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unsigned or user-space apps initiate TLS connections with one hostname and HTTP headers requesting a different domain, commonly abused in CDN-resident domain fronting techniques.", "external_references": [{"external_id": "AN0566", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0196#AN0566"}], "id": "x-mitre-analytic--b4cf91ba-a22b-49b4-978e-32c3e1301c74", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0566", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "network, socket, and http logs", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "process_events", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Helps tune detection when unsigned apps initiate fronted sessions.", "field": "UnsignedBinary"}, {"description": "Threshold to flag inconsistent domain targeting in encrypted sessions.", "field": "HostHeaderMatch"}, {"description": "Alert on unusual ports used in HTTPS+SOCKS activity patterns.", "field": "SOCKSPortAnomaly"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3457', 0, 115, '09-mitre-attack', 'retrieved', '6BCFDEA76625ED1BCDBA48583D898D78EEFBCE0C0BD185897C3596D9C2C333F0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
