VALUES ('doc-09-mitre-attack-p0-3458', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects adversary clearing log files on macOS by correlating calls to shell utilities (e.g., echo >, rm, truncate) targeting files in /var/log/ with unusual context (non-administrative users or abnormal process lineage).", "external_references": [{"external_id": "AN1439", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0520#AN1439"}], "id": "x-mitre-analytic--b4e2440e-8956-4ae6-94cb-da859f407f27", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1439", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "truncate, unlink, write", "name": "fs:fsusage", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Duration in which process activity and file I/O should be temporally linked.", "field": "TimeWindow"}, {"description": "Tunable path filter for macOS logs such as /var/log/system.log or /var/log/asl.log.", "field": "LogFilePathPattern"}, {"description": "Detects higher risk when log deletion is performed by unusual users (e.g., interactive vs. system users).", "field": "UserContext"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3458', 0, 132, '09-mitre-attack', 'retrieved', 'C3C5665556A05F5290C394FD9356A40DABC160D8001F758027C7B974748A94DF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
