VALUES ('doc-09-mitre-attack-p0-3459', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Manual or scripted installation of Chrome extensions using user scripts or config files, followed by unexpected network connections from browser processes.", "external_references": [{"external_id": "AN0125", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0044#AN0125"}], "id": "x-mitre-analytic--b5020e23-475e-4f74-a943-787e090d3e2f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0125", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "Browser connections to known C2 or dynamic DNS domains", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Location of Chrome/Chromium extensions under user profile may vary", "field": "ExtensionDir"}, {"description": "Custom list of suspicious destination domains for browser traffic", "field": "DomainWatchlist"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3459', 0, 110, '09-mitre-attack', 'retrieved', '0ACE1E73B13BE4877E4002ABE5F2511DD1CE4FDB24CCE53815236FB56B77C6CD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "c