VALUES ('doc-09-mitre-attack-p0-3460', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use of file enumeration commands (e.g., ''ls'', ''find'', ''locate'') executed by suspicious users or scripts accessing broad file hierarchies or restricted directories.", "external_references": [{"external_id": "AN1041", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0370#AN1041"}], "id": "x-mitre-analytic--b50bf863-644a-48c2-85a3-2c633f135650", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1041", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "PATH", "name": "auditd:PATH", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Max depth of recursive access to tune noise vs anomaly", "field": "FilePathDepth"}, {"description": "Helpful to exclude known scripts or automation accounts", "field": "UserContext"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3460', 0, 97, '09-mitre-attack', 'retrieved', '1B18BB50A6F8594CAA8E6341ACDA7044D003290C7768236005C1A4AB85993837', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
