VALUES ('doc-09-mitre-attack-p0-3461', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects usage of shared memory directories (/dev/shm, /run/shm) for temporary storage of obfuscated, encoded, or executable data without persistence to disk.", "external_references": [{"external_id": "AN0974", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0344#AN0974"}], "id": "x-mitre-analytic--b521510b-83bc-46a2-8fc8-65a6975bcfca", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0974", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open, write, unlink", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "file_events.path", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Shared memory mount path used (e.g., /dev/shm/ or /run/shm/)", "field": "PathPrefix"}, {"description": "Regex to match non-standard, suspicious, or encoded filenames", "field": "FilenameRegex"}, {"description": "Time window to correlate process execution from shared memory directories", "field": "ExecCorrelationWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3461', 0, 110, '09-mitre-attack', 'retrieved', '9DA122EC15BB0792BEE84E27D1A53A3933A993FCBC2A04BBE4CE5B8C1C4760FD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type"