VALUES ('doc-09-mitre-attack-p0-3462', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detect attempts to enumerate kernel modules through lsmod, modinfo, or inspection of /proc/modules and /dev entries. Focus on unusual execution contexts such as unprivileged users or processes outside expected administrative workflows.", "external_references": [{"external_id": "AN1596", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0579#AN1596"}], "id": "x-mitre-analytic--b55c3339-2d4c-4392-8d26-c257ea2f1bb9", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1596", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve: Execution of lsmod, modinfo, or cat /proc/modules", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "read: File access to /proc/modules or /sys/module/", "name": "auditd:FS", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Limit detection noise by filtering expected kernel module inspection by root or system maintenance scripts.", "field": "KnownAdminUsers"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3462', 0, 113, '09-mitre-attack', 'retrieved', '770B7397C5AB2D24FFB7C76FA91F571EBB7027FEF7E601D362552F8D885BEF59', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
