INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3463', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of destructive utilities (dd, shred, wipe) targeting block devices, or processes invoking syscalls to directly overwrite /dev/sd* or /dev/nvme* partitions. Correlate abnormal file write attempts with shell process execution and block device access.", "external_references": [{"external_id": "AN0883", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0316#AN0883"}], "id": "x-mitre-analytic--b55c84a0-d045-43f6-a5a9-e8f6edbd275e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0883", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open/write syscalls to block devices (/dev/sd*, /dev/nvme*)", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--73ff2dcc-24b1-4368-b9dc-706dd9e68354"}, {"channel": "Execution of dd, shred, or wipe with arguments targeting block devices", "name": "auditd:EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Exclude removable drives or designated partitions that may be overwritten during maintenance.", "field": "TargetDevices"}, {"description": "Tune detection for pseudorandom write patterns to reduce false positives during high-volume I/O.", "field": "EntropyThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3463', 0, 132, '09-mitre-attack', 'retrieved', 'FEA30EB77A8030227264BBACAB0B002E27CBCD489F5DFCF20DFCEA3980D073AD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
