VALUES ('doc-09-mitre-attack-p0-3465', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Behavioral chain: (1) delegated administration offers/relationships created or modified by partner tenants; (2) mailbox delegation/impersonation enabled; (3) follow-on access from partner IPs.", "external_references": [{"external_id": "AN1350", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0488#AN1350"}], "id": "x-mitre-analytic--b5985d46-1d54-4a6d-81c8-0b577b5d8d17", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1350", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Add-DelegatedAdmin, Set-PartnerOfRecord, Add-MailboxPermission, Set-OrganizationRelationship", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "InteractiveUser, NonInteractiveUser", "name": "azure:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Specific mailboxes third-parties may manage.", "field": "MailboxDelegateAllowList"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3465', 0, 86, '09-mitre-attack', 'retrieved', 'F96453341B24BC8BFF08545AC516CD08FC936976A3BECB9CD832FA1BA02F9CE3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
