VALUES ('doc-09-mitre-attack-p0-3467', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects execution of binaries signed with unusual or recently issued certificates, correlation of process execution with abnormal publisher metadata, and mismatched certificate chains. Monitors for revoked or unknown code signing certificates used in high-privilege contexts.", "external_references": [{"external_id": "AN0643", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0230#AN0643"}], "id": "x-mitre-analytic--b5d77678-fff4-41cd-9e77-d3f82243240a", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0643", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Define trusted issuers to suppress noise from legitimate enterprise signing chains", "field": "AllowedCertificateAuthorities"}, {"description": "Correlation window for detecting execution of binaries with newly observed or anomalous certificates", "field": "TimeWindow"}, {"description": "Baseline normal age of certificates; flag very recent or expired certificates", "field": "CertificateAgeThreshold"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3467', 0, 130, '09-mitre-attack', 'retrieved', '1DD3A9E33C99B34993D687C73CCC516022F07A8C5D41AEA6A3102A31F526319E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
