VALUES ('doc-09-mitre-attack-p0-3469', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects USB HID device enumeration under `/sys/bus/usb/devices/` and rapid keystroke injection resulting in command execution such as bash or Python scripts launched without interactive user activity.", "external_references": [{"external_id": "AN1568", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0568#AN1568"}], "id": "x-mitre-analytic--b61673d6-244f-4888-9370-1a3ef391a6c2", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1568", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve: parent process is usb/hid device handler, child process bash/python invoked", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "New HID device enumeration with type ''keyboard'' followed by immediate input injection", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Track suspicious or unapproved USB vendor/product IDs.", "field": "USBVendorIDs"}, {"description": "Time threshold for script execution after HID injection, e.g., less than 10 seconds.", "field": "ScriptExecutionThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3469', 0, 124, '09-mitre-attack', 'retrieved', 'C252F5064E9A245395F628C065FD0D57CC546D796F89E438B770041FC5502B39', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
