VALUES ('doc-09-mitre-attack-p0-3470', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Correlates suspicious removal or modification of the com.apple.quarantine extended attribute, manipulation of LSFileQuarantineEnabled values in Info.plist, and unexpected process execution of unsigned or non-notarized binaries. Also monitors abnormal trust validation failures in unified logs and unusual activity in QuarantineEvents database entries.", "external_references": [{"external_id": "AN0800", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0288#AN0800"}], "id": "x-mitre-analytic--b6516e8b-fd18-4c92-8701-1762d8321168", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0800", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "xattr -d com.apple.quarantine or similar attribute removal commands", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"channel": "Trust validation failures or bypass attempts during notarization and code signing checks", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Changes to LSFileQuarantineEnabled field in Info.plist", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Legitimate enterprise update tools or deployment frameworks that may strip quarantine flags", "field": "QuarantineBypassAllowList"}, {"description": "Baseline trusted Apple Developer IDs and enterprise certs used for code signing", "field": "CertificateAuthorityList"}, {"description": "Time correlation window for xattr modification followed by suspicious process execution", "field": "TimeWindow"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3470', 0, 165, '09-mitre-attack', 'retrieved', '4DC2AD5777C4E98129BB6C1BF00A60076D4E0045355780547596746330C67516', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
