VALUES ('doc-09-mitre-attack-p0-3472', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects assignment of high-privilege roles to user or service accounts via Kubernetes RoleBinding or ClusterRoleBinding objects, especially outside of CI/CD automation or from unknown IPs.", "external_references": [{"external_id": "AN1579", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0572#AN1579"}], "id": "x-mitre-analytic--b721ae18-79fc-4b82-8991-93980b14ded5", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1579", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "create or update events for RoleBinding or ClusterRoleBinding objects", "name": "kubernetes:audit", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Filter expected sources of automated role assignment (e.g., CI/CD tooling)", "field": "UserAgent"}, {"description": "Scope to privileged roles like cluster-admin, edit, admin", "field": "RoleName"}, {"description": "Detect after-hours or irregular-time assignments", "field": "TimeWindow"}, {"description": "Define known service accounts and privileged operators to reduce noise", "field": "UserContext"}], "x_mitre_platforms": ["Containers"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3472', 0, 123, '09-mitre-attack', 'retrieved', '73A3D98EA5749BB58155F009FDBCB43B3E23C4DFDEEB8425AC424BB1AE98A155', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
