VALUES ('doc-09-mitre-attack-p0-3473', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-22T19:00:47.079Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Process execution without GUI context (e.g., powershell.exe, wscript.exe) generates HTTP traffic with a spoofed User-Agent mimicking a legitimate browser. No corresponding UI application (e.g., msedge.exe) is active or in parent lineage. The User-Agent deviates from known enterprise baselines or contains spoofed platform indicators. User-Agent strings can be gathered with API calls such as `ShellExecuteW` to open the default browser on a socket to receive an HTTP reply, or by hard coding the User-Agent string for a specific browser.", "external_references": [{"external_id": "AN2029", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0898#AN2029"}], "id": "x-mitre-analytic--b73489af-2e95-4f41-b82e-327a84da2a1d", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 2029", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Inbound HTTP POST with suspicious payload size or user-agent", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "API Calls", "name": "etw:Microsoft-Windows-Kernel-Process", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Specific HTTP header anomalies or patterns (e.g., spoofed User-Agent).", "field": "HeaderSignatureMatch"}, {"description": "Flag browser-based sessions", "field": "UserAgentFingerprint"}, {"description": "List of non-browser binaries expected not to initiate web requests (e.g., powershell.exe, cscript.exe)", "field": "NonBrowserProcessList"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3473', 0, 181, '09-mitre-attack', 'retrieved', '2322EDC4EB1B7462BA7361BB25232E2FCE065F98091E176A1868042B06FCDD8A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
