INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3474', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of token duplication and impersonation attempts by correlating suspicious command-line executions (e.g., runas) with API calls to DuplicateToken, DuplicateTokenEx, ImpersonateLoggedOnUser, or SetThreadToken. The chain includes the initial command execution or in-memory API invocation → token handle duplication or thread token assignment → a new or existing process assuming the impersonated user''s context.", "external_references": [{"external_id": "AN1324", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0482#AN1324"}], "id": "x-mitre-analytic--b76aeebb-3915-48ed-ac35-6af54c88c3bb", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1324", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "api_call: DuplicateTokenEx, ImpersonateLoggedOnUser, SetThreadToken", "name": "ETW:Token", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Whitelist of known processes that legitimately duplicate tokens (e.g., services.exe).", "field": "AllowedSystemProcesses"}, {"description": "Time interval between API call and subsequent impersonated process (e.g., 5m).", "field": "TimeWindow"}, {"description": "Filter for service accounts or known administrative accounts that perform legitimate impersonation.", "field": "UserContextFilter"}, {"description": "Threshold for parent-child process lineage anomalies indicating token theft.", "field": "ParentProcessAnomalyThreshold"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3474', 0, 167, '09-mitre-attack', 'retrieved', '5EB10C020C42B08FCD2429511E6B3FC49DBBC4E8541538E8D265BACC3D16B191', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
