VALUES ('doc-09-mitre-attack-p0-3475', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Account created using esxcli commands. Sequence includes esxcli execution and successful modification to account DB.", "external_references": [{"external_id": "AN1238", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0447#AN1238"}], "id": "x-mitre-analytic--b7a63a7c-e8c2-4a25-becf-299ea45996e5", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1238", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "esxcli system account add", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Console sessions vs SSH vs vSphere CLI session may affect alert fidelity", "field": "CommandOrigin"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3475', 0, 78, '09-mitre-attack', 'retrieved', '2D4775791A0C62A705735EA3C147F026B08B2C9325ACA4637B3D41B95182EB22', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
