VALUES ('doc-09-mitre-attack-p0-3476', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Malicious script or binary causes repeated kernel panics, OOM kills, or systemd service restarts targeting services like nginx, httpd, sshd.", "external_references": [{"external_id": "AN0585", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0208#AN0585"}], "id": "x-mitre-analytic--b7e4a6de-8ff3-4711-aa83-97533adec211", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0585", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Out of memory killer invoked or kernel panic entries", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}, {"channel": "Repeated service restart attempts or unit failures", "name": "journald:systemd", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Targeted daemon/service such as sshd, nginx, mysql", "field": "ServiceName"}, {"description": "Number of restarts in short succession to trigger alert", "field": "RestartThreshold"}, {"description": "Count of OOM kills over a time window", "field": "OOMKillCount"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3476', 0, 124, '09-mitre-attack', 'retrieved', '7708CC25EA9B688D6D2F70D10F16B194FC4257B4DF8CA754C9F5FF7915E6361A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
