VALUES ('doc-09-mitre-attack-p0-3477', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects DYLD_INSERT_LIBRARIES abuse to hook credential-sensitive applications by correlating process spawns with unauthorized library injection and monitoring changes to the __TEXT segment (code) of credential handling binaries.", "external_references": [{"external_id": "AN0391", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0139#AN0391"}], "id": "x-mitre-analytic--b8141218-1f71-4b65-a611-7c9c55038c4c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0391", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "DYLD event subsystem", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "File Access Monitor", "name": "fs:fsusage", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "Memory Mappings", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tunable based on naming patterns or location of malicious dylibs", "field": "DYLDInjectedPath"}, {"description": "Hooking attempts may stem from terminal.app, bash, or AppleScript-based launchers", "field": "ParentProcessName"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3477', 0, 115, '09-mitre-attack', 'retrieved', '0D838AEA4EDA9655B87F7394EBE14166E1F496B09FBC54BE2627992C143FD3F3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
