VALUES ('doc-09-mitre-attack-p0-3479', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of VNC-based remote control via `screensharingd` activity in Unified Logs along with concurrent remote login activity or suspicious user interaction.", "external_references": [{"external_id": "AN0506", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0178#AN0506"}], "id": "x-mitre-analytic--b88251d3-6406-4512-a55f-a6bc3493e2ad", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0506", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "authentication", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "process_events", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "inbound connection to port 5900", "name": "NSM:firewall", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Unified log predicate to refine suspicious screensharing access", "field": "AuthenticationPredicate"}, {"description": "Time between VNC connection and follow-on activity (e.g., 30s)", "field": "TimeWindow"}, {"description": "Mouse/keyboard interaction spike immediately post-VNC login", "field": "UserActivitySpike"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3479', 0, 114, '09-mitre-attack', 'retrieved', 'B9A5C61D6F3D2D969BB13C27976317279B42FE815643F0EF4976453C0985DE2A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
