INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3480', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects modifications to IAM conditions or policies that alter authentication behavior, such as adding permissive trusted IPs, removing MFA requirements, or changing regional access restrictions. Behavioral detection focuses on anomalous policy updates tied to privileged accounts and subsequent suspicious logon activity from previously blocked regions or devices.", "external_references": [{"external_id": "AN0087", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0030#AN0087"}], "id": "x-mitre-analytic--b88f87d2-4a64-44a2-937e-85a929203843", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0087", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "PutUserPolicy, PutGroupPolicy, PutRolePolicy, CreatePolicyVersion", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Specific condition keys (SourceIp, RequestedRegion, MFAAuthenticated) tuned per environment.", "field": "MonitoredIAMConditions"}, {"description": "Correlates policy modification with follow-on logins from newly permitted sources.", "field": "TimeWindow"}, {"description": "List of administrative accounts to prioritize when monitoring for conditional access changes.", "field": "PrivilegedAccounts"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3480', 0, 135, '09-mitre-attack', 'retrieved', '83EF658255069569C8FC0D80099D99FA1E3C6F27E11ED9FFB980CE8EF688225C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
