INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3481', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "A process/script constructs or references a custom/alphabet translation table (e.g., 64/85/32+ arbitrary chars, XOR/base-N loops) or emits long high-entropy strings that do NOT validate as standard Base64/Hex → shortly after, the same process (or its child) generates outbound traffic with asymmetric bytes_out:bytes_in, fixed-size beacons, or protocol/header mismatches (e.g., Content-Type says JSON but body fails JSON parse / contains non-standard alphabet).", "external_references": [{"external_id": "AN0927", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0326#AN0927"}], "id": "x-mitre-analytic--b8dea721-8e0d-4bcd-bde4-6609afd595e5", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0927", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}, {"channel": "NetworkConnection: high out:in ratio, periodic beacons, protocol mismatch", "name": "m365:defender", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Minimum Shannon entropy for the suspected token/payload (e.g., >4.8).", "field": "EntropyThreshold"}, {"description": "Minimum continuous token length to treat as potential non-standard payload (e.g., ≥120 chars).", "field": "TokenLengthThreshold"}, {"description": "Out:In ratio considered suspicious (e.g., ≥4:1).", "field": "BytesOutToInRatio"}, {"description": "Std. dev. threshold (size or interval) to mark packets as ''uniform'' (beacon-like).", "field": "FixedPacketStdDevThreshold"}, {"description": "Correlation window from encode routine to egress (default 10m).", "field": "TimeWindow"}, {"description": "Legitimate in-house/custom encoders to suppress.", "field": "KnownLegitEncoders"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3481', 0, 206, '09-mitre-attack', 'retrieved', 'C368E197D996064A14BBF76877D3DF45BE2FA803570BACB4BC41B81C7254A800', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
