INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3482', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection focuses on abnormal or unauthorized cloud instance creation events. From a defender’s perspective, suspicious behavior includes VM/instance creation by rarely used or newly created accounts, creation events from unusual geolocations, or rapid sequences of snapshot creation followed by instance creation and mounting. Unexpected network or IAM policy changes applied to new instances can indicate adversarial use rather than legitimate provisioning.", "external_references": [{"external_id": "AN1242", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0449#AN1242"}], "id": "x-mitre-analytic--b8ec766b-cfb9-4ef8-bd46-655f0b820ad3", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1242", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "RunInstances", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--f8213cde-6b3a-420d-9ab7-41c9af1a919f"}, {"channel": "DescribeInstances", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--45fd904d-6eb0-4b50-8478-a961f09f898b"}, {"channel": "MICROSOFT.COMPUTE/VIRTUALMACHINES/WRITE", "name": "azure:activity", "x_mitre_data_component_ref": "x-mitre-data-component--b5b0e8ae-7436-4951-950a-7b83c4dd3f2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "IAM user, service account, or role creating the instance. Tuned to allowlist known automation services.", "field": "UserContext"}, {"description": "Region or source IP where the creation request originates. Helps detect cross-region or unusual location abuse.", "field": "GeoLocation"}, {"description": "Number of instances created per user or account in a time window. Tuned for environments with elastic scaling.", "field": "RateThreshold"}, {"description": "Expected tags (e.g., owner, purpose, cost center) for new instances. Deviations may indicate adversarial creation.", "field": "TaggingPolicy"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3482', 0, 194, '09-mitre-attack', 'retrieved', '75FF36AB9EBB0B5927B278071ECD87C17D416E75A5047515BD53D24DFB8987E2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
