INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3484', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "User-space tools (e.g., `socat`, `ncat`, `iptables`, `ssh`) used in non-standard ways to establish reverse shells, port-forwarding, or inter-host connections. Often chained with uncommon outbound destinations or SSH tunnels.", "external_references": [{"external_id": "AN1230", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0445#AN1230"}], "id": "x-mitre-analytic--b95a3fbf-3d6c-4ead-8421-ff9c07ca4019", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1230", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Connection Tracking", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Shell piping into tools like `socat`, `ncat`, or `openssl` for tunnel creation.", "field": "CommandLinePattern"}, {"description": "Flag connections made from internal systems to uncommon high ports externally.", "field": "OutboundPortRange"}, {"description": "Capture low-privilege or unexpected users executing system-level network tools.", "field": "ProcessUserContext"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3484', 0, 121, '09-mitre-attack', 'retrieved', '75C597BE7B17652B8932F70B8342728E6E8E9648FA14BFDC393926E874A55F92', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
