INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3485', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "LaunchAgents or LaunchDaemons initiate persistent Tor or relay processes that make encrypted outbound connections. May be paired with sandbox bypasses or unsigned executables communicating over SOCKS proxies.", "external_references": [{"external_id": "AN1022", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0359#AN1022"}], "id": "x-mitre-analytic--b97a1c6e-bb02-4e14-ae57-6a9e96512657", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1022", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process, socket, and DNS logs", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "process_events + launchd", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "forwarded encrypted traffic", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Regex for masking patterns in LaunchAgents with proxy behavior.", "field": "LaunchdLabel"}, {"description": "Allow for exceptions for known unsigned binaries.", "field": "UnsignedBinary"}, {"description": "Monitor local 9050/9150 activity and rerouted system traffic.", "field": "SOCKSPortUsage"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3485', 0, 125, '09-mitre-attack', 'retrieved', '9110E06A30B5088FEAFBAFC58F850147CAA281723771A426FF2FCAAB52ED29B1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
