VALUES ('doc-09-mitre-attack-p0-3487', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects creation of scheduled tasks via `at.exe` or WMI `Win32_ScheduledJob` class, followed by execution of anomalous processes by svchost.exe or taskeng.exe.", "external_references": [{"external_id": "AN0943", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0333#AN0943"}], "id": "x-mitre-analytic--b9f79a81-9fee-47f2-bef8-a9f64fde935e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0943", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4698", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Unusual users creating jobs (e.g., non-admin accounts or service users).", "field": "TaskUser"}, {"description": "Delay between task registration and execution.", "field": "ExecutionTimeWindow"}, {"description": "Unexpected script or binary execution (e.g., cmd.exe /c PowerShell payload).", "field": "CommandLinePattern"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3487', 0, 107, '09-mitre-attack', 'retrieved', '5AF6094CACD8475BCF7085335139C590CBDD5BE9B04F5B27F7C244AEFA128A33', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
