VALUES ('doc-09-mitre-attack-p0-3488', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Chain of remote access tool behavior: (1) initial execution of remote-control/assist agent or GUI under user context; (2) persistence via service or autorun; (3) long-lived outbound connection/tunnel to external infrastructure; (4) interactive control signals such as shell or file-manager child processes spawned by the RAT parent.", "external_references": [{"external_id": "AN1366", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0496#AN1366"}], "id": "x-mitre-analytic--ba2056ee-77d7-49d4-a993-5806506964df", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1366", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7045", "name": "WinEventLog:System", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}, {"channel": "EventCode=12", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--7f70fae7-a68d-4730-a83a-f260b9606129"}, {"channel": "EventCode=13, 14", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Correlation period binding start→persistence→egress→child (default 15m, adjust per environment).", "field": "TimeWindow"}, {"description": "Differentiate help-desk/jump hosts and admin accounts from standard endpoints.", "field": "UserContext"}, {"description": "Known-good remote support tools; suppress expected events while still correlating anomalous sequences.", "field": "ProcessAllowlist"}, {"description": "Alert when services/agents execute from user-writable or temp paths.", "field": "InstallPathRegex"}, {"description": "Vendors’ support clouds/CDNs to reduce false positives on egress detection.", "field": "ExternalIPAllowlist"}, {"description": "Define which child shells from GUI parents are acceptable versus suspicious.", "field": "ShellSpawnRegex"}, {"description": "Thresholds for session duration, connection counts, and bytes_out/bytes_in ratio.", "field": "EgressHeuristics"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3488', 0, 213, '09-mitre-attack', 'retrieved', 'BDCBFDDF3CF0001A8FFDA5270B09DCD25033F22C3D380944037626B42ABD62EA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
