VALUES ('doc-09-mitre-attack-p0-3489', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects file access to mbox/maildir files in conjunction with curl/wget/postfix execution, or anomalous shell scripts harvesting user mail directories.", "external_references": [{"external_id": "AN1310", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0476#AN1310"}], "id": "x-mitre-analytic--ba43428d-b5d2-4815-a614-42ff1ea816a9", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1310", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "postfix/smtpd", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "process_events", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Specify user mail directories (/var/mail, ~/Maildir)", "field": "WatchedMailDirs"}, {"description": "Tune based on local mail clients or curl usage in environment", "field": "ProcessNameList"}, {"description": "Define how close together access and exfil events must occur", "field": "TimeWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3489', 0, 112, '09-mitre-attack', 'retrieved', '83CBD8D5DBBAB288710E1925B10DADDF75ACA7378B2AAAD4845B200B4F5CC7DB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
