VALUES ('doc-09-mitre-attack-p0-3491', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "O365 UnifiedAuditLog entries for Remove-Mailbox or Set-Mailbox with account disable or delete actions correlated with suspicious login locations or MFA bypass.", "external_references": [{"external_id": "AN0338", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0120#AN0338"}], "id": "x-mitre-analytic--ba6c8c55-ee38-4219-a426-a3f1e04c7a8a", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0338", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Remove-Mailbox, Set-Mailbox", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--d6257b8e-869c-41c0-8731-fdca40858a91"}, {"channel": "Sign-in from anomalous location or impossible travel condition", "name": "m365:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Determine if operation was delegated to expected admin group", "field": "RoleAssignment"}, {"description": "Trigger on unusual geographic login sources", "field": "GeoThreshold"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3491', 0, 102, '09-mitre-attack', 'retrieved', '9E2A64F46464418E80EC5300D59F2B54F2451A485694DA1D6E81FABD25D7A2AB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
