INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3493', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use of configuration backup utilities or CLI access to dump plaintext passwords, local user hashes, or SNMP strings.", "external_references": [{"external_id": "AN1159", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0412#AN1159"}], "id": "x-mitre-analytic--badcc199-683b-41f5-9522-9710969cff15", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1159", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "CLI access to ''show running-config'', ''show password'', or ''cat config.txt''", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "large transfer from management IPs to unauthorized host", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "IP ranges authorized to perform credential dumps", "field": "ManagementInterfaceIPs"}, {"description": "Regex patterns for suspicious CLI commands", "field": "CommandPattern"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3493', 0, 105, '09-mitre-attack', 'retrieved', 'F7FD37B54F2977A3B457817B6EEF28785934517DA5F2A699A25C4429D3FB021C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
