INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3494', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection monitors SaaS collaboration tools (e.g., Slack, Zoom, Jira) for messages or files containing credential-like patterns, or for suspicious API calls retrieving bulk chat histories by non-admin users. Identifies adversary behavior chains where chat logs are queried via APIs or integration bots to systematically extract sensitive material.", "external_references": [{"external_id": "AN0310", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0111#AN0310"}], "id": "x-mitre-analytic--bafd38ad-aebd-40f1-9f17-bd63a1c74ba9", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0310", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "chat.postMessage, files.upload, or discovery API calls involving token/credential regex", "name": "saas:slack", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Unusual OAuth app requesting message-read scopes for Slack/Teams/Jira", "name": "saas:okta", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune to ignore known enterprise bots with message-read access (e.g., DLP scanners)", "field": "IntegrationScope"}, {"description": "Customizable regex for detecting secret formats (JWT, OAuth tokens, SSH keys)", "field": "RegexPatterns"}, {"description": "Correlate with user role to filter developers vs standard users", "field": "UserContext"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3494', 0, 155, '09-mitre-attack', 'retrieved', '3F354D70CB2859B85982840E399EACA45EAD2F9DB97C1FADF11016560B313660', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
