INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3495', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects exploitation attempts against macOS authentication frameworks such as OpenDirectory or Keychain. Defender perspective includes abnormal crashes in opendirectoryd, unauthorized Keychain API usage, and unusual sudo or login events. Correlation links unexpected process behavior with credential access anomalies.", "external_references": [{"external_id": "AN0495", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0174#AN0495"}], "id": "x-mitre-analytic--bb339113-e807-45fe-99c4-ed8348e51b36", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0495", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "opendirectoryd crashes or abnormal authentication errors", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "execve: Processes unexpectedly invoking Keychain or authentication APIs", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of authentication and Keychain-related APIs to monitor for unauthorized access.", "field": "WatchedAPIs"}, {"description": "Time window for correlating authentication service crashes with subsequent suspicious access.", "field": "CrashCorrelationWindow"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3495', 0, 129, '09-mitre-attack', 'retrieved', 'F79A42026E3054841D5E5C9A7CAE6FEB8B0B6D7556BB1AF47190391D02403A56', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
