VALUES ('doc-09-mitre-attack-p0-3497', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Correlates removable volume mounts (disk arbitration) with file I/O events on that volume, followed by same file execution shortly after insert.", "external_references": [{"external_id": "AN0249", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0090#AN0249"}], "id": "x-mitre-analytic--bb687663-4b26-46ef-a176-e188f538d399", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0249", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "com.apple.diskarbitration", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}, {"channel": "open/write/exec calls", "name": "fs:fsusage", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Known suspicious USB volume labels or types (e.g., NO NAME, SECUREDATA).", "field": "VolumeNameFilter"}, {"description": "Unusual processes accessing USB drives (e.g., bash, Python, unsigned binaries).", "field": "ProcessContext"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3497', 0, 100, '09-mitre-attack', 'retrieved', '6CBB24BEE98B0770547B2F9F5FA3A7D60E8969AB824320E7336A3738DA537807', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
