INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3498', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Identifies unauthorized access or enumeration of administrative roles, security groups, or distribution groups via Exchange/SharePoint/Teams APIs or role discovery scripts.", "external_references": [{"external_id": "AN0696", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0251#AN0696"}], "id": "x-mitre-analytic--bb94692e-e73c-449c-a17e-0658bebbfd93", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0696", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Get-RoleGroup, Get-DistributionGroup", "name": "m365:exchange", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "Enumerate ACLs/role bindings", "name": "m365:sharepoint", "x_mitre_data_component_ref": "x-mitre-data-component--8d8c7cac-94cf-4726-8989-cab33851168c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Adjust based on tenant-level vs. site-level group visibility.", "field": "AccessScope"}, {"description": "Detect script-based role listing (e.g., Graph API call chains).", "field": "ScriptExecutionContext"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3498', 0, 98, '09-mitre-attack', 'retrieved', 'BC2279866658EA39BD62E2058388057228CDC8271CBE84FBA67CFB1699C7E41B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
