VALUES ('doc-09-mitre-attack-p0-3500', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects remote scripts or binaries deployed via Puppet, Chef, Ansible, or shell scripts from orchestration servers executing outside maintenance windows or in unmanaged nodes.", "external_references": [{"external_id": "AN0624", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0223#AN0624"}], "id": "x-mitre-analytic--bbb8adb2-434a-483e-af3c-4843241e2158", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0624", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Approved orchestration or jump box IPs", "field": "DeployingHostAllowList"}, {"description": "Expected scripts, interpreters, or package managers used", "field": "ScriptExecutionBaseline"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3500', 0, 88, '09-mitre-attack', 'retrieved', 'E549D58AEF08245ADF27D5807E4DF02C934170C31C9AC0EC3E2CFA711EB5155E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
