INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3502', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Behavioral chain: (1) browser/office/GUI mail client opens a URL, (2) outbound connection to untrusted domain, (3) a new file is saved in $HOME/Downloads, /tmp, or cache immediately after.", "external_references": [{"external_id": "AN0179", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0066#AN0179"}], "id": "x-mitre-analytic--bbfa2ed1-f8d5-44cf-9da8-5e3fed544172", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0179", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve: Execs of chromium, google-chrome, firefox, libreoffice with http(s) in cmdline", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "open,creat,rename: Writes in $HOME/Downloads, /tmp, ~/.cache with exe/script/archive/office extensions", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "Suspicious URL patterns, uncommon TLDs, URL shorteners", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Typical 10–20m between click and write.", "field": "TimeWindow"}, {"description": "$HOME/Downloads, /tmp, ~/.cache, ~/.local/share.", "field": "UserPaths"}, {"description": "exe, elf, sh, js, py, jar, iso, img, zip, rar, xlsm, docm, xll.", "field": "HighRiskExtensions"}, {"description": "Heuristic or TI score threshold for domains.", "field": "DomainRiskScore"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3502', 0, 151, '09-mitre-attack', 'retrieved', '2AB4103D69CC4A54CB9AE43AC621BE520902D8A986D8AFD547FE2C08D16FE8E2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
