VALUES ('doc-09-mitre-attack-p0-3503', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects embedded macros or scripts added to shared documents or use of external references to execute code.", "external_references": [{"external_id": "AN1302", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0471#AN1302"}], "id": "x-mitre-analytic--bc143cf2-d6fb-4ea4-98a5-a2db81fc3f84", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1302", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "OfficeTelemetry or DLP", "name": "m365:defender", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Controls macro execution based on user or group policy.", "field": "MacroExecutionPolicy"}, {"description": "Regex match on suspicious VBA function names or calls.", "field": "SuspiciousKeywordMatch"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3503', 0, 89, '09-mitre-attack', 'retrieved', '8AE4C0ABF330F6CEC8CD232C82E12C78270A476307BF1C76CD184792D0CA9446', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
