VALUES ('doc-09-mitre-attack-p0-3504', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Changes to NAT/firewall policies enabling outbound port forwarding from internal IPs to Internet-based proxy endpoints. Log spikes in outbound flows to CDN, VPS, or anomalous ASNs with few return packets.", "external_references": [{"external_id": "AN0926", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0325#AN0926"}], "id": "x-mitre-analytic--bca44b88-4615-45b8-8fb9-ce934c65c8be", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0926", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Outbound NAT Rule Changes", "name": "Firewall Audit Logs", "x_mitre_data_component_ref": "x-mitre-data-component--d2ff4b56-8351-4ed8-b0fb-d8605366005f"}, {"channel": "Outbound flow records", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "Dynamic route changes", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Number of flows or bytes transferred per minute—flag surges to unrecognized ASNs.", "field": "FlowThreshold"}, {"description": "Proxy destination categories: CDN, TOR exit node, anonymous hosting.", "field": "DestinationIPCategory"}, {"description": "Track if unexpected user or automation changed NAT/forwarding rules.", "field": "ConfigChangeUser"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3504', 0, 136, '09-mitre-attack', 'retrieved', '0CA8AFD916DFDB9FCFD50BC144F9AC8DFA9B31BA91EDEF29D66167DFF8839F4F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
