VALUES ('doc-09-mitre-attack-p0-3505', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects symmetric key-based encryption operations (e.g., AES via Python, AppleScript, or OpenSSL) followed by unusual outbound connections from non-browser applications or scripted tools.", "external_references": [{"external_id": "AN1391", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0503#AN1391"}], "id": "x-mitre-analytic--bcab4073-2316-4685-be6c-fb5ab92b22be", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1391", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "log stream process subsystem", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "socket_events", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "log stream network activity", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Expected outbound connection profiles per app.", "field": "ApplicationProfileBaseline"}, {"description": "Indicators of manual encryption operations (e.g., script strings invoking AES).", "field": "EncryptionRoutinePattern"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3505', 0, 108, '09-mitre-attack', 'retrieved', '6B1BF4C157B369A45282163C1DAEC0DF82F03AAFE7E36AFA54E709215ED6F9E1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
