INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3506', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects native Python or framework-based execution from Terminal, embedded apps, or launchd jobs. Flags network calls, persistence writes, or system enumeration after Python launch.", "external_references": [{"external_id": "AN0173", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0063#AN0173"}], "id": "x-mitre-analytic--bcac4672-778d-4b35-8b75-eaaf84b91853", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0173", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "log stream --predicate ''eventMessage contains \"python\"''", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}, {"channel": "process_events", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "system.log", "name": "macos:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detects python scripts from ~/Downloads/, /Volumes/, or /tmp/.", "field": "ExecutionPath"}, {"description": "Obfuscated or high entropy script names.", "field": "ScriptName"}, {"description": "Chained behavior: Python → bash → curl or Python → osascript.", "field": "SpawnChain"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3506', 0, 120, '09-mitre-attack', 'retrieved', '29C38AEFA5973E733B126665ECD1636E28E93969114AA4D603381F04CCCA003F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
