VALUES ('doc-09-mitre-attack-p0-3508', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "SSH login from a remote system (via sshd), followed by user context execution of suspicious binaries or privilege escalation behavior.", "external_references": [{"external_id": "AN1638", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0596#AN1638"}], "id": "x-mitre-analytic--bcc6bec5-63c7-4084-9d2f-da8b58d0f621", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1638", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EXECVE", "name": "auditd:EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "None", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "TCP port 22 traffic", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines correlation window from login to first post-SSH process (e.g., 60s)", "field": "TimeWindow"}, {"description": "List of binaries considered unusual in SSH context (e.g., nc, base64, bash -i)", "field": "SuspiciousProcessList"}, {"description": "Accounts of interest for SSH logins (e.g., root, admin)", "field": "UsernameFilter"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3508', 0, 122, '09-mitre-attack', 'retrieved', 'B4EE646860EFF62A0ABE8050F855CC57A8AB6A6CDB575B1A5BB670DC8B763F2