INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3509', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Untrusted processes creating outbound TLS/HTTPS connections with malformed certificates or header fields, often mismatched with target service behavior. Detects protocol impersonation attempts via traffic metadata analysis and host process lineage.", "external_references": [{"external_id": "AN1294", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0470#AN1294"}], "id": "x-mitre-analytic--bcf48294-2388-4ae6-be22-f9038c54e1db", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1294", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "SSL/TLS Handshake Analysis", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Organizations in certificate issuer fields to allowlist or monitor.", "field": "IssuerOrgFilter"}, {"description": "Restrict detection to non-system users or external-facing applications.", "field": "UserContext"}, {"description": "Specific HTTP header anomalies or patterns (e.g., missing User-Agent).", "field": "HeaderSignatureMatch"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3509', 0, 119, '09-mitre-attack', 'retrieved', '737AC3D4653738D7D9DF979A214F1B01989F8A0072C4A59900048AC9CFEF3E08', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
