INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3510', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Chain: (1) interactive/non-interactive `chage -l`, `grep`/`cat` of PAM config (e.g., `/etc/pam.d/common-password`, `/etc/security/pwquality.conf`); (2) optional reads of `/etc/login.defs`; (3) same user performs account enumeration or password change attempts shortly after. Use auditd `execve` and file read events plus shell history collection.", "external_references": [{"external_id": "AN0456", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0161#AN0456"}], "id": "x-mitre-analytic--bcf6e9cb-fee9-4efd-8998-03de4908448b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0456", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "open,openat,read", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}, {"channel": "sudo chage|grep pam_pwquality|cat /etc/login.defs", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Exact PAM/QoP config files used by your distro (Debian vs. RHEL paths differ).", "field": "MonitoredPaths"}, {"description": "System daemons that legitimately parse policies on boot.", "field": "ServiceAccountsExclude"}, {"description": "TTY vs. non-interactive—raise risk for non-interactive remote execution.", "field": "TerminalType"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3510', 0, 138, '09-mitre-attack', 'retrieved', '28DD11D623AFD46319387ED6BB5C1D4C4748930AC8431B3641B98B8F2A32B3FF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
