VALUES ('doc-09-mitre-attack-p0-3511', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Untrusted or unusual process/script (cmd.exe, powershell.exe, w32tm.exe, net.exe, custom binaries) queries system time/timezone (e.g., w32tm /tz, net time \\\\host, Get-TimeZone, GetTickCount API) and (optionally) is followed within a short window by time-based scheduling or conditional execution (e.g., schtasks /create, at.exe, PowerShell Start-Sleep with large values).", "external_references": [{"external_id": "AN0430", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0151#AN0430"}], "id": "x-mitre-analytic--bd34c127-9956-4616-999d-229f30512f74", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0430", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "High-frequency or suspicious sequence of QueryPerformanceCounter/GetTickCount API calls from a non-standard process lineage", "name": "etw:Microsoft-Windows-Kernel-Process", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"channel": "EventCode=106", "name": "WinEventLog:TaskScheduler", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}, {"channel": "Task registration/execution shortly after a time discovery event", "name": "WinEventLog:TaskScheduler", "x_mitre_data_component_ref": "x-mitre-data-component--7b375092-3a61-448d-900a-77c9a4bde4dc"}, {"channel": "Process lineage and API usage enrichment (GetSystemTime, GetTimeZoneInformation, NtQuerySystemTime)", "name": "EDR:Telemetry", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Correlation window (e.g., 5–15 minutes) between time discovery and follow-on scheduling/conditional actions.", "field": "TimeWindow"}, {"description": "Legitimate parent processes (e.g., corporate scripts, management agents) that frequently call time APIs.", "field": "AllowedParents"}, {"description": "Extend/restrict keyword list for time queries (e.g., custom PS functions, .NET calls).", "field": "CommandlineKeywordList"}, {"description": "Restrict to non-service, non-administrative, or newly created/rare users.", "field": "UserContextScope"}, {"description": "Frequency threshold to exclude common estate-wide benign usage.", "field": "ProcessPrevalenceThreshold"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3511', 0, 236, '09-mitre-attack', 'retrieved', 'C05AF0F24752B23FF66C2CE04DDD35147010A5E7D720B3992A19CCAC04DF76AC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
