VALUES ('doc-09-mitre-attack-p0-3512', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary uses compromised instance credentials or web application access to deface content hosted in S3 buckets, Azure Blob Storage, or GCP Buckets.", "external_references": [{"external_id": "AN0666", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0238#AN0666"}], "id": "x-mitre-analytic--bd893675-a17e-4c3b-bec4-ffbad6986c73", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0666", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "PutObject", "name": "CloudTrail:PutObject", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "GetObject, CopyObject", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--58ef998c-f3bf-4985-b487-b1005f5c05d1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Patterns of S3 or GCP buckets used for static website hosting may vary by organization.", "field": "BucketNameRegex"}, {"description": "Some uploads may appear benign unless enriched with user/role metadata.", "field": "IAMRoleContext"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3512', 0, 105, '09-mitre-attack', 'retrieved', '631EF77A3FB937CFFB91C5CC9D8925323EF1564F62A21F9B8A9164BD4E9ED004', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
