VALUES ('doc-09-mitre-attack-p0-3513', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of renamed common utilities (e.g., `bash`, `nc`, `python`, `sh`) from atypical directories or with names intended to deceive defenders or EDRs.", "external_references": [{"external_id": "AN0014", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0005#AN0014"}], "id": "x-mitre-analytic--bd8beea8-48c8-41dc-8991-f8c739d10c70", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0014", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "event-based", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"channel": "cron activity", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Path anomalies such as execution from /dev/shm, /tmp, or user home directories", "field": "ExecutionPath"}, {"description": "Unusual lineage such as scripts invoking renamed tools", "field": "ParentProcessContext"}, {"description": "Correlate between file rename and immediate execution", "field": "TimeWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3513', 0, 116, '09-mitre-attack', 'retrieved', 'B6318D86DEF8E202D79DE4BC14029710609AD7950D7CF40A2E8B0EF0247DB5