VALUES ('doc-09-mitre-attack-p0-3514', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects kill/systemctl/service commands against EDR, auditd, falco, osquery, rsyslog, journald, or agent processes; configuration edits disabling startup; module unload attempts; abrupt cessation of logs after privileged shell execution.", "external_references": [{"external_id": "AN1370", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0497#AN1370"}], "id": "x-mitre-analytic--bda03bab-3f0b-4bd0-8a8f-77bcb2b1ee7d", "modified": "2026-05-12T16:30:18.381Z", "name": "Analytic 1370", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve: systemctl stop, service stop, or kill -9 on security daemons (e.g., falcon-sensor, auditd)", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "delete: Modification of systemd unit files or config for security agents", "name": "auditd:CONFIG_CHANGE", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of endpoint protection service names (varies across deployments).", "field": "AgentServiceNames"}, {"description": "Accounts permitted to legitimately stop or reconfigure services.", "field": "AllowedAdminAccounts"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-3514', 0, 127, '09-mitre-attack', 'retrieved', '04FB4A99CEBFF0F2671137DD6A4921DAEED406C