VALUES ('doc-09-mitre-attack-p0-3516', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "EndpointSecurity/Unified Logs show processes generating custom alphabets or long high-entropy, non-standard tokens → network logs (PF/Zeek/EDR) show asymmetric beacons, protocol mismatches, or periodic fixed-size posts.", "external_references": [{"external_id": "AN0929", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0326#AN0929"}], "id": "x-mitre-analytic--bdc546bb-9d92-489e-8aa8-8de1bd08f320", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0929", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "ES_EVENT_TYPE_NOTIFY_EXEC: arguments contain long, non-standard tokens / custom alphabets", "name": "macos:endpointsecurity", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "high out:in ratio or fixed-size periodic flows", "name": "PF:Logs", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "http: suspicious long tokens with custom alphabets in body/headers", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Payload entropy minimum.", "field": "EntropyThreshold"}, {"description": "Minimum suspicious token length.", "field": "TokenLengthThreshold"}, {"description": "Asymmetry threshold.", "field": "BytesOutToInRatio"}, {"description": "Correlation window.", "field": "TimeWindow"}, {"description": "Signed binaries that legitimately implement custom encoders.", "field": "AllowedSignedBinaries"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3516', 0, 137, '09-mitre-attack', 'retrieved', '1BDB1827EA70436F5E45F29CEF3FE04C2029C8912ADB36D2E7BBAAF854DA39BC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
