VALUES ('doc-09-mitre-attack-p0-3517', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects enumeration of VMs using PowerShell (`Get-VM`), VMware Workstation (`vmrun.exe`), or Hyper-V (`VBoxManage.exe`). Defender observes suspicious command lines executed by unexpected users or outside normal administrative sessions.", "external_references": [{"external_id": "AN0574", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0199#AN0574"}], "id": "x-mitre-analytic--be2239de-ae8e-442d-a9f6-d34460b94e94", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0574", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines which accounts are authorized to execute VM discovery commands.", "field": "ExpectedAdminAccounts"}, {"description": "Whitelist of approved administrative scripts that legitimately invoke VM enumeration.", "field": "RoutineScripts"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3517', 0, 98, '09-mitre-attack', 'retrieved', '49381382C87509194FB12F2370AEBC82B5995FFB63C175FB6FFA2E30FAEF2955', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
