VALUES ('doc-09-mitre-attack-p0-3518', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of suspicious enumeration of cloud storage objects via API calls such as AWS S3 ListObjectsV2, Azure List Blobs, or GCP ListObjects. Correlate access with account role, user context, and prior authentication activity to identify anomalous usage patterns (e.g., unusual account, unexpected regions, or large-scale enumeration in short time windows).", "external_references": [{"external_id": "AN1594", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0578#AN1594"}], "id": "x-mitre-analytic--be55aa59-62b5-40cd-bab2-dbc4de80da0e", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1594", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "ListObjectsV2", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--fcc4811f-9cc8-4db5-8097-4d8242a380de"}, {"channel": "GetObject, CopyObject", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--58ef998c-f3bf-4985-b487-b1005f5c05d1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Correlation window (e.g., multiple enumeration calls within 5 minutes) may indicate automated discovery versus normal user activity.", "field": "TimeWindow"}, {"description": "Expected service accounts and IAM roles that regularly enumerate storage; deviations may indicate suspicious activity.", "field": "UserContext"}, {"description": "Unusual enumeration of buckets across multiple geographic regions in short succession may indicate adversary reconnaissance.", "field": "RegionScope"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3518', 0, 158, '09-mitre-attack', 'retrieved', 'FB8A380A24C73CAF1CAF2DF79CB0FE773E3E94C9279E8AB2387117B561C0CEAC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
