VALUES ('doc-09-mitre-attack-p0-3519', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Enumeration of macOS local users using dscl, id, dscacheutil, or /etc/passwd access.", "external_references": [{"external_id": "AN0848", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0303#AN0848"}], "id": "x-mitre-analytic--be680af0-8d5f-482c-9042-f5d4921e65f8", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0848", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "None", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Monitor dscl . list /Users, dscacheutil -q user, id -un.", "field": "CommandLine"}, {"description": "Focus on enumeration from non-console users or untrusted apps.", "field": "InteractiveSession"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3519', 0, 82, '09-mitre-attack', 'retrieved', '024CB190F9947C46D48ABDE7F28196E2FD9554337D93C59C26DBEB0B3F686BF7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
