VALUES ('doc-09-mitre-attack-p0-3520', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of file discovery commands (e.g., ''dir'', ''show flash'', ''nvram:'') from CLI interfaces, especially by unauthorized users or from abnormal source IPs.", "external_references": [{"external_id": "AN1044", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0370#AN1044"}], "id": "x-mitre-analytic--be6e5f23-0e29-430f-83f7-d76c58de3a2d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1044", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "CLI Command Logging", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Filter allowed commands by account or IP", "field": "CommandWhitelist"}, {"description": "Tunable to restrict detection to remote terminal or Telnet/SSH", "field": "SessionOrigin"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3520', 0, 92, '09-mitre-attack', 'retrieved', 'AC570DABC0742744856A09E6B952A939215A55254D22C21DB750F9A9DEEC19B8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
