VALUES ('doc-09-mitre-attack-p0-3521', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of suspicious use of `tscon.exe` or equivalent methods to hijack legitimate RDP sessions. Defenders can observe anomalies such as session reassignments without corresponding authentication, processes spawned in the context of hijacked sessions, or unusual RDP network traffic flows that deviate from expected baselines.", "external_references": [{"external_id": "AN1620", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0588#AN1620"}], "id": "x-mitre-analytic--be773ad4-9e5f-4063-910a-99a3cab90582", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1620", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4624, 4648", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=7045", "name": "WinEventLog:System", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Whitelist of systems and accounts authorized to use RDP; deviations indicate possible hijacking.", "field": "ExpectedRDPHosts"}, {"description": "Time threshold for correlating logon events with session reassignment and process execution.", "field": "TimeWindow"}, {"description": "Environment-specific mapping of user accounts to session IDs; inconsistencies may reveal hijacking.", "field": "SessionIDMapping"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3521', 0, 155, '09-mitre-attack', 'retrieved', '30D4848B182A30029F4EF5B69788D181E20C40966C2E039A103EC21487A62ECE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
