VALUES ('doc-09-mitre-attack-p0-3522', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects FTP, SMB, or TFTP traffic initiated by suspicious processes like PowerShell, cmd.exe, or rundll32.exe—especially with large outbound file transfers or unbalanced traffic volume.", "external_references": [{"external_id": "AN1169", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0416#AN1169"}], "id": "x-mitre-analytic--befbbdad-a17b-41f2-bb24-5cb477c5cc50", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1169", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "ftp.log, smb_files.log", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Limit to non-standard FTP clients or suspicious binaries (e.g., cmd, mshta)", "field": "ProcessImageFilter"}, {"description": "Ratio of outbound:inbound bytes; e.g., >90% outbound", "field": "DataFlowDirectionThreshold"}, {"description": "Suspicious file extensions or naming (e.g., .zip, .rar, random hash names)", "field": "FilenamePattern"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3522', 0, 121, '09-mitre-attack', 'retrieved', '044031C56200F693982506E4C896A309502065A13EFBB4C0A345EC2BE11341E9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
