VALUES ('doc-09-mitre-attack-p0-3523', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects suspicious changes to SAML/OAuth federation configurations, such as new signing certificates, altered endpoints, or claims issuance rules granting elevated privileges.", "external_references": [{"external_id": "AN0818", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0293#AN0818"}], "id": "x-mitre-analytic--bf166688-0c78-43a5-bb87-3159c1b86584", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0818", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Federation configuration update or signing certificate change", "name": "saas:okta", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Federation/SAML endpoints monitored for modification.", "field": "FederationEndpoints"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3523', 0, 80, '09-mitre-attack', 'retrieved', '5DBE1C2B5776CA72B7D41D63916E58BD997D609120B09B1B010A72255F3EF35A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
