INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3524', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of adversary attempts to enumerate Group Policy settings through suspicious command execution (gpresult), PowerShell enumeration (Get-DomainGPO, Get-DomainGPOLocalGroup), and abnormal LDAP queries targeting groupPolicyContainer objects. Defenders observe unusual process lineage, script execution, or LDAP filter activity against domain controllers.", "external_references": [{"external_id": "AN0152", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0055#AN0152"}], "id": "x-mitre-analytic--bf5772b8-86b4-4d73-bbff-6abb5da9edac", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0152", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4661", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--5c6de881-bc70-4070-855a-7a9631a407f7"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "query: High-volume LDAP traffic with filters targeting groupPolicyContainer attributes", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines the correlation window to link suspicious PowerShell activity, gpresult execution, and LDAP enumeration.", "field": "TimeWindow"}, {"description": "Identifies accounts expected to perform GPO enumeration (administrators vs. standard users).", "field": "UserContext"}, {"description": "Patterns for detecting suspicious gpresult or PowerShell cmdlets; tunable to reduce noise in environments where these tools are common.", "field": "CommandLinePatterns"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3524', 0, 168, '09-mitre-attack', 'retrieved', 'CDC1B8F3DB361378EF30919A9958E24AD052CD57716D385571873663DCF586A6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
