INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3525', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Defenders may observe adversary attempts to patch system images by monitoring for anomalous file transfers (TFTP, SCP, FTP) of image files, unauthorized CLI commands altering boot system variables, integrity check mismatches between running and baseline OS images, and runtime memory manipulation attempts. Suspicious sequences include uploading a new image, modifying boot parameters, and subsequent reload/reboot of the device. In-memory patching attempts may manifest as debug commands or boot loader manipulation inconsistent with normal administrative activity.", "external_references": [{"external_id": "AN1293", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0469#AN1293"}], "id": "x-mitre-analytic--bf64c48c-5834-426c-be21-6db0efbc7909", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1293", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Execution of privileged commands such as ''copy tftp flash'', ''boot system'', or ''debug memory''", "name": "networkdevice:cli", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "Configuration changes to startup image paths, boot loader parameters, or debug flags", "name": "networkdevice:config", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "Debug or memory access commands indicating attempts to alter OS instructions in memory", "name": "firmware:runtime", "x_mitre_data_component_ref": "x-mitre-data-component--b9d031bb-d150-4fc6-8025-688201bf3ffd"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Whitelist of validated vendor OS versions; deviations may indicate tampering.", "field": "ApprovedFirmwareVersions"}, {"description": "Trusted admin accounts permitted to update images; anomalies suggest compromise.", "field": "AuthorizedAdminAccounts"}, {"description": "Baseline hash of approved images; used for detecting file tampering.", "field": "ChecksumBaseline"}, {"description": "Correlation period for detecting chained behaviors (file upload → boot config change → reboot).", "field": "TimeWindow"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3525', 0, 225, '09-mitre-attack', 'retrieved', 'A9FEA71586998063C7CAB8D31B41F984ED5C379A8F1EFF4A3152FBF7AEA53B7C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
