INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3527', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects the redirection of syscall execution flow via modification of VDSO code stubs or GOT entries to load and execute a malicious shared object through mmap and ptrace.", "external_references": [{"external_id": "AN1241", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0448#AN1241"}], "id": "x-mitre-analytic--bfc7e981-ca7e-4b1b-a692-65a8867a7a89", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1241", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "ptrace, mmap, mprotect, open, dlopen", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"channel": "change from PROT_READ|PROT_WRITE to PROT_EXEC", "name": "auditd:memprotect", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}, {"channel": "open of suspicious .so from non-standard paths", "name": "auditd:file-events", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "child process invoking dynamic linker post-ptrace", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Regex to filter dynamic library paths outside of `/lib`, `/usr/lib`, etc. (e.g., `/tmp`, `/dev/shm`)", "field": "SuspiciousSharedObjectPathRegex"}, {"description": "Max delay allowed between ptrace attach and mmap/mprotect execution in target process", "field": "TimeWindow_PtraceToMmap"}, {"description": "Flag when executable memory mappings deviate from normal runtime behavior", "field": "ExecMemoryProtectionThreshold"}, {"description": "Parent processes unlikely to legitimately call ptrace (e.g., nginx, apache2, sshd)", "field": "AnomalousParentProcessList"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3527', 0, 169, '09-mitre-attack', 'retrieved', '4AABFB4206FA25A311C835E831E463C35FD9E7FC5072F3AAA9031E6867D87C88', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
