INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3528', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor email message traces and headers for failed SPF, DKIM, or DMARC checks indicating spoofed sender identities. Correlate abnormal sender domains or mismatched return-paths with elevated spoofing likelihood.", "external_references": [{"external_id": "AN1202", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0431#AN1202"}], "id": "x-mitre-analytic--c0055eb3-5579-48a8-b9d3-df6dd67bc388", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1202", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "AuthenticationDetails=fail OR SPF=fail OR DKIM=fail OR DMARC=fail", "name": "m365:messagetrace", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines sensitivity to SPF/DKIM/DMARC failures; higher thresholds reduce false positives but may miss stealthier spoofing.", "field": "SpoofScoreThreshold"}, {"description": "Specifies which domains to enforce strict validation against; enterprise-specific tuning may be required.", "field": "MonitoredDomains"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3528', 0, 113, '09-mitre-attack', 'retrieved', '2D367171D75F16C9D1FE92C727DD9BBD4EDFF143FAE522EE1FD6B56416036F84', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
