INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3530', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary modifies ESXi host login banner or MOTD file (/etc/motd), either through SSH or host console access. May involve configuration file overwrite or API calls from compromised vSphere clients.", "external_references": [{"external_id": "AN0232", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0082#AN0232"}], "id": "x-mitre-analytic--c024ed9a-02bf-436d-93f5-444e45124e2f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0232", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "changes to /etc/motd or /etc/vmware/welcome", "name": "ESXiLogs:messages", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "modification of config files or shell command execution", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Target file paths (e.g., /etc/motd) may be changed via symbolic link or override", "field": "LoginBannerFilePath"}, {"description": "ESXi hostd vs. SSH-based defacement origin may affect visibility", "field": "AccessOrigin"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3530', 0, 119, '09-mitre-attack', 'retrieved', '01B7CEF32B154F8221A9A1CB2571A3A31F37B3EC701D66DAAA251D21B18C6A2B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
