VALUES ('doc-09-mitre-attack-p0-3531', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects credential interception via malicious LD_PRELOAD-based shared libraries loaded into ssh, sudo, or scp processes. Correlates environment variable injection, unexpected library loads, and memory patching behavior.", "external_references": [{"external_id": "AN0390", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0139#AN0390"}], "id": "x-mitre-analytic--c031c27b-4d05-406a-8538-04ce1df41d35", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0390", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "LD_PRELOAD Logging", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Watch for user-defined suspicious .so files (e.g., libhook.so, libshadow.so)", "field": "InjectedLibraryName"}, {"description": "Hooked binaries vary by use case (e.g., ssh, login, gdm)", "field": "TargetProcessName"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3531', 0, 103, '09-mitre-attack', 'retrieved', '03823B3B71BA31AEAAE1DD245E015147A60991EC30234434BA4361834979E4FB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
