INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3532', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of unauthorized modification of Active Directory SID-History attributes to escalate privileges. This chain involves: (1) privileged operations or API calls to DsAddSidHistory or related AD modification functions, (2) observed attribute changes in SID-History (Event ID 5136), (3) new logon sessions where the token includes unexpected or privileged SID-History values, and (4) follow-on resource access using elevated privileges derived from SID-History injection.", "external_references": [{"external_id": "AN0383", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0136#AN0383"}], "id": "x-mitre-analytic--c061d938-cafa-4e9d-8729-29d63ba633ad", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0383", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=5136", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--5b8b466b-2c81-4fe7-946f-d677a74ae3db"}, {"channel": "EventCode=4720, 4738", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}, {"channel": "api_call: Calls to DsAddSidHistory or related RPC operations", "name": "etw:Microsoft-Windows-Directory-Services-SAM", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Approved migration windows or known SID-History population events.", "field": "AllowedSIDHistoryChanges"}, {"description": "Correlation window between attribute change and suspicious logon activity (default 15–30 minutes).", "field": "TimeWindow"}, {"description": "List of sensitive SIDs (e.g., Enterprise Admins, Domain Admins) that should never appear in SID-History.", "field": "PrivilegedSIDList"}, {"description": "Exclude trusted migration service accounts or pre-approved administrative tasks.", "field": "UserContextFilter"}, {"description": "Raise alerts when a token contains more than X SID-History entries (default X=2).", "field": "AnomalousSIDCountThreshold"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3532', 0, 199, '09-mitre-attack', 'retrieved', '7B0A752964C7295D195962A994D2719B614311E002229EADE8D8824CAD05AF38', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
