VALUES ('doc-09-mitre-attack-p0-3535', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects attempts to forge or replay Kerberos tickets by monitoring Unified Logs for anomalous kinit/klist activity and correlating unusual authentication sequences.", "external_references": [{"external_id": "AN1445", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0522#AN1445"}], "id": "x-mitre-analytic--c08ad617-cc0d-4435-9168-08c762048503", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1445", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Unusual Kerberos TGS-REQ without TGT or anomalous ticket lifetime", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Expected sequence of TGT followed by TGS requests; deviations may indicate forgery.", "field": "TicketRequestPatterns"}, {"description": "Expected ticket lifetimes; anomalies may indicate Golden or Silver Tickets.", "field": "TicketLifetime"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3535', 0, 102, '09-mitre-attack', 'retrieved', 'B7A312155331135D720BBB523964E878C6E099304686BB372D8F74EC33E65ABF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
