VALUES ('doc-09-mitre-attack-p0-3536', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary spawns a process or script to enumerate installed software using WMI, registry, or PowerShell, potentially followed by additional discovery or evasion behavior.", "external_references": [{"external_id": "AN1100", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0392#AN1100"}], "id": "x-mitre-analytic--c0bbe0a5-680f-487b-8f5f-27703efb52b7", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1100", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Execution of ''Get-WmiObject Win32_Product'' or similar PowerShell cmdlets", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detection may be scoped to multiple discovery commands within a short timeframe.", "field": "TimeWindow"}, {"description": "Tuning based on whether discovery activity stems from suspicious versus approved management tools.", "field": "ParentProcess"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3536', 0, 112, '09-mitre-attack', 'retrieved', '03597E8D730736F0F0CD56E907649A9ACB576BE780E19365BFA5AE67BE3DB0EF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
