INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3537', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects suspicious access to SSSD secrets database and Kerberos key material indicating ticket theft or replay attempts. Correlates anomalous file access with unusual Kerberos service ticket requests.", "external_references": [{"external_id": "AN1444", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0522#AN1444"}], "id": "x-mitre-analytic--c101374a-ce7a-46d7-b7d4-c64fbdf1f685", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1444", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Access to /var/lib/sss/secrets/secrets.ldb or .secrets.mkey", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "Unusual kinit or klist activity", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--02d090b6-8157-48da-98a2-517f7edd49fc"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Alert threshold for frequency of access to Kerberos secrets files.", "field": "SecretsAccessThreshold"}, {"description": "Baseline accounts normally performing Kerberos requests; anomalies flagged.", "field": "UnusualServiceAccounts"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3537', 0, 110, '09-mitre-attack', 'retrieved', 'EDCD7C216C7F40E046FA2A97DE40631F0F5B8F439D642F39487B234528C45CB8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
