INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3538', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor for creation or modification of udev rules files in key directories (/etc/udev/rules.d/, /lib/udev/rules.d/, /usr/lib/udev/rules.d/). Look for RUN+= or IMPORT keys invoking suspicious binaries or scripts. Correlate this with process execution from systemd-udevd context, and file writes near udev reload/restart events. Combine this with unexpected background process spawning from udevd-related forks.", "external_references": [{"external_id": "AN1056", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0375#AN1056"}], "id": "x-mitre-analytic--c1167779-9df4-4387-b777-4da097c6b033", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1056", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "chmod, write, create, open", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "udev rule reload or trigger command executed", "name": "auditd:CONFIG_CHANGE", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Path to udev rules (may vary by distro or user configuration)", "field": "UdevRulePath"}, {"description": "Regex or string pattern to flag suspicious command executions in RUN+=", "field": "SuspiciousRunPattern"}, {"description": "Max interval between rule change and execution to correlate activity", "field": "TimeWindow"}, {"description": "Expected parent of RUN-invoked commands (e.g., systemd-udevd)", "field": "ParentProcess"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3538', 0, 168, '09-mitre-attack', 'retrieved', '23A14F2CDE2F3870AADBBA8A8E25D390690B9B5E13A5DCDBFF734DE010EAD281', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
