VALUES ('doc-09-mitre-attack-p0-3539', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary invokes ''dpkg -l'', ''rpm -qa'', or other package managers via shell or script to enumerate installed software.", "external_references": [{"external_id": "AN1101", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0392#AN1101"}], "id": "x-mitre-analytic--c14042f6-5ebd-42a2-b293-b2367b300fb6", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1101", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Execution of dpkg, rpm, or other package manager with list flag", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Manual invocation of software enumeration commands via interactive shell", "name": "linux:shell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Path to the wrapper script that invokes enumeration commands.", "field": "ScriptName"}, {"description": "Scope detection to interactive vs. background shell contexts.", "field": "TTYContext"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3539', 0, 110, '09-mitre-attack', 'retrieved', 'DCB763D213CC9E7D8F2603FE3E5A52C7C434938D2F64ACEF15E184BD18699ACF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
