VALUES ('doc-09-mitre-attack-p0-3540', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects deletion or hiding of security-related mail rules, audit mailboxes, or calendar/log sync artifacts indicative of tampering post-intrusion.", "external_references": [{"external_id": "AN0525", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0184#AN0525"}], "id": "x-mitre-analytic--c15d6b5e-bbb7-4dc7-8b59-8ce2c0663c05", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0525", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Remove-InboxRule, Clear-Mailbox", "name": "m365:exchange", "x_mitre_data_component_ref": "x-mitre-data-component--faa34cf6-cf32-4dc9-bd6a-8f7a606ff65b"}, {"channel": "PurgeAuditLogs, Remove-MailboxAuditLog", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Limit by VIP mailboxes or external-facing users", "field": "TargetMailboxScope"}, {"description": "Tune for log deletion following lateral movement", "field": "AuditLogDepth"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3540', 0, 92, '09-mitre-attack', 'retrieved', 'E570AB9AB29D7FD59133F8AAE3086AF357CE480ACB482AE39E86D33264C55EE0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
