VALUES ('doc-09-mitre-attack-p0-3542', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Process creates a raw/packet socket and attaches a (e)BPF filter (setsockopt SO_ATTACH_FILTER/ATTACH_BPF or bpf(BPF_PROG_LOAD)). Immediately after a matching inbound packet, the same process binds/connects outward to a remote host (reverse shell or beacon).", "external_references": [{"external_id": "AN0463", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0162#AN0463"}], "id": "x-mitre-analytic--c19f8f89-76f9-4345-8bb6-a065fba50bff", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0463", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "socket(AF_PACKET|AF_INET, SOCK_RAW, *), setsockopt(… SO_ATTACH_FILTER|SO_ATTACH_BPF …), bpf(cmd=BPF_PROG_LOAD), open/openat path=\"/dev/bpf*\" (BSD/macOS-like) or setcap cap_net_raw.", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "family=AF_PACKET or protocol raw; process name not in allowlist.", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "Rare inbound packet characteristics (ICMP/UDP/TCP to uncommon port) from src_ip followed ≤TimeWindow by outbound SF from same host to src_ip.", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Flag raw-socket activity outside privileged daemons (root-only by default).", "field": "UserContext"}, {"description": "If using packet content (Zeek), treat high-entropy single-packet triggers as suspicious.", "field": "MinPayloadEntropy"}, {"description": "System services allowed to open AF_PACKET (dhclient, keepalived, LLDP, monitoring agents).", "field": "AFPacketAllowList"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3542', 0, 169, '09-mitre-attack', 'retrieved', 'F5358BB4F7BED5B0B2672699B7D9BAA9C88C5D783DECD07C74B6FB6D1C2EE5FE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
