VALUES ('doc-09-mitre-attack-p0-3543', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "ESXi shell execution of tools/scripts (`nc`, `socat`, `perl`) relaying network traffic to other internal hosts, especially when initiated by unauthorized users or VMs.", "external_references": [{"external_id": "AN0207", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0075#AN0207"}], "id": "x-mitre-analytic--c1fd84b0-953d-463b-a293-3d6aa81e4589", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0207", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "/var/log/shell.log", "name": "esxi:shell", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "/var/log/vmkernel.log", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "conn.log", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Watch for chained shell commands building local-to-local connections.", "field": "CLICommandPattern"}, {"description": "Correlate to which VM initiated the traffic tunnel; unexpected VM behavior may be suspicious.", "field": "VMInitiator"}, {"description": "Unusual east-west communication patterns among VMs.", "field": "ConnectionDirectionality"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3543', 0, 117, '09-mitre-attack', 'retrieved', 'AAB64A4D6584F483C3505551CF1C9FBC97C1014CD0C348AFFF9B15504B4A02FF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
