INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3544', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor kernel module load/unload activity via modprobe, insmod, rmmod, or direct manipulation of /lib/modules. Correlate with installation of kernel headers, compilation commands, or downloads of .ko files. Detect anomalies in unsigned module loading or repeated module load attempts under non-root users.", "external_references": [{"external_id": "AN1243", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0450#AN1243"}], "id": "x-mitre-analytic--c221d379-1dcb-4ca7-908e-59f6ed7afaed", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1243", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Execution of insmod, modprobe, or rmmod commands by non-standard users or outside expected timeframes", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "Access or modification to /lib/modules or creation of .ko files", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "New or modified kernel object files (.ko) within /lib/modules directory", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Scope detection to non-root or unexpected users performing module-related activity", "field": "UserContext"}, {"description": "Limit alerts to module activity outside approved change windows", "field": "TimeWindow"}, {"description": "Adjust regex pattern for directories to monitor depending on kernel version or distro", "field": "FilePathRegex"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3544', 0, 170, '09-mitre-attack', 'retrieved', '0B1ED202C6074D9C320BBF6CD11B4F07441AF7BB9ECEABA017AD6C6AA733C710', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
