VALUES ('doc-09-mitre-attack-p0-3545', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Behavioral correlation of privileged registry key creation under the W32Time TimeProviders path combined with a new DLL written to disk and potential process activity by LocalService. Indicates abuse of Time Providers for persistence.", "external_references": [{"external_id": "AN0341", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0122#AN0341"}], "id": "x-mitre-analytic--c223f997-8323-40c2-98c9-38a8a1779db4", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0341", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=13, 14", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "May need to be tuned to only monitor `W32Time\\TimeProviders` subkey path for performance optimization", "field": "RegistryPathScope"}, {"description": "Should focus on activity from administrative or SYSTEM accounts", "field": "UserContext"}, {"description": "Controls correlation window between registry modification and DLL drop", "field": "TimeWindow"}, {"description": "Used for anomaly scoring on DLL path patterns (e.g., random names or temp directories)", "field": "DllPathEntropyThreshold"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3545', 0, 155, '09-mitre-attack', 'retrieved', '27AFE896E0A0FDE180011504DAF9CA923ED354FD8A225F6DE6563F92F18257DD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
