VALUES ('doc-09-mitre-attack-p0-3546', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Access to browser artifact locations (e.g., Chrome, Edge, Firefox) by processes like PowerShell, cmd.exe, or unknown tools, followed by file reads, decoding, or export operations indicating enumeration of bookmarks, autofill, or history databases.", "external_references": [{"external_id": "AN0037", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0013#AN0037"}], "id": "x-mitre-analytic--c233a50c-0fdb-412b-85f6-8ff71a3539b9", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0037", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Location of browser data folders like %APPDATA%\\Google\\Chrome\\User Data or %APPDATA%\\Mozilla\\Firefox", "field": "TargetPathRegex"}, {"description": "Used to exclude known browser maintenance or backup processes", "field": "ParentProcess"}, {"description": "Used to detect suspicious PowerShell commands targeting browser data", "field": "ScriptBlockPattern"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3546', 0, 130, '09-mitre-attack', 'retrieved', '90E4BDF85FCDB92A4AE408DE1C94B7B98528206D6CDBE89E3B0DE68D107AC073', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
