VALUES ('doc-09-mitre-attack-p0-3549', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Remote/API driven creation **and** start of a container whose image is not on an allow‑list (or is tagged `latest`), executed by a non-admin principal, and/or started with risky runtime attributes (e.g., `--privileged`, host PID/NET namespaces, sensitive host path mounts, capability adds). Correlates *create* ➜ *start* ➜ first network/process actions from that container within a short time window.", "external_references": [{"external_id": "AN0693", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0249#AN0693"}], "id": "x-mitre-analytic--c345908d-4f74-4341-a203-8c76be2a136b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0693", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "container_create,container_start", "name": "docker:daemon", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "CRI CreateContainer/StartContainer with privileged=true OR added capabilities OR host* namespaces", "name": "containerd:runtime", "x_mitre_data_component_ref": "x-mitre-data-component--5fe82895-28e5-4aac-845e-dc886b63be2e"}, {"channel": "process execution or network connect from just-created container PID namespace", "name": "ebpf:syscalls", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "remote API calls to /containers/create or /containers/{id}/start", "name": "docker:events", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Environment-specific allow-list of approved images (with digests).", "field": "known_images"}, {"description": "Service accounts or CI/CD users permitted to deploy containers.", "field": "known_admins"}, {"description": "Max time between create, start, and first activity to consider events causally linked (default 5m).", "field": "TimeWindow"}, {"description": "Minimum number of risky attributes (e.g., unknown image + privileged) to alert.", "field": "RiskThreshold"}, {"description": "Set of runtime flags considered high risk (e.g., --privileged, --cap-add=SYS_ADMIN, hostPID, hostNetwork, /var/run/docker.sock mount).", "field": "PrivilegedFlags"}], "x_mitre_platforms": ["Containers"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3549', 0, 216, '09-mitre-attack', 'retrieved', 'C8CA0D6EF4A067E7229E10A4E5673279806CA4B8FA28E9A40229A65D1020A02B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
