VALUES ('doc-09-mitre-attack-p0-3550', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Authentication failure logs on routers/switches showing repeated use of default or common passwords across multiple accounts", "external_references": [{"external_id": "AN1340", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0487#AN1340"}], "id": "x-mitre-analytic--c35bd9de-acd9-41f9-9e4f-2a3aad461de6", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1340", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "AAA or TACACS authentication failures", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Cluster of failed attempts in short period indicating spray", "field": "AuthFailureBurst"}, {"description": "Limit detection to console/SSH vs web UI interfaces", "field": "InterfaceFilter"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3550', 0, 89, '09-mitre-attack', 'retrieved', '2269641279915CA6935E131BBB2AD148D67414BDB6DD42132301A336DC1AD1BD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
