VALUES ('doc-09-mitre-attack-p0-3553', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Creation of files or directories with a leading ''.'' in privileged directories (/etc, /var, /usr/bin). Defender view: monitoring auditd logs for file creations where name begins with ''.'' and correlated with unusual user/process context.", "external_references": [{"external_id": "AN0092", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0032#AN0092"}], "id": "x-mitre-analytic--c4108797-7eb4-4ef8-8dee-c2db00695ab4", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0092", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "File creation with name starting with ''.''", "name": "auditd:FILE", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "Use of mv or cp to rename files with ''.'' prefix", "name": "auditd:EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Restrict detection to critical directories to avoid noise from benign hidden files like .ssh or .config.", "field": "DirectoryScope"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3553', 0, 120, '09-mitre-attack', 'retrieved', 'D1D8DF2D57B5C8C7CEBF0AAE661839B432B6D10CC281E91593F9FA6A494409FB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
