VALUES ('doc-09-mitre-attack-p0-3554', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects adversaries accessing remote mail systems (e.g., Exchange Online, O365) using stolen credentials or OAuth tokens, followed by scripted access to mailbox contents via PowerShell, AADInternals, or unattended API queries. Detection focuses on abnormal logon sessions, user agents, IP locations, and scripted or tool-based email data access.", "external_references": [{"external_id": "AN0131", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0048#AN0131"}], "id": "x-mitre-analytic--c42179a8-71c5-41ba-bbfa-d6c1a93e729b", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0131", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Abnormal sign-in from scripting tools (PowerShell, AADInternals)", "name": "azure:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "MailItemsAccessed & Exchange Audit", "name": "m365:purview", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Filters user agents like ''PowerShell'', ''AADInternals'', ''python-requests'' which can vary depending on script/tool.", "field": "UserAgentPattern"}, {"description": "Defines the temporal correlation window between login, command execution, and outbound email access.", "field": "TimeWindow"}, {"description": "Defines baseline geo/IP address ranges to suppress known corporate access.", "field": "KnownIPLocations"}, {"description": "Defines the accounts considered privileged (admin, execs) and worthy of tighter thresholds.", "field": "PrivilegedUserList"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3554', 0, 183, '09-mitre-attack', 'retrieved', '60E9338006707F0A83EE425689E0A59A8A9398F99ADAC1D4D3AD89ED55061624', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
