INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3555', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor for abnormal certificate enrollment and usage activity in Active Directory Certificate Services (AD CS), registry access to certificate storage locations, and unusual process executions that attempt to export or access private keys.", "external_references": [{"external_id": "AN0671", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0240#AN0671"}], "id": "x-mitre-analytic--c448cbb5-1256-4a00-8582-1759fb5a6e56", "modified": "2025-11-12T18:12:53.100Z", "name": "Analytic 0671", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4768", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--02d090b6-8157-48da-98a2-517f7edd49fc"}, {"channel": "EventCode=4657", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--ed0dd8aa-1677-4551-bb7d-8da767617e1b"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Organizations may tune which Extended Key Usage (EKU) values are considered risky.", "field": "EKU_Thresholds"}, {"description": "Defines how quickly multiple certificate enrollments from the same entity should trigger correlation alerts.", "field": "TimeWindow"}, {"description": "Differentiate between service accounts and interactive user accounts to reduce false positives.", "field": "LogonContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3555', 0, 133, '09-mitre-attack', 'retrieved', '2B2F21CB85C77A60CDFEC740EF5BE26EFEB09B055A7320FE58230780FB10A24C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
