INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3556', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects the modification or addition of Launch Agents or Startup Items to establish persistence. Adversaries may write plist or executable files to ~/Library/LaunchAgents/, /Library/StartupItems/, or similar directories and configure them to run at user or system boot. Detection requires correlating file creation or modification events with subsequent user logon or boot-time process execution.", "external_references": [{"external_id": "AN1197", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0429#AN1197"}], "id": "x-mitre-analytic--c46d9fac-eac9-479e-91d3-4f5a1066972d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1197", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "launchservices or loginwindow events", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "/Library/StartupItems/, ~/Library/LaunchAgents/", "name": "macos:fsevents", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Specific paths to monitor may differ across macOS versions or enterprise baselines.", "field": "directory_path"}, {"description": "Different users may have unique LaunchAgents folders—tuning may be required.", "field": "user_context"}, {"description": "The correlation time between file creation and process execution may need to be adjusted for boot persistence.", "field": "time_window"}, {"description": "Specific startup binaries (e.g., bash, osascript) may vary across implementations.", "field": "process_name"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3556', 0, 169, '09-mitre-attack', 'retrieved', 'DDB00DF98C280D08D82955CAD6B526253DAF4AC1485B4385F010F7A0BDEAF590', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
