VALUES ('doc-09-mitre-attack-p0-3557', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The adversary uses native utilities like base64, gzip, tar, or openssl to decode, decompress, or decrypt files that were previously staged or downloaded. These tools may be chained with curl/wget and executed via bash/zsh, often to extract an embedded payload or reverse shell script.", "external_references": [{"external_id": "AN0768", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0275#AN0768"}], "id": "x-mitre-analytic--c4866ad5-310c-4a72-89b5-1e5a8683d286", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0768", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "bash/zsh of base64, tar, gzip, or openssl immediately after file write", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Shell interpreter may vary (bash, zsh, dash, sh)", "field": "ShellProcessName"}, {"description": "May include base64, openssl, gunzip, tar, uudecode", "field": "DecodeUtility"}, {"description": "Expected parent process may vary in attacker chain (e.g., curl, bash, ssh)", "field": "ParentProcess"}, {"description": "Detection regex should support flexible patterning of decode switches", "field": "ArgumentPattern"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3557', 0, 147, '09-mitre-attack', 'retrieved', '012D8354FCD031CA559BCA45ACFCFB39BFAF56C998AECB146468D4914D437AA6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
