VALUES ('doc-09-mitre-attack-p0-3558', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of enumeration activity when system processes query ESXi host account configuration or management APIs to retrieve user account listings.", "external_references": [{"external_id": "AN1617", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0587#AN1617"}], "id": "x-mitre-analytic--c4973f27-c8db-4478-aaf8-eb73580fceec", "modified": "2026-05-12T16:30:18.382Z", "name": "Analytic 1617", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "vCenter Management", "name": "esxi:vpxd", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune based on known enumeration commands: ''vim-cmd vimsvc/auth/userlist''.", "field": "CommandPattern"}, {"description": "Elevated enumeration from vpxuser or root may indicate threat activity.", "field": "PrivilegedSession"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3558', 0, 92, '09-mitre-attack', 'retrieved', '802B1480569FA01C8FBC396D4973E744030DC4E300583B1AFF267EE1C2D44441', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
