VALUES ('doc-09-mitre-attack-p0-3559', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "SaaS applications receiving authentication failures for dozens of accounts using same password or login signature", "external_references": [{"external_id": "AN1343", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0487#AN1343"}], "id": "x-mitre-analytic--c4a0d95a-2dfc-4b03-830e-d0dafca0be6f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1343", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "signin_failed", "name": "saas:auth", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Restrict detection to identity providers or select high-risk SaaS platforms", "field": "CloudAppScope"}, {"description": "Adjust based on size and role of account pool", "field": "UserPopulationSensitivity"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3559', 0, 85, '09-mitre-attack', 'retrieved', 'EE32F358966ECAA1DF1D6B8FEEB937930ACCBA641439803018DB8303768EEF97', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
