INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3560', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of suspicious token manipulation chains: use of token-related APIs (e.g., LogonUser, DuplicateTokenEx) or commands (runas) → spawning of a new process under a different security context (e.g., SYSTEM) → mismatched parent-child process lineage or anomalies in Event Tracing for Windows (ETW) token/PPID data → abnormal lateral or privilege escalation activity.", "external_references": [{"external_id": "AN0786", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0283#AN0786"}], "id": "x-mitre-analytic--c4cabd45-86a2-4842-9171-dff93f6ac737", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0786", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4672, 4634", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "token_analysis: API calls such as DuplicateTokenEx or ImpersonateLoggedOnUser", "name": "ETW:Token", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"channel": "EventCode=5136", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--5b8b466b-2c81-4fe7-946f-d677a74ae3db"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Correlation time between suspicious API usage, runas, and process creation (e.g., 5–10m).", "field": "TimeWindow"}, {"description": "Whitelist of service accounts permitted to spawn SYSTEM-level processes.", "field": "AllowedServiceAccounts"}, {"description": "Legitimate administrative utilities that trigger token changes.", "field": "KnownAdminTools"}, {"description": "Deviation threshold for PPID mismatches detected via ETW.", "field": "ParentProcessAnomalyThreshold"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3560', 0, 176, '09-mitre-attack', 'retrieved', '62D624DE56E2A200CB2709095011A3292198A01F4A3E25DFC9870597C961DE0A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
