VALUES ('doc-09-mitre-attack-p0-3562', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects GUI-based credential prompts invoked via zenity/kdialog/dialog or X11 APIs from non-user-facing scripts or background shell sessions, often with authentication-related text.", "external_references": [{"external_id": "AN1441", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0521#AN1441"}], "id": "x-mitre-analytic--c4ff3b74-bba1-4129-b246-50213e77336d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1441", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Terminal Command History", "name": "linux:cli", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Filter zenity/kdialog prompts launched from unexpected parent shells", "field": "ExecutableName"}, {"description": "Look for ''password'', ''authentication required'', or similar tokens", "field": "PromptString"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3562', 0, 96, '09-mitre-attack', 'retrieved', 'F0C0CEC926DF6B009FFD7C361F584DA321B347D152A6C1D0E0A0A5C134884AE4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
