VALUES ('doc-09-mitre-attack-p0-3563', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects application-layer tunneling or unauthorized app protocols like DNS-over-HTTPS, embedded C2 in TLS/HTTP headers, or misused SMB traffic crossing VLANs.", "external_references": [{"external_id": "AN1228", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0444#AN1228"}], "id": "x-mitre-analytic--c5117811-b262-4920-90d9-001d25b6305b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1228", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "conn.log, http.log, dns.log, ssl.log", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detects DNS tunneling, encrypted HTTP C2, or malformed headers", "field": "AppProtocolAbusePattern"}, {"description": "Monitor internal hosts talking externally using internal protocols (e.g., SMB)", "field": "NorthSouthEgressFilter"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3563', 0, 94, '09-mitre-attack', 'retrieved', '4676AB614EBC248CAA93405D221C504AA47A88DFA8A81B0A76EFA6A083561161', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
