VALUES ('doc-09-mitre-attack-p0-3564', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Audit VoIP/SIP logs for suspicious outbound calls or call setup messages to unusual endpoints. Correlate with user activity such as browser execution or package installation following the call.", "external_references": [{"external_id": "AN0684", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0245#AN0684"}], "id": "x-mitre-analytic--c5134555-561a-4905-8601-a6ba307fc121", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0684", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "SIP REGISTER, INVITE, or unusual call destination metadata", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Regular expressions or rules for spotting abnormal call destinations", "field": "CallDestinationPatterns"}, {"description": "Expected users who initiate VoIP traffic vs. anomalous accounts", "field": "UserContext"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3564', 0, 104, '09-mitre-attack', 'retrieved', '7766463F9631D5E1180D71F9D81BC776077A8195A18FE1BBDC1E47B75027C17D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
