VALUES ('doc-09-mitre-attack-p0-3565', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Behavioral chain: (1) cross-account or third-party principal assumes a role into the tenant/subscription/project; (2) privileged API calls are made in short succession; (3) access originates from unfamiliar networks or geos. Correlate assume-role/federation events with sensitive API usage.", "external_references": [{"external_id": "AN1348", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0488#AN1348"}], "id": "x-mitre-analytic--c526f8c1-95ec-494f-b7bf-49a95a803f2a", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1348", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "AssumeRole,AssumeRoleWithSAML,AssumeRoleWithWebIdentity", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "CreateUser|AttachRolePolicy|CreateAccessKey|UpdateAssumeRolePolicy|CreateLoginProfile", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "google.iam.credentials.generateAccessToken / serviceAccountTokenCreator", "name": "gcp:audit", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Cross-account principals permitted to assume roles; used for allow-listing.", "field": "ExternalAccountAllowList"}, {"description": "Provider-specific list of risky APIs for scoring.", "field": "SensitiveAPIs"}, {"description": "Detect impossible travel between partner and tenant actions.", "field": "GeoVelocityThreshold"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3565', 0, 129, '09-mitre-attack', 'retrieved', '437714E9A8344CD9F0EDBBB7B4506A6F42A7D22375401B061E8C8EC13AFD6F8D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
