VALUES ('doc-09-mitre-attack-p0-3566', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects non-native file transfer via curl, Python scripts, or AppleScript using uncommon protocols like FTP, SMTP, or DNS exfiltration through mDNSResponder abuse.", "external_references": [{"external_id": "AN0369", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0131#AN0369"}], "id": "x-mitre-analytic--c545f39e-d1a2-4b0e-bdf1-6a84226557e9", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0369", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "log stream (subsystem: com.apple.system.networking)", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "process_events", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "file_events", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Weight rarely-used protocols in user space.", "field": "ProtocolUnusualnessScore"}, {"description": "Track which binaries usually call curl/nc and alert on deviation.", "field": "ExecutableBaselining"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3566', 0, 104, '09-mitre-attack', 'retrieved', '013E6AE8652A20B4A1398E7B0C0D16169B2ED118586CEF0898F1BACE1E931096', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
