INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3567', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Defenders may observe adversary attempts to extract configuration data from management repositories by monitoring for anomalous SNMP queries, API calls, or protocol requests (e.g., NETCONF, RESTCONF) that enumerate system configuration. Suspicious sequences include repeated queries from untrusted IPs, abnormal query types requesting sensitive configuration data, or repository access occurring outside of normal administrative maintenance windows. Abnormal authentication attempts, sudden enumeration of device inventory, or bulk data transfer of configuration files may also be observed.", "external_references": [{"external_id": "AN1630", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0592#AN1630"}], "id": "x-mitre-analytic--c5544183-4868-4a5c-ad8c-8a9359358298", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1630", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Unexpected or unauthorized inbound connections to SNMP, NETCONF, or RESTCONF services", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "Authentication failures or unusual community string usage in SNMP queries", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Expected IP ranges or hosts permitted to query configuration repositories; deviations may indicate compromise.", "field": "AuthorizedAdminIPs"}, {"description": "Time periods when configuration queries normally occur; anomalies outside these windows may be suspicious.", "field": "NormalAccessTimeWindow"}, {"description": "Number of queries allowed within a given period before an anomaly is triggered.", "field": "QueryVolumeThreshold"}, {"description": "Expected usage of SNMP, NETCONF, or RESTCONF; deviations from baseline patterns may indicate misuse.", "field": "ProtocolUsageBaseline"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3567', 0, 212, '09-mitre-attack', 'retrieved', '8863207C2313CEFBB888CC8B06AC94726946AA0CC95DFEE45921E1DB1F5B87B8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
