VALUES ('doc-09-mitre-attack-p0-3568', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects bash, sh, zsh, or BusyBox shell execution initiated via remote sessions, unauthorized users, or embedded within secondary script interpreters. Focus is on chained behavior: shell > suspicious commands > network discovery or persistence indicators.", "external_references": [{"external_id": "AN1081", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0384#AN1081"}], "id": "x-mitre-analytic--c5556dd5-005a-4c11-b028-240fa379d827", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1081", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "socket_events", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "auth.log / secure.log", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detect variants like /bin/sh, /usr/local/bin/zsh, /bin/busybox sh.", "field": "ExecutableName"}, {"description": "Shell used by service accounts, root, or rare accounts.", "field": "UserContext"}, {"description": "Shell invoked by unexpected parents (e.g., curl, mail, apache2).", "field": "ParentProcess"}, {"description": "Execution outside maintenance windows or normal activity periods.", "field": "TimeWindow"}, {"description": "Flags use of loops, download commands, chaining (|, &&), or reverse shells.", "field": "CommandLinePattern"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3568', 0, 154, '09-mitre-attack', 'retrieved', '9D87A436C7C8A00F1F3DEA935733EB682F5F5B359B154E9DBB591E44CFBD241A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
