VALUES ('doc-09-mitre-attack-p0-3569', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects aggregation of files from different directories into /tmp, /mnt, or user-specified directories with archiving tools like tar or gzip.", "external_references": [{"external_id": "AN0725", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0261#AN0725"}], "id": "x-mitre-analytic--c5e7b8a9-72f6-40db-be4a-ec17386d884f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0725", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "e.g., /tmp, /var/tmp, custom user dirs", "field": "StagingDirs"}, {"description": "tar, gzip, zip, 7z", "field": "ArchiveUtilities"}, {"description": "Number of files or size written in short time", "field": "UserThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3569', 0, 99, '09-mitre-attack', 'retrieved', '55270DF2418FF714342B1515C7C9F64F80C801F48AA1A490BB93D992D8071290', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
