VALUES ('doc-09-mitre-attack-p0-3570', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor for malicious payload delivery through phishing where attachments or URLs in email clients (e.g., Thunderbird, mutt) result in unusual file creation or outbound network connections. Focus on correlation between mail logs, file writes, and execution activity.", "external_references": [{"external_id": "AN0189", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0070#AN0189"}], "id": "x-mitre-analytic--c5fe5b29-c56f-4c40-b880-051ec6644600", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0189", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Inbound messages with anomalous headers, spoofed SPF/DKIM failures", "name": "Application:Mail", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "execve: Execution of scripts or binaries sourced from mail directories (/var/mail, ~/Maildir)", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "System or user directories where emails/attachments are stored.", "field": "MonitoredMailPaths"}, {"description": "Known good hashes for common business document templates.", "field": "AttachmentHashBaseline"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3570', 0, 128, '09-mitre-attack', 'retrieved', '03A14C02F99A089B4214D036BA9E62C4853E7B87FEEDA31CEB730DDC0854D590', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
