VALUES ('doc-09-mitre-attack-p0-3571', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of AppleScript or Automator services launching `ssh -L`, `socat`, or `launchctl` items that dynamically reroute traffic from one Mac endpoint to another. LaunchAgents used to establish permanent internal tunnels.", "external_references": [{"external_id": "AN0206", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0075#AN0206"}], "id": "x-mitre-analytic--c62026a7-3332-489f-bb86-30626c1b3cc8", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0206", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "None", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "pf firewall logs", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "Process Events and Launch Daemons", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Directory where proxying LaunchDaemons may be dropped, e.g., `/Library/LaunchDaemons/`.", "field": "LaunchAgentPath"}, {"description": "Dynamic port forwards often use ephemeral or non-standard service ports.", "field": "PortBindings"}, {"description": "May trigger on less common scripting interfaces for traffic redirection.", "field": "AppleScriptUsage"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3571', 0, 131, '09-mitre-attack', 'retrieved', '6C5A3E346E62B75DBAF63AC8F1312375467D69305087371736D9AC8437B637A2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
