VALUES ('doc-09-mitre-attack-p0-3572', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects interactive or automated use of CLI commands like `show ip sockets`, `show tcp brief`, or SNMP queries for active sessions on routers/switches.", "external_references": [{"external_id": "AN0907", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0320#AN0907"}], "id": "x-mitre-analytic--c6208aa1-fa6e-4d9d-a284-dd0aab1ee31c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0907", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "command logs", "name": "networkdevice:cli", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "management queries", "name": "snmp:trap", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Monitors for known socket/session query strings.", "field": "CommandPatternList"}, {"description": "Restrict detections to non-admin roles executing advanced queries.", "field": "PrivilegedUserCheck"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3572', 0, 97, '09-mitre-attack', 'retrieved', '3FA51E23583DC482E06A24B9922664D2D0BB98AEBEC2B6CB9A14BD9A15AAEE6C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
