VALUES ('doc-09-mitre-attack-p0-3573', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Processes executing commands to query system locale and language settings, such as ''locale'', ''echo $LANG'', or parsing environment variables. Suspicious activity is indicated by these commands being run by unusual users, automation scripts, or non-administrative processes.", "external_references": [{"external_id": "AN1562", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0565#AN1562"}], "id": "x-mitre-analytic--c625c090-edcc-431a-a2fb-c31e4eb5f2cf", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1562", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve calls to /usr/bin/locale or shell execution of $LANG", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "EventCode=1", "name": "linux:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Unexpected or non-admin users executing locale commands may suggest malicious behavior.", "field": "UserContext"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3573', 0, 109, '09-mitre-attack', 'retrieved', '6BAD35467BA094B3FE987261C136B0AEE9228DB00AE8089FF7DB834EF92307D2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
