VALUES ('doc-09-mitre-attack-p0-3574', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Processes invoking network-intensive child processes or uploading large data volumes, often from non-standard user or system contexts, with evidence of long-duration TCP/UDP sessions to unusual destinations.", "external_references": [{"external_id": "AN0080", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0028#AN0080"}], "id": "x-mitre-analytic--c699a4ee-83dd-48d8-94ae-658204066ae9", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0080", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Bandwidth anomalies should be assessed over 5-15 min or hourly windows depending on environment size.", "field": "TimeWindow"}, {"description": "Some organizations whitelist traffic to countries based on geolocation.", "field": "DestinationCountry"}, {"description": "Legitimate processes using high bandwidth (e.g., backup tools) must be excluded.", "field": "ProcessName"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3574', 0, 122, '09-mitre-attack', 'retrieved', '10623EEA9D5ECA277E20042B96C228C00390B5EAD327768580F02FC156811513', 'v1', 