VALUES ('doc-09-mitre-attack-p0-3575', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects adversary removal of persistence implants (e.g., rc.local entries or crontab injections) via CLI (`rm`, `sed`, `crontab -r`) and deletion of startup or management scripts.", "external_references": [{"external_id": "AN0116", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0040#AN0116"}], "id": "x-mitre-analytic--c6ae166f-f2ac-405a-85c2-b7f9349a1b99", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0116", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "/var/log/vmkernel.log", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "shell history", "name": "esxi:shell", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "e.g., /etc/rc.local, /etc/init.d/custom.sh", "field": "ScriptRemovalPath"}, {"description": "Wipe or truncate of persistence locations", "field": "StartupEntryClearance"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3575', 0, 92, '09-mitre-attack', 'retrieved', 'CA05571AB9DAC0CACB81A4E306169EB67127E1AEE1A3F5D9816A5493473736D0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
