INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3576', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary deletes critical infrastructure: EC2 instances, S3 buckets, snapshots, or volumes using elevated IAM credentials. Frequently includes batch API calls with `Delete*` or `TerminateInstances`.", "external_references": [{"external_id": "AN0414", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0146#AN0414"}], "id": "x-mitre-analytic--c6f35e44-459c-456b-97a7-997eb2baefb9", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0414", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "DeleteBucket, DeleteDBCluster, DeleteSnapshot, TerminateInstances", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--4c41e296-b8d2-4a37-b789-eb565c87c00c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Correlate multiple destructive API calls over short intervals.", "field": "OperationType"}, {"description": "Flag non-console/API clients initiating destructive behavior.", "field": "UserAgent"}, {"description": "Observe whether deletions span multiple regions or org accounts.", "field": "RegionScope"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3576', 0, 104, '09-mitre-attack', 'retrieved', '21A46EBA39A89EF2D2C54C833DFF5EA9F9ADEB974D466E733B6E744D540B0026', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
