INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3577', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-16T17:00:04.135Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects exploitation attempts against security daemons or kernel security modules followed by daemon termination, disabled logging, module unload, audit stoppage, or reduced endpoint telemetry. Correlates local execution or network input with control degradation.", "external_references": [{"external_id": "AN2039", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0900#AN2039"}], "id": "x-mitre-analytic--c6fb992c-387e-49ee-beaf-a1351aded262", "modified": "2026-05-12T16:30:18.382Z", "name": "Analytic 2039", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve, kill, ptrace, insmod, rmmod targeting security processes", "name": "auditd:EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "auditd stopped, config changed, logging suspended", "name": "auditd:DAEMON", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Names of EDR, audit, AV, firewall daemons", "field": "ProtectedProcessNames"}, {"description": "Approved maintenance unload operations", "field": "ModuleUnloadAllowlist"}, {"description": "Expected telemetry heartbeat tolerance", "field": "HealthGapThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3577', 0, 122, '09-mitre-attack', 'retrieved', '7FD0971471A0C93B04690D5493501FCA962A4F152EBD91C98806EC70255A5E98', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
