INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3578', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects extraction or mounting of container/archive files (e.g., .iso, .vhd, .zip) that originated from the Internet but whose contained files lack Zone.Identifier MOTW tagging. Correlates file creation metadata with subsequent execution of unsigned or untrusted binaries launched outside SmartScreen or Protected View.", "external_references": [{"external_id": "AN0712", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0257#AN0712"}], "id": "x-mitre-analytic--c7172412-6e48-45a0-a1c5-2eae892c1fc7", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0712", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4663, 4670, 4656", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=15", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Adjust monitored file types (e.g., .iso, .vhd, .zip, .gz, .rar) based on enterprise usage", "field": "WatchedExtensions"}, {"description": "Defines correlation window between extraction/mount and first execution of inner files", "field": "TimeWindow"}, {"description": "Whitelist known enterprise archivers and deployment mechanisms to reduce false positives", "field": "TrustedExtractionTools"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3578', 0, 146, '09-mitre-attack', 'retrieved', '8AC52900ED216F19BE86A343F0D6F969024EA9CC49AEDB8EFD265143A0458018', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
