INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3579', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detect adversaries filtering traffic or modifying server responses to evade scanning. Monitor iptables, nftables, or proxy configurations that deny or redirect requests from known scanning agents or defensive tools.", "external_references": [{"external_id": "AN1149", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0411#AN1149"}], "id": "x-mitre-analytic--c71bf861-9b5a-4f39-a53f-bb6f45f7a971", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1149", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve: Execution of commands modifying iptables/nftables to block selective IPs", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Altered response metadata or blocked content based on user-agent or geolocation", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--1067aa74-5796-4d9b-b4f1-a4c9eb6fd9da"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "User-agent strings or scanning tools to monitor for selective filtering.", "field": "BlockedAgents"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3579', 0, 112, '09-mitre-attack', 'retrieved', 'ED1A93353D7949C34EC8CFB8A5613ED25DECAEA10B62CE623DB279AB263E8C9C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
