INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3584', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Excessive inbound HTTP or TLS connections to services such as Apache or Nginx, causing worker thread exhaustion or segmentation faults.", "external_references": [{"external_id": "AN0490", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0173#AN0490"}], "id": "x-mitre-analytic--c7752951-1077-478d-9511-df852cba6b28", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0490", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "High frequency of accept(), read(), or SSL_read() syscalls tied to nginx/apache processes", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "Sudden spike in incoming flows to web service ports from single/multiple IPs", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "Repetitive HTTP 408, 500, or 503 errors logged within short timeframe", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tunable count of specific HTTP error codes in timeframe", "field": "ErrorCodeWindow"}, {"description": "Defines number of connections per second considered anomalous", "field": "ConnectionRateThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3584', 0, 132, '09-mitre-attack', 'retrieved', '3B3FBC8174E7CE0F3EDBCB4763E2186063FCB1A95ABCBC0F40F26C711DCD8E77', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
