INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3585', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detect suspicious calls to sysctl or ptrace API used to determine if a process is being debugged. Monitor for processes that flood OutputDebugString equivalents or generate abnormal exceptions to evade analysis.", "external_references": [{"external_id": "AN1047", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0371#AN1047"}], "id": "x-mitre-analytic--c78d2e09-07d7-48ef-add1-bde622e502a2", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1047", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "ptrace: Processes invoking ptrace with PTRACE_TRACEME flag", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Number of ptrace calls in a time window that should raise suspicion", "field": "PtraceInvocationThreshold"}, {"description": "Exclude known developer tools and monitoring agents", "field": "DevToolExclusionList"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3585', 0, 107, '09-mitre-attack', 'retrieved', '347172016C276286C808D05131180053A6E9A605C96374196CAB7099910B9DF8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
