INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3586', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Correlation of chmod operations setting setuid/setgid bits followed by privileged process execution (EUID != UID), especially from user-writable or abnormal paths.", "external_references": [{"external_id": "AN0307", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0110#AN0307"}], "id": "x-mitre-analytic--c7d513f4-5113-4031-8125-7f145128c2e1", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0307", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "chmod, execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Track execution of setuid binaries where UID != EUID or executed from unexpected user context", "field": "UserContext"}, {"description": "Restrict detection to non-standard locations (e.g., /tmp, /home/*, /var/tmp)", "field": "FilePathScope"}, {"description": "Time delta between chmod setting setuid/gid and process execution to define a suspicious window", "field": "TimeWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3586', 0, 120, '09-mitre-attack', 'retrieved', '8B8842AFA300C35ACBC06F5ACFDDCE7B7AB90A1CC57DF34BCF0E2835054AEB13', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
