VALUES ('doc-09-mitre-attack-p0-3587', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitoring for SSH logins from default accounts such as ''root'', especially when login is via password and not key-based authentication.", "external_references": [{"external_id": "AN1284", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0465#AN1284"}], "id": "x-mitre-analytic--c804a181-f0be-41dd-81ce-95e0a3e5245d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1284", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "USER_LOGIN", "name": "auditd:USER_LOGIN", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Environments using passwordless SSH should not have password logins enabled for root or other default accounts.", "field": "SSHMethod"}, {"description": "Logins from jump boxes may be whitelisted depending on environment policies.", "field": "RemoteIPWhitelist"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3587', 0, 98, '09-mitre-attack', 'retrieved', '81F2144A0C1BA955D85AE0CCEF36AF5559DCEA74EB8F270E8F5993DD85531448', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
