VALUES ('doc-09-mitre-attack-p0-3588', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Inbound spearphishing attempts delivered via third-party services (e.g., Gmail, LinkedIn messages) leading to malicious file downloads or browser-initiated script execution. Defender view includes correlation of external service logins, unexpected file write operations, and suspicious descendant processes spawned from productivity or browser applications.", "external_references": [{"external_id": "AN0320", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0115#AN0320"}], "id": "x-mitre-analytic--c83f1d8c-ba54-4f2d-91b8-3006a2180497", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0320", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of third-party services (e.g., Gmail, LinkedIn, Dropbox) relevant to the organization’s threat profile.", "field": "MonitoredServices"}, {"description": "Process lineage and parent-child execution relationships considered abnormal (e.g., outlook.exe → powershell.exe).", "field": "SuspiciousProcessPatterns"}, {"description": "Correlates file creation and outbound connection activity within a tunable time period after message receipt.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3588', 0, 150, '09-mitre-attack', 'retrieved', '93AAB45E25A3BBB2D389BB2C2ECAA2A86B04C0F458E5DE84C1124B65CF599563', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
