VALUES ('doc-09-mitre-attack-p0-3589', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary modifies Active Directory domain trust settings via `netdom`, `nltest`, or PowerShell to add new domain trust or alter federation. Modifications occur in AD object attributes like trustDirection, trustType, trustAttributes, often paired with SeEnableDelegationPrivilege or certificate injection.", "external_references": [{"external_id": "AN1259", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0458#AN1259"}], "id": "x-mitre-analytic--c84ed29d-c0bf-465c-9e4a-7685cd4ff444", "modified": "2025-11-12T18:15:01.136Z", "name": "Analytic 1259", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=5136", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--5b8b466b-2c81-4fe7-946f-d677a74ae3db"}, {"channel": "EventCode=4704", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Focus on `trustedDomain` or `foreignSecurityPrincipal` AD objects in trust containers.", "field": "ObjectType"}, {"description": "Monitor attributes like `trustPartner`, `trustDirection`, `trustType`, `msDS-TrustForestTrustInfo`.", "field": "AttributeModified"}, {"description": "Correlate trust creation with unusual logon events or certificate modifications.", "field": "TimeWindow"}, {"description": "Flag rare accounts or non-standard admin users performing trust changes.", "field": "UserContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3589', 0, 145, '09-mitre-attack', 'retrieved', '90958389CBA5F793F142D9072BBB647C376B076F3A145B931626577848FF5614', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
