VALUES ('doc-09-mitre-attack-p0-3590', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Login to M365 or Google Workspace from CLI tools or unexpected source IPs, followed by mailbox or document access", "external_references": [{"external_id": "AN0019", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0008#AN0019"}], "id": "x-mitre-analytic--c85d0aea-06c4-4b0f-8552-0d0873394ffa", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0019", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "FileAccessed, MailboxAccessed", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "UserLoggedIn", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Raise alerts on login from CLI when user typically uses web-only", "field": "DevicePlatformMismatch"}, {"description": "Track access to documents labeled as internal/confidential", "field": "SensitiveDocumentAccessPattern"}, {"description": "Tune for high-volume document reads post login", "field": "AccessFrequencyThreshold"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3590', 0, 106, '09-mitre-attack', 'retrieved', 'D0F815F2B943E5FFE36561EEFBB4E7A64ED96F7ADE63C5976BCDC51AC1CF438D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
