VALUES ('doc-09-mitre-attack-p0-3591', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of EFI/firmware manipulation attempts via abnormal driver loads, unsigned kexts, or tampered NVRAM variables associated with component firmware configuration.", "external_references": [{"external_id": "AN0918", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0323#AN0918"}], "id": "x-mitre-analytic--c89e4f72-a563-4665-9934-14b9efe88a06", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0918", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Firmware update events or kernel extension (kext) loads not signed by Apple", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--b9d031bb-d150-4fc6-8025-688201bf3ffd"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of trusted and signed kexts permitted in production systems", "field": "ApprovedKextList"}, {"description": "Known-clean EFI image hashes used for verification", "field": "EFIHashBaseline"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3591', 0, 99, '09-mitre-attack', 'retrieved', 'F7401077C89C7A36A68641FBBF1F915A1E8140AE624D80ABBD09F62DE3F77E36', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
