INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3592', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects web console login events followed by read-only or metadata retrieval activity from GUI sources (e.g., browser session, mobile client) rather than API/CLI sources. Correlates across CloudTrail, IAM identity logs, and user-agent context.", "external_references": [{"external_id": "AN0808", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0291#AN0808"}], "id": "x-mitre-analytic--c8a50f3f-105a-4107-9781-a3d75479e93d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0808", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "ConsoleLogin", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "Post-authentication metadata enumeration from GUI session", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--e214eb6d-de8f-4154-9015-6d47915fbed1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Allowlist/denylist of user agents to distinguish browser-based vs. CLI/API sessions", "field": "UserAgentFilter"}, {"description": "Maximum time delta between login and suspicious GUI activity", "field": "TimeWindow"}, {"description": "Login attempts to dashboard using elevated IAM roles", "field": "PrivilegedSessionThreshold"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3592', 0, 125, '09-mitre-attack', 'retrieved', '13C9FFE241409FB8C5EED33F8540034588F76AEC10A21FBF858AA05604D6E894', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
