VALUES ('doc-09-mitre-attack-p0-3593', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Enumeration of USB and other peripheral hardware via udevadm, lshw, or /sys or /proc interfaces in proximity to collection or mounting behavior.", "external_references": [{"external_id": "AN1354", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0491#AN1354"}], "id": "x-mitre-analytic--c8d9ad93-e4ce-4b00-89cb-8f0f6452923d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1354", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "open/read", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "hardware_events", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--73ff2dcc-24b1-4368-b9dc-706dd9e68354"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Set of binaries used for peripheral enumeration (e.g., ''lshw'', ''lsusb'', ''udevadm'')", "field": "ExecutableList"}, {"description": "Tuning based on which users/scripts are authorized to query device state", "field": "UserContext"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3593', 0, 107, '09-mitre-attack', 'retrieved', '1B6BE04E5B7D477BEB8C79AE008AEC1943068F6A6830A42B243EDC7A3A826F75', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
