VALUES ('doc-09-mitre-attack-p0-3594', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use of nohup, disown, or AppleScript constructs to suppress process interrupts. Defender perspective: commands containing nohup or hidden background tasks (`osascript` with persistent execution) correlated with processes surviving user logouts.", "external_references": [{"external_id": "AN0183", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0067#AN0183"}], "id": "x-mitre-analytic--c9079261-caa7-4cfe-8be6-1359db599d27", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0183", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "nohup, disown, or osascript execution patterns", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "background process persists beyond user logout", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Shells or interpreters where nohup/disown usage is suspicious, configurable to environment.", "field": "WatchedShells"}, {"description": "Time window to correlate process continuation after logout with suspicious commands.", "field": "PersistenceCorrelationWindow"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3594', 0, 119, '09-mitre-attack', 'retrieved', 'DD7CB54C11C66D508181B93D97346E74B25A25570EDF6493229A9A2318BCCD52', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
