VALUES ('doc-09-mitre-attack-p0-3595', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Network device logs show anomalous inbound file transfers or uncharacteristic flows with high payload volume to network devices with storage or automation hooks.", "external_references": [{"external_id": "AN0169", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0060#AN0169"}], "id": "x-mitre-analytic--c93951a7-7f78-40cf-a891-30d6c6a9bee6", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0169", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "connection metadata", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "firmware write/log event", "name": "snmp:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune based on expected update size vs anomalous bulk data transfers", "field": "PayloadVolumeThreshold"}, {"description": "Flag unexpected protocols like TFTP, FTP, HTTP", "field": "ProtocolUsed"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3595', 0, 102, '09-mitre-attack', 'retrieved', '0D7FB145C0F950F9F0EEC9E9A14A1E177A62D6F1E557689FB4428EDF4E45F3BE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
