VALUES ('doc-09-mitre-attack-p0-3596', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Creation or modification of Apple Mail rules by accessing plist files or GUI automation (AppleScript).", "external_references": [{"external_id": "AN1590", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0576#AN1590"}], "id": "x-mitre-analytic--c93edcb2-385a-4472-a9db-ace5371250eb", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1590", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "log stream --predicate", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "/Users/*/Library/Mail/V*/MailData/RulesActiveState.plist", "name": "fs:plist_monitoring", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Different Mail versions store rules in slightly different locations.", "field": "RuleFilePath"}, {"description": "AppleScript usage for GUI automation may be common in automation workflows.", "field": "ScriptTrigger"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3596', 0, 94, '09-mitre-attack', 'retrieved', 'AB29814F1E3982D7B2867C92826619AA61130508B69ADD0C8D5E77F6E535799C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
