VALUES ('doc-09-mitre-attack-p0-3597', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary registers a malicious Microsoft Exchange transport agent DLL (.NET assembly), configures it via PowerShell or Exchange Management Shell, and persists code execution by manipulating email processing logic based on rules or headers.", "external_references": [{"external_id": "AN0472", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0166#AN0472"}], "id": "x-mitre-analytic--c94b2c2b-8885-4f5e-abec-e80ab0a24f21", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0472", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "Exchange Transport Service loads unusual .NET assembly or errors upon transport agent execution", "name": "WinEventLog:Application", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "May need tuning based on frequency of Exchange agent updates in environment.", "field": "TimeWindow"}, {"description": "Specific DLL paths used by Exchange for registered agents may vary between deployments.", "field": "AssemblyPath"}, {"description": "Tunable threshold for repeated use of transport agent management cmdlets.", "field": "CmdletInvocationThreshold"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3597', 0, 161, '09-mitre-attack', 'retrieved', 'BBC53235F661EED3352A6D269452D318C3091BF9B97717156CF1B3947896E2A3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
