VALUES ('doc-09-mitre-attack-p0-3598', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects registration of new or modified network provider DLLs via registry changes, anomalous file creation of DLLs in system directories, and suspicious process activity (mpnotify.exe interacting with non-standard DLLs). Multi-event correlation ties registry modification events to subsequent DLL loads during user logon activity.", "external_references": [{"external_id": "AN1598", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0580#AN1598"}], "id": "x-mitre-analytic--c94f0795-ef0b-4e22-8395-bbba4f28346f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1598", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4657", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Specific registry keys to monitor for DLL registration (e.g., NetworkProvider Order).", "field": "MonitoredRegistryKeys"}, {"description": "Directories or file name patterns outside of normal system DLL locations.", "field": "SuspiciousDLLPaths"}, {"description": "Window correlating registry modification, DLL creation, and subsequent logon activity.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3598', 0, 147, '09-mitre-attack', 'retrieved', 'D5504C1F901B340F07C54A56F869A6825E5E8C244E5EEC6EF26E4331526FF745', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
