VALUES ('doc-09-mitre-attack-p0-3599', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary modifies web-facing content on macOS via web development environments like MAMP or misconfigured Apache instances, typically with access to the hosting user account or via persistence tools.", "external_references": [{"external_id": "AN1624", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0590#AN1624"}], "id": "x-mitre-analytic--c9b3d194-843a-4f65-ad8b-4b3192571fc5", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1624", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Terminal/Editor processes modifying web folder", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "loginwindow or sshd events with external IP", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "May include ~/Sites or custom Apache paths", "field": "web_root_dir"}, {"description": "Text editor or script modifying the files may vary (e.g., nano, VS Code)", "field": "editor_name"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3599', 0, 115, '09-mitre-attack', 'retrieved', 'EB87F6AEDD3692812636BCDDA258CAEAFFF9200D4A1C3596C047424962CCF568', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
