VALUES ('doc-09-mitre-attack-p0-3600', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects malicious containers or pods using names, labels, or namespaces that mimic legitimate workloads; also checks for image layer mismatches and unauthorized resource deployments.", "external_references": [{"external_id": "AN0986", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0347#AN0986"}], "id": "x-mitre-analytic--c9bdc7a6-ff19-46e9-a534-fa2fd3e0a193", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0986", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Resource creation and update logs", "name": "kubernetes:apiserver", "x_mitre_data_component_ref": "x-mitre-data-component--b597a220-6510-4397-b0d8-342cd2c58827"}, {"channel": "Docker or containerd image pulls and process executions", "name": "containerd:events", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of namespaces that should not be used by unprivileged users or workloads", "field": "trusted_namespace_list"}, {"description": "Reference hashes of approved container images", "field": "image_baseline_hashes"}], "x_mitre_platforms": ["Containers"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3600', 0, 111, '09-mitre-attack', 'retrieved', 'E62DE8A635F96373A8CAAD9CFC27ACD0740E041F42EFBE8416F17AB2F8157190', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
