VALUES ('doc-09-mitre-attack-p0-3603', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Anomalous process (e.g., `rundll32`, `svchost`, `cmd`) initiates connections to internal peer hosts not seen in typical communication baselines, used to proxy or forward traffic internally, often using SMB, RPC, or high ports.", "external_references": [{"external_id": "AN0204", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0075#AN0204"}], "id": "x-mitre-analytic--ca56c2df-0338-4325-964a-0f775d986277", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0204", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "SMB over high port", "name": "Windows Firewall Log", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune based on known host-to-host communications that are rare (e.g., workstation-to-workstation).", "field": "InternalConnectionPattern"}, {"description": "Focus on unusual internal traffic on ports like 1080, 8080, 4444, or SMB over non-standard ports.", "field": "DestinationPort"}, {"description": "Correlate unusual traffic bursts with new process execution.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3603', 0, 139, '09-mitre-attack', 'retrieved', 'DF643E50E712D2073A1F299E693EBF00CEB9D1BBE7C206AC4B9B8AF3472B84CC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
