VALUES ('doc-09-mitre-attack-p0-3604', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of anomalous ROMMON image changes or upgrades, unexpected reboots following firmware updates, and unauthorized use of firmware upgrade commands or TFTP transfers. Correlation of config modification, privilege escalation, and boot cycle anomalies provides visibility into ROMMON tampering attempts.", "external_references": [{"external_id": "AN0497", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0175#AN0497"}], "id": "x-mitre-analytic--ca649f9b-2a1f-4d45-b61b-33ac38d6a4ee", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0497", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Log entries indicating ROMMON image upgrade commands (boot system, upgrade rom-monitor)", "name": "networkdevice:config", "x_mitre_data_component_ref": "x-mitre-data-component--b9d031bb-d150-4fc6-8025-688201bf3ffd"}, {"channel": "Unexpected reload, crashinfo, or boot message not tied to scheduled maintenance", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"channel": "Outbound or inbound TFTP file transfers of ROMMON or firmware binaries", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Baseline ROMMON image versions authorized for the environment", "field": "ApprovedROMMONVersions"}, {"description": "Correlation window between ROMMON update command, TFTP file transfer, and device reboot", "field": "TimeWindow"}, {"description": "Expected privileged accounts allowed to execute ROMMON upgrade commands", "field": "AdminUserContext"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3604', 0, 165, '09-mitre-attack', 'retrieved', '38B7CA0FC5BFE6D97F028D4674C58B61466EB5BC7CBACA6392F62444478F2E07', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
