VALUES ('doc-09-mitre-attack-p0-3605', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor call log records from corporate devices for unusual or unauthorized numbers, especially repeated calls to/from known malicious phone numbers. Correlate with subsequent system events (e.g., browser navigation, remote management tool execution).", "external_references": [{"external_id": "AN0683", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0245#AN0683"}], "id": "x-mitre-analytic--caa11058-4906-48b4-ab3f-a650aab6968d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0683", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Outbound or inbound calls to high-risk or blocklisted numbers", "name": "ApplicationLog:CallRecords", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of known malicious or suspicious phone numbers; must be tuned per environment", "field": "PhoneNumberBlocklist"}, {"description": "Threshold for correlating call events with subsequent suspicious system activity", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3605', 0, 114, '09-mitre-attack', 'retrieved', '1B1924C12E8D60EC1B69754B0B5AB61BAAF6BC7DE5D3B1C5364EC48CEF775143', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
