VALUES ('doc-09-mitre-attack-p0-3606', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "User creation or modification via dscl with IsHidden=1, UID<500, or plist edits to com.apple.loginwindow Hide500Users flag. Defender view: correlation of hidden account attributes with login screen exclusion.", "external_references": [{"external_id": "AN1003", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0353#AN1003"}], "id": "x-mitre-analytic--cabc275f-5097-4d2e-aabe-b49a31ba87b9", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1003", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Execution of dscl . create with IsHidden=1", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "Modification of /Library/Preferences/com.apple.loginwindow plist", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "Creation of user account with UID <500", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune detection based on acceptable UID ranges for hidden/system accounts.", "field": "UIDThreshold"}, {"description": "Restrict plist monitoring to com.apple.loginwindow to reduce false positives.", "field": "PlistScope"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3606', 0, 124, '09-mitre-attack', 'retrieved', '4F7D342ED049A9D5662AF6429F288E6C84129415D05AD1D9976C866FFEC83C25', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
