VALUES ('doc-09-mitre-attack-p0-3607', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of shell commands that leverage encoded execution, command chaining, excessive piping, or unusual token patterns indicative of obfuscation.", "external_references": [{"external_id": "AN1395", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0505#AN1395"}], "id": "x-mitre-analytic--cad9e775-f40f-42fb-8e86-c7aba249a8e4", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1395", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "process_events.command_line", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tuning value for token or argument count in shell invocations", "field": "CommandLineTokenCount"}, {"description": "Environment-specific regex patterns for encoded or eval''d command lines", "field": "EncodedExecRegex"}, {"description": "Shell-specific globbing or directory traversal string detection", "field": "GlobPatternAnomalies"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3607', 0, 105, '09-mitre-attack', 'retrieved', '9B0B72C8AEA4667E3FE4217F1D5FB5824679AAB7F69DF2B4A360FD51533FB41D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_