VALUES ('doc-09-mitre-attack-p0-3608', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "VMCI (Virtual Machine Communication Interface) traffic between guest and host, or between VMs, originating from non-management tools or unauthorized binaries.", "external_references": [{"external_id": "AN1257", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0457#AN1257"}], "id": "x-mitre-analytic--cae917e6-7542-41d0-8b03-ad2b7ab1eb01", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1257", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "VMCI syslog entries", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Monitor for non-vSphere or VMware-native processes using VMCI.", "field": "VMCIBackdoorProcess"}, {"description": "Baseline pattern of guest-to-host traffic vs anomaly (unexpected port, volume).", "field": "GuestToHostCommPattern"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3608', 0, 91, '09-mitre-attack', 'retrieved', '14E5EB45EFC2B75DE25084A9C5DD3B4387345144B3C00C37F4E352B5AF77755D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
