VALUES ('doc-09-mitre-attack-p0-3609', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of identity directory enumeration through API calls or administrative queries retrieving multiple account objects within a short interval.", "external_references": [{"external_id": "AN1616", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0587#AN1616"}], "id": "x-mitre-analytic--cb177f89-c8a4-4233-a2e4-3fdd02dccba1", "modified": "2026-05-12T16:30:18.382Z", "name": "Analytic 1616", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Graph API Query", "name": "azure:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--8c826308-2760-492f-9e36-4f0f7e23bcac"}, {"channel": "User Enumeration Events", "name": "saas:okta", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detect user vs role enumeration. Tune based on query scope.", "field": "QueryType"}, {"description": "Correlate enumeration with unexpected app registrations or identities.", "field": "AppContext"}], "x_mitre_platforms": ["Identity Provider"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3609', 0, 101, '09-mitre-attack', 'retrieved', '91772F8E98C621EF64B6E1671EBBE304B62C680DF3AF8650115692D868C40C2C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
