VALUES ('doc-09-mitre-attack-p0-3610', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "ESXi daemons (e.g., hostd, vpxa) are wrapped or impersonated to send large outbound traffic using gzip/Base64 encoding over SSH or HTTP. These actions follow suspicious logins or shell access.", "external_references": [{"external_id": "AN0305", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0108#AN0305"}], "id": "x-mitre-analytic--cb428c22-0a5a-44c9-ae63-6b1bedb34fee", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0305", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "base64 or gzip use within shell session", "name": "esxi:shell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "Outbound traffic using encoded payloads post-login", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "Unexpected login followed by encoding commands", "name": "ESXiLogs:authlog", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Use to scope encoded traffic suspicion to accounts that should not initiate transfers", "field": "AuthSourceTrustLevel"}, {"description": "Threshold for bursty outbound traffic size deviation from baseline", "field": "ExfilBurstThreshold"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3610', 0, 130, '09-mitre-attack', 'retrieved', 'F98A20BA8778E18F783B7439BD7169C04D11B16F73F29D3D53A5C91A2A43BB9D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
