VALUES ('doc-09-mitre-attack-p0-3611', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use of `esxcli network` commands (e.g., `esxcli network nic list`, `esxcli network ip interface ipv4 get`) via SSH or hostd to enumerate adapter and IP information.", "external_references": [{"external_id": "AN0562", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0195#AN0562"}], "id": "x-mitre-analytic--cb70ad2f-7c96-4669-baed-3007246b0630", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0562", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "None", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detection may vary based on internal vs remote terminal usage", "field": "SSHSessionOrigin"}, {"description": "Distinguish between benign status checks and deep enumeration chains", "field": "esxcliCommandDepth"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3611', 0, 96, '09-mitre-attack', 'retrieved', '16E3D6596EC048FEEDB6C126B44DD829BBAAB5E5B1CE111217714E906F54C2A4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
