VALUES ('doc-09-mitre-attack-p0-3613', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Multiple authentication failures for valid or invalid users followed by success from same IP/user", "external_references": [{"external_id": "AN1276", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0463#AN1276"}], "id": "x-mitre-analytic--cba73580-034b-4cdd-84a2-22704d520e9c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1276", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "USER_AUTH", "name": "auditd:USER_LOGIN", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Period of brute force activity correlation (e.g., 5 mins)", "field": "TimeWindow"}, {"description": "Exclude known monitoring IPs or jump boxes", "field": "IPWhitelist"}, {"description": "Filter SSH vs. local logins", "field": "LoginSource"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3613', 0, 89, '09-mitre-attack', 'retrieved', '7C299CED588BA5BC6642C31429853D06132357D4A2C31C2D55658CBF0DE023F4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
