VALUES ('doc-09-mitre-attack-p0-3615', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects local daemons or scripts generating outbound DNS queries with long or frequent subdomains, indicative of DNS tunneling via tools like `iodine`, `dnscat2`, or `dig` from cronjobs or reverse shells.", "external_references": [{"external_id": "AN1122", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0400#AN1122"}], "id": "x-mitre-analytic--cc8183e1-9de4-469a-9117-79bf2e986e31", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1122", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "dns.log", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detects encoded payloads or randomness in DNS labels", "field": "SubdomainEntropyScore"}, {"description": "Allowlisted system daemons expected to perform frequent lookups", "field": "DaemonAllowList"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3615', 0, 103, '09-mitre-attack', 'retrieved', 'C32F032B5D1EDCC19F4153D6E4BBA8427E4E3A29079ACB1FEE1BC76CAA2D07AD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
