INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3618', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unusual process or API usage attempting to query system locale, timezone, or keyboard layout (e.g., calls to GetLocaleInfoW, GetTimeZoneInformation). Detection can be enhanced by correlating with processes not typically associated with system configuration queries, such as unknown binaries or scripts.", "external_references": [{"external_id": "AN0119", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0043#AN0119"}], "id": "x-mitre-analytic--cd4d2b49-6a27-41a7-ab20-d2a3791142bd", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0119", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "GetLocaleInfoW, GetTimeZoneInformation API calls", "name": "etw:Microsoft-Windows-Kernel-Base", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines trusted processes expected to call locale APIs. Deviations may indicate adversarial activity.", "field": "ParentProcessAllowList"}, {"description": "Specifies correlation window for API calls and suspicious process execution (e.g., 2m).", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3618', 0, 125, '09-mitre-attack', 'retrieved', '98105992E1169C3E8DD26156566A136447D28CFA4061B46F9A55BE6FF69EF9F4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
