VALUES ('doc-09-mitre-attack-p0-3620', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Enumeration of global address lists or email account metadata via PowerShell cmdlets (e.g., Get-GlobalAddressList) or MAPI/RPC from non-admin, non-mailserver systems.", "external_references": [{"external_id": "AN0641", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0229#AN0641"}], "id": "x-mitre-analytic--cd91348f-296f-4007-a853-6d06d8175210", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0641", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Match variations of Get-GlobalAddressList, Get-Recipient, and related cmdlets.", "field": "CommandLinePattern"}, {"description": "Suppress expected usage on Exchange servers or known IT admin consoles.", "field": "HostRole"}, {"description": "Detect bulk execution patterns in short intervals, often used during recon.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3620', 0, 113, '09-mitre-attack', 'retrieved', '5DE872DD79E8378815D83CE00856C6A55D51FEBAE5EADB61B9D5300FDA4654C0', 'v1', '{"source_id": "09-mitre-attack", "version": "retri