VALUES ('doc-09-mitre-attack-p0-3621', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Correlate suspicious registry modifications to known COM object CLSIDs with subsequent DLL loads or unexpected binary execution paths. Detect placement of COM CLSID entries under HKEY_CURRENT_USER\\Software\\Classes\\CLSID\\ overriding default HKLM paths. Flag anomalous DLL loads traced back to hijacked COM registry changes.", "external_references": [{"external_id": "AN1323", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0481#AN1323"}], "id": "x-mitre-analytic--cda93955-7500-49dd-9150-94bedae91d22", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1323", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4657", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defenders may tune specific monitored CLSIDs depending on known-good application behavior.", "field": "RegistryPathScope"}, {"description": "May require tuning based on environment to distinguish rare-but-legit COM DLLs vs suspicious ones.", "field": "BinaryPathAnomalyThreshold"}, {"description": "Correlating registry changes to DLL load or process execution may require configurable time window.", "field": "TimeWindow"}, {"description": "Tuning detection by isolating activity to specific user SIDs or admin-level activity may reduce false positives.", "field": "UserContextFilter"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3621', 0, 165, '09-mitre-attack', 'retrieved', '7164D8EF820D44401AC878ECD1AC353A325C1FD32254A853CEB20DB58DA52E0C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
