VALUES ('doc-09-mitre-attack-p0-3622', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Correlate suspicious file transfers over SMB or Admin$ shares with process creation events (e.g., cmd.exe, powershell.exe, certutil.exe) that do not align with normal administrative behavior. Detect remote file writes followed by execution of transferred binaries.", "external_references": [{"external_id": "AN0516", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0183#AN0516"}], "id": "x-mitre-analytic--ce0f284b-f8d9-4cb0-84ad-97e1e8390d0c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0516", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=5140", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--f5468e67-51c7-4756-9b4f-65707708e7fa"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Time period between file transfer and execution used to correlate events", "field": "TimeWindow"}, {"description": "Accounts allowed to perform legitimate administrative transfers", "field": "UserContext"}, {"description": "Exclude known legitimate software update directories", "field": "FilePathWhitelist"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3622', 0, 125, '09-mitre-attack', 'retrieved', 'ABA585C78B9145E7C751186D48F420D016A1F296D05BF30109CB93916AA1EFB8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
