VALUES ('doc-09-mitre-attack-p0-3623', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use of the `security` command or Keychain API to extract known Wi-Fi passwords for target SSIDs.", "external_references": [{"external_id": "AN1282", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0464#AN1282"}], "id": "x-mitre-analytic--ce2233bb-9715-4e7b-8603-7218f8bae326", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1282", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Match suspicious SSIDs being queried via `security find-generic-password -wa`", "field": "WiFiNetworkFilter"}, {"description": "Monitor root/admin usage of credential tools not linked to UI/system processes", "field": "ExecutionUser"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3623', 0, 87, '09-mitre-attack', 'retrieved', 'B340A296165321115CF9101A3679774ECDB8D4B42A3C4B118DAF34FD79F63A21', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
