VALUES ('doc-09-mitre-attack-p0-3624', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor unified logs for access to payment applications, browser plug-ins, or Apple Pay services from non-standard processes. Detect anomalous use of Automator scripts or keychain extraction targeting financial account credentials.", "external_references": [{"external_id": "AN1363", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0495#AN1363"}], "id": "x-mitre-analytic--ce3ebda8-d47e-4730-a1f4-3366d33a98ab", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1363", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Non-standard processes invoking financial applications or payment APIs", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Anomalous keychain access attempts targeting payment credentials", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Financial or payment applications to explicitly monitor for unauthorized use.", "field": "MonitoredApps"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3624', 0, 107, '09-mitre-attack', 'retrieved', 'E80A766794536A4FF3461D81E2C6CACF8E3D109EB3C0D75A668836C3590DA229', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
