VALUES ('doc-09-mitre-attack-p0-3625', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Installation or execution of a malicious browser or IDE extension, followed by abnormal registry entries or outbound network connections from the host application", "external_references": [{"external_id": "AN0251", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0092#AN0251"}], "id": "x-mitre-analytic--ce76c289-b810-44cf-b71e-afc76a70f7bf", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0251", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=13, 14", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Path of browser or IDE launching subprocesses—may vary depending on installed applications", "field": "Image"}, {"description": "Legitimate parent-child process relationships for known safe extensions", "field": "ParentImage"}, {"description": "Expected registry keys under HKCU/HKLM for installed extensions", "field": "RegistryPath"}, {"description": "Tunable interval to correlate extension install with follow-on C2 traffic", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3625', 0, 138, '09-mitre-attack', 'retrieved', '2D72408D2C2AADBB2AB8358710DF1266DEE0C2E948E7E98DD9327614AFDE64FD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
