VALUES ('doc-09-mitre-attack-p0-3626', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unauthorized firmware uploads to routers, switches, or firewalls via TFTP/FTP/SCP. Logs showing boot variable or startup image path changes redirecting to non-standard firmware images. Abnormal reboots or firmware rollback attempts following configuration modification events.", "external_references": [{"external_id": "AN0276", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0099#AN0276"}], "id": "x-mitre-analytic--ceb2c722-f9ec-41de-980e-d8848b1cb20c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0276", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Boot image path or firmware configuration variable modified outside of maintenance windows", "name": "networkdevice:config", "x_mitre_data_component_ref": "x-mitre-data-component--b9d031bb-d150-4fc6-8025-688201bf3ffd"}, {"channel": "Firmware image uploaded via TFTP/FTP/SCP", "name": "networkdevice:runtime", "x_mitre_data_component_ref": "x-mitre-data-component--4dcd8ba3-2075-4f8b-941e-39884ffaac08"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Known good firmware image hashes stored for validation.", "field": "ApprovedFirmwareHashes"}, {"description": "Expected time periods when firmware uploads or reboots are considered normal.", "field": "MaintenanceWindows"}, {"description": "List of trusted management IPs allowed to initiate firmware uploads.", "field": "SourceIPWhitelist"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3626', 0, 139, '09-mitre-attack', 'retrieved', '2488205F4C2F01B3336EC93C1625B9FEB783C095635F02CFE4975754613FCB7D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
