VALUES ('doc-09-mitre-attack-p0-3628', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of file transfer or network access activity through non-primary interfaces (e.g., WiFi, Bluetooth, cellular) by processes not typically associated with such behavior (e.g., rundll32, powershell, regsvr32).", "external_references": [{"external_id": "AN0212", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0077#AN0212"}], "id": "x-mitre-analytic--cf404364-1397-4f0f-9c21-cd534880722a", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0212", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=5005 (WLAN), EventCode=302 (Bluetooth)", "name": "WinEventLog:System", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Filter for specific interface categories (e.g., WiFi, Bluetooth, 4G).", "field": "InterfaceType"}, {"description": "Tunable for environment-specific large file access events pre-transfer.", "field": "FileSizeThreshold"}, {"description": "Temporal correlation window for file read followed by network activity.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3628', 0, 124, '09-mitre-attack', 'retrieved', 'F955257E5BBAD30F5EB5624B56B64068CBC7659F85DB519B8CD1DA3344404A42', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
