VALUES ('doc-09-mitre-attack-p0-3631', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Processes such as osascript, curl, or office applications sending data to text storage APIs/domains. Defender perspective: anomalous clipboard or file reads by unexpected applications immediately followed by outbound HTTPS requests to pastebin-like services.", "external_references": [{"external_id": "AN0789", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0284#AN0789"}], "id": "x-mitre-analytic--cf74f802-0080-41ff-8745-9c42af313462", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0789", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execution of curl, osascript, or unexpected Office processes", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "file read of sensitive directories", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "HTTPS POST requests to pastebin.com or similar", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Processes not normally associated with data uploads (e.g., Preview, Calculator).", "field": "WatchedApps"}, {"description": "High entropy detection to flag encoded or encrypted data exfiltration.", "field": "EntropyThreshold"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3631', 0, 133, '09-mitre-attack', 'retrieved', '3894E71770E5F85FA2F970D0CB5F3CDC6A6ADEF842BAA18C68CFB198886310E6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
