VALUES ('doc-09-mitre-attack-p0-3632', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of OAuth consent phishing or malicious login attempts initiated through spearphishing links. Behavior chain includes inbound email with OAuth URL → consent page visited → unusual token grants logged in IdP logs.", "external_references": [{"external_id": "AN0301", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0107#AN0301"}], "id": "x-mitre-analytic--cfc7b6bc-2ca3-4407-a835-b40bf6a98efc", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0301", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "ConsentGrant: Suspicious consent grants to non-approved or unknown applications", "name": "azure:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Whitelisted apps permitted for OAuth consent grants.", "field": "AllowedApps"}, {"description": "Patterns of consent from unusual geographies, devices, or unapproved applications.", "field": "AnomalousConsentPatterns"}], "x_mitre_platforms": ["Identity Provider"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3632', 0, 110, '09-mitre-attack', 'retrieved', 'FFCF089ACC2951481F3E54B258C969CA8952837E30312863A9628E0C8B9C27F3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
