VALUES ('doc-09-mitre-attack-p0-3633', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor for in-process mmap + mprotect + execve/execveat activity where memory permissions are changed from writable to executable inside the same process without a corresponding ELF on disk.", "external_references": [{"external_id": "AN0839", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0300#AN0839"}], "id": "x-mitre-analytic--cfdd2422-7e68-417a-9298-062bac59df0c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0839", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "memory region with RWX permissions allocated", "name": "auditd:MMAP", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Uncommon for service binaries to call memfd_create; detection tuned for high-risk processes.", "field": "ProcessNameScope"}, {"description": "Adjust threshold for allowed RWX allocations to reduce false positives in JIT runtimes.", "field": "RWXMemoryThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3633', 0, 115, '09-mitre-attack', 'retrieved', 'F47DC3774A97B290C2435F61C541208DF1375C57AA060E7E987123D8EE18D432', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURE