VALUES ('doc-09-mitre-attack-p0-3634', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Multiple sign-in failures against cloud-based applications using username/password combinations leaked from unrelated domains", "external_references": [{"external_id": "AN1266", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0460#AN1266"}], "id": "x-mitre-analytic--cfff571f-eb6b-41e2-a447-f69bc07aa77a", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1266", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "login_failure", "name": "saas-app:auth", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Correlate credentials reused across multiple SaaS platforms", "field": "UserAccountOverlap"}, {"description": "Number of failed logins from same IP before alerting", "field": "FailedAttemptsPerIP"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3634', 0, 80, '09-mitre-attack', 'retrieved', '9BFD62DAF894B217F04294F8ED905F4DCC731FF2FD283F3ACE03E75FED33623F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
