VALUES ('doc-09-mitre-attack-p0-3635', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Failed authentication attempts across user mailboxes using identical or common passwords (e.g., OWA brute attempts)", "external_references": [{"external_id": "AN1342", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0487#AN1342"}], "id": "x-mitre-analytic--cfffc717-79f1-4aea-9e68-475ef52db11d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1342", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "FailedLogin", "name": "m365:exchange", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Threshold on mailbox login failures by same IP", "field": "MailboxAccessAttempts"}, {"description": "Match target usernames to common spray dictionaries", "field": "EmailPatternAnalysis"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3635', 0, 82, '09-mitre-attack', 'retrieved', '95E393ED1F1A51A19FCE00BF52E85C29D7838B0BD5D1B524D8F837C3C500276D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
