VALUES ('doc-09-mitre-attack-p0-3636', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects removal of Remote Login or Screen Sharing logs in Unified Logging, deletion of `com.apple.UTun`, or suspicious Terminal use of `rm`, `sudo pfctl -F all` to clear network state/config history.", "external_references": [{"external_id": "AN0135", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0049#AN0135"}], "id": "x-mitre-analytic--d01951d8-aae8-48b6-afd3-68c86fc167b1", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0135", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "log stream --predicate ''eventMessage contains \"loginwindow\" or \"pfctl\"''", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "file_events", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "e.g., *com.apple.UTun*, *RemoteManagement* log files", "field": "FilenameMatch"}, {"description": "Correlate deletion with recent SSH or GUI remote login session", "field": "TimeDeltaFromLogin"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3636', 0, 109, '09-mitre-attack', 'retrieved', '1CBA5A7F39596CB6E3B421A392ABDB1E588DB55435DF8F059436F0BD99FF020B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
