VALUES ('doc-09-mitre-attack-p0-3638', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of commands accessing locale, timezone, or language settings such as ''locale'', ''timedatectl'', or parsing /etc/timezone. Anomalous execution by unusual users or automation scripts should be flagged.", "external_references": [{"external_id": "AN0120", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0043#AN0120"}], "id": "x-mitre-analytic--d053d033-b587-4ed0-bdbc-0c6a9bdd7c82", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0120", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve calls to locale, timedatectl, or cat /etc/timezone", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "EventCode=1", "name": "linux:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Unexpected users running location discovery commands may indicate malicious behavior.", "field": "UserContext"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3638', 0, 98, '09-mitre-attack', 'retrieved', '847251D6E98EC8753730DEDA11C4B799FD97E46107D27CE9CC204D5330A10CF8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
