VALUES ('doc-09-mitre-attack-p0-3639', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of interactive and remote logins by service accounts or users at unusual times, with unexpected child process activity.", "external_references": [{"external_id": "AN1545", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0560#AN1545"}], "id": "x-mitre-analytic--d059a437-bf45-4b10-a36c-7e42e183d3c7", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1545", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "loginwindow, sshd", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"channel": "exec logs", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Login sourced from unexpected remote addresses.", "field": "LoginOrigin"}, {"description": "Track execution depth or anomalous chains post-login.", "field": "ProcessTreeDepth"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3639', 0, 91, '09-mitre-attack', 'retrieved', 'D269763CD336C0CD1C16E71A99C2CE33C8279D0A44957C63C8B3C429E1431198', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
