VALUES ('doc-09-mitre-attack-p0-3640', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detect commands such as ''esxcli system shutdown'' or ''vim-cmd vmsvc/power.shutdown'' executed outside of maintenance windows or via unusual users. Reboot logs in hostd.log and shell logs should be correlated.", "external_references": [{"external_id": "AN1541", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0559#AN1541"}], "id": "x-mitre-analytic--d076faf3-c5bd-4e5c-93a5-8408c9e80fe1", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1541", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Powering off or restarting host", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}, {"channel": "esxcli system shutdown or reboot invoked", "name": "esxi:shell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Administrative account context validation.", "field": "AccountRole"}, {"description": "Expected times for reboot/shutdown behavior.", "field": "MaintenanceWindow"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3640', 0, 104, '09-mitre-attack', 'retrieved', 'AC7F964078611F9B9128E4E042D9941ED31CF15D67F6F8BEBBA3BC1ED3BA9D16', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
