VALUES ('doc-09-mitre-attack-p0-3642', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary executes commands to enumerate installed antivirus, EDR, or firewall agents using WMI, registry queries, and built-in tools (e.g., tasklist, netsh, sc query). Correlated with elevated process privileges or scripting engine usage.", "external_references": [{"external_id": "AN0048", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0016#AN0048"}], "id": "x-mitre-analytic--d0d1375d-f5c2-4271-b5e7-415c478d5e86", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0048", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defenders can tune based on trusted or known-good parent process relationships", "field": "ParentProcess"}, {"description": "Regex match on adversary tool or enumeration script used", "field": "ImagePathContains"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3642', 0, 109, '09-mitre-attack', 'retrieved', 'FC6C201AAA3E6786D9E11757064A45A5330518490397036280B67749FECFE213', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
