VALUES ('doc-09-mitre-attack-p0-3643', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of CLI commands erasing file systems or storage (erase flash:, format disk, erase nvram:). Detect authentication events followed by destructive commands within the same privileged session.", "external_references": [{"external_id": "AN0885", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0316#AN0885"}], "id": "x-mitre-analytic--d0e64036-83fb-4ff7-b81b-9b67b6c6b9dc", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0885", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "erase flash:, erase nvram:, format disk", "name": "networkdevice:cli", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "Privileged login followed by destructive command sequence", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune to exclude approved maintenance performed by authorized administrators.", "field": "PrivilegedUsers"}, {"description": "Expand or narrow destructive command coverage depending on vendor-specific syntax.", "field": "CommandPatterns"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3643', 0, 115, '09-mitre-attack', 'retrieved', '6E8FCFE7125F87C20CF69AC3526C4AA440FFF9B6216B307EBC7C58021A1CF282', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_v