VALUES ('doc-09-mitre-attack-p0-3644', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Processes on macOS initiate external connections that consistently transmit data in fixed sizes using LaunchAgents or unexpected users.", "external_references": [{"external_id": "AN0598", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0213#AN0598"}], "id": "x-mitre-analytic--d0edef63-9a98-4435-9f4b-2c577c7de41d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0598", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "com.apple.network", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "ES_EVENT_TYPE_NOTIFY_CONNECT", "name": "macos:endpointsecurity", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Agent context in which transfer occurs (e.g., user/privileged)", "field": "LaunchdJobContext"}, {"description": "Used to define what constitutes ''fixed size'' chunks", "field": "TransferSizeMedian"}, {"description": "Detect if protocol usage deviates from common apps for given destination", "field": "TransferProtocolOutlier"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3644', 0, 105, '09-mitre-attack', 'retrieved', '4D5677F4C8EFA8E94BBE764498C0F0AACCA7C1B823A2A1F574F04D7DB4777A40', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object