VALUES ('doc-09-mitre-attack-p0-3646', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects VIBs, scripts, or binaries placed into directories like /bin or /etc/vmware with names mimicking standard ESXi components. Also monitors unauthorized creation of services.", "external_references": [{"external_id": "AN0987", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0347#AN0987"}], "id": "x-mitre-analytic--d16be21c-6df4-4648-91cd-36152dafa38d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0987", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Exec", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "module load", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "Service events", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}, {"channel": "task creation events", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Known good binaries and their expected paths", "field": "esxi_baseline_file_list"}, {"description": "Threshold for unknown service names or mismatched digital signatures", "field": "service_creation_alert_threshold"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3646', 0, 113, '09-mitre-attack', 'retrieved', '0309A0A61B966F4E7A501F16BB6A3E322D60F313DE99216305F7DCC0DBAE9DB6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
