INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3647', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects modification or truncation of `/var/log/shell.log` used to persist ESXi shell command history. Especially suspicious shortly after login or config changes.", "external_references": [{"external_id": "AN0470", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0165#AN0470"}], "id": "x-mitre-analytic--d17e0719-d338-47eb-a5b4-8616749584cf", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0470", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "/var/log/shell.log", "name": "esxi:shell", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Path to shell command history on ESXi.", "field": "LogFilePath"}, {"description": "Time range post-login or privileged escalation.", "field": "TimeWindow"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3647', 0, 85, '09-mitre-attack', 'retrieved', 'C464936A701632B4EF9B4A4AD5CB4F3A4A6FC313B70D6D4B89C83CAC6BB237A2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
