INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3648', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Processes attempting raw disk access via \\\\.\\PhysicalDrive paths, abnormal file I/O to MBR/boot sectors, or loading of third-party drivers (e.g., RawDisk) that enable disk overwrite. Correlate process creation, privilege usage, and disk modification events within a short time window.", "external_references": [{"external_id": "AN0882", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0316#AN0882"}], "id": "x-mitre-analytic--d1ad1b0b-0050-4737-8993-73c2da8d143b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0882", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4673", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}, {"channel": "Raw disk writes targeting \\\\.\\PhysicalDrive* or MBR locations", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--4dcd8ba3-2075-4f8b-941e-39884ffaac08"}, {"channel": "EventCode=6", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3551476e-14f5-4e48-a518-e82135329e03"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Backup, forensics, or imaging tools may perform legitimate raw disk access — requires tuning per environment.", "field": "ProcessWhitelist"}, {"description": "Correlation threshold for process execution, driver load, and raw disk writes.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3648', 0, 136, '09-mitre-attack', 'retrieved', '4BF6B7F72A4CDC14CC047B416C7C4965FF2751A570A1BBF9AEEE5C6CDEB40C06', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
