INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3651', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Forged web credentials may manifest as anomalous SAML token issuance, OpenID Connect token minting, or Zimbra pre-auth key usage. Defenders may see tokens issued without normal authentication events, multiple valid tokens generated simultaneously, or signing anomalies in IdP logs.", "external_references": [{"external_id": "AN0718", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0260#AN0718"}], "id": "x-mitre-analytic--d1eafedb-ac64-46b0-972d-8f8759fc11b3", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0718", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "SAML/OIDC tokens issued without corresponding MFA or password validation", "name": "azure:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--5f7c9def-0ddf-423b-b1f8-fb2ddeed0ce3"}, {"channel": "Pre-authentication keys generated or token signing anomalies", "name": "NSM:Connections", "x_mitre_data_component_ref": "x-mitre-data-component--ff93f688-d7a4-49cf-9c79-a14454da8428"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Limit the maximum time temporary tokens are valid.", "field": "TokenLifetimeThreshold"}, {"description": "Define normal authentication flows (e.g., password+MFA) to baseline token issuance.", "field": "ExpectedAuthFlows"}], "x_mitre_platforms": ["Identity Provider"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3651', 0, 129, '09-mitre-attack', 'retrieved', '481CE038406B0935EEAB60AAE8694D631643A5AB2B704425EAAD708774E029E4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
