INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3652', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects use of built-in SaaS sharing mechanisms to transfer ownership or share access of critical data to external tenants or untrusted users through API calls or link generation features.", "external_references": [{"external_id": "AN1582", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0573#AN1582"}], "id": "x-mitre-analytic--d1ef9a86-7781-4b9e-9178-c2e5b1782c1f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1582", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "drive.permission.add", "name": "saas:googledrive", "x_mitre_data_component_ref": "x-mitre-data-component--45977f14-1bcc-4ec4-ac14-a30fd3a11f44"}, {"channel": "collaboration.invite", "name": "saas:box", "x_mitre_data_component_ref": "x-mitre-data-component--e214eb6d-de8f-4154-9015-6d47915fbed1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Whether the user is in a high-privileged or VIP group", "field": "UserContext"}, {"description": "Allowlist or blocklist of external SaaS domains", "field": "DomainReputationList"}, {"description": "Size or number of shared files triggering alert", "field": "PayloadVolumeThreshold"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3652', 0, 114, '09-mitre-attack', 'retrieved', '479F2265A22DBB67223BB2C2F98A02ABD904A782D0BACE306A19ED373D949DB3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
