VALUES ('doc-09-mitre-attack-p0-3655', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects unusual use of `cron` or `sleep` loops inside containers executing unfamiliar scripts or binaries repeatedly.", "external_references": [{"external_id": "AN0261", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0094#AN0261"}], "id": "x-mitre-analytic--d20d7cf8-ecac-4011-96e0-3ec862223c11", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0261", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "file change monitoring within /etc/cron.*, /tmp, or mounted volumes", "name": "containerd:runtime", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Labels or tags indicating dev/test containers executing scheduled tasks.", "field": "ContainerLabel"}, {"description": "Repetitive invocation pattern within short container lifespan.", "field": "ScriptFrequency"}, {"description": "Unexpected container image sources creating cron entries.", "field": "ImageSource"}], "x_mitre_platforms": ["Containers"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3655', 0, 107, '09-mitre-attack', 'retrieved', '367BD8CB59AE8C191101AE1EADC522FE7093AEF1267820EA191219482F3FD9D3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type