VALUES ('doc-09-mitre-attack-p0-3662', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Custom scripts or processes encode outbound traffic using gzip, Base64, or hex prior to exfiltration via curl, wget, or custom sockets. Encoding typically occurs before or during outbound connections from non-network daemons.", "external_references": [{"external_id": "AN0303", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0108#AN0303"}], "id": "x-mitre-analytic--d32cc2a4-60ed-4761-809e-a59cde2a1881", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0303", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Base64 strings or gzip in URI, headers, or POST body", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "Unusual outbound transfers from CLI tools like base64, gzip, or netcat", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune duration of multi-stage encoding + transfer operations to account for script variability", "field": "TimeWindow"}, {"description": "Apply user allow/block list depending on which users normally perform CLI encoding", "field": "UserContext"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3662', 0, 139, '09-mitre-attack', 'retrieved', 'C7C0C90B2794B850068BCF18BC8A168FDFD6F6A74172523F1B47036D040F4623', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
