VALUES ('doc-09-mitre-attack-p0-3663', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Anomalous traffic from ESXi host management daemons (like hostd or vpxa) embedding non-standard payloads in management protocols (e.g., HTTPS) or beaconing behavior.", "external_references": [{"external_id": "AN0033", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0011#AN0033"}], "id": "x-mitre-analytic--d3bad85b-9e86-4de8-9e4a-1666133af782", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0033", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Network activity", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "System service interactions", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detects mismatched TLS client behavior vs expected for hostd/vpxa.", "field": "TLSFingerprintMismatch"}, {"description": "Highlight traffic from ESXi hosts to uncommon ports outside vCenter ranges.", "field": "UnusualDestinationPorts"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3663', 0, 102, '09-mitre-attack', 'retrieved', '266AEDD61E826B7F481916246AD9F0F13E3B1756B277534F8769DD384D1C30CE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
