VALUES ('doc-09-mitre-attack-p0-3664', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects SaaS web login followed by dashboard or web GUI page views from unfamiliar locations, devices, or access patterns. Identifies use of sensitive reporting or configuration consoles accessed from high-risk accounts.", "external_references": [{"external_id": "AN0811", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0291#AN0811"}], "id": "x-mitre-analytic--d3e3ed48-7402-40df-a6cc-db9b560bcfd1", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0811", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Zoom Admin Dashboard accessed from unfamiliar IP/device", "name": "saas:zoom", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "Login", "name": "saas:salesforce", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"channel": "User navigated to admin interface", "name": "saas:box", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of GUI pages or endpoints considered sensitive", "field": "SaaSDashboardViewList"}, {"description": "Reputation score or allowlist of source IPs", "field": "IPReputationThreshold"}, {"description": "Typical user/device login pairings or login frequency", "field": "LoginBehaviorBaseline"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3664', 0, 129, '09-mitre-attack', 'retrieved', '9AAE0D1871782B026B8E6BFCA43DEFBBD28AC573A7DC8F3F543D423A607BC143', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
