VALUES ('doc-09-mitre-attack-p0-3665', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Registry modification of the LSA Authentication Packages key followed by LSASS loading a non-standard or unsigned DLL. This includes unusual write access to `HKLM\\SYSTEM\\CurrentControlSet\\Control\\Lsa`, especially during non-installation timeframes. Correlated with `lsass.exe` loading DLLs not present in baseline or lacking valid signatures.", "external_references": [{"external_id": "AN0583", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0207#AN0583"}], "id": "x-mitre-analytic--d415367c-3624-4a68-a2b7-4734662db190", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0583", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4657", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Time between registry write and DLL load; tune based on reboot cycles or scheduled maintenance", "field": "TimeWindow"}, {"description": "Allow listing of known signed LSASS-authenticated DLLs versus unknown/untrusted ones", "field": "ImageSignatureStatus"}, {"description": "Allow tuning for subkeys beyond just `Authentication Packages` (e.g., `Security Packages`, `Notification Packages`)", "field": "RegistryPathScope"}, {"description": "Correlate user responsible for registry edit; tune for expected administrative/service accounts", "field": "UserContext"}, {"description": "Validate process lineage for registry modification; expected tools like `reg.exe` or `powershell.exe`", "field": "ParentProcess"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3665', 0, 168, '09-mitre-attack', 'retrieved', 'A949A914EBC7BB42E47102C4F13B3DC56612B00AE00F0AABCC477D7D8AD5D8C4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
