VALUES ('doc-09-mitre-attack-p0-3666', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor unified logs and Mail.app activity for repetitive incoming messages with attachments. Defenders should look for large volumes of incoming mail stored under ~/Library/Mail with unusual timing or repetitive subjects.", "external_references": [{"external_id": "AN1011", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0355#AN1011"}], "id": "x-mitre-analytic--d41cdfc1-2a82-4442-a1ca-177fe59b8dff", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1011", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Repetitive inbound email delivery activity logged within a short time window", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "create: Attachment file creation in ~/Library/Mail directories", "name": "fs:fsusage", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Threshold for repetitive attachment files created within a defined interval.", "field": "FileCountThreshold"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3666', 0, 110, '09-mitre-attack', 'retrieved', 'EEC99EE354161D9A47A14D758DF238262B0C9A9781DAA2EB3C81D3D1003D0B56', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
