VALUES ('doc-09-mitre-attack-p0-3667', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects shell or API usage of `esxcli network ip connection list` or `netstat` to enumerate ESXi host connections.", "external_references": [{"external_id": "AN0906", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0320#AN0906"}], "id": "x-mitre-analytic--d42c2a80-bf02-460f-b279-147940ece3a9", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0906", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "command log", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detect commands executed outside normal management interfaces (e.g., SSH or root shell).", "field": "ExecutionOriginCheck"}, {"description": "Timeframe when host connection audits are expected (e.g., maintenance windows).", "field": "ExpectedAdminAccessWindow"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3667', 0, 92, '09-mitre-attack', 'retrieved', '5494F569A5D8003E26E84C534AEAE9E2FCD3C00EBBCEC3E4CAD959D61595C5C4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
