INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3668', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Processes invoking destructive commands (dd, shred, wipe) with raw device targets (e.g., /dev/sda, /dev/nvme0n1). Detect direct writes to disk partitions and abnormal superblock or bootloader modifications. Correlate shell execution with subsequent block device I/O.", "external_references": [{"external_id": "AN0385", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0137#AN0385"}], "id": "x-mitre-analytic--d442d480-cfb9-43cc-b959-2f81513b432d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0385", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open/write syscalls on /dev/sd* or /dev/nvme*", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--73ff2dcc-24b1-4368-b9dc-706dd9e68354"}, {"channel": "Execution of dd, shred, wipe targeting block devices", "name": "auditd:EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune to exclude removable drives or test partitions commonly written by administrators.", "field": "TargetDevices"}, {"description": "Detects large blocks of pseudorandom data being written; may need tuning for backup/crypto workloads.", "field": "EntropyThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3668', 0, 129, '09-mitre-attack', 'retrieved', '7819A532A73B1C06EC90F1BFAF174E7334B1C91B84BEF8F7778875DA03814468', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
