VALUES ('doc-09-mitre-attack-p0-3670', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Process using URLSession or similar API to fetch from web services without any response handling, indicative of one-way C2 channels.", "external_references": [{"external_id": "AN1601", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0581#AN1601"}], "id": "x-mitre-analytic--d49f06ba-7a81-440b-bc16-c583ba918a3d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1601", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process, network", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "exec events", "name": "macos:endpointsecurity", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Flag unexpected outbound activity from non-admin or system users", "field": "UserContext"}, {"description": "Optional if script-based obfuscation is seen in web requests", "field": "EntropyScore"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3670', 0, 97, '09-mitre-attack', 'retrieved', '62C6EA30025A4EF825208EB982B53B834451CC9AE3E1006F909D9C9A62A3CF89', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
