INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3671', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects anomalous process execution patterns where a process''s parent terminates quickly after process creation or is re-parented to ''init'' (PID 1), often indicating double-fork or daemon-style detachment. These behaviors sever the parent-child relationship and obscure the execution origin in process tree analysis.", "external_references": [{"external_id": "AN1223", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0443#AN1223"}], "id": "x-mitre-analytic--d4a29d94-bce4-4069-a0b5-9e0e731cff97", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1223", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "fork/clone/daemon syscall tracing", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"channel": "execve of re-parented process", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Maximum time between parent and child process creation and parent process termination", "field": "TimeWindow"}, {"description": "Scope for detecting unexpected re-parenting to init/systemd", "field": "ReparentingDetectionScope"}, {"description": "Subset of monitored executables or services likely to abuse double-fork", "field": "ExecutableScope"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3671', 0, 136, '09-mitre-attack', 'retrieved', '87EE464051BEF8D41BBD0468BF2F681953B9CA32558581F224B22DC121977E65', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
