VALUES ('doc-09-mitre-attack-p0-3673', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Malicious use of webserver plugins (e.g., for nginx, PHP, Node.js) that execute AppleScript or open network sockets.", "external_references": [{"external_id": "AN1509", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0547#AN1509"}], "id": "x-mitre-analytic--d5af4c93-632c-41c3-a101-6e9e534d7d01", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1509", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Script interpreter invoked by nginx/apache worker process", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Web server process initiating outbound TCP connections not tied to normal server traffic", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "If homebrew or manually compiled nginx/httpd used, baseline accordingly.", "field": "ParentBinaryPath"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3673', 0, 98, '09-mitre-attack', 'retrieved', '74B79BA903B62030FF0EAD66744A24F5FB0A9E91ADAE4370111AE8936C91D513', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
