VALUES ('doc-09-mitre-attack-p0-3674', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Abuse of bind mounts to obscure process directories. Defender perspective: detecting anomalous mount operations where a process’s /proc entry is remapped to another directory, often hiding malicious activity from native utilities (ps, top). Behavior chain includes: (1) execution of `mount` with `-o bind` or `-B` flags, (2) modification of /proc entries inconsistent with expected process lineage, and (3) subsequent anomalous activity from processes whose metadata no longer matches execution context.", "external_references": [{"external_id": "AN1196", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0428#AN1196"}], "id": "x-mitre-analytic--d5c81e57-37c4-4393-a202-0955af560983", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1196", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "mount system call with bind or remap flags", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"channel": "mount target path within /proc/*", "name": "auditd:PATH", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "process metadata mismatch between /proc and runtime attributes", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Flags or options used in mount commands (e.g., -o bind, -B). Can vary across distributions and kernels.", "field": "BindMountFlags"}, {"description": "List of /proc paths to monitor. Tunable to reduce noise from benign bind mounts used in containers or chroot environments.", "field": "WatchedProcPaths"}, {"description": "Timeframe to correlate bind mount creation with anomalous process or file activity.", "field": "CorrelationWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3674', 0, 203, '09-mitre-attack', 'retrieved', '2FDF704D07E5B04CEBD63F48FD6F49B35C015F37C002B864BAF72AD3EE73C20C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
