VALUES ('doc-09-mitre-attack-p0-3675', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary registers a Windows device to Entra ID or bypasses conditional access by adding device via Intune registration pipeline using stolen credentials.", "external_references": [{"external_id": "AN0104", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0036#AN0104"}], "id": "x-mitre-analytic--d5dc64ab-bb69-4893-a155-84d403040e1a", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0104", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Device Object Creation", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--18b236d8-7224-488f-9d2f-50076a0f653a"}, {"channel": "Enrollment events (e.g., MDMDeviceRegistration)", "name": "ApplicationLog:Intune/MDM Logs", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Adjust pattern matching logic for unusual or non-corporate device names", "field": "DeviceNamePattern"}, {"description": "Correlate with prior logon location or device usage behavior", "field": "UserContext"}, {"description": "Distinguish between MDM vs manual onboarding vs automated scripts", "field": "EnrollmentMethod"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3675', 0, 116, '09-mitre-attack', 'retrieved', '4E152E22A9C994222F474F2B5EC0FCD5DAFFDC2321D76DF959F106B2BE606451', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
