INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3677', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Abuse of cloud metadata APIs or CLI to push SSH public keys to authorized_keys of virtual machines.", "external_references": [{"external_id": "AN0352", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0126#AN0352"}], "id": "x-mitre-analytic--d613771b-087c-43c4-8430-2a0bf6ebb314", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0352", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "compute.instances.setMetadata", "name": "gcp:audit", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Custom metadata field (e.g., ssh-keys or custom-key)", "field": "MetadataFieldName"}, {"description": "Was it an admin, service principal, or automation user initiating?", "field": "AccountType"}, {"description": "Privilege level of the VM account receiving the key", "field": "TargetRoleEscalation"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3677', 0, 97, '09-mitre-attack', 'retrieved', 'E3C0DA4C7466E14E0484122AFD60553B3E559681D48FBE3EAB5DE3AD8FD83D03', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
