INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3678', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversaries attempt to read sensitive files such as /etc/passwd and /etc/shadow for credential dumping. This may involve access to the files directly via command-line utilities (e.g., cat, less), creation of backup copies, or parsing through post-exploitation frameworks. Multi-event correlation includes elevated process execution, file access/read on sensitive paths, and anomalous read behaviors tied to non-root or unusual users.", "external_references": [{"external_id": "AN1234", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0446#AN1234"}], "id": "x-mitre-analytic--d6166e3d-2e29-4097-9fb4-c66ce0616897", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1234", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open, read", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Executable name used to access credentials (e.g., cat, cp, awk); can vary across environments", "field": "exe"}, {"description": "User context under which the access occurs; typically root, but can be non-standard in attacks", "field": "user"}, {"description": "Target file paths (e.g., /etc/passwd, /etc/shadow); may vary in containerized or customized systems", "field": "PATH"}, {"description": "Time correlation threshold for chaining access and execution events", "field": "TimeWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3678', 0, 173, '09-mitre-attack', 'retrieved', '047C906F414449E05817A30F7AEA4E9298184C5E7AC9593A656411BB7C6BA0B9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
