INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3680', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use of cloud API calls (e.g., AWS EC2 DescribeInstances, Azure VM Inventory) to enumerate system configurations across assets.", "external_references": [{"external_id": "AN1456", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0525#AN1456"}], "id": "x-mitre-analytic--d664b158-5035-4e0b-a069-7a5b27ce0936", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1456", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "DescribeInstances, GetConsoleOutput, DescribeImages", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--2a80d95f-08c4-48e3-833e-151ef19d90f5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Limit detection to non-standard identities performing these calls.", "field": "IAMRoleContext"}, {"description": "Identify enumeration sweeps by volume.", "field": "APIFrequency"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3680', 0, 84, '09-mitre-attack', 'retrieved', 'AE7E20F8FF5F6298666038C7F51BDBE93230F1E3C209C970C6F8095F30A566F1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
