INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3681', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Direct execution of /bin/vmx or presence of rogue .vmx files not registered in vCenter inventory. Defender perspective: anomalous commands in shell history, edits to rc.local.d/local.sh for persistence.", "external_references": [{"external_id": "AN0912", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0321#AN0912"}], "id": "x-mitre-analytic--d677a72d-db0e-4332-a467-95b19836ef16", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0912", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Execution of ''/bin/vmx'' or modifications to ''/etc/rc.local.d/local.sh''", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "VMX startup messages without associated vCenter inventory records", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--b597a220-6510-4397-b0d8-342cd2c58827"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Cross-verify running VMs with vCenter inventory for rogue instances.", "field": "VMInventorySync"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3681', 0, 103, '09-mitre-attack', 'retrieved', '99349871DC393D37FD2770D4E5C2604ACEE7C1C22E3DC2F5FF7254CF623EAEEC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
