INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3682', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "A trusted/signed developer utility (parent) is executed in a non-developer context and (a) spawns suspicious children (e.g., powershell.exe, cmd.exe, rundll32.exe, regsvr32.exe, wscript.exe), (b) loads unsigned/user-writable DLLs, (c) writes and then runs a new PE from user-writable paths, and/or (d) immediately makes outbound network connections.", "external_references": [{"external_id": "AN0488", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0172#AN0488"}], "id": "x-mitre-analytic--d69c9d97-17d6-4dad-a4d4-ec41e7fb34fb", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0488", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "AppLocker audit/blocks showing developer utilities executing scripts/binaries outside policy", "name": "WinEventLog:AppLocker", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Correlation window between developer utility execution, payload write, and network egress (e.g., 0–30 minutes).", "field": "TimeWindow"}, {"description": "Org-specific list of dev utilities legitimately used on build/dev hosts to suppress noise.", "field": "AllowedUtilitiesList"}, {"description": "List of known developer/build systems where these tools are expected; raise severity off-host.", "field": "DeveloperHosts"}, {"description": "Child processes considered high-risk when spawned by dev utilities (powershell.exe, rundll32.exe, regsvr32.exe, cmd.exe, wscript.exe, mshta.exe).", "field": "SuspiciousChildList"}, {"description": "Regex of user-writable or atypical paths (e.g., %TEMP%, %APPDATA%, recycle bin, public profile) for payload drops.", "field": "RarePathRegex"}, {"description": "Toggle to alert only when child/payload is unsigned or signature invalid to reduce noise.", "field": "UnsignedOrInvalidSignatureOnly"}, {"description": "Known orchestrators (e.g., CI/CD agents) that often run these utilities legitimately.", "field": "ParentProcessAllowList"}, {"description": "Heuristic for rare/unknown destination (no DNS reputation, new domain, geo outside region).", "field": "NetworkReputationThreshold"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3682', 0, 254, '09-mitre-attack', 'retrieved', 'C16E5BF478AE6D7A1DA88692288842A46421BE6993EF55D93FE73345C3402656', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
