VALUES ('doc-09-mitre-attack-p0-3683', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Account creation via cloud service APIs or CLI, often associated with key generation. Monitored via CloudTrail or equivalent audit logs.", "external_references": [{"external_id": "AN1608", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0583#AN1608"}], "id": "x-mitre-analytic--d715d148-4d2d-407c-bd83-c471a4163d4e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1608", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "CreateUser", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--deb22295-7e37-4a3b-ac6f-c86666fbe63d"}, {"channel": "AttachUserPolicy", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Alert on account creation outside expected geographies", "field": "Region"}, {"description": "Filter on creation of users scoped to sensitive services", "field": "ServiceScope"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3683', 0, 93, '09-mitre-attack', 'retrieved', '55E3F24743BAE60E4DFD0C2738FD038DACE288F3F8F5CF7EE557E6A0BD5F85B2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
