VALUES ('doc-09-mitre-attack-p0-3684', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Chain: (1) SaaS admin API or PowerShell remote session reads tenant password/authentication settings (e.g., M365 Unified Audit Log ‘Cmdlet’ with `Get-MsolPasswordPolicy`/`Get-OrganizationConfig` parameters that expose password settings); (2) same session proceeds to mailbox or tenant changes.", "external_references": [{"external_id": "AN0460", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0161#AN0460"}], "id": "x-mitre-analytic--d71a1e3e-6507-438b-9ee2-f80dc1f938d2", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0460", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Workload=AzureActiveDirectory OR Exchange AND (Operation=Cmdlet AND Parameters contains ''Password'' AND (CmdletName=''Get-*'' OR CmdletName=''Get-OrganizationConfig''))", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Known admin groups or break-glass accounts.", "field": "SaaSAdminGroup"}, {"description": "Rate/volume of read operations per session considered anomalous.", "field": "SessionAnomalyThreshold"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3684', 0, 112, '09-mitre-attack', 'retrieved', '4DA9B57C8F267F3635CBF11771EF7F2ED284C097508C67924CEEA0FA478C7FC6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
