VALUES ('doc-09-mitre-attack-p0-3685', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects attempts to clear RDP/network history and modify network configuration artifacts through command execution, registry key deletion, firewall rule changes, and suspicious file deletions (e.g., Default.rdp, registry edits to Terminal Server Client keys).", "external_references": [{"external_id": "AN0133", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0049#AN0133"}], "id": "x-mitre-analytic--d71c4839-8d23-41f4-b59a-8bd2c3517d1e", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0133", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4663, 4670, 4656", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Command Line Telemetry", "name": "EDR:cli", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "Firewall Rule Modification", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--d2ff4b56-8351-4ed8-b0fb-d8605366005f"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Filter file/registry paths like *\\Terminal Server Client\\* or *Default.rdp*", "field": "TargetPathRegex"}, {"description": "Correlate command/registry edits within close proximity to suspicious connection activity", "field": "TimeWindow"}, {"description": "Detect cleanup behavior from non-interactive or SYSTEM accounts", "field": "UserContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3685', 0, 138, '09-mitre-attack', 'retrieved', '01C0A8088A795141ACF9260EC3767F8DD96A7A05B30579E3ED17A2B3948A863A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
