VALUES ('doc-09-mitre-attack-p0-3686', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects unexpected encrypted egress traffic from management services (e.g., hostd) or guest VMs utilizing symmetric encryption without traditional protocols (e.g., FTP with embedded AES ciphertext).", "external_references": [{"external_id": "AN1392", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0503#AN1392"}], "id": "x-mitre-analytic--d73a1356-7f4f-4f54-afca-437736e5f53c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1392", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "egress log analysis", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "execution + payload hints", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "host switch egress data", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "VMs with data sensitivity labels or outside normal behavior.", "field": "GuestVMExfilWatchlist"}, {"description": "Expected egress destinations and volume for core services.", "field": "ServiceEgressProfile"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3686', 0, 113, '09-mitre-attack', 'retrieved', 'B7C2A590BCBDA6E299F01C1E9982C3812D984F6884951D2DD8F6AB517D3B1836', 'v1', '{"source_id": "09-