VALUES ('doc-09-mitre-attack-p0-3688', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects usage of commands or binaries (e.g., netstat, PowerShell Get-NetTCPConnection) and WMI or API calls to enumerate local or remote network connections.", "external_references": [{"external_id": "AN0903", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0320#AN0903"}], "id": "x-mitre-analytic--d78b4bb3-bd0a-4e43-bc19-0a7b72f6a9d3", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0903", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Non-standard binaries launching PowerShell or netstat (e.g., winword.exe spawning powershell.exe).", "field": "SuspiciousParentProcesses"}, {"description": "Correlates discovery behavior before lateral movement or credential access.", "field": "TimeWindow"}, {"description": "Regex or keyword patterns to match discovery utilities (e.g., `netstat`, `Get-NetTCPConnection`).", "field": "CommandPatternList"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3688', 0, 115, '09-mitre-attack', 'retrieved', '609ADAD1DAE10F8414171A4EEE6CF4FF8A3DE441BC503C9351863A104F5BD8CC', 'v1