VALUES ('doc-09-mitre-attack-p0-3689', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Abuse of safe mode via BCD modification, boot configuration utilities (bcdedit.exe, bootcfg.exe), and registry persistence under SafeBoot keys. Defender view: suspicious boot configuration changes correlated with registry edits that enable adversary persistence or disable defenses.", "external_references": [{"external_id": "AN0323", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0116#AN0323"}], "id": "x-mitre-analytic--d7a82fc6-047b-47a8-8b3c-d6dcab00d56b", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0323", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=13, 14", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "EventCode=12", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--7f70fae7-a68d-4730-a83a-f260b9606129"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Customize monitored registry paths for safe mode service additions.", "field": "SafeBootRegistryPaths"}, {"description": "Whitelist legitimate administrative use of bcdedit/bootcfg for troubleshooting.", "field": "AllowedAdminTools"}, {"description": "Correlate registry modifications and boot configuration commands within a short timeframe.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3689', 0, 130, '09-mitre-attack', 'retrieved', 'CC2BF92A9CF93CAAA74290C7B28B4B80A5917FDBED6DBDDF8EE7BD7571188BCD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
