VALUES ('doc-09-mitre-attack-p0-3690', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Access to user private key directories (e.g., /Users/*/.ssh) via Terminal, scripting engines, or non-default processes.", "external_references": [{"external_id": "AN1518", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0549#AN1518"}], "id": "x-mitre-analytic--d7a9c7c8-81a0-4988-9617-51f191ab32c8", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1518", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open/read access to private key files (id_rsa, *.pem, *.p12)", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "launch of bash/zsh/python/osascript targeting key file locations", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Processes reading key files (osascript, python, bash, etc.)", "field": "ProcessName"}, {"description": "Private key and certificate paths like /Users/*/.ssh, /Library/Keychains/", "field": "FileAccessPath"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3690', 0, 102, '09-mitre-attack', 'retrieved', 'DDECA3A4DACCDC187C88C5B19F0139ACE49DE154AC5C33E7462AB7150A1F573A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
