VALUES ('doc-09-mitre-attack-p0-3691', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unexpected apps or scripts (osascript, curl, Automator workflows) exfiltrating data via webhooks. Defender perspective: correlation of clipboard/file read operations followed by HTTPS POST traffic to webhook services.", "external_references": [{"external_id": "AN0438", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0153#AN0438"}], "id": "x-mitre-analytic--d7f9b07f-401c-4685-a014-6a824f95f866", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0438", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execution of osascript, curl, or unexpected automation", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "file read of sensitive directories", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "HTTPS POST to known webhook URLs", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Webhook URLs monitored for exfiltration.", "field": "WebhookEndpoints"}, {"description": "High entropy payloads may indicate encoded/encrypted exfiltration.", "field": "EntropyThreshold"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3691', 0, 117, '09-mitre-attack', 'retrieved', '5FC5E265600B11BEC83197B