VALUES ('doc-09-mitre-attack-p0-3693', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Account enumeration via bulk access to user directory features or hidden APIs.", "external_references": [{"external_id": "AN1618", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0587#AN1618"}], "id": "x-mitre-analytic--d85db7b4-5eb1-4781-b92c-a18102a568dc", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1618", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Directory API Access", "name": "gcp:audit", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune based on enumeration from directory endpoints such as /users, /groups.", "field": "EndpointURL"}, {"description": "Detect scripted enumeration via curl/wget or unknown tools.", "field": "UserAgent"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3693', 0, 84, '09-mitre-attack', 'retrieved', 'A0D8E6BF2293C0E6F0E4D115FC268F47E3FEC95B6BC50183BACEFFC50A725A4D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
