VALUES ('doc-09-mitre-attack-p0-3696', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detect execution of `/usr/libexec/security_authtrampoline` or use of AuthorizationExecuteWithPrivileges API, and monitor process lineage for unusual launches of GUI apps with escalated privileges.", "external_references": [{"external_id": "AN0977", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0345#AN0977"}], "id": "x-mitre-analytic--d8b422b3-50e7-48cc-bfa1-a6e0cecf5761", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0977", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "authorization execute privilege requests", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"channel": "execve with escalated privileges", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"channel": "binary execution of security_authtrampoline", "name": "fs:fsusage", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Specify binaries frequently targeted for privilege escalation", "field": "WatchedBinaries"}, {"description": "Which applications should never be allowed to spawn elevated processes", "field": "ExecutionParent"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3696', 0, 111, '09-mitre-attack', 'retrieved', '2EF6617B0F558BB56AEF915D816A7FC385B3E0D879C724200DCA36EEDF35426F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
