VALUES ('doc-09-mitre-attack-p0-3699', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects macros or VBA triggers set to execute on document open or close events, often correlating with embedded payloads or C2 traffic shortly after execution.", "external_references": [{"external_id": "AN0029", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0010#AN0029"}], "id": "x-mitre-analytic--d8e18081-2670-4a88-9246-59a1dc52c51c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0029", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "VBA auto_open, auto_close, or document_open events", "name": "m365:office", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}, {"channel": "External HTTP/DNS connection from Office binary shortly after macro trigger", "name": "m365:office", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Names of event-bound functions like Auto_Open that initiate execution", "field": "MacroFunctionNames"}, {"description": "Time threshold to correlate macro execution with outbound connections", "field": "TimeDeltaMacroToC2"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3699', 0, 115, '09-mitre-attack', 'retrieved', '3BFC467B0F47823665D5D95CA54BDEC5FB8A5AF2548D57E4C314E90CFAD08710', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
