VALUES ('doc-09-mitre-attack-p0-3700', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Installation of configuration profiles or plist entries associated with malicious or unauthorized browser extensions", "external_references": [{"external_id": "AN0252", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0092#AN0252"}], "id": "x-mitre-analytic--d8f9ab20-4c82-42fc-9316-91781fa9e5e1", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0252", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Execution of ''profiles install -type=configuration''", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "Creation of .plist under /Library/Managed Preferences/", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "Suspicious outbound traffic from browser binary to non-standard domains", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Directory path for user-specific extension configuration files", "field": "PlistPath"}, {"description": "Usage of profiles CLI tool—can be modified by legitimate tools or MDMs", "field": "CommandLine"}, {"description": "Correlation window between configuration install and observable extension behavior", "field": "TimeWindow"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3700', 0, 125, '09-mitre-attack', 'retrieved', '9B091706E08F0E0663CE9646182FB5F5DB5C482FFF1D8D6F73514E78DB7BAE73', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
