VALUES ('doc-09-mitre-attack-p0-3701', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Sequence of RAT agent execution, systemd persistence, and long-lived external egress; optional interactive shells spawned from the agent.", "external_references": [{"external_id": "AN1367", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0496#AN1367"}], "id": "x-mitre-analytic--d90a4f16-b5e1-4daa-bf65-91112fe02761", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1367", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve: Agent/headless flags (listen/connect/reverse/tunnel) or remote-control binaries spawning shells", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "WRITE: Drop of binaries/scripts in ~/.local, /tmp, or /opt tool dirs", "name": "auditd:PATH", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Bind exec→service→egress events; extend for staged deployments.", "field": "TimeWindow"}, {"description": "Approved .service names/paths to avoid flagging corporate agents.", "field": "DaemonAllowlist"}, {"description": "Define shells/interpreters considered anomalous when spawned by GUI/agent parents.", "field": "SuspiciousChildProcesses"}, {"description": "Flow heuristics for long-lived, client-heavy connections post-install.", "field": "EgressHeuristics"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3701', 0, 137, '09-mitre-attack', 'retrieved', '2BF4A053263EC662DB82B910862FF3CF415ED69FC3ED3412DD5CF606BFA73E7C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
