VALUES ('doc-09-mitre-attack-p0-3702', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Chain: (1) privileged CLI sessions run read-only commands that dump AAA/password policies (e.g., `show aaa`, `show password-policy`); (2) same account changes AAA or user DB shortly after. Use network device AAA/command accounting or syslog.", "external_references": [{"external_id": "AN0461", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0161#AN0461"}], "id": "x-mitre-analytic--d93312e3-210a-4757-b638-4ed19fca8621", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0461", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "cmd=''show aaa*'' OR ''show running-config | include password|aaa'' OR ''show aaa common-criteria policy all''", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Jump hosts permitted to run show commands.", "field": "ApprovedNOCSources"}, {"description": "Higher risk weight on edge/critical devices.", "field": "DeviceTier"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3702', 0, 112, '09-mitre-attack', 'retrieved', 'ABDCCF249D3243930B9A4D12053E75E31450C74DD54AD793CBA3F3EC38B3F634', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
