VALUES ('doc-09-mitre-attack-p0-3703', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects anomalous use of Dynamic Data Exchange (DDE) for code execution, such as Office applications (WINWORD.EXE, EXCEL.EXE) spawning command interpreters, or loading unusual modules through DDEAUTO/DDE formulas. Correlates suspicious parent-child process relationships, registry keys enabling DDE, and module loads inconsistent with normal Office usage.", "external_references": [{"external_id": "AN1393", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0504#AN1393"}], "id": "x-mitre-analytic--d9383849-c91c-4eef-88a0-97c2454ca1af", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1393", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "EventCode=4663, 4670, 4656", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--ed0dd8aa-1677-4551-bb7d-8da767617e1b"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Define legitimate parent-child relationships for Office processes to reduce false positives.", "field": "AllowedParentChildPairs"}, {"description": "Threshold for correlating Office process creation with subsequent command execution via DDE.", "field": "TimeWindow"}, {"description": "Maintain allow/block list of DLLs that Office is expected to load.", "field": "SuspiciousDLLList"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3703', 0, 146, '09-mitre-attack', 'retrieved', '7B9582DBDFCEC87CB1A1DCF3178242B5CB697B4BA13CEC0B3B5339CAE532A9DE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
