VALUES ('doc-09-mitre-attack-p0-3704', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of destructive CLI commands such as format flash:, format disk, or equivalent vendor-specific commands that erase filesystem structures. Detection correlates AAA logs showing privileged access with immediate format/erase commands.", "external_references": [{"external_id": "AN0830", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0297#AN0830"}], "id": "x-mitre-analytic--d970c6c7-82d0-4977-9e2e-4b27af383ca5", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0830", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "format flash:, format disk, reformat commands", "name": "networkdevice:cli", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "Privileged login followed by destructive format command", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Expand detection to cover vendor-specific destructive commands.", "field": "CommandPatterns"}, {"description": "Whitelist authorized maintenance sessions to reduce false positives.", "field": "PrivilegedUsers"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3704', 0, 114, '09-mitre-attack', 'retrieved', 'EF7628CE2BE5EFDAA6431AFC5DC6DF2F67064B61809A843692C339D53CB55288', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
