VALUES ('doc-09-mitre-attack-p0-3705', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Spike in object access from new IAM user or role followed by data exfiltration to external IPs", "external_references": [{"external_id": "AN1328", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0484#AN1328"}], "id": "x-mitre-analytic--d9a1ace1-6307-4db7-925f-67057361e66a", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1328", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "GetObject, CopyObject", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--58ef998c-f3bf-4985-b487-b1005f5c05d1"}, {"channel": "AssumeRole", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}, {"channel": "Unusual volume of data transferred from S3 storage endpoints to non-corporate IPs", "name": "AWS:VPCFlowLogs", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Timeframe for data transfer correlation (e.g., 10 minutes)", "field": "TimeWindow"}, {"description": "Known list of corporate and expected outbound IP addresses", "field": "ExternalIPAllowList"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3705', 0, 109, '09-mitre-attack', 'retrieved', '00AD91220AE4F080A5527D5A1E899041D75D44AFC28A44DD7F1CB912C2DF199D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
