INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3706', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects ptrace-based process injection by correlating audit logs of ptrace syscalls, memory modifications (e.g., poketext, pokedata), and suspicious register manipulation on a target process not normally debugged by the originator. Alerts on processes attempting to ptrace non-child or privileged processes, especially those followed by abnormal memory or execution behavior.", "external_references": [{"external_id": "AN0579", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0203#AN0579"}], "id": "x-mitre-analytic--d9bcfaee-d2d1-4673-b834-5c219f8dba9b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0579", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "mmap, ptrace, process_vm_writev or direct memory ops", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "state=attached/debugged", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of sensitive or rarely-debugged processes (e.g., sshd, systemd, container daemons) to alert on if ptraced", "field": "TargetProcessNameFilter"}, {"description": "Threshold time (e.g., <10 seconds) between ptrace attach and pokedata syscall", "field": "TimeWindowBetweenPtraceAndMemoryWrite"}, {"description": "Flag when UID of tracer differs from UID of target process (e.g., privilege escalation or container breakout)", "field": "UserContextMismatch"}, {"description": "Allowlist relationships (e.g., parent-child) under which ptrace is considered benign", "field": "ProcessRelationshipConstraint"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3706', 0, 178, '09-mitre-attack', 'retrieved', '3653153746D52C9C407FAA8F11F661FC75C99EC12BFEDD48D41B6ABA58DAAE25', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
