INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3707', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects unauthorized modifications to PAM configuration files or shared object modules. Correlates file modification events under /etc/pam.d/ or /lib/security/ with unusual authentication activity such as multiple simultaneous logins, off-hours logins, or logons without corresponding physical/VPN access.", "external_references": [{"external_id": "AN1250", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0454#AN1250"}], "id": "x-mitre-analytic--d9c7e50d-4b13-4634-80f9-e8032a043414", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1250", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open, write", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "simultaneous or anomalous logon sessions across multiple systems", "name": "NSM:Connections", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of PAM configuration and module directories monitored (e.g., /etc/pam.d/, /lib/security/).", "field": "MonitoredPaths"}, {"description": "Timeframe for correlating suspicious file modifications with anomalous login events.", "field": "TimeWindow"}, {"description": "Expected login frequency and systems per user account; deviations may indicate compromise.", "field": "BaselineAccounts"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3707', 0, 143, '09-mitre-attack', 'retrieved', '8A382EDBA0F643712963899DCE979998E0CD1A37CE11AA758F9F8B8D95858216', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
