INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3708', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of fake or spoofed macOS Security & Privacy GUIs showing healthy status after XProtect, Gatekeeper, or AV processes are disabled. Correlates user-space UI process creation with terminated or missing security daemons.", "external_references": [{"external_id": "AN0870", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0311#AN0870"}], "id": "x-mitre-analytic--d9eb3056-115b-496a-89f7-be38470ff022", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0870", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Execution of processes mimicking Apple Security & Privacy GUIs", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Termination or disabling of XProtect, Gatekeeper, or third-party AV daemons", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Monitored list of macOS security daemons such as XProtect, Gatekeeper, or third-party AV.", "field": "TrustedDaemonList"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3708', 0, 116, '09-mitre-attack', 'retrieved', '7BE107257C4944B306806A87C924B88136EE8D17872EF2C9AFF3C51CB80B5038', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
