INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3709', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detect loading or inspection of kernel extensions (kextstat, kextfind) and file access to /System/Library/Extensions/. Monitor unexpected usage of these utilities by non-administrative users or scripts.", "external_references": [{"external_id": "AN1597", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0579#AN1597"}], "id": "x-mitre-analytic--d9ee822c-6a91-4c83-9698-779ca0bf8663", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1597", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "exec: Execution of kextstat, kextfind, or ioreg targeting driver information", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "read: File access to /System/Library/Extensions/ or related kernel extension paths", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune detection by excluding expected system diagnostic or patch-related invocations of kext utilities.", "field": "AllowedMaintenanceTasks"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3709', 0, 110, '09-mitre-attack', 'retrieved', '1E53DCD2F519A6E05630193585CAB01244F2216032108DD29D2C7FBD2F3662C6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
