VALUES ('doc-09-mitre-attack-p0-3711', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects unauthorized TCC access or use of Quartz Event Services (CGEventTapCreate) or IOHID for event tap installation within unexpected processes.", "external_references": [{"external_id": "AN0245", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0089#AN0245"}], "id": "x-mitre-analytic--da140e65-e30c-4cf2-8961-82fb200a7f0b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0245", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "subsystem=com.apple.TCC", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"channel": "process_events OR launchd", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "com.apple.inputmonitoring, com.apple.accessibility, etc.", "field": "Service"}, {"description": "Tunable to exclude trusted endpoint monitoring tools", "field": "ExecutablePath"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3711', 0, 89, '09-mitre-attack', 'retrieved', '68DA3E649E546EBC4E38D6E86233A83E69C59B4ACB2E5FBFD5788F5139975F45', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
