VALUES ('doc-09-mitre-attack-p0-3712', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use of OAuth tokens by third-party apps to access user mail, calendar, or SharePoint resources where the token was granted recently or via spearphishing.", "external_references": [{"external_id": "AN1426", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0515#AN1426"}], "id": "x-mitre-analytic--da365d5b-c955-46f6-99c2-cd57a3560a57", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1426", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "App-only or delegated access patterns where client_id != known enterprise apps", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--58ef998c-f3bf-4985-b487-b1005f5c05d1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defenders may allow known app IDs, flag unknowns", "field": "ClientAppIDAllowList"}, {"description": "Rate of resource access by a newly consented app", "field": "AccessVolumeThreshold"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3712', 0, 103, '09-mitre-attack', 'retrieved', 'C81FE6D02107D5688D3E9EF97BC1B96CC9990FA6252B5C05355B2CEB76172AAB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
