VALUES ('doc-09-mitre-attack-p0-3713', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor system APIs such as CFNetwork and SecureTransport for anomalies in transmitted data streams. Detect mismatches in file hashes or SSL/TLS downgrade attempts that enable manipulation of transmitted data.", "external_references": [{"external_id": "AN0704", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0254#AN0704"}], "id": "x-mitre-analytic--da6d7de2-a666-4fa3-aa53-54692a8167ae", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0704", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Suspicious anomalies in transmitted data integrity during application network operations", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "CALCULATE: Integrity validation of transmitted data via hash checks", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Custom rules for enforcing HTTPS/TLS integrity checks to prevent downgrade manipulation.", "field": "TLSValidationRules"}, {"description": "Whitelisted macOS apps permitted to transmit critical data.", "field": "AllowedApps"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3713', 0, 122, '09-mitre-attack', 'retrieved', '5E112DE10A23C20C576A9D1C92029E56D26B84A3A680DE8B549518B0DCAB4392', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
