VALUES ('doc-09-mitre-attack-p0-3714', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Suspicious calls to dlopen(), dlsym(), or mmap with RWX flags in processes that do not typically perform dynamic module loading. Monitor anonymous memory regions executed by user processes.", "external_references": [{"external_id": "AN0840", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0300#AN0840"}], "id": "x-mitre-analytic--da7cf744-fc04-4b17-8a96-3140a4b349d6", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0840", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve or dylib load from memory without backing file", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "suspicious dlopen/dlsym usage in non-development processes", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Developer tools may legitimately call dlopen/dlsym; narrow scope to production workloads.", "field": "ApplicationScope"}, {"description": "Correlate suspicious loads with subsequent process activity in a defined window.", "field": "ExecutionTimeWindow"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3714', 0, 120, '09-mitre-attack', 'retrieved', '18D7D0D4BFECDB19814D52AF4E18901F59CE7910AFCCC10C3DB7678A8F2AF6E3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
