VALUES ('doc-09-mitre-attack-p0-3715', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unexpected modification of the KernelCallbackTable in a process’s PEB followed by invocation of modified callback functions (e.g., fnCOPYDATA) through Windows messages. Defender observes suspicious API call chains such as NtQueryInformationProcess → WriteProcessMemory → abnormal GUI callback execution, often correlating to anomalous process behavior such as network activity or code injection.", "external_references": [{"external_id": "AN1593", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0577#AN1593"}], "id": "x-mitre-analytic--da853af7-f2e4-45c2-b78f-3d960fff638e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1593", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "WriteProcessMemory: WriteProcessMemory targeting regions containing KernelCallbackTable addresses", "name": "etw:Microsoft-Windows-Kernel-Process", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "GUI applications (e.g., explorer.exe, notepad.exe) where KernelCallbackTable abuse is more likely.", "field": "MonitoredProcesses"}, {"description": "Specific callback functions (e.g., fnCOPYDATA, fnDWORD) expected to remain stable.", "field": "CallbackFunctions"}, {"description": "Correlation interval between WriteProcessMemory calls and execution of modified callback functions.", "field": "TimeWindow"}, {"description": "Access rights values that should be flagged when targeting GUI processes.", "field": "AccessMaskThresholds"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3715', 0, 168, '09-mitre-attack', 'retrieved', '87B4FF2B1E1C186AFF284896BB333603EAD9F6E53FFF19D8D7051150D2617120', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
