VALUES ('doc-09-mitre-attack-p0-3717', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "A non-whitelisted process receives TCC camera entitlement (kTCCServiceCamera), opens AppleCamera/AVFoundation device handles, writes .mov/.mp4 artifacts to unusual locations, and/or beacons/exfiltrates soon after.", "external_references": [{"external_id": "AN0570", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0197#AN0570"}], "id": "x-mitre-analytic--db3263c7-0abc-47be-a9f3-434d255b1e0e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0570", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Access decisions to kTCCServiceCamera for unexpected binaries", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"channel": "open: Process opens AppleCamera/IOUSB device nodes or AVFoundation frameworks", "name": "macos:endpointsecurity", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "exec: Exec of ffmpeg, avfoundation-based binaries, or custom signed apps accessing camera", "name": "macos:endpointsecurity", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Process wrote large .mov/.mp4 in user temp/hidden dirs", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Legitimate apps (Zoom, Teams, FaceTime) that are permitted to camera.", "field": "TCCAllowList"}, {"description": "Mov/mp4/mkv/yuv etc., tuned to environment workloads.", "field": "VideoExtensions"}, {"description": "Correlation between TCC grant → file write → network egress.", "field": "TimeWindow"}, {"description": "Reduce FP from thumbnails/snapshots.", "field": "MinFileSizeMB"}, {"description": "Allowed persistence paths to reduce false positives when correlating with persistence.", "field": "LaunchAgentPaths"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3717', 0, 173, '09-mitre-attack', 'retrieved', 'D5C2AFC605199F46CEE9BC7440CA1510B6F79BBDFC66139DD90A15B7E4073A00', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
