VALUES ('doc-09-mitre-attack-p0-3719', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "High volume of failed logon attempts followed by a successful one from a suspicious user, host, or timeframe", "external_references": [{"external_id": "AN1275", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0463#AN1275"}], "id": "x-mitre-analytic--db50537c-9234-4350-9bf0-838d4cffbd34", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1275", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4776, 4625", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Adjustable window to correlate failed logons, e.g., 5-10 minutes", "field": "TimeWindow"}, {"description": "Define scope of monitored users (e.g., service accounts, admins)", "field": "UserContext"}, {"description": "Count of failed logons before raising an alert (e.g., 10-15)", "field": "FailureThreshold"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3719', 0, 101, '09-mitre-attack', 'retrieved', '96399BC378A639B71EEB226F1BD16DC892791B208D59A5FC8F69F6CA815D20F1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
