VALUES ('doc-09-mitre-attack-p0-3721', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of spearphishing attachments by correlating suspicious email delivery with subsequent file creation and abnormal process execution (e.g., Office spawning PowerShell or CMD). Behavior chain includes inbound email metadata → attachment stored on disk → process execution → outbound network activity.", "external_references": [{"external_id": "AN0655", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0236#AN0655"}], "id": "x-mitre-analytic--db6995d9-68ab-4638-a430-c0a8d2daf306", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0655", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Send/Receive: Inbound emails with attachments from suspicious or spoofed senders", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of high-risk extensions to monitor (e.g., .exe, .js, .vbs, .docm, .xlsm).", "field": "AttachmentExtensions"}, {"description": "Process lineage patterns considered malicious (e.g., winword.exe → powershell.exe).", "field": "SuspiciousParentChildPairs"}, {"description": "Correlation window between email receipt, file creation, and process execution.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3721', 0, 154, '09-mitre-attack', 'retrieved', 'E57BAD1C2E30D0FF7E3825F5BA32034A22FD770BD2432A47B6EBBBA9194C416A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
