VALUES ('doc-09-mitre-attack-p0-3722', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of shell scripts, ELF binaries, or archives containing embedded secondary payloads, self-extracting components, or unusual compression behavior during runtime.", "external_references": [{"external_id": "AN0600", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0214#AN0600"}], "id": "x-mitre-analytic--db9b55b0-7e54-4625-92d5-fbe9ed8ac868", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0600", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open, write", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "elf_info, hash, yara_matches", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"channel": "container_file_activity", "name": "ebpf:syscalls", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tuning value for ELF binaries with appended sections or resources", "field": "FileSectionCount"}, {"description": "Threshold for long shell scripts with base64-encoded binary content", "field": "ScriptLength"}, {"description": "Number of files written from a single script execution", "field": "ExtractedFileCount"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3722', 0, 117, '09-mitre-attack', 'retrieved', '8BD1A48D8