VALUES ('doc-09-mitre-attack-p0-3723', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unusual daemons or user processes binding/listening on ports outside of standard ranges, or initiating client connections using mismatched protocol/port pairings.", "external_references": [{"external_id": "AN0634", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0227#AN0634"}], "id": "x-mitre-analytic--dba32c3a-1ae7-46a4-9b04-d011f37aa801", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0634", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "socket/connect syscalls", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "processes binding to non-standard ports or sshd configured on unexpected port", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "process listening or connecting on non-standard ports", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Exclude ports intentionally configured for enterprise apps.", "field": "AllowedServices"}, {"description": "Define thresholds for anomalous payload entropy to catch tunneled traffic.", "field": "PayloadEntropyThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3723', 0, 117, '09-mitre-attack', 'retrieved', '7D3D828A3040C93CABE72C1BD665C10B7179189ADA400796415A5C1B23256EF9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
