VALUES ('doc-09-mitre-attack-p0-3726', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of containerized service accounts or compromised kubeconfigs being used for cluster access from unexpected nodes or IPs.", "external_references": [{"external_id": "AN1547", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0560#AN1547"}], "id": "x-mitre-analytic--dc062a09-572e-41fc-bfff-f654751a6a0f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1547", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "authentication.k8s.io", "name": "kubernetes:audit", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Validate access from expected namespaces only.", "field": "ServiceAccountScope"}, {"description": "Permit kubeconfig usage from a limited set of IPs.", "field": "ClusterIPWhitelist"}], "x_mitre_platforms": ["Containers"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3726', 0, 84, '09-mitre-attack', 'retrieved', '9FAA152BBF45E0CDE5D9286FFB2952CD0F56D6F267179EC61084CC763FDB764B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
