VALUES ('doc-09-mitre-attack-p0-3727', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Abuse of trusted Electron apps (Teams, Slack, Chrome) to spawn child processes or execute payloads via malicious command-line arguments (e.g., --gpu-launcher) and modified app resources (.asar). Behavior chain: suspicious parent process (Electron app) → unusual command-line args → child process creation → optional DLL/network artifacts.", "external_references": [{"external_id": "AN0071", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0025#AN0071"}], "id": "x-mitre-analytic--dc0bf4ca-1d65-46ee-b4b1-d8f73a6e0cda", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0071", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Correlation window tying app launch, file tampering, child process, and network events (5–10 minutes typical).", "field": "TimeWindow"}, {"description": "Flag admin/service accounts versus standard users executing Electron apps.", "field": "UserContext"}, {"description": "Baseline of Electron-based executables expected in the enterprise.", "field": "AllowedElectronApps"}, {"description": "Whitelist normal child processes (chrome.exe → crashpad_handler.exe) versus anomalies (powershell.exe).", "field": "AllowedChildProcesses"}, {"description": "Approved service domains for Teams, Slack, etc. to suppress benign traffic.", "field": "ElectronAppDomainAllowlist"}, {"description": "Expected hash/signature of app.asar resources to detect tampering.", "field": "AsarIntegrityHash"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3727', 0, 188, '09-mitre-attack', 'retrieved', 'BB54612ED2F939D92CFBB4C0B732D9E8422DBC8A771E2969E665D0748FAF4D4A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
