VALUES ('doc-09-mitre-attack-p0-3728', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of a process or script that accesses a common web service to retrieve content containing obfuscated indicators of a secondary C2 server (dead drop resolver behavior).", "external_references": [{"external_id": "AN0159", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0058#AN0159"}], "id": "x-mitre-analytic--dc4096a9-b89d-4bef-b20d-58cf5e87f6bf", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0159", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "connect", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "HTTP/TLS Logs", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Dead drop hosting domain (e.g., GitHub, Google Docs)", "field": "TargetDomain"}, {"description": "Detects high entropy in payloads signaling obfuscation", "field": "PayloadEntropyThreshold"}, {"description": "Causal proximity between access to resolver and follow-up connections", "field": "TimeWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3728', 0, 112, '09-mitre-attack', 'retrieved', 'AB93042F083C6F13D8672791FAF8DBDC0D4012923DFE34FE6C324009DE077890', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
