VALUES ('doc-09-mitre-attack-p0-3729', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects anomalous ARP traffic or cache modifications on Windows endpoints that indicate ARP poisoning. Behavioral focus is on multiple IP addresses resolving to a single MAC, or unsolicited ARP replies from unauthorized devices.", "external_references": [{"external_id": "AN1091", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0387#AN1091"}], "id": "x-mitre-analytic--dc4a80e3-7670-474f-aaf6-c051d5dda83c", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1091", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "ARP cache modification attempts observed through event tracing or security baselines", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Expected MAC address for default gateways; deviations may indicate poisoning.", "field": "TrustedGatewayMAC"}, {"description": "Correlation interval for repeated unsolicited ARP replies.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3729', 0, 118, '09-mitre-attack', 'retrieved', '68D6524FB7AB4368230594F9E9D3CBE1527B4A2879243C2333E61D8DA84BA843', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
