VALUES ('doc-09-mitre-attack-p0-3730', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Abuse of ClickOnce applications where rundll32.exe invokes dfshim.dll with ShOpenVerbApplication or dfsvc.exe spawns unexpected child processes or loads unsigned modules.", "external_references": [{"external_id": "AN0550", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0191#AN0550"}], "id": "x-mitre-analytic--dc4d944f-975a-4057-8edb-deb023db387c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0550", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "ETW telemetry indicating ClickOnce deployment (dfsvc.exe) launching payloads", "name": "WinEventLog:Microsoft-Windows-Security-Mitigations/KernelMode", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "The correlation window for dfsvc.exe/rundll32.exe execution and subsequent module loads or child processes (e.g., 0–10 minutes).", "field": "TimeWindow"}, {"description": "Whitelist of legitimate ClickOnce applications and paths.", "field": "KnownClickOnceApps"}, {"description": "Child processes considered abnormal when launched by dfsvc.exe or rundll32.exe.", "field": "SuspiciousChildList"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3730', 0, 126, '09-mitre-attack', 'retrieved', '8A6E1369F9F9B4D3D9C60601F9F05BF3B85DFBE435FAE57226A73F405950C491', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
