VALUES ('doc-09-mitre-attack-p0-3732', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of commands disabling AAA, logging, or security features on routers/switches. Detect privilege escalation followed by config changes that disable defense mechanisms.", "external_references": [{"external_id": "AN0893", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0317#AN0893"}], "id": "x-mitre-analytic--dc5bfda5-057d-4bec-b3e6-a6b2117a4134", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0893", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "no logging buffered, no aaa new-model, disable firewall", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Customize destructive command list per vendor platform.", "field": "CommandPatterns"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3732', 0, 85, '09-mitre-attack', 'retrieved', 'DDA9931AE995F569B2B3A8F91439D182A5B453D7487E52CB25E774045F2A078E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
