VALUES ('doc-09-mitre-attack-p0-3733', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Flags unexpected user applications initiating long-lived HTTP(S) sessions with irregular traffic patterns.", "external_references": [{"external_id": "AN0146", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0053#AN0146"}], "id": "x-mitre-analytic--dc87f086-1764-43c2-a7bf-1a5ba2ea8191", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0146", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "network flow", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "process", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Session length that exceeds average per-user expectations", "field": "SessionDuration"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3733', 0, 74, '09-mitre-attack', 'retrieved', 'D1DC6A81592CB622DAE8F79D416F0FB3001E522BBF6041F79743595EC0AF27E0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
