VALUES ('doc-09-mitre-attack-p0-3734', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Shell scripts or binaries invoking repeated ''sleep'', ''ping'', or low-level syscalls (e.g., nanosleep) in short-lived execution chains with no user or system interaction. Frequently seen in malicious cron jobs or payload stagers.", "external_references": [{"external_id": "AN1049", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0372#AN1049"}], "id": "x-mitre-analytic--dcc422d4-90fc-4e2a-afd5-b4fbc3d6c4a1", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1049", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve or nanosleep with no stdout/stderr I/O", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "scripting loop invoking sleep/ping", "name": "auditd:PROCTITLE", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Environment-specific delay scripts may vary (sleep 300, ping -n 60, etc.).", "field": "CommandLineRegex"}, {"description": "Threshold for determining if delay is artificially extended.", "field": "TimeBetweenSyscalls"}, {"description": "Root vs. service user context alters risk profile.", "field": "UserContext"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3734', 0, 128, '09-mitre-attack', 'retrieved', '3A5C3E6AEB4E699D3EBF0DB8DAB57098348DA8802BC136319151833B16FCF62E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
