INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3737', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use of curl, wget, or custom scripts to POST data to pastebin-like services. Defender perspective: identify chained behavior where files are compressed/read followed by HTTPS POST requests to text-sharing endpoints.", "external_references": [{"external_id": "AN0788", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0284#AN0788"}], "id": "x-mitre-analytic--dd202a3f-c73b-47cf-9689-f14a8def816e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0788", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "curl -d, wget --post-data", "name": "auditd:EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "read/open of sensitive file directories", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "large HTTPS POST requests to text storage domains", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Whitelist of tools (e.g., curl for package repos) to reduce false positives.", "field": "AllowedTools"}, {"description": "Expected time ranges for developer interactions with external paste sites.", "field": "WorkHours"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3737', 0, 129, '09-mitre-attack', 'retrieved', 'A2A6B6A0C59D2B5475EC623C80B1090BF2C49D270D1CD43DF8906DB110B47C7A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
