VALUES ('doc-09-mitre-attack-p0-3738', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitors for abnormal process behavior and API calls like SetWindowsHookEx, GetAsyncKeyState, or device input polling commonly used for keystroke logging.", "external_references": [{"external_id": "AN0282", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0102#AN0282"}], "id": "x-mitre-analytic--dd283114-84d8-4b1a-a765-f3a7f378c2d1", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0282", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "EventCode=4663, 4670, 4656", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Can be scoped to sensitive GUI processes like explorer.exe or winlogon.exe", "field": "TargetImage"}, {"description": "Time threshold for detecting multiple suspicious accesses", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3738', 0, 97, '09-mitre-attack', 'retrieved', 'BC3D47CD4095D50D902AD4E064A3B9D6D7240A3E53A5A19BFD85D8A0D8E8E6DA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
