VALUES ('doc-09-mitre-attack-p0-3739', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary targets macOS-hosted public services (e.g., nginx, node). Chain: suspicious inbound request → service crash/5xx → service spawns shell or writes file → new outbound connection.", "external_references": [{"external_id": "AN0221", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0080#AN0221"}], "id": "x-mitre-analytic--ddab6d30-7e37-462e-b183-39c7ceb2b986", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0221", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "App/web server logs ingested via unified logging or filebeat (nginx/apache/node).", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "exec events where web process starts a shell/tooling", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "outbound egress from web host after suspicious request", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Names/paths of public daemons on macOS (httpd, nginx, node, java).", "field": "ServiceList"}, {"description": "Correlation window for request → exec → egress.", "field": "TimeWindow"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3739', 0, 130, '09-mitre-attack', 'retrieved', 'CEF3A934D13BB297F0B9E17B8033E7D5D94C38B35E7D6008CE24C66253B9B8CF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
