INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3740', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary creates new users using ''dscl'' commands, GUI tools, or by modifying user plist files. Detection includes monitoring dscl invocation and user-related plist changes.", "external_references": [{"external_id": "AN1606", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0583#AN1606"}], "id": "x-mitre-analytic--ddaf8ed8-f6bd-4eac-911c-d9fd243e87e9", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1606", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "dscl . -create", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "modification to /var/db/dslocal/nodes/Default/users/", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Attackers may use service-like names to hide malicious accounts", "field": "UsernamePattern"}, {"description": "Accounts created via Terminal vs GUI vs remote session can affect confidence", "field": "ExecutionSource"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3740', 0, 106, '09-mitre-attack', 'retrieved', '3F5CCDA0171BA8B7C8C7479BA7995A297DDAD522AF9B8D7F622390218061DCB0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
