VALUES ('doc-09-mitre-attack-p0-3741', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects mailbox manipulation or deletion via PowerShell (e.g., Remove-MailboxExportRequest), file deletion from Outlook data stores (Unistore.db), or tampering with quarantined mail logs.", "external_references": [{"external_id": "AN0737", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0266#AN0737"}], "id": "x-mitre-analytic--ddbf61e2-7dad-40ef-90ef-7bec707b50fd", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0737", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "EventCode=23", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}, {"channel": "EventCode=4663, 4670, 4656", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "Transport Rule Modification", "name": "m365:exchange", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Outlook files in AppData\\Local\\Comms\\Unistore\\data", "field": "MailstorePath"}, {"description": "Target suspicious rule changes (e.g., header removal)", "field": "TransportRuleNames"}, {"description": "Regex match on `Remove-MailboxExportRequest` and similar Exchange cmdlets", "field": "PowerShellCommandMatch"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3741', 0, 120, '09-mitre-attack', 'retrieved', 'DEFB353DC6C7512C1089B565117AAC88C0CF20449288B632770F763A26942A44', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
