VALUES ('doc-09-mitre-attack-p0-3742', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Implantation of malicious code into container images followed by registry push and use in new deployments.", "external_references": [{"external_id": "AN0946", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0334#AN0946"}], "id": "x-mitre-analytic--de0a1136-1476-4c28-bf49-004ac3ef97f7", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0946", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "docker build or docker commit commands followed by docker push to internal registry", "name": "docker:daemon", "x_mitre_data_component_ref": "x-mitre-data-component--b008766d-f34f-4ded-b712-659f59aaed6e"}, {"channel": "push event of new image version from unrecognized user or context", "name": "docker:registry", "x_mitre_data_component_ref": "x-mitre-data-component--071a09b1-8945-46fd-8bb7-6bcc89400963"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Time threshold between image creation and use in deployment – typically rapid in adversarial activity.", "field": "TimeWindow"}, {"description": "The expected users or service accounts performing image pushes.", "field": "UserContext"}, {"description": "Expected naming patterns for trusted registries.", "field": "RegistryNameRegex"}], "x_mitre_platforms": ["Containers"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3742', 0, 128, '09-mitre-attack', 'retrieved', '8512479431A9874022D822D331821C0A3E1BD535E81669FA0C55DA16E91B40E3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
