VALUES ('doc-09-mitre-attack-p0-3744', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Burst of failed login attempts across VM instances using leaked credential pairs from single IP in public cloud environments", "external_references": [{"external_id": "AN1270", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0460#AN1270"}], "id": "x-mitre-analytic--de41a23b-b07d-411b-80f7-d1a8f55ba459", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1270", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "eventName=ConsoleLogin | eventType=AwsConsoleSignIn", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Define if detection should group logins per host or across cluster", "field": "InstanceIDScope"}, {"description": "Correlate against past IP reputation or behavioral profiles", "field": "IPBehaviorHistory"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3744', 0, 91, '09-mitre-attack', 'retrieved', '603820EF67309B9A9AEB6A77B20A7BCC4F1B123A7BAECAAB32032A93C23F520F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
