INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3746', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Correlate the creation or modification of containers using restart policies (e.g., ''always'') or DaemonSets with elevated host access, service account misuse, or privileged container contexts. Watch for manipulation of systemd units involving containers or pod scheduling targeting specific nodes or namespaces.", "external_references": [{"external_id": "AN1304", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0473#AN1304"}], "id": "x-mitre-analytic--de64bfbd-a6ed-4674-b0c5-dd485cba943b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1304", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "container run with restart policy set to ''always'' or ''unless-stopped''", "name": "systemd:unit", "x_mitre_data_component_ref": "x-mitre-data-component--a5ae90ca-0c4b-481c-959f-0eb18a7ff953"}, {"channel": "create", "name": "kubernetes:audit", "x_mitre_data_component_ref": "x-mitre-data-component--5263cb33-08cc-4a68-820f-004e1e400d76"}, {"channel": "create", "name": "kubernetes:audit", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune for environments that legitimately use ''always'' or ''unless-stopped'' in trusted containers", "field": "restartPolicy"}, {"description": "Scope detection to high-risk namespaces (e.g., kube-system)", "field": "targetNamespace"}, {"description": "Adjust if targeting known cluster configurations or test environments", "field": "nodeSelector|nodeName"}, {"description": "Adapt to your OS/systemd hierarchy and container binary references", "field": "unitFilePath"}, {"description": "Adjust temporal correlation (e.g., container launch → privilege escalation)", "field": "TimeWindow"}], "x_mitre_platforms": ["Containers"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3746', 0, 174, '09-mitre-attack', 'retrieved', 'EEA22DCDAC0B7370BB897846BA59760FDDCB3E58E8DC5C716D70C615B59B2F65', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
