VALUES ('doc-09-mitre-attack-p0-3747', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unusual access to SSH agent sockets in /tmp/ or /private/tmp, process access to another user’s $SSH_AUTH_SOCK, and lateral SSH activity without corresponding login events. Defender view: correlation of socket access with anomalous network flows to internal systems.", "external_references": [{"external_id": "AN0711", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0256#AN0711"}], "id": "x-mitre-analytic--de71bbc0-66b2-41ae-a3f3-4911ac31b391", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0711", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Process opening SSH_AUTH_SOCK or /tmp/ssh-* socket not owned by same UID", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"channel": "Execution of ssh or sftp without corresponding login event", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Session reuse without new auth event", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Limit detection to monitored SSH agent socket directories.", "field": "SocketPathScope"}, {"description": "Establish normal SSH agent ownership and expected usage for tuning.", "field": "BaselineUsers"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3747', 0, 141, '09-mitre-attack', 'retrieved', '3E29AC0D70872FC12DD71DD61CA1109999342BD0260A401FE417FC0966211149', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
