INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3749', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor for contextual data about a malicious payload, such as compilation times, file hashes, as well as watermarks or other identifiable configuration information. Much of this activity will take place outside the visibility of the target organization, making detection of this behavior difficult. Detection efforts may be focused on post-compromise phases of the adversary lifecycle.\nConsider analyzing malware for features that may be associated with malware providers, such as compiler used, debugging artifacts, code similarities, or even group identifiers associated with specific MaaS offerings. Malware repositories can also be used to identify additional samples associated with the developers and the adversary utilizing their services. Identifying overlaps in malware use by different adversaries may indicate malware was obtained by the adversary rather than developed by them. In some cases, identifying overlapping characteristics in malware used by different adversaries may point to a shared quartermaster.(Citation: FireEyeSupplyChain)", "external_references": [{"external_id": "AN1977", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0845#AN1977"}, {"description": "FireEye. (2014). SUPPLY CHAIN ANALYSIS: From Quartermaster to SunshopFireEye. Retrieved March 6, 2017.", "source_name": "FireEyeSupplyChain", "url": "https://www.mandiant.com/resources/supply-chain-analysis-from-quartermaster-to-sunshop"}], "id": "x-mitre-analytic--de93de79-3f24-4022-9b03-7228ffacca6f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1977", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "None", "name": "Malware Repository", "x_mitre_data_component_ref": "x-mitre-data-component--93a6e38c-02a5-44d8-9035-b2e08459f31f"}, {"channel": "None", "name": "Malware Repository", "x_mitre_data_component_ref": "x-mitre-data-component--167b48f7-76e9-4fcb-9e8d-7121f7bf56c3"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["PRE"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3749', 0, 213, '09-mitre-attack', 'retrieved', '9D1ABD62D13C80FA6831EDA018491F138EE331CEF66F9F954C0888FFFBB491C7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
