VALUES ('doc-09-mitre-attack-p0-3750', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of Office or document viewer processes (e.g., winword.exe) initiating network connections to remote templates or executing scripts due to manipulated template references (e.g., embedded in .docx, .rtf, or .dotm files), followed by suspicious child process creation (e.g., PowerShell).", "external_references": [{"external_id": "AN1564", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0566#AN1564"}], "id": "x-mitre-analytic--dea5f6cc-d3bb-404b-8aab-f7366988a96e", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1564", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Can be tuned to flag known bad domains or external resources in template fields.", "field": "TemplateURLPatterns"}, {"description": "May be environment-specific; typically Word, Excel, PowerPoint.", "field": "ParentProcess"}, {"description": "Correlation window for process + network activity.", "field": "TimeWindow"}, {"description": "Trigger when document-spawned child process deviates from expected profile.", "field": "ChildProcessAnomalyThreshold"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3750', 0, 140, '09-mitre-attack', 'retrieved', '8530802AF4C8A9AA1ACB1332A11FFEE800B5B4790D100540518A90100418A776', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
