VALUES ('doc-09-mitre-attack-p0-3751', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects unauthorized applications or scripts accessing sensitive data followed by establishing encrypted outbound communication to rare external destinations or with abnormal byte ratios.", "external_references": [{"external_id": "AN0990", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0348#AN0990"}], "id": "x-mitre-analytic--deb57305-6324-404d-a9d0-00aa0c285920", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0990", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "eventMessage = ''open'', ''sendto'', ''connect''", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "socket_events", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "process_events", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Enables defenders to tune legitimate vs. suspicious lineage (e.g., launchd → curl is uncommon).", "field": "ParentProcessAncestry"}, {"description": "Focus detection on unusual protocols (e.g., IRC, FTP, DNS over HTTPS).", "field": "ProtocolList"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3751', 0, 115, '09-mitre-attack', 'retrieved', 'B80278CBBE334AFC1AE3592D751FC4D9499ACB6DABD8