VALUES ('doc-09-mitre-attack-p0-3752', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Process chains that use native utilities (vssadmin, wbadmin, diskshadow, bcdedit, REAgentC, wmic) with arguments to delete shadow copies, disable recovery, or remove backup catalogs", "external_references": [{"external_id": "AN0933", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0329#AN0933"}], "id": "x-mitre-analytic--decb2be7-1a0a-46dd-ab48-cf6258c0185e", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0933", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Windows Backup Catalog deletion or catalog corruption", "name": "WinEventLog:Microsoft-Windows-Backup", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}, {"channel": "Service stopped or RecoveryDisabled set via REAgentC", "name": "WinEventLog:System", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}, {"channel": "EventCode=13, 14", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Used to track rapid recovery feature changes over short intervals", "field": "TimeWindow"}, {"description": "Can be tuned to catch variations in destructive flags (/all, /quiet, -delete)", "field": "CommandLinePattern"}, {"description": "Tune based on common parent-child chains (e.g., powershell → diskshadow)", "field": "ParentProcessContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3752', 0, 141, '09-mitre-attack', 'retrieved', '16E556D6F5251EAF14026082F12EC9EF488A8FB850BBB8129EB893AE8A41A5CB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
