VALUES ('doc-09-mitre-attack-p0-3753', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of firewall tampering by monitoring processes executing netsh, PowerShell Set-NetFirewallProfile, or sc stop mpssvc. Registry modifications under HKLM\\SYSTEM\\CurrentControlSet\\Services\\SharedAccess\\Parameters\\FirewallPolicy also indicate adversarial actions.", "external_references": [{"external_id": "AN0406", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0145#AN0406"}], "id": "x-mitre-analytic--df0f8f0a-1e92-415d-b15e-63cea928973a", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0406", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=13, 14", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of admin tools and scripts allowed to legitimately modify firewall settings.", "field": "MonitoredCommands"}, {"description": "Number of firewall rule changes within a time window before triggering alert.", "field": "AlertThreshold"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3753', 0, 105, '09-mitre-attack', 'retrieved', '5A9C23AC10D60D8599ECD8E7DACB7FC213F29A9E129CCE9CD4531DE406B630EB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corp