VALUES ('doc-09-mitre-attack-p0-3754', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Terminal-based grep or open of plist/config files containing credentials, correlated with Keychain or system login attempts.", "external_references": [{"external_id": "AN0858", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0307#AN0858"}], "id": "x-mitre-analytic--df289d0f-0f31-487e-b213-9a492d903f2c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0858", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "grep/cat on files matching credential patterns", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "open/read of *.plist or .env files", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "Keychain or user login post-access", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Monitor unexpected use of security CLI or Keychain helper binaries", "field": "KeychainToolAccess"}, {"description": "Add or remove watched file types based on system usage", "field": "FileTypeList"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3754', 0, 113, '09-mitre-attack', 'retrieved', 'F5130C30C420857F7C2DDA5F67793BAE195A9E5708E0204F5A37D164433A723C', 'v1', '{"source_id": "09-mitre-attack", "ve