VALUES ('doc-09-mitre-attack-p0-3755', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "EFI updates executed via system processes or binaries outside of expected patch windows or using unsigned firmware packages.", "external_references": [{"external_id": "AN0476", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0167#AN0476"}], "id": "x-mitre-analytic--df32865a-79b2-4faa-abd4-3ecfa27c8a77", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0476", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "com.apple.firmwareupdater activity or update-firmware binary invoked", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "boot failure events or SMC validation errors", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--b9d031bb-d150-4fc6-8025-688201bf3ffd"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Firmware updates usually occur after OS update; out-of-band patterns may indicate compromise", "field": "UpdateTimeWindow"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3755', 0, 95, '09-mitre-attack', 'retrieved', '2010581F2497DD1D09DABAF30276CFB1FE0CA1E6E831CB62D2666854BADA5F13', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
