VALUES ('doc-09-mitre-attack-p0-3756', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use of cloud-based bastion or VM console session followed by commands that initiate outbound SSH or RDP sessions from the cloud instance to other environments.", "external_references": [{"external_id": "AN0753", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0269#AN0753"}], "id": "x-mitre-analytic--dfabf07a-8179-43f5-abf6-699202c10343", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0753", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "AWS ConsoleLogin, StartSession", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "Outbound connections to port 22, 3389", "name": "AWS:VPCFlowLogs", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Limit detection to cloud admin/bastion hosts", "field": "SourceAssetTag"}, {"description": "Define critical remote service ports to flag", "field": "TargetPortList"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3756', 0, 102, '09-mitre-attack', 'retrieved', 'A3E8090684D4B1BA1DC488C9BADDF73902AE70A1A3C436B47C21C2A1CF29B063', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
