VALUES ('doc-09-mitre-attack-p0-3757', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Application access tokens used to call APIs (e.g., Google Workspace, Salesforce) without interactive logins, often with unusual scopes or elevated permissions.", "external_references": [{"external_id": "AN0528", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0185#AN0528"}], "id": "x-mitre-analytic--dfad1a86-de44-40b2-95b5-9b18c4103cbb", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0528", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "OAuthTokenGranted, APIRequest", "name": "saas:googleworkspace", "x_mitre_data_component_ref": "x-mitre-data-component--ff93f688-d7a4-49cf-9c79-a14454da8428"}, {"channel": "API login using access_token without login history", "name": "saas:salesforce", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Restrict allowed API scopes for enterprise applications", "field": "ApplicationScopeAllowlist"}, {"description": "Threshold for detecting unusually long-lived tokens", "field": "TokenLifetime"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3757', 0, 98, '09-mitre-attack', 'retrieved', 'D7E900F0CAFF0F72C90EEB9F0EE967F06DEFD4454CEADD1013D56CD4C274201F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
