VALUES ('doc-09-mitre-attack-p0-3758', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Collection of device configuration via CLI commands (e.g., `show running-config`, `copy flash`, `more`), often followed by TFTP/SCP transfers.", "external_references": [{"external_id": "AN1073", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0380#AN1073"}], "id": "x-mitre-analytic--dfe1b67a-a1c1-43f4-a043-5784a315d018", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1073", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "command logging", "name": "networkdevice:cli", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines list of configuration or diagnostic commands to monitor.", "field": "CommandScope"}, {"description": "Helps reduce false positives by whitelisting known admins.", "field": "AuthenticatedUserList"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3758', 0, 88, '09-mitre-attack', 'retrieved', '91EEBB28AF70CBC04C547302A9E4C6508616CB5C2A83D3547A9C0470C5D5A307', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
