VALUES ('doc-09-mitre-attack-p0-3759', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects Exchange Online or on-prem transport rule changes (e.g., header stripping) and mailbox export cleanup via `Remove-MailboxExportRequest`, as well as admin actions via Exchange PowerShell sessions.", "external_references": [{"external_id": "AN0740", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0266#AN0740"}], "id": "x-mitre-analytic--dff59103-f6d4-4580-8316-a0528768b4b3", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0740", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Admin Audit Logs, Transport Rules", "name": "m365:exchange", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Exchange Cmdlets", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Include `New-TransportRule`, `Set-TransportRule`, `Remove-*` actions", "field": "CmdletFilter"}, {"description": "Track role assignments for admins performing deletions", "field": "UserRoleScope"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3759', 0, 101, '09-mitre-attack', 'retrieved', '0B5809A92BB711D29DF86BB3008DBCB1072130E96E833E744AE97E7088B1FDC4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
