VALUES ('doc-09-mitre-attack-p0-3760', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Abuse of file/registry attributes to hide malicious files, directories, or services. Defender view: detection of attrib.exe setting hidden/system flags, creation of Alternate Data Streams, or registry keys altering file visibility.", "external_references": [{"external_id": "AN1384", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0502#AN1384"}], "id": "x-mitre-analytic--e01b29cd-2369-4ad5-bd91-98994f36cd1e", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1384", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=13, 14", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Filter for sensitive file types likely targeted for hiding.", "field": "FileExtensions"}, {"description": "Enable or disable detection of Alternate Data Streams depending on business use.", "field": "ADSDetection"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3760', 0, 115, '09-mitre-attack', 'retrieved', 'BA8A7CC0C9FFDB7B8C32338EE2A5B98413721395DADC47BC821A5CF