VALUES ('doc-09-mitre-attack-p0-3761', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Applications such as `curl`, `wget`, or custom binaries initiate HTTPS connections where the TLS SNI is mismatched or absent while HTTP Host targets CDN-available C2 endpoints.", "external_references": [{"external_id": "AN0565", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0196#AN0565"}], "id": "x-mitre-analytic--e031d1a5-92a9-46df-9467-d6899d48f57b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0565", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "ssl.log + http.log", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detect TLS sessions where SNI is empty—''domainless'' fronting.", "field": "SNIFieldAbsent"}, {"description": "Environmental tuning for known binaries using alternate SNI for testing (e.g., API tests).", "field": "AllowedTools"}, {"description": "Enrich command-line arguments or parent-child lineage to detect abuse.", "field": "ProcessContext"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3761', 0, 118, '09-mitre-attack', 'retrieved', '2ECB5BB825A5CFC2782866A98B4AF2661B2131ACE968B731339360AF760731FA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
