VALUES ('doc-09-mitre-attack-p0-3762', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of spearphishing links through mail logs and browser activity. Behavior includes email with suspicious URLs → user click recorded in mail/web proxy logs → shell or interpreter launched from browser process.", "external_references": [{"external_id": "AN0299", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0107#AN0299"}], "id": "x-mitre-analytic--e08e4dd6-cab5-41c0-b136-1bc8426c25ed", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0299", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Inbound emails containing hyperlinks from suspicious sources", "name": "Application:Mail", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "execve: Execution of scripts or binaries spawned from browser processes", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Outbound requests to domains not previously resolved or associated with phishing campaigns", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of browser processes to monitor (e.g., firefox, chrome, chromium).", "field": "MonitoredBrowsers"}, {"description": "Custom regex patterns for detecting obfuscated or IDN homograph URLs.", "field": "PhishingIndicators"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3762', 0, 141, '09-mitre-attack', 'retrieved', '66EBCF9533FA9D04300DA7A26D02BE85CE2B990CFF3A7DEEA55B801C6A8CC76F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
