VALUES ('doc-09-mitre-attack-p0-3764', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Suspicious querying of organization-wide directory data via Google Workspace Directory API or Outlook GAL sync in high volume from abnormal users, service accounts, or unknown device contexts.", "external_references": [{"external_id": "AN0642", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0229#AN0642"}], "id": "x-mitre-analytic--e0ad2e3d-c109-4af0-ac44-0d4cd45407c2", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0642", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Directory API Access: users.list or groups.list", "name": "gcp:audit", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}, {"channel": "GAL Lookup or Address Book download", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Unusual Token Usage or Application Consent", "name": "azure:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Set thresholds for excessive use of ''users.list'' or recursive group enumerations.", "field": "APIQueryVolume"}, {"description": "Flag non-admin or previously unseen user agents requesting directory information.", "field": "UserContext"}, {"description": "Distinguish between sanctioned sync tools and unauthorized scripts or OAuth tokens.", "field": "AppSource"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3764', 0, 141, '09-mitre-attack', 'retrieved', 'E704F75BC22F86F5BBBDC353A6B84DEB241CA9FB8584BC414E06611FB0EF8A6C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
