VALUES ('doc-09-mitre-attack-p0-3766', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects registration of new PTA agents, conditional access changes disabling hybrid MFA enforcement, or suspicious updates to AD FS token-signing configurations.", "external_references": [{"external_id": "AN0815", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0293#AN0815"}], "id": "x-mitre-analytic--e1063b92-9be0-4d25-9df5-bae4171c8153", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0815", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Register PTA Agent or Modify AD FS trust", "name": "azure:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "New agent registration by non-admin user", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Roles authorized to configure PTA/AD FS integrations.", "field": "PrivilegedRoles"}], "x_mitre_platforms": ["Identity Provider"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3766', 0, 95, '09-mitre-attack', 'retrieved', 'A8A776D3DCD1B9800C66E63346654FC855368F237B043F2E33D1C99A3F50FC44', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
