VALUES ('doc-09-mitre-attack-p0-3767', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects attempts to access browser credential stores (e.g., Firefox `logins.json`, Chrome SQLite DB) or processes (e.g., gnome-keyring-daemon). Observes unauthorized file reads and memory inspection of browser processes using ptrace or gdb.", "external_references": [{"external_id": "AN0106", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0037#AN0106"}], "id": "x-mitre-analytic--e11709c9-0203-4f76-bbfb-379ed36723ce", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0106", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "/home/*/.mozilla/firefox/*/logins.json OR /home/*/.config/google-chrome/*/Login Data", "name": "auditd:FILE", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "ptrace attach", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Paths of web browser credential databases to monitor", "field": "BrowserCredentialFiles"}, {"description": "List of expected debugging tools for dev/test environments", "field": "AllowedDebuggers"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3767', 0, 108, '09-mitre-attack', 'retrieved', 'D3E027046936D7718D648E6A586F7D84BAA77A83C08929253CCE8B8D64C32F95', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
