VALUES ('doc-09-mitre-attack-p0-3769', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "ESXi host processes (vmx, hostd) initiating HTTPS sessions toward external code repositories. Defender perspective: detect datastore reads followed by outbound web traffic inconsistent with administrative baselines.", "external_references": [{"external_id": "AN0898", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0318#AN0898"}], "id": "x-mitre-analytic--e18f0682-6610-4ba8-8159-a4afea3b7974", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0898", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "datastore file access", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "HTTPS traffic to repository domains", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Amount of data moved from datastore to external services before raising alert.", "field": "DatastoreTransferThreshold"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3769', 0, 98, '09-mitre-attack', 'retrieved', '369A4DBCE506FEB7DBFE5EEF18BA4C15F6E02A80CAF7D49280D016F31045D98D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
