VALUES ('doc-09-mitre-attack-p0-3770', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Behavioral chain: (1) sshd or federated SSO logins from third-party networks or identities; (2) rapid sudo/su privilege elevation; (3) access to sensitive paths or east-west SSH. Correlate auth logs, process execution, and network flows.", "external_references": [{"external_id": "AN1345", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0488#AN1345"}], "id": "x-mitre-analytic--e19cbf11-fabf-4dfd-aeb2-1c62660ebd8f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1345", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve,socket,connect,openat", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"channel": "Accepted publickey/password for * from * port * ssh2", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "ssh connections originating from third-party CIDRs", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "POSIX accounts assigned to vendors/partners.", "field": "ThirdPartyUsers"}, {"description": "Bastion hosts permitted for third-party access.", "field": "AllowedJumpHosts"}, {"description": "Flag indicating whether PAM/MFA should be present; used to score risk.", "field": "MFAExpected"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3770', 0, 135, '09-mitre-attack', 'retrieved', 'DDAD310A6913C8A6B1D6139B7F5B9FC83CC6AD154C8D80319DABDBF76C008DAC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
