VALUES ('doc-09-mitre-attack-p0-3771', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of USB-based remote access hardware (e.g., TinyPilot, PiKVM) attached to the host via drive or peripheral enumeration, triggering vendor identifiers or unusual EDID announcements.", "external_references": [{"external_id": "AN0446", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0159#AN0446"}], "id": "x-mitre-analytic--e1e76ffd-b452-429e-8ea0-a25ba877a2b5", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0446", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=2003", "name": "WinEventLog:System", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Device vendor strings may need tuning to include additional remote hardware sources.", "field": "VendorID"}, {"description": "Serial numbers for known implants can vary per campaign and may need expansion.", "field": "SerialNumber"}, {"description": "Adjust the detection window for peripheral enumeration based on environment and operating hours.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3771', 0, 117, '09-mitre-attack', 'retrieved', '1B2F59B35A15A4C3A3A8474BF868DEE2BB9EFE697304F78B26D45CDB7E966911', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
