INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3773', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary manipulation of shared library paths, environment variables, or replacement of service binaries. Defender observes suspicious modifications in /etc/ld.so.preload, service config changes, or file writes replacing existing executables.", "external_references": [{"external_id": "AN0610", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0218#AN0610"}], "id": "x-mitre-analytic--e21542c4-8df8-4c9e-8b1d-2c9bbe058386", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0610", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open/write syscalls targeting /etc/ld.so.preload or binaries in /usr/bin", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "Service restart with modified executable path", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}, {"channel": "Process execution with LD_PRELOAD or modified library path", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Directories where binary replacement should trigger alerts.", "field": "MonitoredDirectories"}, {"description": "Environment variables like LD_PRELOAD or PATH to monitor.", "field": "EnvVarMonitors"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3773', 0, 125, '09-mitre-attack', 'retrieved', '96CA718713BA896C6D1DE60590ECE0FF6ED58CAB5BF6EA8D9CBA9F607D3B32BB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
