INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3775', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "MSBuild.exe is invoked outside expected developer/build contexts or with anomalous arguments (e.g., non-canonical paths, remote shares, Base64/obfuscated property values). Within a short window, it (a) spawns high-risk LOLBins/script interpreters, (b) writes new PE/DLL/script artifacts into user-writable paths and executes them, (c) loads unsigned/user-writable modules, (d) performs memory injection/thread creation into other processes, and/or (e) initiates outbound network connections.", "external_references": [{"external_id": "AN1535", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0556#AN1535"}], "id": "x-mitre-analytic--e24b6c08-4fd0-40c7-a71a-762cc08d6085", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1535", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=8", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}, {"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "Unsigned/invalid signature modules or images loaded by msbuild.exe or its children", "name": "WinEventLog:Microsoft-Windows-CodeIntegrity/Operational", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"channel": "Malicious inline C#/script blobs embedded in MSBuild projects if intercepted by AMSI-aware loaders (rare but possible via chained LOLBins)", "name": "EDR:AMSI", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Correlation window between msbuild.exe start, payload write, suspicious child spawn, and network (e.g., 0–30 minutes).", "field": "TimeWindow"}, {"description": "Tag/allowlist known developer or CI/CD hosts to reduce noise.", "field": "DeveloperHosts"}, {"description": "High-risk children (powershell.exe, rundll32.exe, regsvr32.exe, cmd.exe, wscript.exe, mshta.exe) spawned by msbuild.exe.", "field": "SuspiciousChildList"}, {"description": "Regex of user-writable or atypical paths (e.g., %TEMP%, %APPDATA%, OneDrive sync dirs) used to drop payloads.", "field": "RarePathRegex"}, {"description": "Tighten alerting to cases with invalid or missing signatures on modules/children.", "field": "UnsignedOrInvalidSignatureOnly"}, {"description": "Minimum rarity/risk score for external destinations to alert.", "field": "NetworkReputationThreshold"}, {"description": "Numeric threshold for fused, scored correlation (e.g., ≥70/100 triggers an alert).", "field": "BehaviorRiskScoreThreshold"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3775', 0, 276, '09-mitre-attack', 'retrieved', '2AB44093CD998E12113D91DB724C5CA995F530AB7239D26B1EB183B5D55275C5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
