VALUES ('doc-09-mitre-attack-p0-3776', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Remote login via ARD or SSH followed by screensharingd process activity or modification of TCC-protected files.", "external_references": [{"external_id": "AN0752", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0269#AN0752"}], "id": "x-mitre-analytic--e26778ca-0fd9-4a1b-9d1d-d8ba561b065a", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0752", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "eventMessage CONTAINS ''screensharingd'' or ''AuthorizationRefCreate''", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "process_events", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Differentiate ARD vs SSH access patterns", "field": "RemoteService"}, {"description": "Tunable list of sensitive directories or TCC targets", "field": "TargetedPath"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3776', 0, 91, '09-mitre-attack', 'retrieved', 'C6A5670CD524DE1FA01725E2B843CA13575F859B577EDBD1B64B808C50B3B5E5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
