VALUES ('doc-09-mitre-attack-p0-3777', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Behavioral sequence of unauthorized privilege escalation via permission modification: (1) chmod/chown/setfacl process execution with suspicious parameters, (2) Targeting of critical system files or unusual permission values, (3) Correlation with non-privileged user context or unusual timing patterns, (4) Follow-on file access indicating successful permission bypass", "external_references": [{"external_id": "AN0835", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0299#AN0835"}], "id": "x-mitre-analytic--e268a6cb-2264-473e-9683-fb0f33ecd793", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0835", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "syscall in (chmod, fchmod, fchmodat, chown, fchown, fchownat, setxattr, lsetxattr, fsetxattr)", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"channel": "proctitle contains chmod, chown, setfacl, or attr commands with suspicious parameters", "name": "auditd:PROCTITLE", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Octal permission values that indicate potential malicious intent (default: 777, 755, 4755)", "field": "SuspiciousPermissionValues"}, {"description": "Linux filesystem paths requiring enhanced monitoring (/etc/, /usr/bin/, /home/)", "field": "CriticalPathPatterns"}, {"description": "User accounts permitted to perform system-level permission modifications", "field": "AuthorizedAdminUsers"}, {"description": "Statistical threshold for detecting unusual permission modification frequency", "field": "AnomalyThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3777', 0, 164, '09-mitre-attack', 'retrieved', '8501B43DCC0A7D6F38EBA9312216F69E89DF271B2A0553A5628447189EA55D9A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
