VALUES ('doc-09-mitre-attack-p0-3778', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unusual modification of boot records (MBR, VBR) or EFI partitions not associated with legitimate patch cycles or OS upgrades. Registry or WMI events associated with firmware update tools executed from unexpected parent processes. API calls (e.g., DeviceIoControl) writing directly to raw disk sectors. Subsequent abnormal boot configuration changes followed by unsigned driver loads.", "external_references": [{"external_id": "AN0774", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0278#AN0774"}], "id": "x-mitre-analytic--e2ca60b5-82df-4e7e-8528-dd24d9a79750", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0774", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=9", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--73ff2dcc-24b1-4368-b9dc-706dd9e68354"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Legitimate vendor tools or processes authorized to modify firmware or boot records.", "field": "AllowedFirmwareUpdateTools"}, {"description": "Correlating boot-sector modification with subsequent reboot events.", "field": "TimeWindow"}, {"description": "Heuristic threshold for detecting obfuscated/packed boot code.", "field": "EntropyThreshold"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3778', 0, 145, '09-mitre-attack', 'retrieved', 'F0CEBBA170A837DFA2E6265D9670EA961F4545E36943E5C2865BCE4131842449', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
