VALUES ('doc-09-mitre-attack-p0-3779', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Enumeration of directories, applications, or service principals through APIs such as Microsoft Graph or Okta API. Defender perspective includes unexpected listing of users, roles, applications, and abnormal access to identity management endpoints.", "external_references": [{"external_id": "AN1128", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0402#AN1128"}], "id": "x-mitre-analytic--e2dd9fee-91b7-4e32-8031-69ed4d7b927c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1128", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "ListApplications, ListServicePrincipals: Large-scale queries against identity or application objects", "name": "azure:audit", "x_mitre_data_component_ref": "x-mitre-data-component--8c826308-2760-492f-9e36-4f0f7e23bcac"}, {"channel": "InteractiveUserLogin: Discovery behavior linked to privileged logins from atypical IP ranges", "name": "azure:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Threshold for number of object enumeration calls before triggering detection.", "field": "QueryVolumeThreshold"}, {"description": "High-value identity roles (Global Admin, Application Admin) for targeted discovery monitoring.", "field": "PrivilegedRoleList"}], "x_mitre_platforms": ["Identity Provider"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3779', 0, 129, '09-mitre-attack', 'retrieved', '75199656FBD119EB800E6A4431B876D1156D7744E9DE741657F6EF41B19334C0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
