INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3780', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detect runtime manipulation by monitoring system calls for modifications to shared libraries, ELF binaries, or environment variables that affect how data is displayed. Look for suspicious writes to application directories and mismatch in binary integrity baselines.", "external_references": [{"external_id": "AN1098", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0391#AN1098"}], "id": "x-mitre-analytic--e2e39b7e-02e4-4e7a-966c-6b05721da8f7", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1098", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open, write: File writes to application binaries or libraries at runtime", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "Execution of modified binaries or abnormal library load sequences", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Specific critical application binaries or libraries to monitor for unauthorized changes.", "field": "WatchedBinaries"}, {"description": "Interval for verifying hashes of executables and libraries.", "field": "IntegrityCheckFrequency"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3780', 0, 130, '09-mitre-attack', 'retrieved', '7B7974CA548A883D11681F39D4E7CA4A220A9C542084AF7703107DEEC9B732EF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
