VALUES ('doc-09-mitre-attack-p0-3782', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Burst of failed authentications with rotating usernames against loginwindow or remote management service using reused breached credentials", "external_references": [{"external_id": "AN1264", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0460#AN1264"}], "id": "x-mitre-analytic--e2f104ac-b21a-4c48-8987-3e0ad73997df", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1264", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Login failure / authorization denied", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tunable threshold for number of attempted usernames in a time window", "field": "DistinctUsernameCount"}, {"description": "Restrict behavior detection to remote login interfaces", "field": "RemoteAccessFilter"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3782', 0, 90, '09-mitre-attack', 'retrieved', '7E1A487BB1834CF9E5C8713FF87B92271E40D129A12088C81E3EDD172F765BC1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
