VALUES ('doc-09-mitre-attack-p0-3783', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "ESXi shell or vim-cmd execution that deletes all VM snapshots using vmsvc/snapshot.removeall or rm on snapshot paths", "external_references": [{"external_id": "AN0935", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0329#AN0935"}], "id": "x-mitre-analytic--e2fb4be5-bd70-45d6-89ad-e687bc475285", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0935", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "snapshot.removeall or snapshot file deletion", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--16e07530-764b-4d83-bae0-cdbfc31bf21d"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Limit to critical VM names to reduce false positives", "field": "TargetVMNames"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3783', 0, 78, '09-mitre-attack', 'retrieved', '91B315D12DDC3C30BFA1BF6603051BA76B4E5C6337945590ECF62F5C7B700EA0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
