INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3784', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Defender observes unauthorized modification or creation of Python hook files such as `.pth`, `sitecustomize.py`, or `usercustomize.py` in Python `site-packages`, `dist-packages`, or user paths. This is often correlated with subsequent unexpected interpreter execution (e.g., python3 running without user interaction), changes in interpreter behavior (e.g., malicious imports), and outbound connections initiated from Python. Defender links write/modify actions on hook files with execve of python process and/or anomalous child process or network activity.", "external_references": [{"external_id": "AN0713", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0258#AN0713"}], "id": "x-mitre-analytic--e32ce63a-7c82-4115-8c50-e43113562132", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0713", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve: execve where exe=/usr/bin/python3 or similar interpreter", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "write or create events on *.pth, sitecustomize.py, usercustomize.py in site-packages or dist-packages", "name": "auditd:PATH", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "chmod or chown of hook files indicating privilege escalation or execution permission change", "name": "auditd:CONFIG_CHANGE", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"channel": "http::request: Outbound HTTP initiated by Python interpreter", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Absolute or regex paths to Python startup files (.pth, customize.py); vary by distro or virtual environment location", "field": "HookFilePathPatterns"}, {"description": "Restrict alerts to non-root users, service accounts, or interactive shell sessions", "field": "UserContext"}, {"description": "Correlate file modification and Python execution within short time span (default: 2–5 minutes)", "field": "TimeWindow"}, {"description": "Filter out known legitimate Python executions tied to expected cron jobs or automation", "field": "InterpreterWhitelist"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3784', 0, 234, '09-mitre-attack', 'retrieved', 'AD8A8E22166125CAD5C3273764B21395DDA2465C6C4641545FF12C3A35FD2F26', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
