VALUES ('doc-09-mitre-attack-p0-3785', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of the creation of VSCode or JetBrains CLI tunneling profiles followed by persistent remote access via IDE-integrated tunnels, potentially authenticated via GitHub or JetBrains accounts.", "external_references": [{"external_id": "AN0375", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0133#AN0375"}], "id": "x-mitre-analytic--e3517ec0-f12a-4f64-8d10-e6bc2677f7d7", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0375", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "Outbound connection to *.tunnels.api.visualstudio.com or *.devtunnels.ms", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Used to define the temporal proximity between tunnel profile creation and outbound connection.", "field": "TimeWindow"}, {"description": "Domain patterns for tunnel endpoints may change with IDE versions or organizations.", "field": "TunnelDomainPatterns"}, {"description": "Helps filter tunnel usage from trusted developer accounts.", "field": "AuthorizedUserList"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3785', 0, 130, '09-mitre-attack', 'retrieved', '986498BAD65A5001B0054A083B1D7AC22060446639AF73D9A5434524E3A9C70A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
