VALUES ('doc-09-mitre-attack-p0-3786', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor PAM and syslog entries for unusual frequency of login attempts that trigger MFA prompts, particularly when MFA challenges do not match expected user behavior.", "external_references": [{"external_id": "AN0452", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0160#AN0452"}], "id": "x-mitre-analytic--e36b2d32-05a8-4bcf-b7cf-58dc3ad4c0d3", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0452", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "pam_unix or pam_google_authenticator invoked repeatedly within short interval", "name": "auditd:AUTH", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Number of retries per user allowed before detection is triggered", "field": "AuthRetryThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3786', 0, 90, '09-mitre-attack', 'retrieved', 'F16151E8F866E901DA4C4AFCED042B94FEA8DAB2536B5E9A82F7FEBDC6B9271A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
