VALUES ('doc-09-mitre-attack-p0-3787', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "API usage or filesystem access revealing user state or browser artifacts (e.g., Safari bookmarks, CGEventState).", "external_references": [{"external_id": "AN1184", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0420#AN1184"}], "id": "x-mitre-analytic--e3a0ea8d-0018-4603-912a-4d40d0f75390", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1184", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Execution of input detection APIs (e.g., CGEventSourceKeyState)", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"channel": "Access to ~/Library/Safari/Bookmarks.plist or recent files", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Temporal correlation between login and file access", "field": "TimeWindow"}, {"description": "Exclude expected UI activity from login agents", "field": "UserContext"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3787', 0, 97, '09-mitre-attack', 'retrieved', '41E9A9548B4416A5DBE8D22C80607D7973DDA0E8876A942A8799A5D4F935A094', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
