INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3789', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Defender detects execution of `mdfind`, `launchctl`, or GUI-based enumeration (e.g., `/Applications/Time Machine.app`) along with command-line usage of `find`, `grep`, or `system_profiler` to identify installed backup tools like Time Machine, Carbon Copy Cloner, or Backblaze. Often triggered from Terminal sessions or within post-exploitation scripts.", "external_references": [{"external_id": "AN0242", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0088#AN0242"}], "id": "x-mitre-analytic--e3c81570-be1b-48c8-b000-b70173c5c226", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0242", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Process execution logs showing discovery commands like mdfind, system_profiler, or launchctl list", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Read access to Time Machine plist files or CCC configurations in ~/Library/Preferences/", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Directories or bundles where backup tools are commonly installed", "field": "InstallLocationScope"}, {"description": "Plist files related to backup software configurations", "field": "KnownAppPlistPaths"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3789', 0, 138, '09-mitre-attack', 'retrieved', '364F21D8177AF38E360F045E58A4CF10675B6376B44D162E3C3157D74087E9D5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
