INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3790', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary renames LOLBINs or deploys binaries with spoofed file names, internal PE metadata, or misleading icons to appear legitimate. File creation is followed by execution or service registration inconsistent with known usage.", "external_references": [{"external_id": "AN0355", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0127#AN0355"}], "id": "x-mitre-analytic--e3d982ec-2729-4e98-b340-affa13096fd6", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0355", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7045", "name": "WinEventLog:System", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Compare executable file name with PE metadata OriginalFilename field", "field": "OriginalFilenameMismatch"}, {"description": "Tune based on expected installation directories for signed binaries", "field": "KnownSystemUtilityPaths"}, {"description": "Correlation window between file creation and service/process execution", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3790', 0, 118, '09-mitre-attack', 'retrieved', 'BEB67583DD3F6386C7D43BFBED48971906CE8ED6009451EF46348436FA67AC3C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
