INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3792', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Multiple failed authentication attempts using distinct username/password pairs from a single IP address or session within a short time window, targeting common services like RDP or SMB", "external_references": [{"external_id": "AN1262", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0460#AN1262"}], "id": "x-mitre-analytic--e3e2d59b-220f-43b0-9891-7b299be27c50", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1262", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4625", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Minimum number of unique usernames in failed login attempts before triggering alert", "field": "UsernameUniquenessThreshold"}, {"description": "Duration (e.g., 5 minutes) to observe the behavior chain of rapid login attempts", "field": "TimeWindow"}, {"description": "Whether to group by full IP or CIDR block for bursty behavior from botnets", "field": "SourceIPScope"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3792', 0, 120, '09-mitre-attack', 'retrieved', '26050958FA1FC3BBF3C1FF7EDC6D454EC688DD9A1EDA0B3967819D832C5FFEED', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
