INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3793', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor for anomalous email activity originating from Windows-hosted applications (e.g., Outlook) where the sending account name or display name does not match the underlying SMTP address. Detect abnormal volume of outbound messages containing sensitive keywords (e.g., ''payment'', ''wire transfer'') or anomalous login locations for accounts associated with email sending activity.", "external_references": [{"external_id": "AN0792", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0286#AN0792"}], "id": "x-mitre-analytic--e4246c20-fbe4-4750-a29e-44e3fe179bf2", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0792", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4624, 4648", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "SendOnBehalf/SendAs: Emails sent where the sending identity mismatches account ownership", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Adjust impersonation detection keywords based on local business risk terms (e.g., ''ACH'', ''Invoice'').", "field": "KeywordList"}, {"description": "Define trusted geographic regions for normal user email activity.", "field": "GeoLocationBaseline"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3793', 0, 139, '09-mitre-attack', 'retrieved', '1365ECB5BF0006BEB2E655E92FE59D1AC17E4A78057DF155231CA0CA133B7853', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
