INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3796', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor access to /proc/self/status where TracerPID field is queried, as this is a common technique for debugger detection. Detect processes that attempt to trigger exceptions intentionally and monitor whether exception handling indicates presence of a debugger.", "external_references": [{"external_id": "AN1046", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0371#AN1046"}], "id": "x-mitre-analytic--e4a9dd91-3354-40c8-a55c-941d53f2ddec", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1046", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open/read: Access to /proc/self/status with focus on TracerPID field", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Set of /proc paths to monitor for suspicious access", "field": "MonitoredPaths"}, {"description": "Rate of syscalls (open/read) used to detect repeated probing for debug artifacts", "field": "SyscallThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3796', 0, 116, '09-mitre-attack', 'retrieved', '56C0C43E9C3DD6D0A5E591EF8FE60C2DCA71A938B6AF59BC866A2848B6838A75', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3797', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Much of this activity will take place outside the visibility of the target organization, making detection of this behavior difficult. Detection efforts may be focused on behaviors relating to the potential use of generative artificial intelligence (i.e. [Phishing](https://attack.mitre.org/techniques/T1566), [Phishing for Information](https://attack.mitre.org/techniques/T1598)).", "external_references": [{"external_id": "AN1974", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0842#AN1974"}], "id": "x-mitre-analytic--e4b35edc-f7fe-4f0d-aaaf-60fabc9d2698", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1974", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["PRE"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3797', 0, 78, '09-mitre-attack', 'retrieved', '96C5ED046C2D455EBFF610A851DB9DDB538FBB195DEDCE35E7FC7AB031F2CD7D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3798', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of container orchestration commands (e.g., `docker exec`, `kubectl exec`) or API-driven interactions with running containers from unauthorized hosts or non-standard user contexts. Defender sees programmatic or interactive command execution within containers outside expected CI/CD tools or automation frameworks, often followed by file writes, privilege escalation, or lateral discovery.", "external_references": [{"external_id": "AN0233", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0083#AN0233"}], "id": "x-mitre-analytic--e4dd4100-2387-4029-a478-35aefd37c288", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0233", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve: Execution of container management CLIs (docker, crictl, kubectl) or interpreted shells (sh, bash, python) within container context", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "exec_create: docker exec events targeting running containers from non-CI sources", "name": "docker:events", "x_mitre_data_component_ref": "x-mitre-data-component--5fe82895-28e5-4aac-845e-dc886b63be2e"}, {"channel": "create/exec: Kubernetes API calls to exec into containers or create pods from curl, kubectl, or SDK clients", "name": "kubernetes:apiserver", "x_mitre_data_component_ref": "x-mitre-data-component--a5ae90ca-0c4b-481c-959f-0eb18a7ff953"}, {"channel": "CreatePod: Programmatic creation of new pod resources using container images not seen before in the environment", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--5263cb33-08cc-4a68-820f-004e1e400d76"}, {"channel": "Shell process (e.g., /bin/sh, /bin/bash) spawned in a container without an interactive session attached (i.e., automation anomaly)", "name": "kubernetes:audit", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of CI/CD pipeline runners, SRE tools, or cluster mgmt agents allowed to invoke API/CLI commands in containers.", "field": "AuthorizedUserAgents"}, {"description": "Threshold for alerting on unseen container images pulled and executed. Adjust to reduce noise from frequent deploys.", "field": "NewImageThreshold"}, {"description": "Temporal window to correlate container exec with shell spawn and network activity (default: 2 minutes).", "field": "TimeWindow"}, {"description": "Set whether shell spawns without TTY or PTY should be flagged — based on org deployment model.", "field": "InteractiveSessionExpectation"}], "x_mitre_platforms": ["Containers"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3798', 0, 270, '09-mitre-attack', 'retrieved', 'C6C352E38B25CFFD47E6F438F0E49745AF23D275B3171B501FFE69D00E4F65B0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
