VALUES ('doc-09-mitre-attack-p0-3799', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Cloud API calls disabling snapshot scheduling, backup policies, versioning, followed by DeleteSnapshot/DeleteVolume operations", "external_references": [{"external_id": "AN0937", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0329#AN0937"}], "id": "x-mitre-analytic--e50f8247-73da-4461-a560-745ed84f1209", "modified": "2025-11-12T18:17:38.273Z", "name": "Analytic 0937", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "DeleteSnapshot", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--16e07530-764b-4d83-bae0-cdbfc31bf21d"}, {"channel": "DeleteBucket, DeleteDBCluster, DeleteSnapshot, TerminateInstances", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--4c41e296-b8d2-4a37-b789-eb565c87c00c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune for legitimate backup automation vs unknown tools", "field": "UserAgent"}, {"description": "Filter only on production images or vaults", "field": "ResourceType"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3799', 0, 90, '09-mitre-attack', 'retrieved', 'C9F7D90BABA644F7648A072A1F3AA84469A5157C501650CDE4EB465BA8989C23', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
