VALUES ('doc-09-mitre-attack-p0-3800', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "ESXi shell or scripts produce long, high-entropy tokens (non-standard alphabets) in shell.log/hostd, followed by outbound flows (NSX/Zeek) with asymmetric ratios or protocol mismatches to non-management endpoints.", "external_references": [{"external_id": "AN0930", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0326#AN0930"}], "id": "x-mitre-analytic--e518b7e5-6e98-43f6-86c2-f45f684c650f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0930", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "commands containing long non-standard tokens or custom lookup tables", "name": "esxi:shell", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "unexpected script invocations producing long encoded strings", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "network_flow: bytes_out >> bytes_in, fixed packet sizes/intervals to non-approved CIDRs", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "http: HTTP bodies from ESXi host IPs containing long, non-standard tokens", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "CIDRs allowed for normal ESXi mgmt/backup.", "field": "MgmtCIDRs"}, {"description": "Asymmetry cutoff (e.g., ≥3).", "field": "BytesOutToInRatio"}, {"description": "Minimum token length.", "field": "TokenLengthThreshold"}, {"description": "Correlation window.", "field": "TimeWindow"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3800', 0, 149, '09-mitre-attack', 'retrieved', '6ADA112C2D34B6FCFA63140A96F04B4331720E2E77D3100B0CF7B0718DA56A4F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
