VALUES ('doc-09-mitre-attack-p0-3801', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects disabling AAA, syslog, SNMP traps, ACL logging, or security features on routers/switches/firewalls; correlates privileged login followed by configuration commit reducing visibility.", "external_references": [{"external_id": "AN1374", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0497#AN1374"}], "id": "x-mitre-analytic--e542342f-5a08-408d-b292-797bcb2da5eb", "modified": "2026-05-12T16:30:18.383Z", "name": "Analytic 1374", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "write: Startup configuration changes disabling security checks", "name": "networkdevice:config", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}, {"channel": "no logging host, no aaa new-model, no snmp-server, commit", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Reference configuration state for detecting unauthorized modifications.", "field": "ConfigBaseline"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-3801', 0, 100, '09-mitre-attack', 'retrieved', 'B134B6A39C1343B3A95F115455BE565E9E6AC2A733A07204CFB2BFA57BEA66AA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
