VALUES ('doc-09-mitre-attack-p0-3802', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "macOS-specific permission modification behavioral chain: (1) chmod/chown/chflags process execution, (2) System Integrity Protection (SIP) bypass attempts, (3) Extended attribute (xattr) modifications, (4) Unified log correlation with file system events, (5) Subsequent access to previously restricted resources", "external_references": [{"external_id": "AN0836", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0299#AN0836"}], "id": "x-mitre-analytic--e564e2b8-542b-4003-a8b7-df9d3396f5b9", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0836", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process execution events for chmod, chown, chflags with unusual parameters or targets", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "file system events indicating permission or attribute changes", "name": "fs:fsevents", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "macOS system paths protected by SIP that should never have permission modifications", "field": "SIPProtectedPaths"}, {"description": "chflags parameter combinations indicating evasive behavior (uchg, schg, hidden)", "field": "SuspiciousFlagCombinations"}, {"description": "Extended attributes to monitor for unauthorized modifications", "field": "XattrMonitoringScope"}, {"description": "Log retention period for correlating permission changes with subsequent access", "field": "UnifiedLogRetention"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3802', 0, 155, '09-mitre-attack', 'retrieved', '78DFB715146F9B1599A754EF287E96AA855A74A80429EC1E4D519C884D93E259', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
