VALUES ('doc-09-mitre-attack-p0-3803', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of processes performing local or domain account enumeration by invoking account directory queries or security APIs followed by structured output of account lists. The defender observes command execution or API invocation patterns that retrieve account information and produce enumeration artifacts shortly afterward.", "external_references": [{"external_id": "AN1612", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0587#AN1612"}], "id": "x-mitre-analytic--e576eaeb-2158-40f9-8edb-c119eac56442", "modified": "2026-05-12T16:30:18.383Z", "name": "Analytic 1612", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=4798, 4799", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--8e44412e-3238-4d64-8878-4f11e27784fe"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Match variations in enumeration commands like ''net user'', ''Get-ADUser'', ''dsquery''.", "field": "CommandLinePattern"}, {"description": "Short burst of account enumeration commands may indicate automation.", "field": "TimeWindow"}, {"description": "Restrict to non-admin accounts or unexpected users executing enumeration commands.", "field": "UserContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-3803', 0, 141, '09-mitre-attack', 'retrieved', '980047DF3F597D24A3CE38E5E43DC6A97B1D8231A946D82E4D78048A12B0AB5D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
