VALUES ('doc-09-mitre-attack-p0-3804', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects snapshots or data stored in VMFS volumes from root CLI or remote agents.", "external_references": [{"external_id": "AN0044", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0014#AN0044"}], "id": "x-mitre-analytic--e59e2d8c-20cb-4a77-9d8b-1d838b01bd87", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0044", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "VMFS access logs", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "snapshot create/copy, esxcli", "name": "esxi:shell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Number of snapshots in short time period", "field": "SnapshotFrequency"}, {"description": "Non-admins or automation accounts writing to datastores", "field": "AccessUserList"}, {"description": "Manual or unexpected API calls triggering snapshots", "field": "CLIContext"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3804', 0, 99, '09-mitre-attack', 'retrieved', '22526A01AB4EFA5B97ABBD2D46FC90CFCEA85EC7EA512994D1241AE85FDC6325', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
