VALUES ('doc-09-mitre-attack-p0-3806', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects modification of ESXi cron jobs, local.sh scripts, or scheduled API calls to persist custom binaries or shell scripts.", "external_references": [{"external_id": "AN0262", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0094#AN0262"}], "id": "x-mitre-analytic--e5adcc7e-5d68-4080-bb87-e901f297485d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0262", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Startup script and task execution logs", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}, {"channel": "shell access or job registration", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "manual edits to /etc/rc.local.d/local.sh or cron.d", "name": "esxi:cron", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Filename not matching expected initialization scripts.", "field": "StartupScriptName"}, {"description": "Commands run from unexpected SSH sessions or elevated shells.", "field": "ExecutionContext"}, {"description": "Rare scheduling triggers (e.g., @reboot + hourly repetition).", "field": "PersistenceInterval"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3806', 0, 122, '09-mitre-attack', 'retrieved', '7F4613DF