VALUES ('doc-09-mitre-attack-p0-3807', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Direct modification of /etc/ssh/keys- /authorized_keys or enabling SSH in sshd_config to support public key auth.", "external_references": [{"external_id": "AN0353", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0126#AN0353"}], "id": "x-mitre-analytic--e5b0d0ab-a464-4e9f-a1c0-dfb08a6ef53f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0353", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "file write or edit", "name": "esxi:shell", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Could be modified SSH path in hypervisor", "field": "SSHConfigPath"}, {"description": "Whether shell was enabled beforehand via DCUI or API", "field": "ESXiShellActivity"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3807', 0, 85, '09-mitre-attack', 'retrieved', 'CF527CC3B996D626F03D3EAFB87DA98F95B009B37A23C7A9D076B87DB0AF3022', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
