VALUES ('doc-09-mitre-attack-p0-3808', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects exploitation attempts targeting defensive security software or OS services. Defender observation includes abnormal process behavior (e.g., AV or EDR crashing unexpectedly), unsigned/untrusted modules loaded into defensive processes, or privilege escalation from security agent services. Multi-event correlation ties exploitation attempts to subsequent evasive behavior like service termination or missing logs.", "external_references": [{"external_id": "AN1633", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0595#AN1633"}], "id": "x-mitre-analytic--e5b0fcab-05e5-4687-a1a9-dd382a19980b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1633", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of defensive services/processes (e.g., AV, EDR) monitored in the environment.", "field": "DefensiveProcessList"}, {"description": "Whitelisted DLL/module paths normally loaded by defensive tools.", "field": "AllowedModulePaths"}, {"description": "Number of abnormal terminations of defensive processes tolerated before triggering an alert.", "field": "CrashThreshold"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3808', 0, 141, '09-mitre-attack', 'retrieved', 'C3F49BB3911C81F6DE61A75AD7C59CD9704685DBE2BB0EBEFACFB0A645649CF6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
