VALUES ('doc-09-mitre-attack-p0-3809', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Suspicious outbound HTTPS connections where the TLS Server Name Indication (SNI) does not match the HTTP Host header, indicating potential use of domain fronting to mask C2 traffic via CDNs.", "external_references": [{"external_id": "AN0564", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0196#AN0564"}], "id": "x-mitre-analytic--e5cb92b6-75b0-4eed-aa1e-4ea529f50fbb", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0564", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "TLS handshake + HTTP headers", "name": "NSM:Connections", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Define acceptable mismatch ratio between SNI and HTTP Host fields based on legitimate domain usage patterns.", "field": "SNIHostMismatch"}, {"description": "Whitelist of known safe CDN front-end domains (e.g., `cdn.company.com`).", "field": "CDNAllowList"}, {"description": "Filter for suspicious initiators of domain fronting, e.g., scripting engines, lolbins, unknown binaries.", "field": "ProcessInitiator"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3809', 0, 133, '09-mitre-attack', 'retrieved', '4C190A7150D8BE001C2D8F1617AA55A11A98B6495330E9A05DC0E0155ECA97EE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
