VALUES ('doc-09-mitre-attack-p0-3810', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Shell script or binary initiates curl/wget request to staging domain, writes output to disk or memory, and shortly afterward launches another process that establishes new outbound connection to a different IP or hostname.", "external_references": [{"external_id": "AN0638", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0228#AN0638"}], "id": "x-mitre-analytic--e5fcc815-0ab4-4da9-aade-659b87d079da", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0638", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve, connect", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "OUTBOUND", "name": "iptables:LOG", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune for suspicious binaries like curl, wget, python, netcat", "field": "BinaryPath"}, {"description": "Detect multiple different external IPs contacted within short timeframe", "field": "IPDistance"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3810', 0, 109, '09-mitre-attack', 'retrieved', 'AC226139AD39CDD27C3D863707328E2F3521CA4E4F6AC7B4ABDE922DF5BB0032', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
