VALUES ('doc-09-mitre-attack-p0-3811', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of mshta.exe execution where command-line arguments reference remote or local HTA/script content (VBScript/JScript) followed by subsequent file creation, network retrieval, or process spawning that indicates payload execution outside standard Internet Explorer security context. Correlation includes parent process lineage, command-line inspection, and network connection creation to untrusted or anomalous endpoints.", "external_references": [{"external_id": "AN1397", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0506#AN1397"}], "id": "x-mitre-analytic--e6037bea-ba25-40bf-b681-361d4f901adb", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1397", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Regex patterns for mshta.exe arguments referencing remote HTA/script content; may need tuning to exclude known-good internal scripts.", "field": "CommandLinePattern"}, {"description": "List of parent processes considered suspicious when spawning mshta.exe (e.g., Office applications, script interpreters).", "field": "SuspiciousParentProcesses"}, {"description": "Whitelist of domains/paths from which legitimate HTAs are executed.", "field": "AllowedHTASources"}, {"description": "Time threshold for correlating mshta.exe execution with subsequent network connections or file creations.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3811', 0, 173, '09-mitre-attack', 'retrieved', 'B4F695F44A75556D334E6F4AEC23FF2356D3F00EA2F86CB2DB2070D2DF748F3A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
