VALUES ('doc-09-mitre-attack-p0-3812', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversaries create SaaS accounts via admin dashboards or integrations (e.g., Zoom, Salesforce, Slack). Monitor lifecycle.create or account provisioning events from non-standard sources or times.", "external_references": [{"external_id": "AN0901", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0319#AN0901"}], "id": "x-mitre-analytic--e619c27e-3d57-489c-8ce9-cbb5f0c195bd", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0901", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "New user created", "name": "saas:zoom", "x_mitre_data_component_ref": "x-mitre-data-component--deb22295-7e37-4a3b-ac6f-c86666fbe63d"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Trigger only for high-privilege or sensitive applications", "field": "ApplicationScope"}, {"description": "Compare actor to list of approved SaaS administrators", "field": "AdminUserList"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3812', 0, 92, '09-mitre-attack', 'retrieved', '6C1B49C4876FC82710DF450FA497CDDDF3D7AE9DAC333BC1642518F0BD4864A8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
