VALUES ('doc-09-mitre-attack-p0-3813', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of processes launching downgraded PowerShell versions (e.g., v2) or other legacy binaries that lack logging or security features. Correlates command-line arguments, process metadata, and version fields. Monitors registry changes to Defender or HVCI keys that could indicate intentional downgrades.", "external_references": [{"external_id": "AN0995", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0350#AN0995"}], "id": "x-mitre-analytic--e61d2099-1517-4bf4-b2e6-6e61cdf94be3", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0995", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=4657", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines which versions of interpreters like PowerShell are permitted in the environment.", "field": "AllowedInterpreterVersions"}, {"description": "Specific registry paths for monitoring Defender/HVCI configurations that may vary by Windows version.", "field": "RegistryDefenderKeys"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3813', 0, 122, '09-mitre-attack', 'retrieved', 'D48E8DAE3392FF546D5F37FFED745988666323FB24A7CBE22483F4B2FA652C0E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
