VALUES ('doc-09-mitre-attack-p0-3814', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects virtual disk expansion or file copy operations to cloud buckets or mounted volumes from isolated instances.", "external_references": [{"external_id": "AN0043", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0014#AN0043"}], "id": "x-mitre-analytic--e622500c-4217-466c-955c-82ef3217653a", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0043", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "GetObject, CopyObject", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--58ef998c-f3bf-4985-b487-b1005f5c05d1"}, {"channel": "Write operations to storage", "name": "gcp:audit", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Staging bucket or mount point for data", "field": "CloudBucketList"}, {"description": "Behavior restricted to specific ephemeral instances", "field": "InstanceTag"}, {"description": "Volume or size of files pushed in burst", "field": "ObjectWriteThreshold"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3814', 0, 102, '09-mitre-attack', 'retrieved', 'C96868096439111A6C8CBF09015795225EAE49B6F4EF38D5D0FDC5AC737D6FF9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
