VALUES ('doc-09-mitre-attack-p0-3815', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Office-based persistence via Office template macros, Outlook forms/rules/homepage, or registry-persistent scripts. Adversary modifies registry keys or Office application directories to load malicious scripts at startup.", "external_references": [{"external_id": "AN1116", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0398#AN1116"}], "id": "x-mitre-analytic--e643c4aa-dc7d-43d9-b36e-f13d733f8e9a", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1116", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=13, 14", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "Outlook rule creation, form load, or homepage redirection", "name": "WinEventLog:Application", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune based on expected Office process tree (e.g., WINWORD.EXE spawning cmd.exe)", "field": "ParentProcessName"}, {"description": "Specific keys related to Office startup such as Outlook Today, AddIns, or Template Macros", "field": "RegistryPath"}, {"description": "Window of process execution after user login or Outlook launch", "field": "TimeWindow"}, {"description": "Detect persistence within high-value user mailboxes (e.g., admin, finance, C-suite)", "field": "UserContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3815', 0, 153, '09-mitre-attack', 'retrieved', '1DC1D457512899EBEEB904826E7639050851E3910FD402E2F0F3BDD8D3B4C749', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
