VALUES ('doc-09-mitre-attack-p0-3816', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unexpected firmware image uploads via TFTP/FTP/SCP. Configuration changes modifying boot image pointers. Logs showing boot variable redirection to non-standard images. Anomalous reboots immediately following firmware changes not tied to patch schedules.", "external_references": [{"external_id": "AN0777", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0278#AN0777"}], "id": "x-mitre-analytic--e64aebfd-8343-45ec-bdce-6681a8255637", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0777", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Boot variable modified to point to non-standard or unsigned image", "name": "networkdevice:config", "x_mitre_data_component_ref": "x-mitre-data-component--b9d031bb-d150-4fc6-8025-688201bf3ffd"}, {"channel": "Unexpected firmware image upload events via TFTP/FTP/SCP", "name": "networkdevice:firmware", "x_mitre_data_component_ref": "x-mitre-data-component--4dcd8ba3-2075-4f8b-941e-39884ffaac08"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Known good firmware image hashes allowed for boot.", "field": "ApprovedFirmwareHashes"}, {"description": "Timeframes during which firmware updates are expected.", "field": "MaintenanceWindows"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3816', 0, 119, '09-mitre-attack', 'retrieved', '4DD95837FAB1F72869E0D2610A38A9A2E67BDC36C1219E4C076A254BA3CDD82D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
