VALUES ('doc-09-mitre-attack-p0-3818', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of unpacking behavior through abnormal memory allocation, followed by executable code injection and execution from non-image sections.", "external_references": [{"external_id": "AN0066", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0023#AN0066"}], "id": "x-mitre-analytic--e6a7eeb3-0652-460c-b68b-f17d2ed82822", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0066", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "To scope detections to suspicious parent-child process relationships typical of loaders or droppers.", "field": "ParentProcessName"}, {"description": "To tune for unusually large virtual memory allocations that might indicate unpacked payloads.", "field": "AllocationSizeThreshold"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3818', 0, 101, '09-mitre-attack', 'retrieved', '699CBA83CC27256D315DC5CDAF8C83198E7495DC07E8F845C4609C29ECB0BC0C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
