VALUES ('doc-09-mitre-attack-p0-3819', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Application crash or repeated restart cycle triggered by malformed input or exploit file, observed via unified logs and process crash monitoring.", "external_references": [{"external_id": "AN0852", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0304#AN0852"}], "id": "x-mitre-analytic--e6b92e19-5bc8-414b-b200-96ed6d286388", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0852", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Crash log entries for a process receiving malformed input or known exploit patterns", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Unusual child process tree indicating attempted recovery after crash", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Binary crash hash or affected dylib for distinguishing malicious faults from benign ones", "field": "CrashSignature"}, {"description": "File, IPC, or network-based input that may be triggering exploitation (e.g., PDF file, POST request)", "field": "InputVector"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3819', 0, 126, '09-mitre-attack', 'retrieved', 'E4C3A330BE840C8BF6C3FD5C46A45CCC695367242D6EAA910AABB0A16C886B6D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
