VALUES ('doc-09-mitre-attack-p0-3820', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Process opens /dev/bpf* (libpcap) or loads NetworkExtension filter, then after a crafted inbound packet the same process initiates an outbound connection to the trigger origin.", "external_references": [{"external_id": "AN0464", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0162#AN0464"}], "id": "x-mitre-analytic--e6d04b50-7bdc-480e-9bda-291db9b270f6", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0464", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open/openat of /dev/bpf*; ioctl BIOCSETF-like operations.", "name": "OpenBSM:AuditTrail", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "First outbound connection from the same PID/user shortly after an inbound trigger.", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "Inbound one-off packet to uncommon port → outbound SF to same src_ip within TimeWindow.", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Alternate BPF device paths if customized (default /dev/bpf*).", "field": "BPFDevicePath"}, {"description": "Relax thresholds on known developer tooling hosts (Xcode, instrumenting tools).", "field": "DeveloperMode"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3820', 0, 135, '09-mitre-attack', 'retrieved', '4FD42C64002FD015D9B4A06E3C7AA6771AE70612E074CA18BD79D4A518A021EE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
