VALUES ('doc-09-mitre-attack-p0-3821', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of command-line activity exhibiting syntactic obfuscation patterns, such as excessive escape characters, base64 encoding, command concatenation, or outlier command length and entropy.", "external_references": [{"external_id": "AN1394", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0505#AN1394"}], "id": "x-mitre-analytic--e6e98024-2fa7-444c-af90-32ec5d4d2666", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1394", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Used to flag base64 or token-heavy command-line strings", "field": "CommandLineEntropyThreshold"}, {"description": "Escape character and symbol frequency in command-line strings", "field": "SuspiciousCharacterCount"}, {"description": "Window between command execution and follow-up child or file write behavior", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3821', 0, 104, '09-mitre-attack', 'retrieved', '653FC08EF1B1756F29C46C37DCD88F6D51B6E79971CDA1B3EBEAEAE3C24652CD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
