VALUES ('doc-09-mitre-attack-p0-3822', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Abuse of mmc.exe to execute non-Microsoft or user-staged .msc files and malicious COM CLSIDs. Behavioral chain: (1) suspicious mmc.exe invocation with /a or -Embedding and non-standard .msc path → (2) COM activation of non-baseline CLSIDs by mmc.exe → (3) mmc.exe loads non-baseline DLLs (user-writable/UNC/unsigned) → (4) optional network/DNS activity from mmc.exe.", "external_references": [{"external_id": "AN0622", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0222#AN0622"}], "id": "x-mitre-analytic--e6f38f76-4e60-4b8a-881c-5d3f206e912c", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0622", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=12", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--7f70fae7-a68d-4730-a83a-f260b9606129"}, {"channel": "EventCode=13, 14", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "CLSID activation events where ProcessName=mmc.exe and CLSID not in allowed baseline", "name": "WinEventLog:Microsoft-Windows-COM/Operational", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Correlation window (e.g., 5–10 minutes) tying .msc creation → mmc.exe start → module loads → COM/net activity.", "field": "TimeWindow"}, {"description": "Set of Microsoft-supplied .msc names/paths allowed in the environment to suppress noise.", "field": "AllowedMSCList"}, {"description": "Regex for user-writable and network paths indicating risky .msc staging (Users, AppData, Downloads, Desktop, UNC).", "field": "SuspiciousMSCPathRegex"}, {"description": "Baseline of CLSIDs expected to be activated by mmc.exe; alert on unknown/new.", "field": "AllowedCLSIDs"}, {"description": "Expected parents for mmc.exe (explorer.exe, services) vs. unusual (powershell, wscript, office apps).", "field": "ParentProcessAllowList"}, {"description": "Flag when signed mmc.exe results in loading unsigned DLLs.", "field": "SignedToUnsignedTransition"}, {"description": "Approved external ranges/domains to exclude when mmc.exe makes network requests.", "field": "ExternalIPAllowlist"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3822', 0, 261, '09-mitre-attack', 'retrieved', '6091329081B290D37584B611775F6CF62D6746113068F4BE1976A5F7150A056E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
