VALUES ('doc-09-mitre-attack-p0-3823', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Cause→effect chain in cloud consoles: (1) user clicks link then invokes instance/image creation via API, (2) instance/image originates from external AMI or unknown image, (3) instance immediately egresses or retrieves payloads.", "external_references": [{"external_id": "AN1318", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0478#AN1318"}], "id": "x-mitre-analytic--e707cd33-8e20-4b1d-ad3f-fd3a3233fcdd", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1318", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "RunInstances,CreateImage", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--b5b0e8ae-7436-4951-950a-7b83c4dd3f2c"}, {"channel": "StartInstances", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--f8213cde-6b3a-420d-9ab7-41c9af1a919f"}, {"channel": "first 5m egress to unknown ASNs", "name": "gcp:vpcflow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "AMI/image allow-list with owners.", "field": "ApprovedImages"}, {"description": "High-risk identities (federated, external IdP).", "field": "UserContext"}, {"description": "5–30 minutes from console/API action to network egress.", "field": "TimeWindow"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3823', 0, 119, '09-mitre-attack', 'retrieved', 'EB609ACE132DFF64190846DDD3957230A7F971FC3F8D952A8D89EDF09CA5BEAA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
