VALUES ('doc-09-mitre-attack-p0-3824', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of edits or additions to /etc/rc.common, /Library/StartupItems, or /System/Library/StartupItems and associated script execution during login or reboot.", "external_references": [{"external_id": "AN0659", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0237#AN0659"}], "id": "x-mitre-analytic--e716b209-5b06-4bc4-843f-cbe4c51ddc0d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0659", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process events", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "file activity", "name": "fs:fsusage", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Name of script or LaunchDaemon plist is tunable across environments", "field": "script_name"}, {"description": "Time window between modification and reboot/login", "field": "event_interval"}, {"description": "Permissions on modified RC files can vary between systems", "field": "file_permission"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3824', 0, 105, '09-mitre-attack', 'retrieved', '1B9625A26B4306390B64C4A4505030C6C89E58EE313E478A1F7A59E1C71CB1AF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
