VALUES ('doc-09-mitre-attack-p0-3825', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of PubPrn.vbs via cscript.exe using the ''script:'' moniker to load and execute a remote .sct scriptlet file, bypassing signature validation and proxying remote payloads through a signed Microsoft script host.", "external_references": [{"external_id": "AN1464", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0528#AN1464"}], "id": "x-mitre-analytic--e7444be7-3c0a-4ff2-927d-f623af05936d", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1464", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detects ''script:'' moniker with HTTP/HTTPS URI as argument to pubprn.vbs", "field": "CommandLineRegex"}, {"description": "May vary between cscript.exe, wscript.exe, or cmd.exe depending on execution method", "field": "ParentProcessName"}, {"description": "Used to detect external domains being contacted for remote scriptlet execution", "field": "NetworkDestinationDomain"}, {"description": "Maximum allowed time delta between pubprn.vbs invocation and network connection or child process", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3825', 0, 155, '09-mitre-attack', 'retrieved', '95EA59DACACF363002AADF8F3AAB2053E2AACFE34EF8541F33E0C4794A2CDAED', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
