VALUES ('doc-09-mitre-attack-p0-3826', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Correlates Office 365 or Google Workspace audit logs for spoofed sender addresses, failed email authentication, and anomalies in message delivery metadata. Defender observes failed SPF/DKIM checks and domain mismatches tied to suspicious campaigns.", "external_references": [{"external_id": "AN1205", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0431#AN1205"}], "id": "x-mitre-analytic--e7a0e155-e0bc-45b5-b0ef-98ec4f5eea63", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1205", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "AuthenticationFailures (SPF/DKIM/DMARC) OR Domain Mismatch", "name": "saas:email", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines thresholds for spoofed messages volume before alerts trigger, reducing noise for isolated misconfigs.", "field": "MessageVolumeThreshold"}, {"description": "Restricts higher-sensitivity detection to high-value groups (executives, admins, finance) for efficiency.", "field": "TargetedUserGroups"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3826', 0, 114, '09-mitre-attack', 'retrieved', '0D0A44A61BA121263730E5A110D5BEF371455D93D278EAEB3BE8C53550ABBD11', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
