VALUES ('doc-09-mitre-attack-p0-3827', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Executable or script payloads lacking symbol information and readable strings that are created or dropped by unusual or short-lived processes.", "external_references": [{"external_id": "AN0055", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0019#AN0055"}], "id": "x-mitre-analytic--e7b2c8da-d54d-446a-a7f6-062fe234a8cc", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0055", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "File Metadata Inspection (Low String Entropy, Missing PDB)", "name": "EDR:file", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Payloads with extremely low string entropy may indicate stripped or obfuscated binaries", "field": "EntropyThreshold"}, {"description": "Used to scope or whitelist common system builders, compilers, or admin tools", "field": "ParentProcessName"}, {"description": "Correlates file creation and process spawning within a short timeframe", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3827', 0, 127, '09-mitre-attack', 'retrieved', 'F4670C91D0BE385FB954F724EBF3490D9E0FC9D213BCB918FE4ABDD6D077B7F4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
