VALUES ('doc-09-mitre-attack-p0-3828', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detect the creation or modification of common media file formats (e.g., .jpg, .png, .wav) following suspicious process activity like compression or encryption, especially when paired with lateral movement or exfiltration behavior.", "external_references": [{"external_id": "AN0651", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0235#AN0651"}], "id": "x-mitre-analytic--e7be37f1-88f9-45e3-91d0-1ff37bc94892", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0651", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "Session Transfer Content", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Allows tuning of monitored file types (e.g., .jpg, .png, .docx).", "field": "FileExtensionFilter"}, {"description": "Threshold for flagging potential hidden data in outbound payloads.", "field": "PayloadEntropyThreshold"}, {"description": "Time window between media creation and network transmission.", "field": "ExecutionToExfilTimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3828', 0, 133, '09-mitre-attack', 'retrieved', 'B1AE0D2E58BDA371804F0181AC82259F30582E50490E78432B5456DA98D1D185', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
