VALUES ('doc-09-mitre-attack-p0-3829', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use of stolen Kerberos tickets or token impersonation resulting in logon sessions from accounts without expected interactive logon events.", "external_references": [{"external_id": "AN0954", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0338#AN0954"}], "id": "x-mitre-analytic--e7ce6bda-a4d3-43a4-afa0-34d57c34ef0d", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0954", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4624, 4648", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Allows tuning of how far apart related logon and process events can be correlated", "field": "TimeWindow"}, {"description": "Customize for high-value or service accounts with restricted access policies", "field": "UserContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3829', 0, 101, '09-mitre-attack', 'retrieved', '6ECD0309024BE28C182F683DD04F354D15E975D97A531BC0E2A5B61FFCB3861B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
