VALUES ('doc-09-mitre-attack-p0-3830', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "CLI-based execution of interface and routing discovery commands (e.g., `show ip interface`, `show arp`, `show route`) over Telnet, SSH, or console.", "external_references": [{"external_id": "AN0563", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0195#AN0563"}], "id": "x-mitre-analytic--e7debe02-4326-48ae-aa22-59c2a847d3e7", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0563", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "None", "name": "networkdevice:cli", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Highlight low-privileged or non-routine users performing discovery", "field": "Username"}, {"description": "Allow for tuning based on command regex or frequency", "field": "CommandString"}, {"description": "SSH vs Telnet vs Console session logging scope", "field": "TransportType"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3830', 0, 100, '09-mitre-attack', 'retrieved', '9349B6BFF742CD65A0FDACC8B0BDA601089038CA0B89016A9E2B72CC84C999B6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
