VALUES ('doc-09-mitre-attack-p0-3832', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Curl, wget, or custom HTTP clients initiated by uncommon user accounts or cron jobs to popular web services, with no observed response parsing logic.", "external_references": [{"external_id": "AN1600", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0581#AN1600"}], "id": "x-mitre-analytic--e83afa89-0ec1-49e7-b351-eef67b085480", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1600", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "OUTBOUND", "name": "iptables:LOG", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "May tune to detect unknown parents like custom scripts or reverse shells", "field": "ParentProcess"}, {"description": "May adjust based on known curl/wget C2 behaviors", "field": "CommandLineArgs"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3832', 0, 101, '09-mitre-attack', 'retrieved', '8580282D6E7678AD54494FDB8C00E05BFF9931418875E0C4A0090B01EEADD936', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
