VALUES ('doc-09-mitre-attack-p0-3833', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor Windows Registry modifications to Winlogon keys (Shell, Userinit, Notify) that introduce new executable or DLL paths. Correlate these changes with subsequent DLL loading, image loads, or process creation originating from winlogon.exe or userinit.exe. Abnormal child process lineage or unauthorized binaries in C:\\Windows\\System32 may indicate abuse.", "external_references": [{"external_id": "AN1133", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0404#AN1133"}], "id": "x-mitre-analytic--e8569cdc-a018-4eee-95d9-5979cebae519", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1133", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "modification to Winlogon registry keys such as Shell, Notify, or Userinit", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "Enumerate Winlogon subkeys for unknown or unsigned binaries", "name": "Autoruns:RegistryScan", "x_mitre_data_component_ref": "x-mitre-data-component--ed0dd8aa-1677-4551-bb7d-8da767617e1b"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Time correlation between registry modification and malicious module load or process creation", "field": "TimeWindow"}, {"description": "Privilege level or user context under which registry changes or process executions occur", "field": "UserContext"}, {"description": "Whether to validate binary signatures when DLLs are loaded via Winlogon helper paths", "field": "BinarySignatureValidation"}, {"description": "Scope of directories considered suspicious for helper DLLs (e.g., temp paths, non-System32 locations)", "field": "ExecutablePathScope"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3833', 0, 189, '09-mitre-attack', 'retrieved', '028CC25453BA2863C887962DAB871D9260504CCC8483E956E808A8208BB7D2EE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
