INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3834', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary with access to domain management tools (e.g., `realmd`, `samba-tool`, `ldapmodify`) creates a new domain user via command-line utilities. Behavior chain: LDAP command or script triggers → user entry added in AD via Kerberos/LDAP traffic.", "external_references": [{"external_id": "AN0007", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0003#AN0007"}], "id": "x-mitre-analytic--e86081ab-aad1-48a1-abd8-5a5c8c7c936a", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0007", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execution of realmd, samba-tool, or ldapmodify with user-related arguments", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "TGS-REQ and AS-REQ seen for new user shortly after domain-modifying process", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "realmd, samba-tool, ldapmodify or custom script", "field": "DomainToolUsed"}, {"description": "Expected Kerberos traffic from new domain account within X minutes of command", "field": "TrafficWindow"}, {"description": "Script execution from interactive shell vs scheduled task", "field": "SessionType"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3834', 0, 139, '09-mitre-attack', 'retrieved', '948C9961B75090377E4264C4803AA72DD94F2322996F253E8536D147AB33C69F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
