INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3835', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Correlation of Registry key creation/modification events under known Run/Startup keys with new or unusual binary paths or script-based payloads. Multi-event detection includes registry modification followed by process execution from non-standard directories or abnormal parent-child process relationships.", "external_references": [{"external_id": "AN1032", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0365#AN1032"}], "id": "x-mitre-analytic--e863e865-8ecc-47ce-b736-eec54b6399d6", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1032", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=13, 14", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "New startup folder shortcut or binary placed in Startup directory", "name": "WinEventLog:Microsoft-Windows-Shell-Core", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Full path of the binary/script being registered in Run keys. Tunable to exclude known software baselines.", "field": "ImagePath"}, {"description": "Tunable list of startup-related registry keys to monitor more/less aggressively based on enterprise software context.", "field": "RegistryKeyPath"}, {"description": "Correlate registry key creation and process execution within this window. Defaults between 5–10 minutes.", "field": "TimeWindow"}, {"description": "Filter for specific user SIDs or exclude known admin/script accounts.", "field": "UserContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3835', 0, 170, '09-mitre-attack', 'retrieved', 'D4DDDF8F6BEE1C8031FF39511C7B4CF0D6C4E4E039EECD77EA4F8F1B4BAC7CBC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
