VALUES ('doc-09-mitre-attack-p0-3836', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Registry key modification to AppInit_DLLs value followed by anomalous DLL loading by processes importing user32.dll, especially unsigned or uncommon DLLs, suggesting unauthorized AppInit persistence or privilege escalation.", "external_references": [{"external_id": "AN1536", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0557#AN1536"}], "id": "x-mitre-analytic--e886b9c8-2187-4363-9043-1e5c60d75363", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1536", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "EventCode=13, 14", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Paths or filenames of known-good DLLs to exclude from alerting", "field": "ImagePathWhitelist"}, {"description": "Context of the user modifying the registry key (e.g., admin vs standard user)", "field": "UserContext"}, {"description": "Temporal threshold for correlating registry modification and DLL load", "field": "TimeWindow"}, {"description": "Filter or flag unsigned or suspiciously signed DLLs", "field": "DLLSignatureStatus"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3836', 0, 137, '09-mitre-attack', 'retrieved', '7F9621CFCAF69CA96A57DFEAB08914EACB8BD1B1BCAB615AE5EC1BFF9F949DB0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
