VALUES ('doc-09-mitre-attack-p0-3837', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "CLI-based or API-based network call from the hypervisor to external staging host, shortly followed by a connection to a second external IP by a spawned process or scheduled task.", "external_references": [{"external_id": "AN0640", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0228#AN0640"}], "id": "x-mitre-analytic--e8c91885-736e-4348-ba09-2acfbdd8b176", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0640", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "CLI network calls", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "process or cron activity", "name": "esxi:cron", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detect unknown or obfuscated task names launching follow-up stages", "field": "ScheduledTaskName"}, {"description": "Scope multiple IP destinations outside corporate ranges in short sequence", "field": "DestinationIP"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3837', 0, 110, '09-mitre-attack', 'retrieved', '1BB74470F6A3757F4BF6FD4A2E8F9F92B4C88FF8C5340073BDD6510E50B75FD9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
