VALUES ('doc-09-mitre-attack-p0-3838', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Abuse of DYLD_INSERT_LIBRARIES or hijacking framework paths for malicious libraries. Defender observes processes invoking abnormal dylibs, modified plist files, or persistence entries pointing to altered binaries.", "external_references": [{"external_id": "AN0611", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0218#AN0611"}], "id": "x-mitre-analytic--e8fc16bf-6654-4912-96c9-208e4c5bbaa6", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0611", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Execution of process with DYLD_INSERT_LIBRARIES set", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Modified application plist or binary replacement in /Applications", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "Dylib loaded from abnormal location", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Baseline directories for dylib loading.", "field": "AllowedDylibPaths"}, {"description": "Specific plist files used for persistence monitoring.", "field": "PlistMonitors"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3838', 0, 117, '09-mitre-attack', 'retrieved', '07FA1769C74F