VALUES ('doc-09-mitre-attack-p0-3839', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Addition of credentials (keys, app passwords, x.509 certs) to existing cloud accounts, service principals, or OAuth apps via portal or API by non-standard identities or IP ranges.", "external_references": [{"external_id": "AN1469", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0531#AN1469"}], "id": "x-mitre-analytic--e95d8309-8435-4c32-9ac3-38e350c170c5", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1469", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Add service principal credentials, app password added, app role assignment", "name": "azure:audit", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "App password or legacy auth activity bypassing MFA policies.", "field": "MFABypassMechanism"}, {"description": "Expected IPs allowed to perform admin identity operations.", "field": "SourceIPAllowlist"}, {"description": "Track types like `client_secret`, `certificate`, `password`, `federated`.", "field": "ApplicationCredentialType"}], "x_mitre_platforms": ["Identity Provider"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3839', 0, 115, '09-mitre-attack', 'retrieved', '59795594844D4851129697DE098A2B59334F356B8168DE05AB8C622EEB1974D7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
