VALUES ('doc-09-mitre-attack-p0-3840', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use unified logs to detect unusual DNS responses correlated with subsequent connections to calculated or non-standard ports. Monitor non-browser apps making repeated outbound connections that deviate from expected patterns.", "external_references": [{"external_id": "AN0730", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0262#AN0730"}], "id": "x-mitre-analytic--e95ed4e2-d6bc-4a6f-acbc-bdbfcbaca158", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0730", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "DNS responses followed by connections to ports outside standard ranges", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "Unexpected processes making network calls based on DNS-derived ports", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Expected processes allowed to open non-standard ports (e.g., developer tools)", "field": "ProcessAllowlist"}, {"description": "Volume of unusual connections needed before flagging as suspicious", "field": "ConnectionVolumeThreshold"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3840', 0, 122, '09-mitre-attack', 'retrieved', '200DEF3B4A45DD445197B619FEDAEAA5A3F9FC8B8DE4F3212AAF42C2772B67CE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
