VALUES ('doc-09-mitre-attack-p0-3841', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detect anomalous OAuth or SSO logins that repeatedly generate MFA challenges, particularly where MFA approvals are denied or timed out by the user.", "external_references": [{"external_id": "AN0453", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0160#AN0453"}], "id": "x-mitre-analytic--e96b0210-f7d5-43ac-bf73-893f243f6015", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0453", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "MFAChallengeIssued", "name": "saas:okta", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Identify which MFA service provider logs are in use (Okta, Duo, Microsoft Authenticator)", "field": "MFAProvider"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3841', 0, 84, '09-mitre-attack', 'retrieved', 'F069DA206C89BBB1AFB00EAD29B7A12EE09429B6EC46B25543267E2CCDCC5C5A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
