VALUES ('doc-09-mitre-attack-p0-3842', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Much of this activity may have a very high occurrence and associated false positive rate, as well as potentially taking place outside the visibility of the target organization, making detection difficult for defenders.\n\nDetection efforts may be focused on related stages of the adversary lifecycle, such as during Initial Access.", "external_references": [{"external_id": "AN1975", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0843#AN1975"}], "id": "x-mitre-analytic--e9808ca9-3019-4395-b2d8-717f5d4863fe", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1975", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["PRE"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3842', 0, 86, '09-mitre-attack', 'retrieved', '4BA8D16C367BAAA022159115BCAC9F70D8308CFC48657A3084EDF1014F94C0C0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
