VALUES ('doc-09-mitre-attack-p0-3843', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects when a script or binary is named with misleading or benign-looking extensions (.jpg, .doc) and is then executed via command line or a scheduled task. Includes ELF header mismatches and content-type inconsistencies on disk.", "external_references": [{"external_id": "AN0631", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0226#AN0631"}], "id": "x-mitre-analytic--e9ba7101-369f-48c6-8e6d-075ddd5744ba", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0631", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Read headers and detect MIME type mismatch", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Linux-targeted masquerade extensions (.jpg, .pdf, .png)", "field": "benign_extensions"}, {"description": "Whether to parse file signatures or MIME types from file headers", "field": "HeaderInspectionEnabled"}, {"description": "Monitored directory scope for adversarial execution (e.g., /tmp/, /home/username/Downloads)", "field": "ExecPathScope"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3843', 0, 127, '09-mitre-attack', 'retrieved', 'AD9C790291ED40297581E2B13581CC1391C571E7317E07663C91E95CC319480D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
