VALUES ('doc-09-mitre-attack-p0-3844', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of suspicious use of shell utilities or scripts that decode or decrypt a payload and execute it without writing to disk.", "external_references": [{"external_id": "AN0238", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0087#AN0238"}], "id": "x-mitre-analytic--e9de9003-46e9-438f-929a-94a33c2eb5bd", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0238", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=3, 22", "name": "linux:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Normal usage of `base64`, `openssl`, or `gpg` varies by user/role.", "field": "UserContext"}, {"description": "Parent-child process chains may differ across deployments.", "field": "ProcessLineage"}, {"description": "Time between decode and execution is implementation-specific.", "field": "TimeWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3844', 0, 107, '09-mitre-attack', 'retrieved', '843B42941A38C71B3170F933EF298CAC0511CD17506A0B3A26B7FB8BA491C856', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
