VALUES ('doc-09-mitre-attack-p0-3845', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects script or user activity copying files to a central temp or /mnt directory followed by archive/compression utilities.", "external_references": [{"external_id": "AN0041", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0014#AN0041"}], "id": "x-mitre-analytic--e9ee76c8-e959-4925-8f93-4b8fb66bc9f1", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0041", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "creat", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "e.g., /tmp/, /var/tmp/, /mnt/", "field": "StagingDirectoryList"}, {"description": "grep for ''tar'', ''zip'', ''gzip'', ''7z''", "field": "ArchivingCommandPatterns"}, {"description": "Interactive or elevated shells running archiving commands", "field": "UserContext"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3845', 0, 95, '09-mitre-attack', 'retrieved', '90E8EEDD538A6A3710E745736595BF45DDED7851E6BEC98F4D54D6D7D13328C3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
