VALUES ('doc-09-mitre-attack-p0-3846', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects abuse of verclsid.exe to execute COM objects by monitoring process creation, CLSID arguments, DLLs or scriptlet engines loaded into memory, and If the CLSID points to remote SCT/HTA content, verclsid.exe makes outbound connections.", "external_references": [{"external_id": "AN0118", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0042#AN0118"}], "id": "x-mitre-analytic--e9f451b7-1b9e-420e-983a-3442547b7180", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0118", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "EventCode=13, 14", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Baseline CLSIDs frequently invoked by verclsid.exe in normal shell extension verification.", "field": "AllowedCLSIDs"}, {"description": "Unusual parents (e.g., winword.exe, excel.exe) spawning verclsid.exe should be treated as suspicious.", "field": "ParentProcessFilter"}, {"description": "Correlation window between verclsid.exe start, module load, and network activity.", "field": "TimeWindow"}, {"description": "Restrict detection to external IPs not in approved ranges to cut noise.", "field": "ExternalIPRange"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3846', 0, 158, '09-mitre-attack', 'retrieved', '438976BF7ED5A0FC66A3A034A67520F217BA3DA3049F86C12C0F228774A6237C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
