VALUES ('doc-09-mitre-attack-p0-3848', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Installation of malicious IIS/Apache/SQL server modules that later execute command-line interpreters or establish outbound connections.", "external_references": [{"external_id": "AN1507", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0547#AN1507"}], "id": "x-mitre-analytic--ea250997-091b-4c5e-8827-a41f03e34caf", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1507", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4698", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Unusual DLL/plugin registration for IIS/SQL/Apache or unexpected error logs", "name": "WinEventLog:Application", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Time delta between module install and process execution (e.g., persistence delay).", "field": "TimeWindow"}, {"description": "Custom server wrapper processes or renamed webserver processes may require tuning.", "field": "ParentProcessName"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3848', 0, 108, '09-mitre-attack', 'retrieved', '8A31F9A310744FACA496D9BEDCCFDEDC4BA3CDCEE366B3B7061C3DD46