VALUES ('doc-09-mitre-attack-p0-3849', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary executes systemctl or service stop targeting high-value services (e.g., mysql, sshd), possibly followed by rm or shred against data stores. Behavioral chain: sudo/su usage + stop command + /var/log/messages or syslog entries + file access/delete.", "external_references": [{"external_id": "AN0062", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0021#AN0062"}], "id": "x-mitre-analytic--ea793457-89e6-47d2-8ae1-7fd2bd814f82", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0062", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve of systemctl or service stop", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "unlink/unlinkat on service binaries or data targets", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}, {"channel": "service stopped messages", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Window between service stop and suspicious file deletion", "field": "TimeWindow"}, {"description": "Username or UID executing service stop command", "field": "ExecUser"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3849', 0, 127, '09-mitre-attack', 'retrieved', '3520C2EE9A8A3BE2E8C45AE791ACF0959F9DA463FD2135201815474D7DC6F0C8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
