INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3850', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Access of mounted cloud shares or document repositories via browser, terminal, or Finder by users not typically interacting with those resources. Includes script-based enumeration or mass download.", "external_references": [{"external_id": "AN1163", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0413#AN1163"}], "id": "x-mitre-analytic--eac7b88d-0ee2-4fbf-9e0b-ea73c376ccb3", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1163", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "access to /Volumes/SharePoint or network mount", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "curl, python scripts, rsync with internal share URLs", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Paths to sensitive volumes may differ based on org setup.", "field": "AccessedMountPath"}, {"description": "Expected user groups that typically access shared data.", "field": "UserGroup"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3850', 0, 114, '09-mitre-attack', 'retrieved', '9739D8CA485859A935AF7FAC0134E0775FD29698A59455E46500FF8C430BDE20', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
