INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3851', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "A process or terminal command outside of standard shell utilities reads the user''s .bash_history file. On macOS, unified logs or telemetry tools like EndpointSecurity (ESF) may observe file read APIs or terminal process lineage that shows non-user-initiated access.", "external_references": [{"external_id": "AN1086", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0385#AN1086"}], "id": "x-mitre-analytic--ead38dff-ee26-477d-be5a-69b52dc8bd50", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1086", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open or read syscall to ~/.bash_history", "name": "macos:endpointsecurity", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "non-shell process tree accessing bash history", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Scope access to .bash_history only if parent is not Terminal.app or bash/zsh", "field": "ParentProcessCheck"}, {"description": "Raise priority if .bash_history is accessed multiple times in short window", "field": "AccessFrequency"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3851', 0, 128, '09-mitre-attack', 'retrieved', 'A4368ECDB65FA3EB254A1068A92AA278181DF29BF9BC323DB40CBBBBFB6838C3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
