VALUES ('doc-09-mitre-attack-p0-3854', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Observes creation or modification of LaunchAgent/LaunchDaemon property list files combined with anomalous plist payload execution after user logon", "external_references": [{"external_id": "AN0766", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0274#AN0766"}], "id": "x-mitre-analytic--eb0d78b0-f35d-49db-a8a5-d3cf840db6fd", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0766", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Observed loading of new LaunchAgent or LaunchDaemon plist", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}, {"channel": "write", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "Execution of binary listed in newly modified LaunchAgent plist", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Organizations may use specific keys or additional payload parameters", "field": "PlistKey"}, {"description": "Tunable based on expected delay between plist write and execution", "field": "TimeWindow"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3854', 0, 115, '09-mitre-attack', 'retrieved', '1E3A2CE3F52A96F9D14CA7780663770BE4C1D738B8CA3550B06BBE4BDF15EB69', 'v1', '{"s