VALUES ('doc-09-mitre-attack-p0-3855', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Role escalation (e.g., Editor → Owner) in cloud collaboration tools (Google Workspace, O365) or file sharing apps to maintain elevated access.", "external_references": [{"external_id": "AN0270", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0096#AN0270"}], "id": "x-mitre-analytic--eb4a55f0-eff2-40f8-912e-43ba7e34603c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0270", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Admin Activity > Role Change or Sharing Change", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Threshold for labeling sensitive document access escalation.", "field": "SharingSensitivityLabel"}, {"description": "Track changes made across organizational boundaries (e.g., guest users).", "field": "CrossOrgChanges"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3855', 0, 95, '09-mitre-attack', 'retrieved', 'DBDE3231E3EFFC65EE1C83074B2D727575669160C4A3164D9538E8AFDE30900A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
