VALUES ('doc-09-mitre-attack-p0-3857', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "A process (non-system or user-initiated) accesses private key files in user profile paths or system certificate stores followed by potential network connections or compression activity.", "external_references": [{"external_id": "AN1516", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0549#AN1516"}], "id": "x-mitre-analytic--eb569d45-a5b6-47df-a098-bdb26ef0597f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1516", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=5145", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--f5468e67-51c7-4756-9b4f-65707708e7fa"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Regex for matching key file extensions (.pem, .pfx, .ppk, etc.) or known certificate directories like C:\\Users\\*\\.ssh\\", "field": "FilePathRegex"}, {"description": "Set of known benign certificate management tools to exclude (e.g., certutil.exe, ssh.exe)", "field": "ParentProcessName"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3857', 0, 116, '09-mitre-attack', 'retrieved', '7BC0967B6E5AA06368AD52647