VALUES ('doc-09-mitre-attack-p0-3858', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Abnormal usage of Preview, ImageMagick, or binary editors to alter images/documents, followed by exfiltration or outbound connections with mismatched file MIME types or payload structure.", "external_references": [{"external_id": "AN0653", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0235#AN0653"}], "id": "x-mitre-analytic--eb6edb6d-9684-4ef7-96b2-13c087276d80", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0653", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "File creation", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "process_events", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "C2 exfiltration", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Allow tuning based on expected apps calling image-editing tools.", "field": "ParentProcessBaseline"}, {"description": "Gap between file manipulation and outbound connection.", "field": "TimeDelta"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3858', 0, 106, '09-mitre-attack', 'retrieved', 'B23697CDEAB3AAEB54C4F58930CF2700EE562D268E269C46AA32E10B442EF253', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "