VALUES ('doc-09-mitre-attack-p0-3859', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Spoofed outbound packets sent to amplification services from command-line tools or scripts, combined with abnormal outbound packet volume on known reflector ports", "external_references": [{"external_id": "AN1141", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0408#AN1141"}], "id": "x-mitre-analytic--eb7692b0-5592-4d23-ba06-fdded48a2a0d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1141", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Execution of spoofing tools (e.g., hping3, nping, scapy) sending UDP packets to known amplifier ports", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "Outbound UDP floods targeting common reflection services with spoofed IP headers", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "Outbound network saturation with minimal process activity", "name": "sar:network", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Sliding interval for detecting volumetric anomalies", "field": "TimeWindow"}, {"description": "Which protocols to watch (e.g., DNS, NTP, SSDP, Memcached)", "field": "AmplificationProtocolList"}, {"description": "Set of binaries and scripts commonly abused for spoofing/reflection", "field": "ExecutionToolList"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3859', 0, 142, '09-mitre-attack', 'retrieved', '098AC19CE3E7212E74FF75CEA5C233283B5F5116DCC07ACBFE1149135CEFAEB7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
