VALUES ('doc-09-mitre-attack-p0-3860', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Identifies use of sh/bash/zsh in suspicious context, such as user scripts launched from non-standard apps (e.g., Preview.app), embedded in LaunchDaemons, or executed outside Terminal.app. Looks for misuse in Automator, LaunchAgents, or NSAppleScript-executed shell.", "external_references": [{"external_id": "AN1082", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0384#AN1082"}], "id": "x-mitre-analytic--ebd61e14-852c-403b-8b50-7e15a1c32d05", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1082", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "log stream --predicate ''eventMessage contains \"exec\"''", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "launchd + process_events", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "system.log, asl.log", "name": "macos:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Execution from /Users/Shared, ~/Library/LaunchAgents, /tmp.", "field": "ScriptLocation"}, {"description": "Shells spawned from Preview, Safari, or AppleScript.", "field": "ParentProcess"}, {"description": "Detection thresholds may differ for admin vs standard users.", "field": "UserRole"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3860', 0, 128, '09-mitre-attack', 'retrieved', '88646110B1F20E660D644B71AC19CB937862BC9A9714AE4974EB471BDFEE73EB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
