VALUES ('doc-09-mitre-attack-p0-3862', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of binaries where the on-disk filename does not match PE metadata such as OriginalFilename or InternalName. Often observed with renamed LOLBAS or system binaries like rundll32, powershell, or psexec.", "external_references": [{"external_id": "AN0012", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0005#AN0012"}], "id": "x-mitre-analytic--ec036273-4e90-465e-b115-a69bbb68dde4", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0012", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "None", "name": "EDR:AMSI", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Filter by suspicious or non-standard directory paths", "field": "ImagePath"}, {"description": "Enable tuning based on mismatch rules between metadata and disk filename", "field": "PEInternalNameMismatch"}, {"description": "Flag unusual or rare argument combinations for LOLBAS-like tools", "field": "CommandLinePattern"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3862', 0, 123, '09-mitre-attack', 'retrieved', 'B65A9AC14D237331115526B5E50210465F35E3B0510582BC0210785F7F7D6754', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
