VALUES ('doc-09-mitre-attack-p0-3863', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary modifies GPO containers or files under SYSVOL using LDAP, ADSI, PowerShell (e.g., New-GPOImmediateTask) or GUI tools. This includes directory object changes (e.g., gPCFileSysPath), delegation assignments (SeEnableDelegationPrivilege), and SYSVOL file writes (ScheduledTasks.xml, GptTmpl.inf).", "external_references": [{"external_id": "AN0854", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0305#AN0854"}], "id": "x-mitre-analytic--ec6e1f3c-e9ff-4944-a426-863eaf9979ea", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0854", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=5136", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--5b8b466b-2c81-4fe7-946f-d677a74ae3db"}, {"channel": "EventCode=4663, 4670, 4656", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "EventCode=4704", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Focus detection on AD paths like CN=Policies,CN=System,DC=domain,DC=com.", "field": "ObjectDN"}, {"description": "Target specific files like ScheduledTasks.xml or GptTmpl.inf in SYSVOL.", "field": "TargetFilename"}, {"description": "Correlate GPO object change and SYSVOL file modification within N seconds.", "field": "TimeWindow"}, {"description": "Alert on unexpected modification by non-admins or uncommon accounts.", "field": "UserContext"}, {"description": "Flag usage of GPO manipulation tools like Set-GPRegistryValue, New-GPOImmediateTask.", "field": "CommandLine"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3863', 0, 166, '09-mitre-attack', 'retrieved', '383C641642A26076814968257EB7BD90E476E7C145546DE939F2E7AC18D7179E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
