VALUES ('doc-09-mitre-attack-p0-3864', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of system enumeration commands such as `uname`, `df`, `uptime`, `hostname`, `lscpu`, and `cat /etc/os-release` through local terminal or scripts.", "external_references": [{"external_id": "AN1453", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0525#AN1453"}], "id": "x-mitre-analytic--eca769c3-9497-4c87-b624-4003fd1b0304", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1453", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Customize list of commands of interest (e.g., uname, lscpu, etc.)", "field": "CommandList"}, {"description": "Correlate sessions for behavior context.", "field": "TerminalSessionID"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3864', 0, 86, '09-mitre-attack', 'retrieved', 'E852CB0CD73A929873EEE8F067DAE48A92B44C768A650265F5021E08E733B368', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
