VALUES ('doc-09-mitre-attack-p0-3865', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Federated login using SSO or OAuth grant to cloud control plane, followed by directory or permissions enumeration", "external_references": [{"external_id": "AN0018", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0008#AN0018"}], "id": "x-mitre-analytic--ecb9db5c-55ef-48df-8ccb-f57db8c32a08", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0018", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "user.authentication.sso, app.oauth.grant", "name": "Okta:SystemLog", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune based on applications federated to high-priv cloud assets", "field": "SSOApplicationScope"}, {"description": "Filter based on expected OIDC clients used for login", "field": "ClientIDScope"}, {"description": "Track multiple geographic logins within short windows", "field": "LoginVelocity"}], "x_mitre_platforms": ["Identity Provider"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3865', 0, 98, '09-mitre-attack', 'retrieved', '84FEA474663767A289447DB56BBC6CB9070537032E52549520260FE60E9F09DC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
