VALUES ('doc-09-mitre-attack-p0-3866', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Correlate creation or modification of serverless functions (e.g., AWS Lambda, GCP Cloud Functions, Azure Functions) with anomalous IAM role assignments or permissions escalation events. Detect subsequent executions of newly created functions that perform unexpected actions such as spawning outbound network connections, accessing sensitive resources, or creating additional credentials.", "external_references": [{"external_id": "AN1053", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0374#AN1053"}], "id": "x-mitre-analytic--ecf190d1-5311-466f-a361-a33820b3c7b7", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1053", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "CreateFunction / UpdateFunctionConfiguration: Function creation, role assignment, or configuration change events", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}, {"channel": "InvokeFunction: Unexpected or repeated invocation of functions not tied to known workflows", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Which IAM roles or privileges are considered sensitive when applied to functions", "field": "RoleScope"}, {"description": "Known baseline list of approved serverless functions to reduce false positives", "field": "AllowedFunctions"}, {"description": "Temporal threshold for correlating function creation with anomalous execution", "field": "TimeWindow"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3866', 0, 161, '09-mitre-attack', 'retrieved', '8B5F46109080AF126AFA1A47BCF15D638649BAB0C19A480435D3D82CF56E744E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
