INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3867', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects kernel- or user-space exploitation attempts targeting auditd, AV daemons, or security monitoring agents. Defender observation includes unexpected segfaults, privilege escalation attempts from low-privileged processes, or modifications to security binaries. Correlates exploitation attempts with subsequent gaps in logging or terminated processes.", "external_references": [{"external_id": "AN1634", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0595#AN1634"}], "id": "x-mitre-analytic--ecf26d05-48ef-43b2-bfc3-4ea331be735b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1634", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve: Execution of suspicious exploit binaries targeting security daemons", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Segfaults, kernel oops, or crashes in security software processes", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of critical security daemons (e.g., auditd, falco, AV agents) to monitor for exploitation.", "field": "WatchedBinaries"}, {"description": "Regex or patterns for kernel/syslog errors correlated with exploitation attempts.", "field": "CrashPatterns"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3867', 0, 138, '09-mitre-attack', 'retrieved', '46A9A2199316454CCACC31FB6D8406CE211CAEEDA1F587213DD1E6F7CBDDE414', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
