VALUES ('doc-09-mitre-attack-p0-3868', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of built-in tools (e.g., ipconfig, route, netsh) or PowerShell/WMI queries to enumerate IP, MAC, interface status, or routing configuration.", "external_references": [{"external_id": "AN0559", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0195#AN0559"}], "id": "x-mitre-analytic--edfec58e-e591-4057-a906-1baf3674d80b", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0559", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Filter known/legit CLI chains (e.g., explorer.exe → cmd.exe) to reduce FP", "field": "ParentProcess"}, {"description": "Target executions by non-admin or unexpected users", "field": "UserContext"}, {"description": "Cluster enumeration commands within short time windows", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3868', 0, 108, '09-mitre-attack', 'retrieved', 'C88274C5F4B3AD2509C11477888C223A2413C511CC362D6B23449E8685B27259', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
