VALUES ('doc-09-mitre-attack-p0-3869', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Local user accounts are created via binaries like ''useradd'', ''adduser'', or by editing passwd/shadow. Behavior chain includes execution of user management binaries or modification of user database files.", "external_references": [{"external_id": "AN1236", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0447#AN1236"}], "id": "x-mitre-analytic--ee065e5f-5a04-49bd-b2b6-33b404ac37c7", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1236", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "useradd or adduser executed", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--deb22295-7e37-4a3b-ac6f-c86666fbe63d"}, {"channel": "write operation on /etc/passwd or /etc/shadow", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Account creation may be scripted via shell scripts, cron jobs, or remote shells", "field": "BinaryPath"}, {"description": "Flag if commands are issued from remote sessions (e.g., sshd)", "field": "ExecutionSource"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3869', 0, 116, '09-mitre-attack', 'retrieved', 'E0337AD1AA79360CE65AE7635236916BFB3265CD99743302A6CA398843A08BF3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
