VALUES ('doc-09-mitre-attack-p0-3870', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects unauthorized additions or changes to /Library/Security/SecurityAgentPlugins and suspicious process activity attempting to hook authentication APIs. Correlates file modifications with abnormal plugin loads in authentication flows.", "external_references": [{"external_id": "AN0289", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0104#AN0289"}], "id": "x-mitre-analytic--ee0f60f3-2fb3-4857-b02e-58c69b5aab52", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0289", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "SecurityAgentPlugins modification", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "process_open", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of approved authentication plugin directories to baseline.", "field": "PluginPaths"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3870', 0, 89, '09-mitre-attack', 'retrieved', '43422E9F268991DE1777CCD8E954C09B5E5FAAF7235B26F003084179EF19E430', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
