VALUES ('doc-09-mitre-attack-p0-3871', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor for suspicious use of commands such as cat, less, grep, or journalctl accessing /var/log/ files. Abnormal enumeration of authentication logs (auth.log, secure) or bulk access to multiple logs in short time windows should be flagged.", "external_references": [{"external_id": "AN0706", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0255#AN0706"}], "id": "x-mitre-analytic--ee468e26-d179-47ba-af8b-43118db24939", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0706", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve: Execution of cat, less, grep, journalctl targeting log directories (/var/log/)", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "open: Access to sensitive log files (/var/log/auth.log, /var/log/secure, /var/log/syslog)", "name": "auditd:PATH", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Filter routine scripts used for log rotation or troubleshooting.", "field": "AdminMaintenanceScripts"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3871', 0, 117, '09-mitre-attack', 'retrieved', 'FA4ACDB8D009C50094457884EC81A055B3368B45C9B91E27AD76BB81A2629CD2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
