VALUES ('doc-09-mitre-attack-p0-3872', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects non-standard processes (e.g., PowerShell, python.exe, rundll32.exe) making outbound connections using publish/subscribe protocols (e.g., MQTT, AMQP) over non-browser, encrypted channels, often beaconing to message brokers.", "external_references": [{"external_id": "AN0002", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0002#AN0002"}], "id": "x-mitre-analytic--ee4e3e61-e138-498b-93bf-3a5f8fea691c", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0002", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "mqtt.log / xmpp.log (custom log feeds)", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detect suspicious processes initiating outbound pub/sub connections", "field": "UnusualProcessList"}, {"description": "Define beaconing interval used for temporal correlation", "field": "TimeWindow"}, {"description": "Custom MQTT/XMPP port use in non-standard ranges (e.g., 1883, 5222, 5672)", "field": "ProtocolPortList"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3872', 0, 116, '09-mitre-attack', 'retrieved', '3F0A60DD4C2C20EBC1E418ABDC18706FD34FFF52418521EE6A1F508632C08382', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
