VALUES ('doc-09-mitre-attack-p0-3873', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Correlate DNS queries that generate domains with high entropy or gibberish patterns, combined with short-lived connections from unusual processes. Monitor Sysmon DNS events and Windows Security logs for abnormal query rates and failed lookups.", "external_references": [{"external_id": "AN1178", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0419#AN1178"}], "id": "x-mitre-analytic--ee7499f8-4262-47cf-8fff-5344f60bf2cf", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1178", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Set threshold for randomness in queried domain strings (e.g., >4.0)", "field": "EntropyThreshold"}, {"description": "Failed resolution ratio above normal baseline (e.g., >30%)", "field": "QueryFailureRate"}, {"description": "Duration for aggregating suspicious DNS queries (e.g., 5–10 min)", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3873', 0, 122, '09-mitre-attack', 'retrieved', '3AC5E25F4F6F6A04FCC1643CDF6BBD093DD6E2C768D2C9B5E99E959C062F78D9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
