VALUES ('doc-09-mitre-attack-p0-3875', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use of non-enterprise email or messaging services in Thunderbird, Evolution, or browsers leading to suspicious file downloads and subsequent execution. Defender view includes browser-initiated downloads of unexpected content and shell or interpreter processes launched post-download.", "external_references": [{"external_id": "AN0321", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0115#AN0321"}], "id": "x-mitre-analytic--eed7a6f2-496d-47c6-bdfd-1b885b58a651", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0321", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve: Execution of bash, python, or perl processes spawned by browser/email client", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Inbound messages from webmail services containing attachments or URLs", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Outbound traffic to domains/IPs not previously resolved, occurring shortly after attachment download or link click", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Configured list of browsers or email clients to monitor (e.g., firefox, chromium, thunderbird).", "field": "BrowserProcesses"}, {"description": "Custom regex rules for suspicious URL patterns, file extensions, or encoded links.", "field": "PhishingIndicators"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3875', 0, 156, '09-mitre-attack', 'retrieved', 'DD2B1A93C9BCAC04A55020E89F91F3B0D7E414B597C6592CFF21BCD9934245FF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
