VALUES ('doc-09-mitre-attack-p0-3876', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects adversarial use of cloud-native APIs (e.g., AWS IAM, Azure RBAC, GCP Identity) to enumerate cloud group memberships or policy mappings via unauthorized sessions or scripts.", "external_references": [{"external_id": "AN0695", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0251#AN0695"}], "id": "x-mitre-analytic--ef4f995e-6f20-42b7-802e-555ac54ab7b9", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0695", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "ListGroups, ListAttachedRolePolicies", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--8e44412e-3238-4d64-8878-4f11e27784fe"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Scope to anomalous IAM principals or assume-role usage.", "field": "UserContext"}, {"description": "Correlate enumeration activity within lateral movement prep windows.", "field": "TimeWindow"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3876', 0, 94, '09-mitre-attack', 'retrieved', 'A5A7984F4EF5E93F1C34538E0F75DD1CC316702FE0CEB669065610A4545C803C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
