VALUES ('doc-09-mitre-attack-p0-3877', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Domain group and user enumeration via dscl or dscacheutil, or queries to directory services from non-admin endpoints.", "external_references": [{"external_id": "AN0365", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0129#AN0365"}], "id": "x-mitre-analytic--ef50b854-172a-457b-9d0e-c95d9835eaaa", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0365", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Process Execution", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "DS daemon log entries", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Match patterns such as ''dscl /Active\\ Directory/All\\ Domains -list /Users''.", "field": "CommandPattern"}, {"description": "Flag this activity only on non-directory hosts or non-admin accounts.", "field": "EndpointRole"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3877', 0, 98, '09-mitre-attack', 'retrieved', 'E4B9C010CA67816EB233E95B691ABAB62DDFF9B727955A295D4FB526DC1D75AB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
