VALUES ('doc-09-mitre-attack-p0-3878', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of `ping`, `vmkping`, or `curl` from shell or through automation jobs/scripts to verify Internet egress.", "external_references": [{"external_id": "AN1018", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0357#AN1018"}], "id": "x-mitre-analytic--ef76221d-d5fe-4285-af27-54711e94e2b5", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1018", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "None", "name": "esxi:shell", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}, {"channel": "process", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Distinguish external SSH sessions from internal admin maintenance", "field": "SSHSessionOrigin"}, {"description": "Egress test destination may be filtered to known CDNs/test nodes", "field": "TargetIP"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3878', 0, 91, '09-mitre-attack', 'retrieved', 'E0D50BA7CC33B458DA12A7EC1481DF1A92D2D6E195C98EA570E71C00B023F3D9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
