VALUES ('doc-09-mitre-attack-p0-3879', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Group membership checks via ''dscl'', ''dscacheutil'', or ''id'', typically executed via terminal or automation scripts.", "external_references": [{"external_id": "AN0509", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0179#AN0509"}], "id": "x-mitre-analytic--ef8fa56d-882e-42da-990e-2adc3a771041", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0509", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process:launch", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Filters for suspicious execution of ''dscl . -read /Groups'', etc.", "field": "CommandLine"}, {"description": "Flag group enumeration from automation tools (e.g., LaunchAgents or suspicious apps).", "field": "ParentProcess"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3879', 0, 87, '09-mitre-attack', 'retrieved', 'DDB04289F94713350A8323E80710ADC03DD61E0FB2DD1AA8C373D6202D4B3EE7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
