VALUES ('doc-09-mitre-attack-p0-3880', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor server and endpoint logs for unusual outbound network connections to cryptocurrency nodes, unauthorized scripts accessing financial systems, or automation targeting payment file formats. Detect curl/wget activity aimed at exfiltrating transaction data or credentials from financial apps.", "external_references": [{"external_id": "AN1362", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0495#AN1362"}], "id": "x-mitre-analytic--efdca1e1-5a4a-4039-99ab-1cdb7e50e52c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1362", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve: Execution of curl, wget, or custom scripts accessing financial endpoints", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "Authentication attempts into finance-related servers from unusual IPs or times", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Whitelisted IPs for finance-related traffic to reduce noise.", "field": "KnownFinanceIPs"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3880', 0, 118, '09-mitre-attack', 'retrieved', '38B8D4EFF0FA7C9F99EA8587F457D64FC15187B05C4D2A02548990B577E81B55', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": 