VALUES ('doc-09-mitre-attack-p0-3881', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Processes like curl, wget, python, socat, or custom binaries initiating TLS/SSL sessions to non-standard destinations. Defender sees abnormal syscalls for connect(), loading of libssl libraries, and persistent outbound encrypted traffic from daemons not normally communicating externally.", "external_references": [{"external_id": "AN0760", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0273#AN0760"}], "id": "x-mitre-analytic--f0dacfba-bcc0-43cb-bad5-0cd3fe3a7f5f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0760", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "socket/connect with TLS context by unexpected process", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "system daemons initiating TLS sessions outside expected services", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Processes linked with libssl or crypto libraries making outbound connections", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Legitimate system services expected to use TLS (e.g., package updates).", "field": "WhitelistedDaemons"}, {"description": "Trusted CAs; flag self-signed or unrecognized certs.", "field": "CertificateAuthorities"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3881', 0, 138, '09-mitre-attack', 'retrieved', '953D57FB1438FCD5CB6F081070F5C3C9477451BECDFB20AE9046F238C98D6B11', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
