VALUES ('doc-09-mitre-attack-p0-3882', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Behavioral chain: (1) delegated admin or external identity establishes session (e.g., partner/reseller DAP, B2B guest, SAML/OAuth trust); (2) role elevation or app consent/permission grant; (3) downstream privileged actions in the tenant. Correlate IdP sign-in, admin/role assignment, and consent/admin-on-behalf events.", "external_references": [{"external_id": "AN1347", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0488#AN1347"}], "id": "x-mitre-analytic--f0e2baa2-3bb7-4587-8eae-6abddd1cf140", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1347", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "InteractiveUser, ServicePrincipalSignIn", "name": "azure:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "Add delegated admin / Assign admin roles / Update application consent", "name": "azure:audit", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"channel": "Set-PartnerOfRecord / CompanyAdministrator role assignments / New-DelegatedAdminRelationship", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tenant IDs of approved partners; any others are suspicious.", "field": "TrustedPartnerTenantIDs"}, {"description": "Require MFA for partner sessions; alert on bypass or step-up failure.", "field": "RequiredMFA"}, {"description": "Roles third-parties may hold (e.g., Helpdesk Admin); flag broader scopes.", "field": "RoleScopeAllowList"}], "x_mitre_platforms": ["Identity Provider"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3882', 0, 153, '09-mitre-attack', 'retrieved', 'A9E617B858DBA6A4766D1206C309968F0B2300ADDAD99F2710B01F99E7A1861D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
