VALUES ('doc-09-mitre-attack-p0-3884', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Initial process initiates outbound connection to first-stage C2, receives payloads or commands, then spawns or injects into a second process that establishes a new outbound connection to an unrelated destination (second-stage C2).", "external_references": [{"external_id": "AN0637", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0228#AN0637"}], "id": "x-mitre-analytic--f13ff1ad-5c7b-4136-b5cb-7a5663c3c54f", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0637", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Correlate two-stage behavior occurring within a short window (e.g., 1-5 minutes)", "field": "TimeWindow"}, {"description": "Tune to exclude known legitimate updaters and management agents", "field": "ParentProcess"}, {"description": "May be customized to exclude known corporate domains and CDNs", "field": "DestinationHostname"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3884', 0, 123, '09-mitre-attack', 'retrieved', '1942B296883CEC41238476328887C88C18EE2E4DE7BC6D3A1CD9D73C82B973DC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
