VALUES ('doc-09-mitre-attack-p0-3885', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detect ''shutdown'', ''reboot'', or ''systemctl poweroff'' executions with auditd/syslog and absence of scheduled maintenance windows or approved user context.", "external_references": [{"external_id": "AN1539", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0559#AN1539"}], "id": "x-mitre-analytic--f1a019df-12f0-442e-9b0e-b1a82352389b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1539", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve=/sbin/shutdown or /sbin/reboot", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "system is powering down", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Supports multiple binary names or symlinked utilities.", "field": "CommandLineMatch"}, {"description": "Privileged user (e.g., root or via sudo) context matching expected roles.", "field": "UserContext"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3885', 0, 99, '09-mitre-attack', 'retrieved', 'DE2188D70B3A84F6D6031BE76315A2D4F754E163C6831676EB8FD9E9C66E4DE8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
