VALUES ('doc-09-mitre-attack-p0-3886', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Cloud workload exploitation leads to repeated container, service, or VM termination/restart, typically associated with CVE-based crash triggers or fuzzed payloads.", "external_references": [{"external_id": "AN0853", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0304#AN0853"}], "id": "x-mitre-analytic--f1aae71a-6460-4c08-9aa7-49743f766a71", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0853", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "TerminateInstances", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--1361e324-b594-4c0e-a517-20cee32b8d7f"}, {"channel": "Repeated crash pattern within container or instance logs", "name": "AWS:CloudWatch", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Large volume of malformed or synthetic payloads to application endpoints prior to failure", "name": "AWS:VPCFlowLogs", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Number of repeated crashes or terminations observed before triggering alert", "field": "CrashThreshold"}, {"description": "Cloud service name, workload, or container ID to scope alerting", "field": "ServiceID"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3886', 0, 122, '09-mitre-attack', 'retrieved', 'C58008695861EDF38AE8A90929F4B9F0415BAB5FBD0A6F90E7CBFE07837F0FD5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
