INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3888', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects encoded PowerCLI or Base64-encoded payloads staged via datastore uploads or shell access (e.g., ESXi Shell or backdoored VIBs).", "external_references": [{"external_id": "AN1068", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0378#AN1068"}], "id": "x-mitre-analytic--f1ec63bc-294c-471c-ae9f-4dd70f3c036a", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1068", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Datastore modification events", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"channel": "Remote access API calls and file uploads", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune based on observed adversary paths (e.g., /vmfs/volumes/...)", "field": "StagingLocation"}, {"description": "Tune length of encoded payloads before triggering detection", "field": "EncodedLengthThreshold"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3888', 0, 100, '09-mitre-attack', 'retrieved', 'C7B96D095B1701029DAE70017838B79D6A22110CF80CCF15F7BE93D9F66DF932', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
