INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3889', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "ESXi guest OS or management interface processes establishing unexpected external HTTPS connections. Defender perspective: monitor vmx or hostd processes making outbound web requests with significant data transfer.", "external_references": [{"external_id": "AN1515", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0548#AN1515"}], "id": "x-mitre-analytic--f1f23910-7ecd-498b-92e8-7b5aa0d53ac8", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1515", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "network session initiation with external HTTPS services", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "file copy or datastore upload via HTTPS", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Threshold for outbound transfers from ESXi datastores.", "field": "DatastoreTransferThreshold"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3889', 0, 100, '09-mitre-attack', 'retrieved', 'D9E36D3A3A594EA3D5570CCE28F7A743A4DB001748429BB1541D18FEDAF1D173', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
