VALUES ('doc-09-mitre-attack-p0-3891', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unusual or uncommon processes initiate network connections to external destinations followed by file creation (tools downloaded).", "external_references": [{"external_id": "AN0165", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0060#AN0165"}], "id": "x-mitre-analytic--f20d9241-84cc-4393-b2fb-798241da73fa", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0165", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune for known good updaters (e.g., ChromeUpdate, OneDrive)", "field": "ParentProcessName"}, {"description": "Allow filtering by internal vs external IP blocks", "field": "DestinationIPCategory"}, {"description": "Focus on uncommon file drop paths (e.g., C:\\Users\\Public\\)", "field": "FilePathRegex"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3891', 0, 107, '09-mitre-attack', 'retrieved', 'E7DDB25501F8B170E2B6CAEC5FE4C05263104022C7C4F17EEC630349B36C6417', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
