VALUES ('doc-09-mitre-attack-p0-3892', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-16T16:23:55.764Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects suspicious inbound communications or collaboration requests followed by rapid sensitive user actions such as file sharing changes, macro enablement, OAuth consent, credential submission, or financial workflow approvals that deviate from historical relationships or normal approval patterns.\n ", "external_references": [{"external_id": "AN2033", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0899#AN2033"}], "id": "x-mitre-analytic--f238e0f3-7354-4304-9101-69cefd8446fc", "modified": "2026-05-12T16:30:18.383Z", "name": "Analytic 2033", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "MailItemsAccessed; AddedInboxRule; ConsentToApplication; SharingSet", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "External sender message followed by user action involving links or attachments", "name": "m365:exchange", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "External chat request or new tenant communication preceding approval activity", "name": "m365:teams", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Time window between inbound communication and sensitive action", "field": "ActionAfterMessageWindow"}, {"description": "Known legitimate vendors or partner domains", "field": "TrustedDomainAllowlist"}, {"description": "Monetary threshold for finance workflows", "field": "ApprovalAmountThreshold"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3892', 0, 148, '09-mitre-attack', 'retrieved', '7825116EFB2031D16851B8D1EA3BAEF06447B2195D1DE607168C56C533EB76D4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
