INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3893', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects anomalous usage of ESXi Guest Operations APIs such as StartProgramInGuest, ListProcessesInGuest, ListFileInGuest, or InitiateFileTransferFromGuest. Defender perspective focuses on unusual frequency of guest API calls, invocation from unexpected management accounts, or execution outside of business hours. These correlated signals indicate adversarial abuse of ESXi administrative services to run commands on guest VMs.", "external_references": [{"external_id": "AN0646", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0232#AN0646"}], "id": "x-mitre-analytic--f25cf3cf-53b8-4fa4-be4c-d0a7a02bf739", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0646", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Guest Operations API invocation: StartProgramInGuest, ListProcessesInGuest, ListFileInGuest, InitiateFileTransferFromGuest", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Whitelist of management accounts authorized to use ESXi Guest Ops APIs.", "field": "ExpectedAdminUsers"}, {"description": "Business hours during which Guest Ops API usage is expected; activity outside may be suspicious.", "field": "TimeWindow"}, {"description": "Number of Guest Ops API calls considered anomalous if exceeded in a given timeframe.", "field": "OperationThreshold"}, {"description": "List of VMs where Guest Ops usage is permitted; usage on other VMs may indicate malicious activity.", "field": "AuthorizedVMs"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3893', 0, 173, '09-mitre-attack', 'retrieved', '0DF5390C39493D265FD5A6A6217C439D544AD51BAE2439F41F91DF5FD9915657', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
