VALUES ('doc-09-mitre-attack-p0-3894', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of msiexec.exe execution where command-line arguments reference remote MSI packages, UNC paths, HTTP/HTTPS URLs, or DLLs, correlated with subsequent module loads and/or network connections to previously unseen destinations. The behavioral chain links process creation of msiexec.exe with suspicious parameters, network activity to retrieve payloads, and module loading indicative of malicious installation or DLL execution.", "external_references": [{"external_id": "AN0445", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0158#AN0445"}], "id": "x-mitre-analytic--f27c0482-fbea-47a3-9b19-7302a058a9e5", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0445", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Patterns for identifying malicious msiexec.exe usage (e.g., UNC paths, external domains, DLL execution flags)", "field": "SuspiciousCommandlinePatterns"}, {"description": "List of external domains or IP ranges considered suspicious for msiexec network connections", "field": "SuspiciousDestinationList"}, {"description": "Time range in seconds/minutes for correlating msiexec.exe execution with module load and network activity", "field": "TimeWindow"}, {"description": "Hash list of MSI packages considered known-good to reduce false positives", "field": "LegitimateMSIHashes"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3894', 0, 177, '09-mitre-attack', 'retrieved', '3D9FF665D9A82880D6574D1604EB8A5DA48ABACF288639A8F57DB38650B585F3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
