VALUES ('doc-09-mitre-attack-p0-3895', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor for anomalous access to financial applications, browser-based banking sessions, or enterprise ERP systems from Windows endpoints. Detect mass emailing of payment instructions, sudden rule changes in Outlook for financial staff, or use of clipboard data exfiltration tied to cryptocurrency wallet addresses.", "external_references": [{"external_id": "AN1361", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0495#AN1361"}], "id": "x-mitre-analytic--f2aef85a-c1ea-4d1a-b359-32692c973cdc", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1361", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4624, 4648", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Baseline of finance-related executables or ERP processes to monitor closely.", "field": "FinanceAppList"}, {"description": "Accounts belonging to finance, treasury, or executives that should be monitored with higher sensitivity.", "field": "HighRiskAccounts"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3895', 0, 124, '09-mitre-attack', 'retrieved', '3A20BAF41544EF75014A3E7CB7721B251DAB67FF3F9BDF85D90104B47B5A0685', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
