VALUES ('doc-09-mitre-attack-p0-3896', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects abuse of container orchestration platforms (e.g., Kubernetes) where adversaries create CronJobs to maintain persistence or execute malicious Jobs across the cluster.", "external_references": [{"external_id": "AN0582", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0206#AN0582"}], "id": "x-mitre-analytic--f2c03ef0-cd36-42b8-9c2d-e25a3b1b8b1c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0582", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "verb=create, resource=cronjobs, group=batch", "name": "kubernetes:apiserver", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}, {"channel": "container start/stop activity via Docker, containerd, or CRI-O", "name": "kubernetes:events", "x_mitre_data_component_ref": "x-mitre-data-component--a5ae90ca-0c4b-481c-959f-0eb18a7ff953"}, {"channel": "outbound/inbound network activity from spawned pods", "name": "container:proxy", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Kubernetes namespace the job is deployed to—scoping this to known trusted namespaces may reduce noise.", "field": "NamespaceScope"}, {"description": "The container image registry or repository the job pulls from—can be filtered by trusted registries.", "field": "ImageRepository"}, {"description": "Time window or frequency of CronJob execution (e.g., ‘@hourly’)—jobs running at odd hours may be suspicious.", "field": "ScheduleWindow"}, {"description": "The command or entrypoint executed by the Job—unexpected shell commands or interpreters may warrant inspection.", "field": "ExecutionCommand"}], "x_mitre_platforms": ["Containers"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3896', 0, 166, '09-mitre-attack', 'retrieved', '56DDD172A3352AC0084AFCD1D97251547C1748A0A04FD7537FD52C7DB2E47014', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
