VALUES ('doc-09-mitre-attack-p0-3897', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Abuse of macOS Electron apps by modifying app.asar bundles and spawning child processes (osascript, curl, sh) from Electron executables.", "external_references": [{"external_id": "AN0073", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0025#AN0073"}], "id": "x-mitre-analytic--f2c91a4c-1e79-4350-8a7e-94bc7b7b9a4c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0073", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Electron app spawning unexpected child process", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "CREATE/MODIFY: Modification of app.asar inside .app bundle", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Baseline of legitimate Electron app paths under /Applications.", "field": "AllowedAppBundlePaths"}, {"description": "Alert when signed Electron parent spawns unsigned child.", "field": "SignedToUnsignedTransition"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3897', 0, 103, '09-mitre-attack', 'retrieved', 'C74E5380152A4EE5C5C819B9C3697BDE25E830E8FAAD0ED539DE1C19C78F1914', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
