INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3899', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of XSL scripts via msxsl.exe or wmic.exe using embedded JScript or VBScript for proxy execution. Detection correlates process creation, command-line patterns, and module load behavior of scripting components (e.g., jscript.dll).", "external_references": [{"external_id": "AN0581", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0205#AN0581"}], "id": "x-mitre-analytic--f313053f-5898-4f47-b263-a60098f5c963", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0581", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "May need to tune based on encoded input or custom extensions (e.g., .jpeg instead of .xsl).", "field": "CommandLinePattern"}, {"description": "Legitimate administrative or developer tools may use msxsl; validate the parent process chain.", "field": "ParentProcess"}, {"description": "Temporal correlation window between script engine DLL load and suspicious process spawn.", "field": "TimeWindow"}, {"description": "Filter known safe URLs used by enterprise for XSL transformations.", "field": "RemoteXSLDomainWhitelist"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3899', 0, 145, '09-mitre-attack', 'retrieved', '196AE22688A927CAA53C9FA550279EE0A9EA7D3CD60491F5DF234FA31B1C07B8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
