VALUES ('doc-09-mitre-attack-p0-3900', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects creation or modification of `LaunchDaemon` or `LaunchAgent` plist files under `/Library/LaunchDaemons/`, `~/Library/LaunchAgents/`, or similar. Monitors execution of `launchctl`, property list edits, and file permission changes.", "external_references": [{"external_id": "AN1577", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0571#AN1577"}], "id": "x-mitre-analytic--f315abd4-7115-45ac-9466-64c23367cd41", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1577", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "launchctl load/unload or plist file modification", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "file write to launchd plist paths", "name": "fs:fsusage", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Watched directories for LaunchDaemons and LaunchAgents", "field": "PlistPathList"}, {"description": "Monitored keys such as `RunAtLoad`, `KeepAlive`, or `ProgramArguments`", "field": "PlistKeyMonitor"}, {"description": "Flag execution of unsigned or non-Apple-signed binaries within plist", "field": "UnsignedBinaryAlert"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3900', 0, 119, '09-mitre-attack', 'retrieved', '9734F2119ED3E0197D9EBEF5E21361515E212F2F064CB956BC3C5DAC1A3F4634', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
