VALUES ('doc-09-mitre-attack-p0-3902', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects Python execution via python.exe or py.exe with anomalous parent lineage (e.g., Office macros, LOLBAS), execution from unusual directories, or chained network/PowerShell/system-level activity.", "external_references": [{"external_id": "AN0172", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0063#AN0172"}], "id": "x-mitre-analytic--f392a2cb-dd4b-4585-84d5-1fa4bd65ff60", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0172", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Advanced Hunting: DeviceProcessEvents + DeviceNetworkEvents", "name": "EDR:hunting", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Non-standard processes spawning python.exe (e.g., winword.exe, mshta.exe).", "field": "ParentProcess"}, {"description": "Execution of .py from temp directories or user profile paths.", "field": "ScriptPath"}, {"description": "Execution outside maintenance or patch windows.", "field": "TimeWindow"}, {"description": "Execution by low-privileged or service accounts.", "field": "UserContext"}, {"description": "Python spawning suspicious binaries or scripts (e.g., PowerShell, certutil).", "field": "ChildProcess"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3902', 0, 131, '09-mitre-attack', 'retrieved', '8DF95FC8076164E1E6E6215CC9EC237ED835CA121FF7D09DF11AD774F2A3726D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
