INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3904', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "A process opens/reads /dev/video* (V4L2), performs ioctl/read loops, writes large/continuous video artifacts to disk, and/or quickly establishes outbound connections for exfiltration.", "external_references": [{"external_id": "AN0569", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0197#AN0569"}], "id": "x-mitre-analytic--f3c5c71a-da1b-4d09-bda7-ec07b0b7c05d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0569", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "openat/read/ioctl: openat/read/ioctl on /dev/video* by uncommon user/process", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"channel": "PATH records referencing /dev/video*", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "select: path LIKE ''/dev/video%''", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"channel": "sudo execution of ffmpeg/gst-launch/v4l2-ctl by non-standard user", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "http/file-xfer: Outbound transfer of large video-like MIME types soon after capture", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Which syscalls to audit (openat, read, ioctl) – performance sensitive.", "field": "SyscallSet"}, {"description": "Legitimate processes (e.g., motion, Zoom, Chrome) that access /dev/video*.", "field": "AllowedCallers"}, {"description": "List of file extensions to flag (.mp4/.avi/.mov/.mkv/.yuv/.h264).", "field": "VideoExtensions"}, {"description": "Minimum read/ioctl count to infer continuous capture.", "field": "MinContinuousReadCount"}, {"description": "Correlate device open → file write → network exfil (e.g., 30m).", "field": "TimeWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3904', 0, 177, '09-mitre-attack', 'retrieved', 'A425920112BFBA8EFF304718E7DAC98564DE3CA0780F59049EEF926FCE65F08E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
