VALUES ('doc-09-mitre-attack-p0-3905', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary places scripts or binaries with misleading names in /etc/rc.local.d or /var/spool/cron, or registers services with legitimate-sounding names not present in default ESXi builds.", "external_references": [{"external_id": "AN0359", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0127#AN0359"}], "id": "x-mitre-analytic--f3dfb562-94ef-44ea-be4f-17ac2d0771b5", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0359", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "registers services with legitimate-sounding names", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}, {"channel": "scripts or binaries with misleading names", "name": "esxi:shell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune based on default service names vs. suspicious new entries", "field": "ServiceNameBaseline"}, {"description": "Watch for new binaries/scripts in boot or cron folders", "field": "ScriptFilePath"}, {"description": "Determine if execution happens at boot or scheduled interval", "field": "ExecutionContext"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3905', 0, 121, '09-mitre-attack', 'retrieved', '523148B29E719181985FAF9E1C20872D81EEB5B6A2E8AB0C69CD6717C553CDF4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
