VALUES ('doc-09-mitre-attack-p0-3906', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary modifies Group Policy Objects (GPOs), domain trust, or directory service objects via GUI, CLI, or programmatic APIs. Behavior includes creation/modification of GPOs, delegation permissions, trust objects, or rogue domain controller registration.", "external_references": [{"external_id": "AN0755", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0270#AN0755"}], "id": "x-mitre-analytic--f403ae40-31ff-4550-b21f-e1c24315276d", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0755", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=5136", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--5b8b466b-2c81-4fe7-946f-d677a74ae3db"}, {"channel": "EventCode=4663, 4670, 4656", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Filter to specific AD containers (e.g., CN=Policies,CN=System,DC=domain,DC=com) for GPOs.", "field": "ObjectDN"}, {"description": "Focus on high-risk attributes such as gPCFileSysPath, ntSecurityDescriptor.", "field": "AttributeModified"}, {"description": "Correlate changes with suspicious process creation or privileged user logon.", "field": "TimeWindow"}, {"description": "Alert on unexpected user or service account modifying domain policy.", "field": "UserContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3906', 0, 142, '09-mitre-attack', 'retrieved', '527B0A4A533F1EAA7F4221CC246EA3428A2E46FBCF5C851FFF6BF053D375C1E4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
