VALUES ('doc-09-mitre-attack-p0-3907', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects disabling container runtime security controls, removing sidecar sensors, modifying seccomp/AppArmor profiles, mounting host proc/sys paths to interfere with host logging, or killing in-container monitoring agents.", "external_references": [{"external_id": "AN1373", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0497#AN1373"}], "id": "x-mitre-analytic--f421cbe1-d42e-45e9-adad-12c6ed0a5cb8", "modified": "2026-05-12T16:30:18.383Z", "name": "Analytic 1373", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "kubectl delete or patch of security pods/admission controllers", "name": "kubernetes:audit", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Exclusion of namespaces where temporary deletion of monitoring tools is legitimate (e.g., staging).", "field": "NamespaceExclusions"}], "x_mitre_platforms": ["Containers"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-3907', 0, 96, '09-mitre-attack', 'retrieved', 'A0B8D9409FF5CFF6E8C71B4E992744CBF89284F54B271DC07BED0424EFB2112E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
