VALUES ('doc-09-mitre-attack-p0-3908', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-16T17:10:51.287Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects exploitation or abuse of SaaS security workflows resulting in disabled alerts, reduced retention, bypassed enforcement, role escalation, or tokenized persistence that weakens monitoring. Correlates unusual admin/API activity with visibility reduction.", "external_references": [{"external_id": "AN2042", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0900#AN2042"}], "id": "x-mitre-analytic--f46639b5-4d99-4d52-8da9-112a468cc6d8", "modified": "2026-05-12T16:30:18.384Z", "name": "Analytic 2042", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "policy.rule.update;system.log.disable;admin.role.assign", "name": "saas:okta", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Set-AdminAuditLogConfig;New-ApplicationAccessPolicy;ConsentToApplication", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Approved admins allowed to change controls", "field": "PrivilegedActorAllowlist"}, {"description": "Minimum acceptable logging retention", "field": "RetentionChangeThreshold"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3908', 0, 100, '09-mitre-attack', 'retrieved', '25A52EF5047790F490E90ACF4FB36A46FC0269C4EFF0AF15369E6AA7DE2F12DD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
