VALUES ('doc-09-mitre-attack-p0-3909', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor DNS query results where subsequent connections use derived or unusual port numbers not explicitly resolved, especially when tied to suspicious processes. Correlate Sysmon DNS logs (Event ID 22) with process creation and socket activity.", "external_references": [{"external_id": "AN0728", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0262#AN0728"}], "id": "x-mitre-analytic--f47f256d-686f-4553-85e2-bd4d156da1e7", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0728", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Deviation from common service ports (e.g., >1024 when DNS resolved service expects 80/443)", "field": "PortDeviationThreshold"}, {"description": "Correlation window between DNS response and network connection (e.g., 5 minutes)", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3909', 0, 119, '09-mitre-attack', 'retrieved', 'CBCD5A45C68FF00674580E02B4606D4E737A8770D3FBF52C5C2CB0FE2B8DDFB2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
