VALUES ('doc-09-mitre-attack-p0-3910', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects access attempts to cloud instance metadata endpoints (e.g., 169.254.169.254) from virtual machines or containerized workloads. This includes both direct access and SSRF exploitation patterns.", "external_references": [{"external_id": "AN0001", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0001#AN0001"}], "id": "x-mitre-analytic--f4af0b1b-db51-4266-8b02-2cdfcb191f60", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0001", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Outbound connection to 169.254.169.254 from EC2 workload", "name": "AWS:VPCFlowLogs", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "GetInstanceIdentityDocument", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--b33d36e3-d7ea-4895-8eed-19a08a8f7c4f"}, {"channel": "Process within container accesses link-local address 169.254.169.254", "name": "ebpf:syscalls", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Adjust temporal window for correlation of access attempts and SSRF triggers", "field": "TimeWindow"}, {"description": "Tune based on expected roles that access metadata APIs (e.g., root, service accounts)", "field": "UserContext"}, {"description": "Customize detection for HTTP Host headers indicating SSRF", "field": "RequestHeaderMatch"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3910', 0, 135, '09-mitre-attack', 'retrieved', 'DC221A74336A0768F4EC7EA118574FD35B254B9A6E43E8F2E9B70F38D5D13CCA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
