VALUES ('doc-09-mitre-attack-p0-3911', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor for excessive or anomalous MFA push notifications or token requests, especially when login attempts originate from unusual IPs or geolocations and do not correspond to legitimate user-initiated sessions.", "external_references": [{"external_id": "AN0449", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0160#AN0449"}], "id": "x-mitre-analytic--f51edea3-e0e8-4090-8e81-a01c3394ba53", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0449", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Multiple MFA challenge requests without successful primary login", "name": "azure:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"channel": "PushNotificationSent", "name": "NSM:Connections", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Threshold of MFA prompts per user within a short time period", "field": "TimeWindow"}, {"description": "Expected login locations for workforce; deviations can be tuned", "field": "GeoIPAllowList"}], "x_mitre_platforms": ["Identity Provider"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3911', 0, 114, '09-mitre-attack', 'retrieved', 'DE0BA285D37C1A9D0DDE82AE4B16B2119DAA2D9A6B4C5C8F26C4129EBA7EFF83', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
