VALUES ('doc-09-mitre-attack-p0-3912', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Multiple failed sign-in attempts from external sources across many users followed by success from the same IP", "external_references": [{"external_id": "AN1524", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0551#AN1524"}], "id": "x-mitre-analytic--f525a464-a4e5-40fb-831a-162af2f232e7", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1524", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Sign-in logs", "name": "azure:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Elevate anomalies from uncommon geolocations", "field": "GeoRiskScore"}, {"description": "Elevate logins missing MFA on high-value accounts", "field": "MFAStatus"}], "x_mitre_platforms": ["Identity Provider"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3912', 0, 82, '09-mitre-attack', 'retrieved', '802B9AA8E6BB31728E7D5B5286B6C4DD1476B31DEE5C388AE0DED67B95AD8E03', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
