INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3913', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of container image build activity directly on the host using Docker or Kubernetes APIs. Defenders may observe Docker build requests, anomalous Dockerfile instructions (such as downloading code from unknown IPs), or creation of new images followed by immediate deployment. This behavior chain typically consists of an unexpected image creation event correlated with outbound network communication to non-standard or untrusted destinations.", "external_references": [{"external_id": "AN1261", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0459#AN1261"}], "id": "x-mitre-analytic--f568a973-fb34-41aa-950f-f46457544564", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1261", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "docker build or POST /build API request", "name": "docker:daemon", "x_mitre_data_component_ref": "x-mitre-data-component--b008766d-f34f-4ded-b712-659f59aaed6e"}, {"channel": "outbound connections from host during or immediately after image build", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines trusted registries for image pulls/builds. Builds referencing unapproved registries may indicate adversary behavior.", "field": "RegistryAllowList"}, {"description": "Threshold for number of new custom images created in a given time window. Exceeding this threshold may indicate malicious builds.", "field": "NewImageThreshold"}, {"description": "Defines correlation window (e.g., 5m) between suspicious build activity and subsequent network traffic anomalies.", "field": "TimeWindow"}], "x_mitre_platforms": ["Containers"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3913', 0, 184, '09-mitre-attack', 'retrieved', '439689A4D541A6B45A79777320E00477AB975D38B0B7A8312B9A98615F6369F3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
