VALUES ('doc-09-mitre-attack-p0-3915', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor ESXi shell or API access to host logs under /var/log/. Abnormal enumeration of vmkernel.log, hostd.log, or vpxa.log by unauthorized accounts should be flagged.", "external_references": [{"external_id": "AN0709", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0255#AN0709"}], "id": "x-mitre-analytic--f5b9ad98-3a10-4ff3-9e25-890488253bef", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0709", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Execution of cat, tail, grep targeting /var/log/vmkernel.log or /var/log/hostd.log", "name": "esxi:shell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "read: Access to sensitive log files by non-admin users", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Correlate with legitimate administrator access sessions to reduce noise.", "field": "AdminSessions"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3915', 0, 103, '09-mitre-attack', 'retrieved', '9BA326DF8BD3153A6D1712EF288EC9CB44B53C4203F570E1E73A2BB8C3D8C8D2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
