VALUES ('doc-09-mitre-attack-p0-3916', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects ELF binaries written to disk that demonstrate anomalous file size or entropy, quickly followed by execution or memory region writes into remote processes (e.g., using ptrace).", "external_references": [{"external_id": "AN0914", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0322#AN0914"}], "id": "x-mitre-analytic--f606ec01-15d2-4432-b91b-669411205015", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0914", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "write", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "SYSCALL ptrace/mprotect", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Used to flag binaries much larger than typical shell utilities or payloads", "field": "BinarySizeThreshold"}, {"description": "Which processes are allowed ptrace/mprotect – can limit to suspicious child-to-parent targeting", "field": "MemoryWriteTargets"}, {"description": "Temporal threshold for file write to execution", "field": "ExecutionAfterWriteWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3916', 0, 125, '09-mitre-attack', 'retrieved', 'E11EDAD6207A23360760C77E496E66AAF752B36C835C5AD3E48095A825DAA554', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
