VALUES ('doc-09-mitre-attack-p0-3917', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitors CLI-based execution of `show process` or equivalent on routers/switches. Correlates unusual device access, unauthorized roles, or config mode changes.", "external_references": [{"external_id": "AN0099", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0034#AN0099"}], "id": "x-mitre-analytic--f6985c70-6de1-4600-aba0-5b3324184dce", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0099", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "CLI command", "name": "networkdevice:cli", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "Admin activity", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tunable based on authorized operators for network infrastructure", "field": "Username"}, {"description": "Pattern match or regex scope for discovery commands", "field": "CommandString"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3917', 0, 96, '09-mitre-attack', 'retrieved', '15B25ADC2DC74A629502E75D33298A577056E0FF8819ED5047801E7F884BA263', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
