VALUES ('doc-09-mitre-attack-p0-3918', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use of pbpaste, AppleScript, or third-party automation frameworks (e.g., Automator) to collect clipboard or file content in bursts. Observable via unified logs.", "external_references": [{"external_id": "AN0533", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0186#AN0533"}], "id": "x-mitre-analytic--f6ad51e5-b869-455d-acb1-ef725acb27cb", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0533", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "logMessage contains pbpaste or osascript", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "subsystem=launchservices", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detectable script interpreters or clipboard tools (pbpaste, osascript).", "field": "AutomationTool"}, {"description": "Threshold for how often clipboard access occurs within a given time window.", "field": "ClipboardCheckRate"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3918', 0, 103, '09-mitre-attack', 'retrieved', 'C4DD328A0A8467D17CC8D88D384056CDA5E22D25FB54EBCA15C1D8E591C663BB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
