VALUES ('doc-09-mitre-attack-p0-3919', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary with write access to storage modifies lifecycle policies (e.g., via PutBucketLifecycle) to schedule rapid object deletion across one or more storage buckets. This is often used to trigger impact (destruction), remove logs (defense evasion), or force extortion (ransomware).", "external_references": [{"external_id": "AN0117", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0041#AN0117"}], "id": "x-mitre-analytic--f6f90ad5-3182-4b1a-a612-51b251a8a34c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0117", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "PutBucketLifecycle, PutLifecycleConfiguration, SetBucketLifecycle, storage.buckets.update", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--45977f14-1bcc-4ec4-ac14-a30fd3a11f44"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Policy values setting Expiration in fewer than N days (e.g., 0–1) are highly suspicious.", "field": "LifecycleExpirationDays"}, {"description": "Filter by bucket types (e.g., log storage, production DB snapshots) to prioritize detection.", "field": "TargetBucket"}, {"description": "Correlate rare or anomalous IAM principals making destructive lifecycle changes.", "field": "Principal"}, {"description": "Link lifecycle policy change with API activity suggesting staged deletion or extortion attempt.", "field": "TimeWindow"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3919', 0, 149, '09-mitre-attack', 'retrieved', '08C84D7AE6090AE046564268B45253B989F9EA116FF8AB0A067B0266F42C6F85', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
