VALUES ('doc-09-mitre-attack-p0-3921', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use of bash scripts or interactive shells to issue sequential ping, arp, or traceroute commands to map remote hosts.", "external_references": [{"external_id": "AN1584", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0574#AN1584"}], "id": "x-mitre-analytic--f794d2f4-ad8e-4e11-b374-2c35f8ca38e9", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1584", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "network", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune for sensitive internal segments or known lateral targets", "field": "TargetIPRange"}, {"description": "Distinguish user-interactive enumeration vs. cronjob or baseline tooling", "field": "ShellContext"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3921', 0, 93, '09-mitre-attack', 'retrieved', 'E3E49575A227233F06CAE8CE74FDC3B677AE412FDBAB6EF91CB1EDCB720C202D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
