VALUES ('doc-09-mitre-attack-p0-3922', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Processes invoking AVFoundation or CoreAudio frameworks, accessing input devices via TCC logs or Unified Logs, followed by writing AIFF/WAV/MP3 files to disk.", "external_references": [{"external_id": "AN0621", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0221#AN0621"}], "id": "x-mitre-analytic--f79a68ff-07f4-49ba-849b-9edb636f0b39", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0621", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "audio APIs", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"channel": "Microphone Access Events", "name": "Apple TCC Logs", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "File IO", "name": "fs:fsusage", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "CoreAudio vs. AVFoundation vs. lower-level device access APIs.", "field": "FrameworkCall"}, {"description": "Suspicious file drops (e.g., ~/Library/Caches/, /tmp/, nonstandard user folders).", "field": "TargetDirectory"}, {"description": "Unexpected parent-child relationship between non-media apps and AV capture.", "field": "AnomalousParent"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3922', 0, 120, '09-mitre-attack', 'retrieved', 'C87964056ED1