VALUES ('doc-09-mitre-attack-p0-3923', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects unauthorized termination of system daemons or commands issued through launchctl or kill to stop competing services or malware processes. Defenders should monitor unified logs and EDR telemetry for unusual service modifications or terminations.", "external_references": [{"external_id": "AN0047", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0015#AN0047"}], "id": "x-mitre-analytic--f84124d2-8bc6-4dae-a579-f0ddb0338a2f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0047", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "launchctl unload, kill, or pkill commands affecting daemons or background services", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "process_termination: Unexpected termination of processes tied to vulnerable or high-value services", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--61f1d40e-f3d0-4cc6-aa2d-937b6204194f"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines macOS services (e.g., securityd, keychain-related daemons) that should never be disabled.", "field": "ProtectedServiceList"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3923', 0, 120, '09-mitre-attack', 'retrieved', '9DE40B2D2FD36020D169E57E24486E34C75404B14D7345FA19BD5CEC4658978F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
