VALUES ('doc-09-mitre-attack-p0-3924', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor for creation of new Power Automate flows or equivalent automation scripts that trigger on user or file events. Detect anomalous actions performed by these automations, such as email forwarding, anonymous link creation, or unexpected API calls to external endpoints.", "external_references": [{"external_id": "AN1054", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0374#AN1054"}], "id": "x-mitre-analytic--f8787a86-552b-4e03-8d68-7177001a215d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1054", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "AddFlow / UpdateFlow: New automation or workflow creation events", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}, {"channel": "New-InboxRule: Automation that triggers abnormal forwarding or external link generation", "name": "m365:exchange", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Business units or users where automation creation is expected (developers, admins)", "field": "UserContext"}, {"description": "Specific automation actions (email forwarding, file sharing) that should be considered suspicious", "field": "FlowActions"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3924', 0, 138, '09-mitre-attack', 'retrieved', 'D45C3E728C763F60CB90B9749806D4AF1313AA6530261274C2EB8610350F389E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
