VALUES ('doc-09-mitre-attack-p0-3925', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects access to media files followed by execution of scripts (bash, Python, etc.) referencing those same files, or outbound traffic triggered shortly after file read. Correlates unusual use of tools like `steghide`, `exiftool`, or image libraries.", "external_references": [{"external_id": "AN0332", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0119#AN0332"}], "id": "x-mitre-analytic--f884a712-ace6-426c-ab81-8ff33e83be92", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0332", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "connect", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Define the list of steganographic or image-parsing tools to alert on (e.g., `steghide`, `imagemagick`)", "field": "MonitoredToolsList"}, {"description": "Tune to detect script engines accessing media files (e.g., `python script.py image.png`)", "field": "ScriptInterpreterMatch"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3925', 0, 125, '09-mitre-attack', 'retrieved', '7DD9CB68