VALUES ('doc-09-mitre-attack-p0-3926', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Identify lateral transfer via datastore file uploads or internal scp/ssh sessions that result in new VMX/VMDK or script files. Correlate transfer with VM execution or datastore modification.", "external_references": [{"external_id": "AN0519", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0183#AN0519"}], "id": "x-mitre-analytic--f8857048-181f-4883-a50b-65aca5204228", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0519", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Upload of file to datastore", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"channel": "scp/ssh used to move file across hosts", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Known authorized paths for legitimate VM operations", "field": "DatastoreWhitelist"}, {"description": "Protocols allowed for intra-VM host transfers", "field": "TransferProtocol"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3926', 0, 107, '09-mitre-attack', 'retrieved', 'A40748E58E1945A21DA44CE61AFFAC75494B3D6D6CD32B0D008840983B78697E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
