INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3927', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects VMs sending outbound traffic through non-standard services or to unknown destinations. Exfiltration over reverse shells tunneled via VMkernel or custom payloads routed via hostd/vpxa.", "external_references": [{"external_id": "AN0991", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0348#AN0991"}], "id": "x-mitre-analytic--f8998263-e55f-428f-b8d0-46d9e31277d2", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0991", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "connection attempts and data transmission logs", "name": "esxi:vpxa", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "network stack module logs", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "guest OS outbound transfer logs", "name": "esxi:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Limit detection to sensitive or externally-exposed VMs handling confidential data.", "field": "GuestOSAllowList"}, {"description": "Minimum outbound transfer size before flagging anomalous C2-based exfiltration.", "field": "TransferSizeThresholdMB"}, {"description": "Define expected protocols for outbound data (e.g., disallow FTP/SCP over high ports).", "field": "ProtocolAllowList"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3927', 0, 134, '09-mitre-attack', 'retrieved', '4434AB6E03E4B4AE20F12C2BB583A1E8BDBCF5BC48E2C1DCEB4E09D515570701', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
