VALUES ('doc-09-mitre-attack-p0-3928', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Forged cookies in SaaS environments manifest as valid web sessions without matching login activity, MFA enforcement bypass, or cookies reused across multiple devices/IPs. Defenders should look for cookie replay, concurrent sessions from multiple geographies, or session tokens generated by unrecognized apps.", "external_references": [{"external_id": "AN0487", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0171#AN0487"}], "id": "x-mitre-analytic--f8c255ac-8ba5-4971-9e11-420a10e688ad", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0487", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Session activity without correlated login event", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--ff93f688-d7a4-49cf-9c79-a14454da8428"}, {"channel": "Multiple concurrent logins using same cookie from different locations", "name": "saas:access", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Number of concurrent uses of a cookie that should trigger an alert.", "field": "TokenReplayThreshold"}, {"description": "Unusual SaaS logins from geographically distant locations in short timeframes.", "field": "GeoLocationAlerts"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3928', 0, 133, '09-mitre-attack', 'retrieved', '3AA2E36A976E0709B5B5D7C8897F9FB32AB606D242FD65CEF441B6EA3513B42E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
