VALUES ('doc-09-mitre-attack-p0-3930', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects invocation of lua or luajit interpreters by users or services outside of expected packages, chained with script drop or memory artifacts.", "external_references": [{"external_id": "AN0279", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0101#AN0279"}], "id": "x-mitre-analytic--f8e77c9a-2b8c-47d2-b44a-23857d246016", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0279", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "PATH", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Lua interpreter path may vary based on distro or adversary staging.", "field": "ExecutablePath"}, {"description": "May need to exclude service or admin accounts that use Lua legitimately.", "field": "UserContext"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3930', 0, 102, '09-mitre-attack', 'retrieved', '77009F198DB0DC6B72408321F97154632787F97220AF7F9CF5BC1E1735C92759', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
