VALUES ('doc-09-mitre-attack-p0-3931', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects the creation or execution of padded binary files (e.g., large size but minimal legitimate content) followed by process execution or lateral movement from the host.", "external_references": [{"external_id": "AN1528", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0553#AN1528"}], "id": "x-mitre-analytic--f9079cb0-76ff-4b4a-a73c-4f6572e7eef5", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1528", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=4663, 4670, 4656", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Threshold size in MB to determine suspicious padding", "field": "FileSizeThresholdMB"}, {"description": "Correlation time window between file creation and execution", "field": "TimeWindow"}, {"description": "Scope the detection to suspicious or non-standard user accounts", "field": "UserContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3931', 0, 119, '09-mitre-attack', 'retrieved', '38E18FCD2CB573C