VALUES ('doc-09-mitre-attack-p0-3932', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Login to vSphere or ESXi hosts using domain accounts, especially those associated with vpxuser or unexpected group memberships.", "external_references": [{"external_id": "AN0593", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0210#AN0593"}], "id": "x-mitre-analytic--f931e587-28f8-4923-b054-98d6348dcafe", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0593", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "/var/log/vmware/vpxd.log", "name": "esxi:vpxd", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"channel": "/var/log/hostd.log", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Prioritize detection on accounts with elevated access.", "field": "AccountType"}, {"description": "Distinguish interactive UI login from API or SSH access.", "field": "LoginInterface"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3932', 0, 91, '09-mitre-attack', 'retrieved', 'D400723A6669E2109711F75DBD4F7E29326B006F928F83365A454DA9288D73CF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
