VALUES ('doc-09-mitre-attack-p0-3934', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor ESXi syslog and esxcli outputs for abnormal DNS resolver behavior, such as frequent domain-to-IP changes or unauthorized modifications of DNS settings used by management agents. Correlate domain lookups with short TTL values.", "external_references": [{"external_id": "AN1334", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0485#AN1334"}], "id": "x-mitre-analytic--f9534b4a-57ef-40a0-801a-d56a217304f0", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1334", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Frequent DNS resolution of same domain with rotating IPs", "name": "esxi:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Whitelist of expected DNS resolvers configured on ESXi", "field": "ResolverConfigPaths"}, {"description": "Known trusted external domains for hypervisor services", "field": "ExternalDomainWhitelist"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3934', 0, 107, '09-mitre-attack', 'retrieved', 'B6A05ADC6B868C1ED3B64DD83AA8663F71882661A40D46CA1790E7AC8708F9D8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
