VALUES ('doc-09-mitre-attack-p0-3936', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Tracks suspicious use of ESXi shell commands or PowerCLI to delete logs, rotate system files, or tamper with hostd/vpxa history.", "external_references": [{"external_id": "AN0524", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0184#AN0524"}], "id": "x-mitre-analytic--f9b13a61-0110-4882-9384-3468d22ac221", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0524", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "rm, clearlogs, logrotate", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune per vCenter, vSphere, ESXi CLI telemetry collection", "field": "LogSourceType"}, {"description": "Target specific high-value log paths (e.g., /var/log/hostd.log)", "field": "LogPathPattern"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3936', 0, 88, '09-mitre-attack', 'retrieved', '7447B4541D8883035A9AA6577228AD3143906423D6CE701C9A553D9EAC329E45', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
