VALUES ('doc-09-mitre-attack-p0-3942', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Remote access to third-party SaaS with OAuth or API tokens post-initial compromise, followed by sensitive data access or configuration changes", "external_references": [{"external_id": "AN0020", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0008#AN0020"}], "id": "x-mitre-analytic--fb23f9ee-cdc8-46be-8f40-3631afbaff5a", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0020", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "LoginSuccess, APIKeyUse, AdminAction", "name": "saas:auth", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Older tokens issued before password change may indicate compromise", "field": "OAuthTokenAge"}, {"description": "Restrict detection to high-value or regulated SaaS apps", "field": "AppScope"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3942', 0, 90, '09-mitre-attack', 'retrieved', '74BF5EE275857CA18E2DF596CF154F8A2E3A2BA2032D7C8D98F321C4B5106164', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
