VALUES ('doc-09-mitre-attack-p0-3943', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of files containing right-to-left override characters (U+202E) to masquerade true file extensions. Often found in phishing payloads or file downloads.", "external_references": [{"external_id": "AN1461", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0527#AN1461"}], "id": "x-mitre-analytic--fb330f70-f0f4-4a5b-9b91-37d29a097a4c", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1461", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "Operational", "name": "WinEventLog:Windows Defender", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "RTLO variants such as \\u202E, %E2%80%AE, or byte-encoded forms", "field": "FilenamePattern"}, {"description": "Allows tuning for untrusted sources, e.g., browser downloads or email attachments", "field": "ExecutionContext"}, {"description": "Defines correlation between file creation and process execution", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3943', 0, 119, '09-mitre-attack', 'retrieved', '34006677E5017E88E80E198641EA39D2DE60006BF815180EAF1DB15AFC7EC7DB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
