VALUES ('doc-09-mitre-attack-p0-3944', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of commands or APIs that disable Gatekeeper, XProtect, or system integrity protections. Detect configuration changes through unified logs. Monitor termination of system security daemons (e.g., syspolicyd).", "external_references": [{"external_id": "AN0888", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0317#AN0888"}], "id": "x-mitre-analytic--fb51dd4c-b751-4282-a447-d9f5f257b435", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0888", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "spctl --master-disable, csrutil disable, or defaults write to disable Gatekeeper", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "Termination of syspolicyd or XProtect processes", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--61f1d40e-f3d0-4cc6-aa2d-937b6204194f"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Developers may legitimately disable Gatekeeper; whitelist approved contexts.", "field": "AdminToolWhitelist"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3944', 0, 103, '09-mitre-attack', 'retrieved', 'E562A957C667B27761356D7CDA1D584522EE25AE432C18EE56FB76B7D0383EBE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
