VALUES ('doc-09-mitre-attack-p0-3945', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitors for the creation of accounts inside containers using names that resemble legitimate orchestrator or backup identities to mask adversary persistence.", "external_references": [{"external_id": "AN1080", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0383#AN1080"}], "id": "x-mitre-analytic--fb767270-25ad-4fea-a8e7-8f9c57ac1fa8", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1080", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "ExecCreate + usermod or useradd", "name": "docker:daemon", "x_mitre_data_component_ref": "x-mitre-data-component--deb22295-7e37-4a3b-ac6f-c86666fbe63d"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Limit detection to containers with persistent volumes or specific workloads", "field": "ContainerContextScope"}, {"description": "Custom list of commonly abused names to blend into container environments (e.g., kubelet, cronjob_sync)", "field": "MasqueradePatternList"}], "x_mitre_platforms": ["Containers"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3945', 0, 100, '09-mitre-attack', 'retrieved', '156B2FF7A694DB4D369A376B0FDA6BE334D70CDBC9D2EE8EAF82D2DA77167C1D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
