INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3946', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects adversarial use of cloud APIs for command execution, resource control, or reconnaissance. Focuses on CLI/SDK/scripting language abuse via stolen credentials or in-browser Cloud Shells. Monitors for anomalous API calls chained with authentication context shifts (e.g., stolen token -> privileged action) and cross-service impacts.", "external_references": [{"external_id": "AN0215", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0078#AN0215"}], "id": "x-mitre-analytic--fb933fd5-5dd8-4879-b2bb-e68bc26ff60d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0215", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "eventName: RunInstances, CreateUser, PutRolePolicy, InvokeCommand", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "operationName: Write, Access Review, RoleAssignment", "name": "azure:activity", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}, {"channel": "eventType: user.authentication.sso, app.oauth2.token.grant", "name": "Okta:SystemLog", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Off-hours API usage or configuration changes are more suspicious outside business context.", "field": "TimeWindow"}, {"description": "Unexpected SDK usage (e.g., `boto3`, `azcopy`, unknown User-Agent strings).", "field": "UserAgent"}, {"description": "High-risk if access token or API key used outside expected geographic/IP behavior.", "field": "CredentialType"}, {"description": "Unusual or rapid chaining of provisioning, IAM, and execution APIs.", "field": "APISequence"}, {"description": "Browser-based Cloud Shell vs local CLI may indicate insider vs external use case.", "field": "ConsoleContext"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3946', 0, 182, '09-mitre-attack', 'retrieved', 'C0D8B38F5D1B401D20F90DAED13848DD7927A801C1B7FAB735CE4CF64BB25F50', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
