VALUES ('doc-09-mitre-attack-p0-3948', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use of `usleep`, `nanosleep`, or `NSTimer` calls in executables or binaries with no GUI interaction, especially followed by disk/network activity.", "external_references": [{"external_id": "AN0398", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0141#AN0398"}], "id": "x-mitre-analytic--fbbe7372-5d33-4181-a68a-e68f5da94df7", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0398", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "application logs referencing NSTimer, sleep, or launchd delays", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Correlate with known/expected signed apps vs. unsigned binaries to reduce noise.", "field": "AppBundleIdentifier"}, {"description": "Minimum time expected between process start and observable I/O for normal apps.", "field": "TimeToNextEvent"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3948', 0, 107, '09-mitre-attack', 'retrieved', 'F4E51ECE29CCA0B7A479390894F56AA25270C25882052F4C2C703034CD5343D2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
