VALUES ('doc-09-mitre-attack-p0-3949', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Access tokens or SSH keys used without corresponding login shell or PAM module activity, particularly for remote execution.", "external_references": [{"external_id": "AN0955", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0338#AN0955"}], "id": "x-mitre-analytic--fbe17895-73cc-432e-8576-f6cab851feb1", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0955", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execution of ssh, scp, or sftp using previously unseen credentials or keys", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"channel": "Accepted publickey for user from unusual IP or without tty", "name": "NSM:Connections", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune for approved jump boxes or bastion hosts", "field": "SourceIPWhitelist"}, {"description": "Filter on use of password vs publickey methods for better coverage", "field": "AuthMethod"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3949', 0, 114, '09-mitre-attack', 'retrieved', 'AAB9D5AC874401F85164C2AB7600F641E8D3AA5BB760E902B8491BE0302C0B84', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
