INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3951', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Attachment of hardware-backed USB KVM devices (e.g., TinyPilot) that enumerate new HID or serial communication interfaces with identifiable metadata.", "external_references": [{"external_id": "AN0448", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0159#AN0448"}], "id": "x-mitre-analytic--fc3e13fd-cbee-4bb0-aae7-ce1e8af7d768", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0448", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Hardware enumeration events via IOKit or USBMuxd showing TinyPilot or unknown keyboard/mouse", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Input or HID devices may be benign or malicious depending on context; tune based on environment (e.g., BYOD/dev stations).", "field": "DeviceClass"}, {"description": "Correlating serials across multiple device insertions may reduce noise but requires tuning.", "field": "SerialCorrelationDepth"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3951', 0, 112, '09-mitre-attack', 'retrieved', 'B288F468CD2AD77544282B3A4E855F74D8E30B544320BF5AD9A0A5AA19809181', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
