INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3952', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects cloud account use for API calls that exceed normal scope, such as IAM changes or access to services never used before.", "external_references": [{"external_id": "AN1504", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0546#AN1504"}], "id": "x-mitre-analytic--fc507123-4267-4cf8-9e30-a90a89043b20", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1504", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "ConsoleLogin, AssumeRole, ListAccessKeys, CreateUser", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"channel": "admin.googleapis.com", "name": "gcp:audit", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Custom list of expected service interactions per user or role.", "field": "ServiceInteractionBaseline"}, {"description": "Frequency of assume-role operations that triggers an alert.", "field": "RoleSwitchRateThreshold"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3952', 0, 100, '09-mitre-attack', 'retrieved', '18201D4BC84CF67B62CA642C5607E259D07967157A89D1E5B6A0DED58D428001', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
