INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3954', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Defenders may detect adversaries forging web credentials in IaaS environments by monitoring for anomalous API activity such as AssumeRole or GetFederationToken being executed by unusual principals. These events often correlate with sudden logon sessions from unfamiliar IP addresses or regions. The chain is usually secret material misuse (stolen private key or password) → API request generating a new token → access to high-value resources.", "external_references": [{"external_id": "AN0717", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0260#AN0717"}], "id": "x-mitre-analytic--fca70138-f183-4deb-b2a4-59908c76070b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0717", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "AssumeRole, GetFederationToken API calls by unusual or new entities", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--5f7c9def-0ddf-423b-b1f8-fb2ddeed0ce3"}, {"channel": "Temporary security credentials used to authenticate into management console or APIs", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Define expected users and roles allowed to use AssumeRole or federation APIs.", "field": "AuthorizedRoleMappings"}, {"description": "Alert if the same user authenticates from geographically disparate locations within a short time.", "field": "GeoVelocityThreshold"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3954', 0, 165, '09-mitre-attack', 'retrieved', 'A01E28FF540342D710F4E153D00490526DA861B28BA5C4437155976340266FF3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
