INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3955', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Establishing network connections on uncommon ports or protocols following C2 disruption or blocking. Often executed by processes that typically exhibit no network activity.", "external_references": [{"external_id": "AN1376", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0499#AN1376"}], "id": "x-mitre-analytic--fcb2ed1a-2f39-47e8-9524-95ceac0ff383", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1376", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "uncommon ports", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Can be tuned to include unexpected or high-entropy ports not typically associated with the process.", "field": "DestinationPort"}, {"description": "Useful to filter benign applications vs suspicious fallback attempts.", "field": "ProcessName"}, {"description": "Tunable ratio of sent/received bytes to indicate potential C2 beaconing or exfiltration.", "field": "DataVolumeRatio"}, {"description": "Adjust temporal window to match likely fallback C2 retries after primary channel fails.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3955', 0, 137, '09-mitre-attack', 'retrieved', 'BDDE0ED46918F3CAB13D7C07F806AF587FEFAC30F4E1165687280366D516B713', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
