INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3956', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Identifies Mach-O binaries dropped into temporary directories with abnormally high binary size or padding patterns, followed by privilege escalation, `exec`, or memory mapping of other processes.", "external_references": [{"external_id": "AN0915", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0322#AN0915"}], "id": "x-mitre-analytic--fcc2b0dc-93c4-49de-abfe-6273c24d1d89", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0915", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "ES_EVENT_TYPE_NOTIFY_EXEC", "name": "macos:endpointsecurity", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "ES_EVENT_TYPE_NOTIFY_MMAP", "name": "macos:endpointsecurity", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}, {"channel": "ES_EVENT_TYPE_NOTIFY_OPEN", "name": "macos:endpointsecurity", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Track dropped executables in ~/Library/, /tmp/, or /private/tmp/", "field": "TempFilePaths"}, {"description": "Define padding size or section entropy anomalies in Mach-O file format", "field": "MachOPaddingThreshold"}, {"description": "Detects whether the binary attempts privilege escalation within short execution window", "field": "FollowOnPrivilegeEscalation"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3956', 0, 122, '09-mitre-attack', 'retrieved', '0499EB65AE7BF207A24F9A3F2020B47F52206EBE3030C0262E986CB120098593', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
