INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3957', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects forged Kerberos Golden Tickets by correlating anomalous Kerberos ticket lifetimes, unexpected encryption types (e.g., RC4 in modern domains), malformed fields in logon/logoff events, and TGS requests without preceding TGT requests. Also monitors for abnormal patterns of access associated with elevated privileges across multiple systems.", "external_references": [{"external_id": "AN0405", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0144#AN0405"}], "id": "x-mitre-analytic--fd614a66-7e99-4a69-9070-3c11036f0335", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0405", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4672, 4634", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"channel": "EventCode=4769", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--02d090b6-8157-48da-98a2-517f7edd49fc"}, {"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Kerberos TGT ticket lifetime exceeding default domain duration; tunable to environment-specific policies.", "field": "TicketLifetimeThreshold"}, {"description": "Valid encryption algorithms for Kerberos tickets; anomalies (e.g., RC4) may indicate forgery.", "field": "AllowedEncryptionTypes"}, {"description": "Baseline of privileged accounts expected to perform Kerberos operations; deviations indicate suspicious activity.", "field": "PrivilegedAccountPatterns"}, {"description": "Expected processes interacting with lsass.exe; deviations may indicate credential dumping.", "field": "ProcessAllowlist"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3957', 0, 164, '09-mitre-attack', 'retrieved', '0AE991925CC6CBD2D9CA7C6E261372E9B966273B99F587C0BA3DBBD76E60A88F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
