INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3959', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversaries writing or moving payloads into directories configured as AV/EDR exclusion paths (e.g., /tmp, /var/lib, or custom directories from auditd exclusion rules). Defender perspective: detect file creation in paths matching known exclusions correlated with unusual parent processes.", "external_references": [{"external_id": "AN0140", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0051#AN0140"}], "id": "x-mitre-analytic--fd7bf05d-6f80-471c-99bf-7aa82ab25440", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0140", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open or creat syscalls targeting excluded paths", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "file path matches exclusion directories", "name": "auditd:PATH", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "System- or security-tool-configured exclusion directories where files should rarely change.", "field": "ExcludedDirectories"}, {"description": "Time window to correlate file creation in excluded paths with execution or network activity.", "field": "CorrelationWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3959', 0, 128, '09-mitre-attack', 'retrieved', 'D45D6640DF3B3BD3740E3D6B4FB2EC91A76FEC7A2FAF427856E08F5CC0D8182D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
