VALUES ('doc-09-mitre-attack-p0-3960', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Flood of spoofed SYN or ACK packets causing exhaustion of OS TCP state table, potentially via user-space utilities or kernel-level DoS agents.", "external_references": [{"external_id": "AN1013", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0356#AN1013"}], "id": "x-mitre-analytic--fde025ac-a180-472c-a9b5-b4fa1e97cc75", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1013", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Invocation of packet generation tools (e.g., hping3, nping) or fork bombs", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "High volumes of SYN/ACK packets with unacknowledged TCP handshakes", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "TCP: possible SYN flood or backlog limit exceeded", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Volume of fake TCP requests before OS begins degradation", "field": "AmplificationThreshold"}, {"description": "Which network interface is being targeted or impacted", "field": "Interface"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3960', 0, 127, '09-mitre-attack', 'retrieved', '9E76D55D7DC648115A490665B89888D55653C6690A62FB6BD067351DA15AF110', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
