VALUES ('doc-09-mitre-attack-p0-3961', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Outbound spoofed traffic to known amplification protocols (e.g., DNS, NTP, Memcached) combined with abnormal network traffic volume targeting remote reflectors, resulting in disproportionate traffic returned to a victim", "external_references": [{"external_id": "AN1140", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0408#AN1140"}], "id": "x-mitre-analytic--fdf11d76-3bd7-41c4-b117-7b0f17b31b17", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1140", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "Sudden spike in outbound throughput without corresponding inbound traffic", "name": "Windows:perfmon", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Interval for measuring sudden outbound spike or volume pattern", "field": "TimeWindow"}, {"description": "List of known ports used for reflection amplification (e.g., 53/DNS, 123/NTP, 11211/Memcached)", "field": "AmplificationProtocolPorts"}, {"description": "Heuristic threshold where the response volume far outweighs the request volume", "field": "PacketToByteRatio"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3961', 0, 129, '09-mitre-attack', 'retrieved', '08872864D782320CCAF7427A24CE4ECB7EF9A5876A233A1F790DE1163F2ED24C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
