VALUES ('doc-09-mitre-attack-p0-3962', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects SVGs downloaded via browser that invoke AppleScript, osascript, or JavaScriptCore processes, followed by network egress or file drop to LaunchAgents or ~/Library.", "external_references": [{"external_id": "AN1409", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0510#AN1409"}], "id": "x-mitre-analytic--fe1cff12-9772-4ba9-92bc-c26eae79da24", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1409", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "ES_EVENT_TYPE_NOTIFY_EXEC", "name": "macos:endpointsecurity", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "subsystem: com.apple.WebKit or com.apple.WebKit.Networking", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Scriptable binaries such as osascript, jsc, JavaScriptCore – may vary by OS version", "field": "ScriptEngines"}, {"description": "Restrict to non-system users or only specific login sessions", "field": "UserContext"}, {"description": "SVGs embedded inside PDFs or HTML with script-based triggers", "field": "EmbeddedContentIndicators"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3962', 0, 117, '09-mitre-attack', 'retrieved', '98820C2B27E75CB09CC6A8C4783CCD57C84B195FA774FE2DB9E96EE2CBD2B11E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
