VALUES ('doc-09-mitre-attack-p0-3963', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary installation or use of RMM software (e.g., TeamViewer, AnyDesk, ScreenConnect) followed by outbound beaconing or remote session establishment", "external_references": [{"external_id": "AN0714", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0259#AN0714"}], "id": "x-mitre-analytic--fe1e10ae-ddd2-40f0-8e62-3db88c0c8c68", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0714", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "new rule allowing inbound or outbound connections for remote desktop software", "name": "WinEventLog:Microsoft-Windows-Windows Firewall With Advanced Security/Firewall", "x_mitre_data_component_ref": "x-mitre-data-component--d2ff4b56-8351-4ed8-b0fb-d8605366005f"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "RMM software can vary; defenders should update rules to account for additional binaries (e.g., ConnectWise, Zoho Assist)", "field": "Image"}, {"description": "RMM software may use configurable or random high ports outside of standard (e.g., 7070, 5650)", "field": "DestinationPort"}, {"description": "Expected parent process may vary in different enterprise contexts", "field": "ParentImage"}, {"description": "Correlation window for install-to-beacon or process-to-network event should match operational environment", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3963', 0, 155, '09-mitre-attack', 'retrieved', '0A4E357685345AF2333705DE10D3B81026810E54A867D47E856E7DA265F1D12C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
