VALUES ('doc-09-mitre-attack-p0-3964', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Creation of inbox rules via PowerShell (New-InboxRule) or transport rules using Exchange cmdlets. Correlates user behavior, cmdlet usage, and rule properties.", "external_references": [{"external_id": "AN1589", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0576#AN1589"}], "id": "x-mitre-analytic--fe489775-b01e-4da2-a0e2-962d1572ba09", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1589", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Cmdlet - New-InboxRule", "name": "m365:exchange", "x_mitre_data_component_ref": "x-mitre-data-component--b33d36e3-d7ea-4895-8eed-19a08a8f7c4f"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Certain service accounts or admin contexts may be expected to run these rules.", "field": "UserContext"}, {"description": "Correlate between rule creation and follow-on message forwarding within this timeframe.", "field": "TimeWindow"}, {"description": "Whitelisted or trusted destination addresses may be tuned per org policy.", "field": "TargetMailbox"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3964', 0, 127, '09-mitre-attack', 'retrieved', 'FAE44D5CBE0F84E2F661B85C8B8FE29B7CD162C3CD8DB9B4C16E43CD3ECA478C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
