VALUES ('doc-09-mitre-attack-p0-3965', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects clients issuing DNS queries with high volume, long subdomain lengths, encoded payload patterns, or to known malicious infrastructure; indicative of DNS-based C2 channels.", "external_references": [{"external_id": "AN1124", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0400#AN1124"}], "id": "x-mitre-analytic--fe648823-66c8-4cc3-8a8e-38616194464c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1124", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "dns.log", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of suspicious/malicious C2 domains", "field": "DomainReputationFeed"}, {"description": "Tunable burst rate per IP per second", "field": "QueryRatePerClient"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3965', 0, 88, '09-mitre-attack', 'retrieved', '48AAC4EE1C98A6C6EFE05EBDAA88B724E572688E5E2043CB27CF0BDDC42C6EDE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
