VALUES ('doc-09-mitre-attack-p0-3966', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Router/switch receives a knock pattern (same src touches device unicast, broadcast, and network-address on same or stepped ports) followed by ACL/line-vty/service enable and the first mgmt session success.", "external_references": [{"external_id": "AN0845", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0302#AN0845"}], "id": "x-mitre-analytic--fe82e2a6-a928-4fe0-a899-fead90eabb29", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0845", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Config/ACL changes, line vty transport input changes, telnet/ssh/http(s) enable, image/feature module changes.", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "Series of denied/closed flows to distinct ports then success to mgmt port from same src_ip within TimeWindow.", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Mgmt ports to focus on: 22,23,2323,80,443,161,4786.", "field": "MgmtPortSet"}, {"description": "Tighten thresholds on edge/internet-facing devices.", "field": "DeviceRole"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3966', 0, 124, '09-mitre-attack', 'retrieved', '7A4FF5435B4D2A2329497B1C41098D8E109330DA04CC9DDDE893662CFBF5EE28', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
