INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3967', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unusual enumeration of services and resources through cloud APIs such as AWS CLI `describe-*`, Azure Resource Manager queries, or GCP project listings. Defender perspective includes anomalous API calls, unexpected volume of service enumeration, and correlation of discovery with recently compromised sessions.", "external_references": [{"external_id": "AN1127", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0402#AN1127"}], "id": "x-mitre-analytic--fe8c1ef5-59ed-40c3-b7f6-eb560555ee22", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1127", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "DescribeInstances, DescribeServices, ListFunctions: High frequency enumeration calls or unusual user agents performing discovery", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--8c826308-2760-492f-9e36-4f0f7e23bcac"}, {"channel": "AssumeRole: Discovery actions tied to assumed identities outside of normal context", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Rate of API calls used to enumerate services; tuned to reduce noise from automated inventory tools.", "field": "EnumerationRateThreshold"}, {"description": "Expected user agents for cloud management tools; deviations may indicate adversarial tools.", "field": "UserAgentFilter"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3967', 0, 148, '09-mitre-attack', 'retrieved', 'F26B67BF5ABDA4776A8D9ABA4E541C67352082845D6D571D947D35BD109F92C0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
