INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3968', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unusual service stop events, termination of AV/EDR processes, registry modifications disabling security tools, and firewall/defender configuration changes. Correlate process creation with service stop requests and registry edits.", "external_references": [{"external_id": "AN0886", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0317#AN0886"}], "id": "x-mitre-analytic--febc685b-997f-4095-b60b-5dfeefe01ae3", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0886", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7045", "name": "WinEventLog:System", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}, {"channel": "EventCode=12", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--7f70fae7-a68d-4730-a83a-f260b9606129"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Exclude authorized administrative tools that stop services during maintenance.", "field": "ProcessWhitelist"}, {"description": "Refine which services are considered security-critical (e.g., AV, EDR, firewall).", "field": "ServiceNamePatterns"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3968', 0, 109, '09-mitre-attack', 'retrieved', '769646E8880AC64022D500838D3224D75BC6AD61ED8583BC76BE42BCEB8776DF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
