INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3971', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects the execution of scripting or command interpreters (e.g., powershell.exe, cmd.exe, wscript.exe) outside expected administrative time windows or from abnormal user contexts, often followed by encoded/obfuscated arguments or secondary execution events.", "external_references": [{"external_id": "AN1428", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0516#AN1428"}], "id": "x-mitre-analytic--fee823fd-f31e-4898-820e-322e49574438", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1428", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tunable to match encoded or uncommon script execution patterns specific to the environment.", "field": "CommandLinePattern"}, {"description": "May vary across managed/unmanaged workstations or user-driven script activity.", "field": "ParentProcessName"}, {"description": "Used to restrict analysis to work hours or known admin maintenance windows.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3971', 0, 119, '09-mitre-attack', 'retrieved', 'C74B72F78A5A67957148373797AFB7A355E5167DB7534F4C84CA81E9CBB60401', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
