INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3973', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects unexpected use of usermod, gpasswd, or direct modification of /etc/group to elevate user group membership.", "external_references": [{"external_id": "AN0866", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0310#AN0866"}], "id": "x-mitre-analytic--ff692121-8bbd-4d22-8192-fe6a7dd94f57", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0866", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "SYSCALL for usermod or /etc/group file modification", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Focus on ''sudo'', ''wheel'', or custom high-privilege groups", "field": "GroupName"}, {"description": "Account that initiated the change (e.g., service account or unrecognized user)", "field": "UserContext"}, {"description": "Detect elevation outside change windows", "field": "TimeWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3973', 0, 100, '09-mitre-attack', 'retrieved', '2781C0EE9C1BEC287D1E84C1533145C9B198740D567ABCA068CB14F3C6ACAADA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
