INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3974', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects creation or modification of Windows Services through command-line tools (e.g., `sc.exe`, `powershell.exe`), Registry key changes under `HKLM\\System\\CurrentControlSet\\Services`, and service execution under SYSTEM with unsigned or anomalous binary paths. Detects privilege escalation via driver installation or `CreateServiceW` usage. Correlates parent-child lineage, startup behavior, and rare service names.", "external_references": [{"external_id": "AN1527", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0552#AN1527"}], "id": "x-mitre-analytic--ffaa281c-dd99-486d-bc7f-225580f784f4", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1527", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4697", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=13, 14", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "EventCode=6", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3551476e-14f5-4e48-a518-e82135329e03"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Regex for suspicious or uncommon service names (e.g., `svhostx`, `winhelp`, etc.)", "field": "ServiceNamePattern"}, {"description": "Flag services whose image path resides in uncommon directories (e.g., `C:\\Users\\`, `C:\\Temp\\`)", "field": "ImagePathFilter"}, {"description": "Watch for `.sys` files loaded by `sc`, Registry, or `ZwLoadDriver` APIs", "field": "DriverExtensionList"}, {"description": "Temporal window to correlate Registry `Start` key changes with service creation", "field": "StartupTypeChangeWindow"}, {"description": "Raise alerts for unsigned binaries registered as services", "field": "UnsignedBinaryAlert"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3974', 0, 179, '09-mitre-attack', 'retrieved', '70E2642D97E7AC9F66F99847158E7F3E5F14E6583753983B0AECAD79EA2EAA8E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
