INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3975', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of commands to query system locale and language settings, such as ''defaults read -g AppleLocale'' or ''systemsetup -gettimezone''. Unusual parent processes or execution contexts of these commands may indicate adversarial discovery.", "external_references": [{"external_id": "AN1563", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0565#AN1563"}], "id": "x-mitre-analytic--ffc71b21-982b-4fc7-8276-bd679d67bc95", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1563", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "defaults read -g AppleLocale or systemsetup -gettimezone", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "execve", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Restrict or monitor processes outside of system utilities that query AppleLocale or system language settings.", "field": "ExecutionPath"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3975', 0, 107, '09-mitre-attack', 'retrieved', '78ACAF42F8A2A4AF85F1790677CE5059E7AC997A32AC44CD34A7830F20BBB3FB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
