INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3976', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Correlated registry modifications under Print Processors path, followed by DLL file creation within the system print processor directory, and DLL load by spoolsv.exe. Malicious execution often occurs during service restart or system boot, with SYSTEM-level privileges.", "external_references": [{"external_id": "AN0074", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0026#AN0074"}], "id": "x-mitre-analytic--ffe7278f-7cd1-402f-a3a7-dcc7a363b031", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0074", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=13, 14", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Correlate Registry + DLL Write + Module Load within a short boot or spooler restart window (e.g., 5 minutes).", "field": "TimeWindow"}, {"description": "System-specific path derived from GetPrintProcessorDirectory API call; may differ across Windows versions or configurations.", "field": "PrintProcessorDirectory"}, {"description": "Some environments may use custom or non-standard DLL naming conventions for print processors. Allowlist known values.", "field": "DLLNamePattern"}, {"description": "Check Authenticode signature and issuer chain for loaded DLLs to reduce false positives.", "field": "SignedImageValidation"}, {"description": "Monitor for spoolsv.exe restart events that trigger malicious print processor loading.", "field": "ServiceRestartTrigger"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3976', 0, 188, '09-mitre-attack', 'retrieved', '347A3F0E72182DB78D80A4E9F0568F889083FC3182E04D43A871844F386515A0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
