VALUES ('doc-09-mitre-attack-p0-3978', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-20T15:05:19.271Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Initial construction of a WMI object, such as a filter, consumer, subscription, binding, or providers.", "external_references": [{"external_id": "DC0008", "source_name": "mitre-attack", "url": "https://attack.mitre.org/datacomponents/DC0008"}], "id": "x-mitre-data-component--05645013-2fed-4066-8bdc-626b2e201dd4", "modified": "2025-11-12T22:03:39.105Z", "name": "WMI Creation", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-data-component", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_sources": [{"channel": "Creation or modification of __EventFilter, __FilterToConsumerBinding, or CommandLineEventConsumer", "name": "WinEventLog:WMI"}, {"channel": "EventCode=5857, 5858, 5860, 5861", "name": "WinEventLog:WMI"}, {"channel": "WMI Object Creation Events", "name": "WinEventLog:Application"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-3978', 0, 78, '09-mitre-attack', 'retrieved', 'B976C15F96665F2B3BCA4754979AC417B45B4159A9CCC4F0D20798D282EABB4C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
