VALUES ('doc-09-mitre-attack-p0-3980', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-20T15:05:19.272Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Changes made to a virtual machine image, including setting and/or control data (ex: Azure Compute Service Images PATCH)", "external_references": [{"external_id": "DC0036", "source_name": "mitre-attack", "url": "https://attack.mitre.org/datacomponents/DC0036"}], "id": "x-mitre-data-component--071a09b1-8945-46fd-8bb7-6bcc89400963", "modified": "2025-10-21T15:14:40.151Z", "name": "Image Modification", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-data-component", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_sources": [{"channel": "push event of new image version from unrecognized user or context", "name": "docker:registry"}, {"channel": "ModifyImageAttribute", "name": "AWS:CloudTrail"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-3980', 0, 72, '09-mitre-attack', 'retrieved', 'C12A251F47A52EE143810C0BA40DFEB726EAC64E2CC1590E2F62010EE9C4FAE8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
