VALUES ('doc-09-mitre-attack-p0-3983', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-20T15:05:19.275Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Contextual data about a cloud volume and activity around it, such as id, type, state, and size", "external_references": [{"external_id": "DC0100", "source_name": "mitre-attack", "url": "https://attack.mitre.org/datacomponents/DC0100"}], "id": "x-mitre-data-component--0f72bf50-35b3-419d-ab95-70f9b6a818dd", "modified": "2025-11-12T22:03:39.105Z", "name": "Volume Metadata", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-data-component", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_sources": [{"channel": "None", "name": "Metadata"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-3983', 0, 57, '09-mitre-attack', 'retrieved', 'E3CFC5FF5F4345FBD33C7236F879F365C9B7579246878B9D58B101A75942AFE5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
