INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3989', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-20T15:05:19.274Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The initial establishment of a network session, where a system or process initiates a connection to a local or remote endpoint. This typically involves capturing socket information (source/destination IP, ports, protocol) and tracking session metadata. Monitoring these events helps detect lateral movement, exfiltration, and command-and-control (C2) activities.\n\n*Data Collection Measures:*\n\n- Windows:\n - Event ID 5156 – Filtering Platform Connection - Logs network connections permitted by Windows Filtering Platform (WFP).\n - Sysmon Event ID 3 – Network Connection Initiated - Captures process, source/destination IP, ports, and parent process.\n- Linux/macOS:\n - Netfilter (iptables), nftables logs - Tracks incoming and outgoing network connections.\n - AuditD (`connect` syscall) - Logs TCP, UDP, and ICMP connections.\n - Zeek (`conn.log`) - Captures protocol, duration, and bytes transferred.\n- Cloud & Network Infrastructure:\n - AWS VPC Flow Logs / Azure NSG Flow Logs - Logs IP traffic at the network level in cloud environments.\n - Zeek (conn.log) or Suricata (network events) - Captures packet metadata for detection and correlation.\n- Endpoint Detection & Response (EDR):\n - Detect anomalous network activity such as new C2 connections or data exfiltration attempts.", "external_references": [{"external_id": "DC0082", "source_name": "mitre-attack", "url": "https://attack.mitre.org/datacomponents/DC0082"}], "id": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba", "modified": "2026-05-12T15:12:00.770Z", "name": "Network Connection Creation", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-data-component", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["ics-attack", "mobile-attack", "enterprise-attack"], "x_mitre_log_sources": [{"channel": "log entries indicating network connection initiation on macOS", "name": "NSM:Flow"}, {"channel": "connect", "name": "auditd:SYSCALL"}, {"channel": "execve: Execs of chromium, google-chrome, firefox, libreoffice with http(s) in cmdline", "name": "auditd:SYSCALL"}, {"channel": "connect/sendto", "name": "auditd:SYSCALL"}, {"channel": "open or connect syscalls on /tmp/ssh-* or $SSH_AUTH_SOCK", "name": "auditd:SYSCALL"}, {"channel": "socket/connect with TLS context by unexpected process", "name": "auditd:SYSCALL"}, {"channel": "socket/bind: New bind() to a previously closed port shortly after the sequence.", "name": "auditd:SYSCALL"}, {"channel": "sendto/connect", "name": "auditd:SYSCALL"}, {"channel": "outbound connections", "name": "auditd:SYSCALL"}, {"channel": "socket/bind: Process binds to a new local port shortly after knock", "name": "auditd:SYSCALL"}, {"channel": "socket/connect calls showing SSH processes forwarding arbitrary ports", "name": "auditd:SYSCALL"}, {"channel": "openat,connect -k discovery", "name": "auditd:SYSCALL"}, {"channel": "Outbound connection to 169.254.169.254 from EC2 workload", "name": "AWS:VPCFlowLogs"}, {"channel": "Large transfer volume (>20MB) from RDS IP range to external public IPs", "name": "AWS:VPCFlowLogs"}, {"channel": "High outbound traffic from new region resource", "name": "AWS:VPCFlowLogs"}, {"channel": "Outbound connections to port 22, 3389", "name": "AWS:VPCFlowLogs"}, {"channel": "Traffic observed on mirror destination instance", "name": "AWS:VPCFlowLogs"}, {"channel": "outbound connection to internal or external APIs", "name": "cni:netflow"}, {"channel": "socket connect", "name": "ebpf:syscalls"}, {"channel": "/var/log/esxupdate.log or /var/log/vmksummary.log", "name": "esxi:esxupdate"}, {"channel": "System service interactions", "name": "esxi:hostd"}, {"channel": "Service initiated connections", "name": "esxi:hostd"}, {"channel": "Service-Based Network Connection", "name": "esxi:hostd"}, {"channel": "protocol egress", "name": "esxi:vmkernel"}, {"channel": "network activity", "name": "esxi:vmkernel"}, {"channel": "None", "name": "esxi:vmkernel"}, {"channel": "network session initiation with external HTTPS services", "name": "esxi:vmkernel"}, {"channel": "family=AF_PACKET or protocol raw; process name not in allowlist.", "name": "linux:osquery"}, {"channel": "network", "name": "linux:syslog"}, {"channel": "postfix/smtpd", "name": "linux:syslog"}, {"channel": "New Wi-Fi connection established or repeated association failures", "name": "linux:syslog"}, {"channel": "None", "name": "linux:syslog"}, {"channel": "EventCode=3, 22", "name": "linux:Sysmon"}, {"channel": "ES_EVENT_TYPE_NOTIFY_CONNECT", "name": "macos:endpointsecurity"}, {"channel": "process_events/socket_events", "name": "macos:osquery"}, {"channel": "execution of trusted tools interacting with external endpoints", "name": "macos:osquery"}, {"channel": "launchd or network_events", "name": "macos:osquery"}, {"channel": "process_events + launchd", "name": "macos:osquery"}, {"channel": "process_events, socket_events", "name": "macos:osquery"}, {"channel": "CONNECT: Long-lived connections from remote-control parents to external IPs/domains", "name": "macos:osquery"}, {"channel": "None", "name": "macos:osquery"}, {"channel": "connection attempts", "name": "macos:unifiedlog"}, {"channel": "connection open", "name": "macos:unifiedlog"}, {"channel": "network connection events", "name": "macos:unifiedlog"}, {"channel": "First outbound connection from the same PID/user shortly after an inbound trigger.", "name": "macos:unifiedlog"}, {"channel": "network sessions initiated by remote desktop apps", "name": "macos:unifiedlog"}, {"channel": "Inbound connections to VNC/SSH ports", "name": "macos:unifiedlog"}, {"channel": "network", "name": "macos:unifiedlog"}, {"channel": "Outbound Traffic", "name": "macos:unified