VALUES ('doc-09-mitre-attack-p0-3991', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-20T15:05:19.274Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Creating new objects in AD, such as user accounts, groups, organizational units (OUs), or trust relationships. Logged as Event ID 5137. Examples:\n\n- User Account Creation: New user account.\n- Group Creation: New security/distribution group.\n- OU Creation: New organizational unit.\n- Service Account Creation: New service account for automation or malicious tasks.\n- Trust Object Creation: Trust relationship with another domain.", "external_references": [{"external_id": "DC0087", "source_name": "mitre-attack", "url": "https://attack.mitre.org/datacomponents/DC0087"}], "id": "x-mitre-data-component--18b236d8-7224-488f-9d2f-50076a0f653a", "modified": "2025-11-12T22:03:39.105Z", "name": "Active Directory Object Creation", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-data-component", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_sources": [{"channel": "New device object creation", "name": "azure:audit"}, {"channel": "Device Object Creation", "name": "WinEventLog:Security"}, {"channel": "EventCode=4928", "name": "WinEventLog:Security"}, {"channel": "CreateAccessKey, ImportKeyPair, CreateLoginProfile, CreateKeyPair", "name": "AWS:CloudTrail"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-3991', 0, 121, '09-mitre-attack', 'retrieved', '40928628D6263CCE5FB8D139B22E64066BBF50D4A541E428E369B5065D6E112C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
