VALUES ('doc-09-mitre-attack-p0-3993', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-20T15:05:19.273Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "To events where a file is opened or accessed, making its contents available to the requester. This includes reading, executing, or interacting with files by authorized or unauthorized entities. Examples include logging file access events (e.g., Windows Event ID 4663), monitoring file reads, and detecting unusual file access patterns. Examples: \n\n- File Read Operations: A user opens a sensitive document (e.g., financial_report.xlsx) on a shared drive.\n- File Execution: A script or executable file is accessed and executed (e.g., malware.exe is run from a temporary directory).\n- Unauthorized File Access: An unauthorized user attempts to access a protected configuration file (e.g., `/etc/passwd` on Linux or `System32` files on Windows).\n- File Access Patterns: Bulk access to multiple files in a short time (e.g., mass access to documents on a file server).\n- File Access via Network: Files on a network share are accessed remotely (e.g., logs of SMB file access).", "external_references": [{"external_id": "DC0055", "source_name": "mitre-attack", "url": "https://attack.mitre.org/datacomponents/DC0055"}], "id": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71", "modified": "2026-05-12T15:12:00.770Z", "name": "File Access", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-data-component", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["ics-attack", "enterprise-attack", "mobile-attack"], "x_mitre_log_sources": [{"channel": "looking for file access to scripts with abnormal encoding patterns", "name": "macOS:unifiedlog"}, {"channel": "READ or COPY operations where path matches external/shared locations of other apps (e.g., /storage/emulated/0/Android/data/ /files/, /storage/emulated/0/Download/ /*)", "name": "android:logcat"}, {"channel": "KeyChain/AndroidKeyStore read of token alias", "name": "android:logcat"}, {"channel": "READ/LIST/STAT of /sdcard|/storage/emulated/0|/Android/media|/Documents with >N distinct paths in TimeWindow", "name": "android:logcat"}, {"channel": "/home/*/.mozilla/firefox/*/logins.json OR /home/*/.config/google-chrome/*/Login Data", "name": "auditd:FILE"}, {"channel": "/proc/*/mem read attempt", "name": "auditd:FILE"}, {"channel": "read: File access to /proc/modules or /sys/module/", "name": "auditd:FS"}, {"channel": "Read access to known backup software configuration files (e.g., /etc/rsnapshot.conf, /opt/veeam/config.ini)", "name": "auditd:PATH"}, {"channel": "open: Access to sensitive log files (/var/log/auth.log, /var/log/secure, /var/log/syslog)", "name": "auditd:PATH"}, {"channel": "PATH", "name": "auditd:PATH"}, {"channel": "file read", "name": "auditd:PATH"}, {"channel": "open, read, or stat of browser config files", "name": "auditd:SYSCALL"}, {"channel": "open: File access attempt on /tmp/krb5cc_* or /tmp/krb5.ccache", "name": "auditd:SYSCALL"}, {"channel": "openat", "name": "auditd:SYSCALL"}, {"channel": "open", "name": "auditd:SYSCALL"}, {"channel": "open, read", "name": "auditd:SYSCALL"}, {"channel": "open, flock, fcntl, unlink", "name": "auditd:SYSCALL"}, {"channel": "read/open of sensitive files", "name": "auditd:SYSCALL"}, {"channel": "Unusual processes accessing or modifying cookie databases", "name": "auditd:SYSCALL"}, {"channel": "PATH records referencing /dev/video*", "name": "auditd:SYSCALL"}, {"channel": "open, read: /etc/ssl/, /etc/pki/, ~/.pki/nssdb/", "name": "auditd:SYSCALL"}, {"channel": "Processes reading credential or token cache files", "name": "auditd:SYSCALL"}, {"channel": "read/open of sensitive file directories", "name": "auditd:SYSCALL"}, {"channel": "open/read of sensitive config or secret files", "name": "auditd:SYSCALL"}, 