VALUES ('doc-09-mitre-attack-p0-3995', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-20T15:05:19.274Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The process of retrieving or querying a list of virtual machine instances or compute instances within a cloud infrastructure. This activity provides a view of all available or running instances, typically including their associated metadata such as instance ID, name, state, and configuration details. Examples:\n\n- AWS: instance enumeration involves the `DescribeInstances` API call, which retrieves information about running or stopped EC2 instances.\n- Azure: VM enumeration can be monitored via the `Microsoft.Compute/virtualMachines/read` operation.\n- GCP: instance enumeration is logged as an `instance.list` operation within GCP Audit Logs.\n\n*Data Collection Measures:*\n\n- AWS CloudTrail: CloudTrail logs stored in S3 or forwarded to CloudWatch.\n- Azure Activity Logs: Accessible via Azure Monitor or exported to a storage account.\n- GCP Audit Logs: Logs Explorer or BigQuery.", "external_references": [{"external_id": "DC0075", "source_name": "mitre-attack", "url": "https://attack.mitre.org/datacomponents/DC0075"}], "id": "x-mitre-data-component--2a80d95f-08c4-48e3-833e-151ef19d90f5", "modified": "2025-10-21T15:14:38.969Z", "name": "Instance Enumeration", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-data-component", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_sources": [{"channel": "DescribeDBInstances", "name": "AWS:CloudTrail"}, {"channel": "MICROSOFT.COMPUTE/VIRTUALMACHINES/LIST", "name": "azure:activity"}, {"channel": "compute.instances.list OR storage.buckets.list", "name": "gcp:audit"}, {"channel": "DescribeInstances, GetConsoleOutput, DescribeImages", "name": "AWS:CloudTrail"}, {"channel": "Microsoft.Compute/virtualMachines/read", "name": "azure:activity"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-3995', 0, 180, '09-mitre-attack', 'retrieved', '738C0C9AFDF79E7BC9357719D6BC45E5F3D012AA50EB593DD84CC8E4E83B9798', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
