VALUES ('doc-09-mitre-attack-p0-4001', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-20T15:05:19.275Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The removal of a cloud-based or on-premise block storage volume. This action permanently deletes the allocated storage and may result in data loss if not backed up.\n\n*Data Collection Measures:*\n\n- Cloud Logging & APIs\n - AWS CloudTrail Logs\n - `eventName: DeleteVolume` (tracks volume deletions)\n - Azure Monitor Logs\n - `operationName: Microsoft.Compute/disks/delete`\n - `status: Success | Failure` (flag unauthorized delete attempts)\n - Google Cloud Audit Logs\n - `protoPayload.methodName: \"v1.compute.disks.delete\"`\n - `authenticationInfo.principalEmail` (identifies the user deleting the volume)\n- System & Host-Based Logging\n - Linux & macOS Logs:\n - `/var/log/syslog` or `/var/log/messages` for volume detach/deletion actions\n - Windows Event Logs:\n - Event ID 98 (Storage Class Memory)\n - Event ID 225 (Volume Removal Detected)\n - Event ID 12 (Disk Removal Notification)", "external_references": [{"external_id": "DC0098", "source_name": "mitre-attack", "url": "https://attack.mitre.org/datacomponents/DC0098"}], "id": "x-mitre-data-component--3acecdde-c327-4498-9bb8-33a2e63c6c57", "modified": "2025-11-12T22:03:39.105Z", "name": "Volume Deletion", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-data-component", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_sources": [{"channel": "file delete|datastore purge", "name": "esxi:vmkernel"}, {"channel": "DeleteVolume", "name": "AWS:CloudTrail"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-4001', 0, 165, '09-mitre-attack', 'retrieved', '76CC3BE07ABA5A747507D62DA66560DFE085DA0F96B02133CDFA3C87083167CF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
