VALUES ('doc-09-mitre-attack-p0-4002', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-20T15:05:19.272Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Refers to the event in which a new process (executable) is initialized by an operating system. This can involve parent-child process relationships, process arguments, and environmental variables. Monitoring process creation is crucial for detecting malicious behaviors, such as execution of unauthorized binaries, scripting abuse, or privilege escalation attempts.. ", "external_references": [{"external_id": "DC0032", "source_name": "mitre-attack", "url": "https://attack.mitre.org/datacomponents/DC0032"}], "id": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077", "modified": "2026-05-12T15:12:00.773Z", "name": "Process Creation", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-data-component", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["ics-attack", "mobile-attack", "enterprise-attack"], "x_mitre_log_sources": [{"channel": "None", "name": "Process"}, {"channel": "execve", "name": "auditd:SYSCALL"}, {"channel": "log stream ''eventMessage contains pubsub or broker''", "name": "macos:unifiedlog"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon"}, {"channel": "Execution of binary resolved from $PATH not located in /usr/bin or /bin", "name": "linux:osquery"}, {"channel": "Process execution path inconsistent with baseline PATH directories", "name": "macos:unifiedlog"}, {"channel": "ES_EVENT_TYPE_NOTIFY_EXEC", "name": "macos:endpointsecurity"}, {"channel": "EventCode=4688", "name": "WinEventLog:Security"}, {"channel": "process_events", "name": "linux:osquery"}, {"channel": "exec", "name": "macos:endpointsecurity"}, {"channel": "processes", "name": "macos:osquery"}, {"channel": "Execution of launchctl with suspicious arguments", "name": "macos:unifiedlog"}, {"channel": "execve network tools", "name": "auditd:SYSCALL"}, {"channel": "process_events", "name": "macos:osquery"}, {"channel": "execve calls to soffice.bin with suspicious macro execution flags", "name": "auditd:SYSCALL"}, {"channel": "Process execution of Microsoft Word, Excel, PowerPoint with macro execution attempts", "name": "macos:unifiedlog"}, {"channel": "process reading browser configuration paths", "name": "macos:osquery"}, {"channel": "exec logs", "name": "macos:unifiedlog"}, {"channel": "execve: Processes launched with LD_PRELOAD/LD_LIBRARY_PATH pointing to non-system dirs", "name": "auditd:EXECVE"}, {"channel": "exec: Process execution context for loaders calling dlopen/dlsym", "name": "macos:endpointsecurity"}, {"channel": "EXECVE", "name": "auditd:EXECVE"}, {"channel": "execution of unexpected binaries during user shell startup", "name": "auditd:EXECVE"}, {"channel": "launch of Terminal.app or shell with non-standard environment setup", "name": "macos:unifiedlog"}, {"channel": "ES_EVENT_TYPE_NOTIFY_EXEC with unusual parent-child process relationships from zsh", "name": "macos:endpointsecurity"}, {"channel": "execve of systemctl or service stop", "name": "auditd:SYSCALL"}, {"channel": "execve of launchctl or pkill", "name": "auditd:SYSCALL"}, {"channel": "process::exec", "name": "macos:unifiedlog"}, {"channel": "execve: Execution of klist, kinit, or tools interacting with ccache outside normal user context", "name": "auditd:SYSCALL"}, {"channel": "Execution of non-standard binaries accessing Kerberos APIs", "name": "macos:osquery"}, {"channel": "execve: Electron-based binary spawning shell or script interpreter", "name": "auditd:SYSCALL"}, {"channel": "Electron app spawning unexpected child process", "name": "macos:unifiedlog"}, {"channel": "/root/.ash_history or /etc/init.d/*", "name": "esxi:shell"}, {"channel": "execve calls with high-frequency or known bandwidth-intensive tools", "name": "auditd:SYSCALL"}, {"channel": "exec or spawn calls to proxy tools or torrent clients", "name": "macos:unifiedlog"}, {"channel": "bandwidth-intensive command execution from within a container namespace", "name": "containers:osquery"}, {"channel": "process launch", "name": "macos:unifiedlog"}, {"channel": "log stream --info --predicate ''subsystem == \"com.apple.cfprefsd\"''", "name": "macos:unifiedlog"}, {"channel": "execution of security, sqlite3, or unauthorized binaries", "name": "macos:unifiedlog"}, {"channel": "Unexpected applications generating outbound DNS queries", "name": "macos:unifiedlog"}, {"channel": "EventCode=1", "name": "linux:Sysmon"}, {"channel": "execve", "name": "macos:osquery"}, {"channel": "Unexpected child process of Safari or Chrome", "name": "macos:unifiedlog"}, {"channel": "execve or syscall invoking vm artifact check commands (e.g., dmidecode, lspci, dmesg)", "name": "auditd:SYSCALL"}, {"channel": "execution of system_profiler, ioreg, kextstat with argument patterns related to VM/sandbox checks", "name": "macos:unifiedlog"}, {"channel": "process writes or modifies files in excluded paths", "name": "macos:unifiedlog"}, {"channel": "process", "name": "macos:unifiedlog"}, {"channel": "com.apple.mail.* exec.*", "name": "macos:unifiedlog"}, {"channel": "execution of memory inspection tools (lldb, gdb, osqueryi)", "name": "macos:unifiedlog"}, {"channel": "/var/log/vobd.log", "name": "esxi:vobd"}, {"channel": "kubectl exec or kubelet API calls targeting running pods", "name": "kubernetes:apiserver"}, {"channel": "Process execution events within container namespace context", "name": "docker:audit"}, {"channel": "process persists beyond parent shell termination", "name": "auditd:SYSCALL"}, {"channel": "background process persists beyond user logout", "name": "macos:unifiedlog"}, {"channel": "execve: Execution of scripts or binaries sourced from mail directories (/var/mail, ~/Maildir)", "name": "auditd:SYSCALL"}, {"channel": "Preview.app, Safari.app, or Mail.app spawning new processes outside normal patterns", "name": "macos:unifiedlog"}, {"channel": "process execution across cloud VM", "name": "esxi:hostd"}, {"channel": "systemctl spawning managed processes", "name": "auditd:EXECVE"}, {"channel": "None", "name": "macos:unifiedlog"}, {"channel": "/var/log/shell.log", "name": "esxi:shell"}, {"channel": "Execution of processes linked to hijacked sessions (e.g., anomalous parent-child process lineage)", "name": "macos:unifiedlog"}, {"channel": "exec events where web process starts a shell/tooling", "name": "macos:unifiedlog"}, {"channel": "Docker/Kubernetes audit of exec/attach (kubectl exec) or unexpected child processes inside container", "name": "docker:events"}, {"channel": "exec of osascript, bash, curl with suspicious parameters", "name": "macos:unifiedlog"}, {"channel": "execve: Execution of container management CLIs (docker, crictl, kubectl) or interpreted shells (sh, bash, python) within container context", "name": "auditd:SYSCALL"}, {"channel": "es_event_exec", "name": "macos:endpointsecurity"}, {"channel": "execve: Execution of discovery commands targeting backup binaries, processes, or config paths", "name": "auditd:SYSCALL"}, {"channel": "Process execution logs showing discovery commands like mdfind, system_profiler, or launchctl list", "name": "macos:unifiedlog"}, {"channel": "process_events OR launchd", "name": "macos:osquery"}, {"channel": "execve", "name": "auditd:EXECVE"}, {"channel": "launchd or process_events", "name": "macos:osquery"}, {"channel": "process and file events via log stream", "name": "macos:unifiedlog"}, {"channel": "execve: Execution of scripts or binaries spawned from browser processes", "name": "auditd:SYSCALL"}, {"channel": "Browser processes launching unexpected interpreters (osascript, bash)", "name": "macos:unifiedlog"}, {"channel": "exec: Execution of defaults, plutil, or common editors (vim/nano) targeting plist files", "name": "macos:unifiedlog"}, {"channel": "EXECVE", "name": "auditd:SYSCALL"}, {"channel": "process:exec", "name": "macos:unifiedlog"}, {"channel": "execve: Execution of bash, python, or perl processes spawned by browser/email client", "name": "auditd:SYSCALL"}, {"channel": "Execution of osascript, bash, or Terminal initiated from Mail.app or Safari", "name": "macos:unifiedlog"}, {"channel": "execve of /bin/sh,/bin/bash,/usr/bin/curl,/usr/bin/python by service accounts (e.g., apache, mysql, nobody) immediately after inbound network activity.", "name": "auditd:SYSCALL"}, {"channel": "parent_name in (''sshd'',''httpd'',''screensharingd'') spawning shells or scripting runtimes.", "name": "macos:osquery"}, {"channel": "process activity stream", "name": "macos:unifiedlog"}, {"channel": "SYSCALL record where exe contains passwd/userdel/chage and auid != root", "name": "auditd:SYSCALL"}, {"channel": "Post-login execution of unrecognized child process from launchd or loginwindow", "name": "macos:unifiedlog"}, {"channel": "execve of base64|openssl|xxd|python|perl with arguments matching Base64 flags", "name": "auditd:SYSCALL"}, {"channel": "process command line contains base64, -enc, openssl enc -base64", "name": "macos:unifiedlog"}, {"channel": "exec: arguments contain Base64-like strings", "name": "macos:endpointsecurity"}, {"channel": "commands containing base64, openssl enc -base64, xxd -p", "name": "esxi:shell"}, {"channel": "Execution of process launched via loginwindow session restore", "name": "macos:unifiedlog"}, {"channel": "process: exec + filewrite: ~/.ssh/authorized_keys", "name": "macos:unifiedlog"}, {"channel": "/var/log/containers/*.log", "name": "containerd:runtime"}, {"channel": "Execution of Java apps or other processes with hidden window attributes", "name": "macos:unifiedlog"}, {"channel": "Process Execution", "name": "macos:unifiedlog"}, {"channel": "execve on code or jetbrains-gateway with remote flags", "name": "auditd:SYSCALL"}, {"channel": "process: code or jetbrains-gateway launching with --tunnel or --remote", "n