VALUES ('doc-09-mitre-attack-p0-4007', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-20T15:05:19.274Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Contextual data about an instance and activity around it such as name, type, or status", "external_references": [{"external_id": "DC0086", "source_name": "mitre-attack", "url": "https://attack.mitre.org/datacomponents/DC0086"}], "id": "x-mitre-data-component--45fd904d-6eb0-4b50-8478-a961f09f898b", "modified": "2025-11-12T22:03:39.105Z", "name": "Instance Metadata", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-data-component", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_sources": [{"channel": "DescribeInstances", "name": "AWS:CloudTrail"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-4007', 0, 55, '09-mitre-attack', 'retrieved', '60AE4E2602955A23CB6CD51DD41E152ACEF420008852107C5CFC75E369F3B0EF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
