VALUES ('doc-09-mitre-attack-p0-4009', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-20T15:05:19.273Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The alteration of a drive letter, mount point, or other attributes of a data storage device, which could involve reassignment, renaming, permissions changes, or other modifications. Examples: \n\n- Drive Letter Reassignment: A USB drive previously assigned `E:\\` is reassigned to `D:\\` on a Windows machine.\n- Mount Point Change: On a Linux system, a mounted storage device at `/mnt/external` is moved to `/mnt/storage`.\n- Drive Permission Changes: A shared drive''s permissions are modified to allow write access for unauthorized users or processes.\n- Renaming of a Drive: A network drive labeled \"HR_Share\" is renamed to \"Shared_Resources.\"\n- Modification of Cloud-Integrated Drives: A cloud storage mount such as Google Drive is modified to sync only specific folders.\n\nThis data component can be collected through the following measures:\n\nWindows Event Logs\n\n- Relevant Events:\n - Event ID 98: Indicates changes to a volume (e.g., drive letter reassignment).\n - Event ID 1006: Logs permission modifications or changes to removable storage.\n- Configuration: Enable \"Storage Operational Logs\" in the Event Viewer:\n`Applications and Services Logs > Microsoft > Windows > Storage-Tiering > Operational`\n\nLinux System Logs\n\n- Auditd Configuration: Add audit rules to track changes to mounted drives: `auditctl -w /mnt/ -p w -k drive_modification`\n- Command-Line Monitoring: Use `dmesg` or `journalctl` to observe drive modifications.\n\nmacOS System Logs\n\n- Unified Logs: Collect mount or drive modification events: `log show --info | grep \"Volume modified\"`\n- Command-Line Monitoring: Use `diskutil` to track changes:\n\nEndpoint Detection and Response (EDR) Tools\n\n- Configure policies in EDR solutions to monitor and log changes to drive configurations or attributes.\n\nSIEM Tools\n\n- Aggregate logs from multiple systems into a centralized platform like Splunk to correlate events and alert on suspicious drive modification activities.\n", "external_references": [{"external_id": "DC0046", "source_name": "mitre-attack", "url": "https://attack.mitre.org/datacomponents/DC0046"}], "id": "x-mitre-data-component--4dcd8ba3-2075-4f8b-941e-39884ffaac08", "modified": "2025-11-12T22:03:39.105Z", "name": "Drive Modification", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-data-component", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack", "ics-attack"], "x_mitre_log_sources": [{"channel": "None", "name": "Drive"}, {"channel": "Firmware image uploaded via TFTP/FTP/SCP", "name": "networkdevice:runtime"}, {"channel": "Raw disk write access via \\\\.\\PhysicalDrive* or \\\\.\\C:", "name": "WinEventLog:Sysmon"}, {"channel": "IOKit disk write calls targeting raw devices", "name": "macos:unifiedlog"}, {"channel": "Block device write errors or unusual bootloader activity", "name": "linux:syslog"}, {"channel": "Unexpected firmware image upload events via TFTP/FTP/SCP", "name": "networkdevice:firmware"}, {"channel": "Raw write attempts targeting \\\\.\\PhysicalDrive0 or sector 0 (MBR/partition table)", "name": "WinEventLog:Sysmon"}, {"channel": "IOKit raw disk write to EFI/boot partition sectors", "name": "macos:unifiedlog"}, {"channel": "Raw disk writes targeting \\\\.\\PhysicalDrive* or MBR locations", "name": "WinEventLog:Sysmon"}, {"channel": "IOKit raw disk write activity targeting physical devices", "name": "macos:unifiedlog"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-4009', 0, 405, '09-mitre-attack', 'retrieved', 'FE54DFC9A828A66434A1599D30A3188C8F3F71AF366BBB0C6A4CDF17CD6BE584', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
