VALUES ('doc-09-mitre-attack-p0-4011', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-20T15:05:19.273Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The registration of a new service or daemon on an operating system.\n\n*Data Collection Measures:*\n\n- Windows Event Logs\n - Event ID 4697 - Captures the creation of a new Windows service.\n - Event ID 7045 - Captures services installed by administrators or adversaries.\n - Event ID 7034 - Could indicate malicious service modification or exploitation.\n- Sysmon Logs\n - Sysmon Event ID 1 - Process Creation (captures service executables).\n - Sysmon Event ID 4 - Service state changes (detects service installation).\n - Sysmon Event ID 13 - Registry modifications (captures service persistence changes).\n- PowerShell Logging\n - Monitor `New-Service` and `Set-Service` PowerShell cmdlets in Event ID 4104 (Script Block Logging).\n- Linux/macOS Collection Methods\n - AuditD & Syslog Daemon Logs (`/var/log/syslog`, `/var/log/messages`, `/var/log/daemon.log`)\n - AuditD Rules:\n - `auditctl -w /etc/systemd/system -p wa -k service_creation`\n - Detects changes to `systemd` service configurations.\n- Systemd Journals (`journalctl -u `)\n - Captures newly created systemd services.\n- LaunchDaemons & LaunchAgents (macOS)\n - Monitor `/Library/LaunchDaemons/` and `/Library/LaunchAgents/` for new plist files.", "external_references": [{"external_id": "DC0060", "source_name": "mitre-attack", "url": "https://attack.mitre.org/datacomponents/DC0060"}], "id": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705", "modified": "2025-11-12T22:03:39.105Z", "name": "Service Creation", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-data-component", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["ics-attack", "enterprise-attack"], "x_mitre_log_sources": [{"channel": "None", "name": "Service"}, {"channel": "EventCode=7036", "name": "WinEventLog:System"}, {"channel": "creation or modification of systemd services", "name": "auditd:CONFIG_CHANGE"}, {"channel": "Process Events and Launch Daemons", "name": "macos:osquery"}, {"channel": "EventCode=7045", "name": "WinEventLog:System"}, {"channel": "newly registered unit file with ExecStart pointing to unknown binary", "name": "linux:osquery"}, {"channel": "creation or loading of new launchd services", "name": "macos:unifiedlog"}, {"channel": "EventCode=4697", "name": "WinEventLog:Security"}, {"channel": "systemctl start/enable with uncommon binary paths", "name": "linux:syslog"}, {"channel": "EventCode=7031, 7034", "name": "WinEventLog:System"}, {"channel": "launch_daemons", "name": "macos:osquery"}, {"channel": "launchd loading new LaunchDaemon or changes to existing daemon configuration", "name": "macos:unifiedlog"}, {"channel": "detection of new launch agents with suspicious paths or unsigned binaries", "name": "macos:osquery"}, {"channel": "create", "name": "kubernetes:audit"}, {"channel": "unit file referencing container binary with persistent flags", "name": "containerLogs:systemd_unit_files"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-4011', 0, 316, '09-mitre-attack', 'retrieved', '5644E33B01485CA5A19F0E0A49536FC504F9DD387CBE8D8FAA39E72C07E5C450', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
