VALUES ('doc-09-mitre-attack-p0-4013', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-20T15:05:19.272Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Cloud Storage Creation refers to the initial creation of a new cloud storage resource, such as buckets, containers, or directories, within a cloud environment. This action is critical to track as it might indicate the legitimate provisioning of resources or unauthorized actions taken by adversaries to stage, store, or exfiltrate data. Examples: \n\n- AWS S3 Bucket Creation: An AWS user creates a new S3 bucket using the `CreateBucket` API call.\n- Azure Blob Storage Container Creation: A user creates a new container in Azure Blob Storage using the `Create Container` operation.\n- Google Cloud Storage Bucket Creation: A Google Cloud user creates a new bucket using `storage.buckets.create`.\n- OpenStack Swift Container Creation: A user creates a new container in OpenStack Swift using the `PUT` method.", "external_references": [{"external_id": "DC0024", "source_name": "mitre-attack", "url": "https://attack.mitre.org/datacomponents/DC0024"}], "id": "x-mitre-data-component--59ec10d9-546b-4b8e-bccb-fa85f71e5055", "modified": "2025-11-12T22:03:39.105Z", "name": "Cloud Storage Creation", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-data-component", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_sources": [{"channel": "CreateBucket", "name": "AWS:CloudTrail"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-4013', 0, 165, '09-mitre-attack', 'retrieved', '4EEEF8C70EAD38B39DE92E652E1BC5B34A947BA1F91BD169F1110C5ED6F96042', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
