VALUES ('doc-09-mitre-attack-p0-4020', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-20T15:05:19.273Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Changes made to an existing service or daemon, such as modifying the service name, start type, execution parameters, or security configurations.", "external_references": [{"external_id": "DC0065", "source_name": "mitre-attack", "url": "https://attack.mitre.org/datacomponents/DC0065"}], "id": "x-mitre-data-component--66531bc6-a509-4868-8314-4d599e91d222", "modified": "2026-05-12T15:12:00.774Z", "name": "Service Modification", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-data-component", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["ics-attack", "enterprise-attack"], "x_mitre_log_sources": [{"channel": "service state change", "name": "esxi:hostd"}, {"channel": "None", "name": "Service"}, {"channel": "Module or ISAPI filter registration events", "name": "WinEventLog:Microsoft-IIS-Configuration"}, {"channel": "EventCode=7040", "name": "WinEventLog:System"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "2.1"}', 'kb-doc-09-mitre-attack-p0-4020', 0, 83, '09-mitre-attack', 'retrieved', 'E77862C36BCA3EA80C0329B64546CB115D36F858E4B65E3CA91C66E2C7ABEE19', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
