VALUES ('doc-09-mitre-attack-p0-4021', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-20T15:05:19.272Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Changes made to a pod’s configuration or control data within a containerized cluster. This can include updating settings such as resource limits, environment variables, annotations, labels, or even the containers running within the pod. Pod modifications are often executed using commands like kubectl set, kubectl patch, or kubectl edit.\n\n*Data Collection Measures:* \n\n- Kubernetes API Server Audit Logs:\n - Capture all API calls related to pod modification, such as PATCH, PUT, or UPDATE methods on v1/pods.\n- Runtime Security Tools:\n - Tools like Falco, Sysdig, and Kube-bench can monitor pod modifications at runtime and alert on policy violations.\n- Container Orchestration Logs:\n - Monitor events logged by Kubernetes itself (e.g., `kubectl logs -n kube-system kube-controller-manager`).\n- SIEM and EDR Solutions:\n - Use SIEM platforms (e.g., Splunk) to aggregate API server logs and detect patterns of unauthorized or suspicious pod modifications.\n - Endpoint Detection and Response (EDR) tools configured with container visibility can monitor commands like `kubectl` set or `kubectl patch`.\n- Host-Based Monitoring:\n - Collect and analyze logs for processes executing `kubectl` commands or interacting with Kubernetes configuration files (e.g., `.kube/config`).", "external_references": [{"external_id": "DC0030", "source_name": "mitre-attack", "url": "https://attack.mitre.org/datacomponents/DC0030"}], "id": "x-mitre-data-component--672b2ebd-4310-4efe-bf03-7ab005298a74", "modified": "2025-10-21T15:10:28.402Z", "name": "Pod Modification", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-data-component", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-4021', 0, 213, '09-mitre-attack', 'retrieved', 'EC9E7DE0FEC4C8A26E75763C98A924B1809A72868033E8B66A4BE933CD5AF30E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
