VALUES ('doc-09-mitre-attack-p0-4022', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-20T15:05:19.273Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Command Execution involves monitoring and capturing the execution of textual commands (including shell commands, cmdlets, and scripts) within an operating system or application. These commands may include arguments or parameters and are typically executed through interpreters such as `cmd.exe`, `bash`, `zsh`, `PowerShell`, or programmatic execution. Examples: \n\n- Windows Command Prompt\n - dir – Lists directory contents.\n - net user – Queries or manipulates user accounts.\n - tasklist – Lists running processes.\n- PowerShell\n - Get-Process – Retrieves processes running on a system.\n - Set-ExecutionPolicy – Changes PowerShell script execution policies.\n - Invoke-WebRequest – Downloads remote resources.\n- Linux Shell\n - ls – Lists files in a directory.\n - cat /etc/passwd – Reads the user accounts file.\n - curl http://malicious-site.com – Retrieves content from a malicious URL.\n- Container Environments\n - docker exec – Executes a command inside a running container.\n - kubectl exec – Runs commands in Kubernetes pods.\n- macOS Terminal\n - open – Opens files or URLs.\n - dscl . -list /Users – Lists all users on the system.\n - osascript -e – Executes AppleScript commands.", "external_references": [{"external_id": "DC0064", "source_name": "mitre-attack", "url": "https://attack.mitre.org/datacomponents/DC0064"}], "id": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0", "modified": "2026-05-12T15:12:00.774Z", "name": "Command Execution", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-data-component", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["ics-attack", "mobile-attack", "enterprise-attack"], "x_mitre_log_sources": [{"channel": "Command ''pm list packages'' executed by app sandbox or child proc", "name": "android:logcat"}, {"channel": "udev rule reload or trigger command executed", "name": "auditd:CONFIG_CHANGE"}, {"channel": "execve of script/interpreter (bash, python, node) with suspicious encoded or non-printable content", "name": "auditd:EXECVE"}, {"channel": "Use of mv or cp to rename files with ''.'' prefix", "name": "auditd:EXECVE"}, {"channel": "execve: Execution of update-ca-certificates or trust anchor modification commands", "name": "auditd:EXECVE"}, {"channel": "gcore, gdb, strings, hexdump execution", "name": "auditd:EXECVE"}, {"channel": "Execution of auditctl, systemctl stop auditd, or kill -9 auditd", "name": "auditd:EXECVE"}, {"channel": "execution of systemctl with subcommands start, stop, enable, disable", "name": "auditd:EXECVE"}, {"channel": "Execution of GUI-related binaries with suppressed window/display flags", "name": "auditd:EXECVE"}, {"channel": "curl -X POST, wget --post-data", "name": "auditd:EXECVE"}, {"channel": "command line arguments containing lsblk, fdisk, parted", "name": "auditd:EXECVE"}, {"channel": "exec: Execution of dd, efibootmgr, or flashrom modifying firmware/boot partitions", "name": "auditd:EXECVE"}, {"channel": "curl -d, wget --post-data", "name": "auditd:EXECVE"}, {"channel": "grep/cat/awk on files with password fields", "name": "auditd:EXECVE"}, {"channel": "git push, curl -X POST", "name": "auditd:EXECVE"}, {"channel": "Execution of gsettings set org.gnome.login-screen disable-user-list true", "name": "auditd:EXECVE"}, {"channel": "execution of setfattr or getfattr commands", "name": "auditd:EXECVE"}, {"channel": "Process execution of update-ca-certificates or openssl with suspicious arguments", "name": "auditd:EXECVE"}, {"channel": "Execution of chattr to set +i or +a attributes", "name": "auditd:EXECVE"}, {"channel": "curl or wget with POST/PUT options", "name": "auditd:EXECVE"}, {"channel": "curl -T, rclone copy", "name": "auditd:EXECVE"}, {"channel": "execve of curl,wget,bash,sh,python with piped or remote content", "name": "auditd:EXECVE"}, {"channel": "execve, kill, ptrace, insmod, rmmod targeting security processes", "name": "auditd:EXECVE"}, {"channel": "proctitle contains chmod, chown, setfacl, or attr commands with suspicious parameters", "name": "auditd:PROCTITLE"}, {"channel": "proctitle contains chmod, chown, chgrp, setfacl, or attr with suspicious parameters (777, 755, +x, -R)", "name": "auditd:PROCTITLE"}, {"channel": "process title records containing discovery command sequences and environmental assessment patterns", "name": "auditd:PROCTITLE"}, {"channel": "command-line execution patterns for system discovery utilities (uname, hostname, ifconfig, netstat, lsof, ps, mount)", "name": "auditd:PROCTITLE"}, {"channel": "execution of realmd, samba-tool, or ldapmodify with user-related arguments", "name": "auditd:SYSCALL"}, {"channel": "Execution of script interpreters by systemd timer (ExecStart)", "name": "auditd:SYSCALL"}, {"channel": "execve: Commands like systemctl stop , service stop, or kill -9 ", "name": "auditd:SYSCALL"}, {"channel": "execve calls to locale, timedatectl, or cat /etc/timezone", "name": "auditd:SYSCALL"}, {"channel": "sleep function usage or loops (nanosleep, usleep) in scripts", "name": "auditd:SYSCALL"}, {"channel": "connect, execve, write", "name": "auditd:SYSCALL"}, {"channel": "execve call including ''nohup'' or trailing ''&''", "name": "auditd:SYSCALL"}, {"channel": "None", "name": "auditd:SYSCALL"}, {"channel": "execve: Commands executed within an SSH session where no matching logon/authentication event exists", "name": "auditd:SYSCALL"}, {"channel": "chmod, execve", "name": "auditd:SYSCALL"}, {"channel": "execve: iptables, nft, firewall-cmd modifications", "name": "auditd:SYSCALL"}, {"channel": "execve: Invocation of scp, rsync, curl, or sftp", "name": "auditd:SYSCALL"}, {"channel": "execve calls modifying local mail filter configuration files", "name": "auditd:SYSCALL"}, {"channel": "execve: process_name IN (\"virsh\", \"VBoxManage\", \"qemu-img\") AND command IN (\"list\", \"info\")", "name": "auditd:SYSCALL"}, {"channel": "execve: service stop syslog, systemctl stop rsyslog, kill -9 syslog", "name": "auditd:SYSCALL"}, {"channel": "execve: openssl pkcs12, certutil, keytool", "name": "auditd:SYSCALL"}, {"channel": "execve: Process in container namespace executes curl|wget|bash|sh|python|nc with outbound args", "name": "auditd:SYSCALL"}, {"channel": "execution of systemctl or service with enable/start parameters", "name": "auditd:SYSCALL"}, {"channel": "execve: Execution of cat, less, grep, journalctl targeting log directories (/var/log/)", "name": "auditd:SYSCALL"}, {"channel": "execve: Execution of python, perl, or custom binaries invoking compression libraries", "name": "auditd:SYSCALL"}, {"channel": "execve, USER_CMD", "name": "auditd:SYSCALL"}, {"channel": "bash/zsh of base64, tar, gzip, or openssl immediately after file write", "name": "auditd:SYSCALL"}, {"channel": "execve: Processes executing sendmail/postfix with forged headers", "name": "auditd:SYSCALL"}, {"channel": "execve: Execution of tar, gzip, bzip2, xz, zip, or openssl with compression/encryption arguments", "name": "auditd:SYSCALL"}, {"channel": "promiscuous mode transitions (ioctl or ifconfig)", "name": "auditd:SYSCALL"}, {"channel": "chattr, rm, shred, dd run on recovery directories or partitions", "name": "auditd:SYSCALL"}, {"channel": "execve: Execution of curl or wget writing files to /tmp/* followed by chmod or execution", "name": "auditd:SYSCALL"}, {"channel": "execve: Execution of downgraded interpreters such as python2 or forced fallback commands", "name": "auditd:SYSCALL"}, {"channel": "Command line arguments including SPApplicationsDataType", "name": "auditd:SYSCALL"}, {"channel": "Execution of spoofing tools (e.g., hping3, nping, scapy) sending UDP packets to known amplifier ports", "name": "auditd:SYSCALL"}, {"chan