VALUES ('doc-09-mitre-attack-p0-4024', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-20T15:05:19.273Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Contextual information about firewalls, including their configurations, policies, status, and other details such as names and associated rules. This metadata provides valuable insights into the operational state and configurations of firewalls, both in cloud control planes and host systems. Examples: \n\n- Firewall Name and Configuration: The name, type, and purpose of a firewall such as \"Azure Firewall - Production Environment.\"\n- Policy Details: Capturing firewall policy details, such as \"Allow inbound TCP 443 to web servers.\"\n- Firewall Status: Status indicators like \"Active,\" \"Disabled,\" or \"Pending Updates.\"\n- Audit Log Metadata: Log entries showing administrative changes, such as \"Policy modified by admin@domain.com.\"\n- Rules Associated with Firewalls: Rules specifying source/destination IP ranges, protocols, and ports.\n- Tagging Information: Tags like \"Environment: Production\" or \"Owner: NetworkOps.\"\n\nThis data component can be collected through the following measures:\n\nCloud Control Plane\n\n- Azure: Use Azure Activity Logs and Network Watcher to collect metadata for Azure Firewall.\n - Example: `az network firewall show --name `\n- AWS: Use AWS CloudTrail and describe commands: `aws ec2 describe-security-groups`\n- Google Cloud: Use gcloud commands to extract metadata: `gcloud compute firewall-rules list --format=json`\n\nHost-Based Firewalls\n\n- Windows: Use PowerShell to gather metadata: `Get-NetFirewallRule -PolicyStore PersistentStore`\n- Linux: Query iptables or nftables rulesets: `iptables -S`\n- macOS: Use pfctl to extract metadata: `sudo pfctl -sr`\n\nSIEM Integration\n\n- Collect logs from cloud platforms, host systems, and network appliances.\n\nAPI Monitoring\n\n- Monitor API calls for metadata requests. Example (AWS): `Capture DescribeSecurityGroups or DescribeNetworkAcls` calls via CloudTrail.\n\nEndpoint Detection and Response (EDR)\n\n- Use EDR solutions to monitor firewall management tools for configuration changes or queries.", "external_references": [{"external_id": "DC0053", "source_name": "mitre-attack", "url": "https://attack.mitre.org/datacomponents/DC0053"}], "id": "x-mitre-data-component--746f095a-f84c-4ccc-90a5-c7caa5c100a2", "modified": "2025-10-21T15:10:28.402Z", "name": "Firewall Metadata", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-data-component", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-4024', 0, 284, '09-mitre-attack', 'retrieved', 'E6F8380F99F2B5EB328A797970B688E201B1E2C68E3E9BC144EC789C1188E657', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
