VALUES ('doc-09-mitre-attack-p0-4026', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-20T15:05:19.274Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Removal of a virtual machine (VM) or compute instance within a cloud infrastructure. This activity results in the termination and deletion of the allocated resources (e.g., CPU, memory, storage), making the instance unavailable for future use. Examples:\n\n- AWS: instance deletion involves the `TerminateInstances` API call, which is recorded in CloudTrail logs.\n- Azure: VM deletion can be monitored via Azure Activity Logs, showing the `Microsoft.Compute/virtualMachines/delete` operation.\n- GCP: instance deletion is logged as an instance.delete operation within GCP Audit Logs.", "external_references": [{"external_id": "DC0081", "source_name": "mitre-attack", "url": "https://attack.mitre.org/datacomponents/DC0081"}], "id": "x-mitre-data-component--7561ed50-16cb-4826-82c7-c1ddca61785e", "modified": "2025-11-12T22:03:39.105Z", "name": "Instance Deletion", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-data-component", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_sources": [{"channel": "MICROSOFT.COMPUTE/VIRTUALMACHINES/DELETE", "name": "azure:activity"}, {"channel": "compute.instances.delete", "name": "gcp:audit"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-4026', 0, 124, '09-mitre-attack', 'retrieved', '275EB6ED92BA419A1AAA27BE79286DB332032C8A32172E049C56DAB0DC7C6327', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
