VALUES ('doc-09-mitre-attack-p0-4029', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-20T15:05:19.273Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Changes made to a file, including updates to its contents, metadata, access permissions, or attributes. These modifications may indicate legitimate activity (e.g., software updates) or unauthorized changes (e.g., tampering, ransomware, or adversarial modifications). Examples: \n\n- Content Modifications: Changes to the content of a configuration file, such as modifying `/etc/ssh/sshd_config` on Linux or `C:\\Windows\\System32\\drivers\\etc\\hosts` on Windows.\n- Permission Changes: Altering file permissions to allow broader access, such as changing a file from `644` to `777` on Linux or modifying NTFS permissions on Windows.\n- Attribute Modifications: Changing a file''s attributes to hidden, read-only, or system on Windows.\n- Timestamp Manipulation: Adjusting a file''s creation or modification timestamp using tools like `touch` in Linux or timestomping tools on Windows.\n- Software or System File Changes: Modifying system files such as `boot.ini`, kernel modules, or application binaries.", "external_references": [{"external_id": "DC0061", "source_name": "mitre-attack", "url": "https://attack.mitre.org/datacomponents/DC0061"}], "id": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8", "modified": "2026-05-12T15:12:00.775Z", "name": "File Modification", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-data-component", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["ics-attack", "enterprise-attack", "mobile-attack"], "x_mitre_log_sources": [{"channel": "None", "name": "File"}, {"channel": "open/write calls modifying ~/.bashrc, ~/.profile, or /etc/paths.d", "name": "auditd:SYSCALL"}, {"channel": "File modification in /etc/paths.d or user shell rc files", "name": "macos:unifiedlog"}, {"channel": "/var/log/quarantine.log", "name": "fs:fileevents"}, {"channel": "Modification of ~/Library/LaunchAgents or /Library/LaunchDaemons plist", "name": "macos:unifiedlog"}, {"channel": "open, write", "name": "auditd:SYSCALL"}, {"channel": "AUDIT_SYSCALL (open, write, rename, unlink)", "name": "auditd:SYSCALL"}, {"channel": "ES_EVENT_TYPE_NOTIFY_WRITE, targeting .zshrc, .zlogin, .zprofile", "name": "macos:endpointsecurity"}, {"channel": "/var/log/install.log", "name": "fs:fileevents"}, {"channel": "PATH", "name": "auditd:SYSCALL"}, {"channel": "file_events", "name": "macos:osquery"}, {"channel": "EventCode=2", "name": "WinEventLog:Sysmon"}, {"channel": "execve call for modification of /etc/sudoers or writing to /var/db/sudo", "name": "auditd:SYSCALL"}, {"channel": "open, write: File modifications under /etc/ssl/certs, /usr/local/share/ca-certificates, or /etc/pki/ca-trust/source/anchors", "name": "auditd:SYSCALL"}, {"channel": "query: Enumeration of root certificates showing unexpected additions", "name": "macos:osquery"}, {"channel": "open, unlink, rename: Suspicious file access, deletion, or modification of sensitive paths", "name": "auditd:SYSCALL"}, {"channel": "Anomalous plist modifications or sensitive file overwrites by non-standard processes", "name": "macos:unifiedlog"}, {"channel": "Modification or deletion of /etc/audit/audit.rules or /etc/audit/audit.conf", "name": "auditd:FILE"}, {"channel": "open/write of .service unit files", "name": "auditd:SYSCALL"}, {"channel": "open/write/unlink", "name": "auditd:SYSCALL"}, {"channel": "loginwindow or desktopservices modified settings or files", "name": "macos:unifiedlog"}, {"channel": "changes to /etc/motd or /etc/vmware/welcome", "name": "ESXiLogs:messages"}, {"channel": "write, rename", "name": "auditd:SYSCALL"}, {"channel": "file change monitoring within /etc/cron.*, /tmp, or mounted volumes", "name": "containerd:runtime"}, {"channel": "ma