INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-4033', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-20T15:05:19.274Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Cloud service enumeration involves listing or querying available cloud services in a cloud control plane. This activity is often performed to identify resources such as virtual machines, storage buckets, compute clusters, or other services within a cloud environment. Examples include API calls like `AWS ECS ListServices`, `Azure ListAllResources`, or `Google Cloud ListInstances`. Examples: \n\nAWS Cloud Service Enumeration: The adversary gathers details about existing ECS services to identify opportunities for privilege escalation or exfiltration.\n- Azure Resource Enumeration: The adversary collects information about virtual machines, resource groups, and other Azure assets for reconnaissance purposes.\n- Google Cloud Resource Enumeration: The attacker seeks to map the environment and find misconfigured or underutilized resources for exploitation.\n- Office 365 Service Enumeration: The attacker may look for data repositories or collaboration tools to exfiltrate sensitive information.", "external_references": [{"external_id": "DC0083", "source_name": "mitre-attack", "url": "https://attack.mitre.org/datacomponents/DC0083"}], "id": "x-mitre-data-component--8c826308-2760-492f-9e36-4f0f7e23bcac", "modified": "2026-05-12T15:12:00.775Z", "name": "Cloud Service Enumeration", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-data-component", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack", "mobile-attack"], "x_mitre_log_sources": [{"channel": "GetSecretValue", "name": "AWS:CloudTrail"}, {"channel": "accessSecretVersion", "name": "gcp:secrets"}, {"channel": "SecretGet", "name": "azure:ad"}, {"channel": "ssm:ListInventoryEntries", "name": "AWS:CloudTrail"}, {"channel": "DescribeInstances, DescribeServices, ListFunctions: High frequency enumeration calls or unusual user agents performing discovery", "name": "AWS:CloudTrail"}, {"channel": "ListApplications, ListServicePrincipals: Large-scale queries against identity or application objects", "name": "azure:audit"}, {"channel": "Get-MsolServicePrincipal, ListAppRoles: Service discovery operations executed by accounts not normally performing administrative tasks", "name": "m365:unified"}, {"channel": "ListIntegrations, ListServices: Repeated service discovery requests from accounts without administrative responsibilities", "name": "saas:adminapi"}, {"channel": "GetInstanceIdentityDocument or IMDSv2 token requests", "name": "AWS:CloudTrail"}, {"channel": "DescribeUsers / ListUsers / GetUser", "name": "AWS:CloudTrail"}, {"channel": "Graph API Query", "name": "azure:signinlogs"}, {"channel": "Device lookup, location query, or remote management operation", "name": "saas:MDM"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "3.0"}', 'kb-doc-09-mitre-attack-p0-4033', 0, 276, '09-mitre-attack', 'retrieved', '337497E87A47828CC435CAF521DD269B815F833367E6CA2E12882F4045F9B958', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
