INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-4034', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-20T15:05:19.275Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Group metadata includes attributes like name, permissions, purpose, and associated user accounts or roles, which adversaries may exploit for privilege escalation. Examples:\n\n- Active Directory: `Get-ADGroup -Identity \"Domain Admins\" -Properties Members, Description`\n- Azure AD: `Get-AzureADGroup -ObjectId `\n- Google Workspace: `GET https://admin.googleapis.com/admin/directory/v1/groups/ `\n- AWS IAM: `aws iam list-group-policies --group-name `\n- Office 365: `GET https://graph.microsoft.com/v1.0/groups/ `\n\n*Data Collection Measures:*\n\n- Cloud Logging:\n - AWS CloudTrail for IAM group-related activities.\n - Azure AD Sign-In/Audit logs for metadata changes.\n - Google Admin Activity logs for API calls.\n- Directory Logging: Log metadata access (e.g., Windows Event ID 4662).\n- API Monitoring: Log API calls to modify group metadata (e.g., Microsoft Graph API).\n- SIEM Integration: Centralize group metadata logs for analysis.\n", "external_references": [{"external_id": "DC0105", "source_name": "mitre-attack", "url": "https://attack.mitre.org/datacomponents/DC0105"}], "id": "x-mitre-data-component--8d8c7cac-94cf-4726-8989-cab33851168c", "modified": "2025-10-21T15:14:39.577Z", "name": "Group Metadata", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-data-component", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_sources": [{"channel": "Enumerate ACLs/role bindings", "name": "m365:sharepoint"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-4034', 0, 155, '09-mitre-attack', 'retrieved', '1D690DCDA480EE3D7CE1DCA64D0A97D54A407685C8A1F25D4DEBA3A13E8796E5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
