INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-4035', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-20T15:05:19.275Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Extracting group lists from identity systems identifies permissions, roles, or configurations. Adversaries may exploit high-privilege groups or misconfigurations. Examples:\n\n- AWS CLI: `aws iam list-groups`\n- PowerShell: `Get-ADGroup -Filter *`\n- (Saas) Google Workspace: Admin SDK Directory API\n- Azure: `Get-AzureADGroup`\n- Microsoft 365: Graph API `GET https://graph.microsoft.com/v1.0/groups`\n\n*Data Collection Measures:*\n\n- Cloud Logging: Enable AWS CloudTrail, Azure Activity Logs, and Google Workspace Admin Logs for group-related actions.\n- Directory Monitoring: Track logs like AD Event ID 4662 (object operations).\n- API Monitoring: Log API activity like AWS IAM queries.\n- SaaS Monitoring: Use platform logs (e.g., Office 365 Unified Audit Logs).\n- SIEM Integration: Centralize group query tracking.", "external_references": [{"external_id": "DC0099", "source_name": "mitre-attack", "url": "https://attack.mitre.org/datacomponents/DC0099"}], "id": "x-mitre-data-component--8e44412e-3238-4d64-8878-4f11e27784fe", "modified": "2026-05-12T15:12:00.775Z", "name": "Group Enumeration", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-data-component", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_sources": [{"channel": "ListGroups, ListAttachedRolePolicies", "name": "AWS:CloudTrail"}, {"channel": "az ad user get-member-groups, Get-AzRoleAssignment", "name": "azure:audit"}, {"channel": "cloudidentity.groups.list", "name": "gcp:audit"}, {"channel": "GET /services/data/vXX.X/groups", "name": "saas:salesforce"}, {"channel": "GET /orgs/:org/teams, GET /teams/:team/members", "name": "saas:github"}, {"channel": "EventCode=4798, 4799", "name": "WinEventLog:Security"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "2.1"}', 'kb-doc-09-mitre-attack-p0-4035', 0, 170, '09-mitre-attack', 'retrieved', 'F965CFF0C2FB38B19382D7B4C5244134D0501125A7B5079218DF5856ACE4E6C1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
