INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-4036', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-20T15:05:19.273Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Established, compromised, or otherwise acquired by adversaries to conduct reconnaissance, influence operations, social engineering, or other cyber threats.\n\n*Data Collection Measures:*\n\n- API Monitoring\t\n - Social media APIs (e.g., Twitter API, Facebook Graph API) can extract behavioral patterns of accounts.\n- Web Scraping\n - Extracts public profile data, friend lists, or interactions to identify impersonation attempts.\n- Threat Intelligence Feeds\t\n - External feeds track malicious personas linked to disinformation campaigns or phishing.\n- OSINT Tools\n - Maltego, SpiderFoot, and OpenCTI can map social media persona relationships.\n- Endpoint Detection\t\n - EDR logs user behavior and alerts on suspicious social media interactions.\n- SIEM Logging\n - Detects access to known phishing pages or social media abuse via proxy logs.\n- Dark Web Monitoring\t\n - Identifies compromised social media credentials being sold.", "external_references": [{"external_id": "DC0052", "source_name": "mitre-attack", "url": "https://attack.mitre.org/datacomponents/DC0052"}], "id": "x-mitre-data-component--8fb2f315-1aca-4cef-ae0d-8105e1f95985", "modified": "2025-10-21T15:10:28.402Z", "name": "Social Media", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-data-component", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_sources": [{"channel": "None", "name": "Persona"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-4036', 0, 164, '09-mitre-attack', 'retrieved', 'C13A3FE1A7CA1D61E1138158034430DD5F3546741E8BE8A086107C058821FE24', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
