INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-4037', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-20T15:05:19.274Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Object deletion in AD (e.g., user accounts, groups, OUs) is logged as Event ID 5141. Examples:\n\n- User Account: Deleted user.\n- Group: Deleted security/distribution group.\n- Organizational Unit (OU): Loss of configurations or policies.\n- Service Account: Disrupted operations or cover tracks.\n- Trust Object: Removed domain trust, disrupting connectivity.\n\n*Data Collection Measures:*\n\n- Audit Policy:\n - Enable \"Audit Directory Service Changes\" (Success and Failure).\n - Path: `Computer Configuration > Policies > Windows Settings > Security Settings > Advanced Audit Policy Configuration > Audit Policies > Directory Service Changes`.\n - Key Event: Event ID 5141.\n- Log Forwarding: Use WEF to centralize logs for SIEM tools (e.g., Splunk).\n- Enable EDR Monitoring:\n - Detect processes or users that initiate unauthorized object deletions.\n - Monitor tools and scripts that may delete key directory objects.", "external_references": [{"external_id": "DC0068", "source_name": "mitre-attack", "url": "https://attack.mitre.org/datacomponents/DC0068"}], "id": "x-mitre-data-component--9085a576-636a-455b-91d2-c2921bbe6d1d", "modified": "2025-11-12T22:03:39.105Z", "name": "Active Directory Object Deletion", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-data-component", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_sources": [{"channel": "EventCode=4929", "name": "WinEventLog:Security"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-4037', 0, 169, '09-mitre-attack', 'retrieved', 'D81ABA1A4A29628ECCE70F7EC88753B541A79C4FB3752434561CFFB14969470A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
