VALUES ('doc-09-mitre-attack-p0-4039', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-20T15:05:19.271Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Contextual data about a malicious payload, such as compilation times, file hashes, as well as watermarks or other identifiable configuration information", "external_references": [{"external_id": "DC0003", "source_name": "mitre-attack", "url": "https://attack.mitre.org/datacomponents/DC0003"}], "id": "x-mitre-data-component--93a6e38c-02a5-44d8-9035-b2e08459f31f", "modified": "2025-10-21T15:10:28.402Z", "name": "Malware Metadata", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-data-component", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_sources": [{"channel": "None", "name": "Malware Repository"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-4039', 0, 64, '09-mitre-attack', 'retrieved', 'C35F332EB1A3E6E5C64A1304D1A35B204FC84C2A612D551A7BDB15E130675D52', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
