INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-4041', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-20T15:05:19.272Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Application Log Content refers to logs generated by applications or services, providing a record of their activity. These logs may include metrics, errors, performance data, and operational alerts from web, mail, or other applications. These logs are vital for monitoring application behavior and detecting malicious activities or anomalies. Examples: \n\n- Web Application Logs: These logs include information about requests, responses, errors, and security events (e.g., unauthorized access attempts).\n- Email Application Logs: Logs contain metadata about emails sent, received, or blocked (e.g., sender/receiver addresses, message IDs).\n- SaaS Application Logs: Activity logs include user logins, configuration changes, and access to sensitive resources.\n- Cloud Application Logs: Logs detail control plane activities, including API calls, instance modifications, and network changes.\n- System/Application Monitoring Logs: Logs provide insights into application performance, errors, and anomalies.", "external_references": [{"external_id": "DC0038", "source_name": "mitre-attack", "url": "https://attack.mitre.org/datacomponents/DC0038"}], "id": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa", "modified": "2026-05-12T15:12:00.776Z", "name": "Application Log Content", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-data-component", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["ics-attack", "enterprise-attack", "mobile-attack"], "x_mitre_log_sources": [{"channel": "Default IME active or bound to (InputMethodManager reports imeId= )", "name": "android:logcat"}, {"channel": "Default IME changed/active: imeId= , onStartInput/onFinishInput high frequency. TYPE_APPLICATION_OVERLAY|addView .* showing on top of package ", "name": "android:logcat"}, {"channel": "Default IME active imeId= ; frequent onStartInput/commitText calls", "name": "android:logcat"}, {"channel": "addView TYPE_APPLICATION_OVERLAY|TYPE_APPLICATION_ATTACHED_DIALOG shown over ", "name": "android:logcat"}, {"channel": "Secure/Global reads of device_policy_manager, accessibility_enabled, default_vpn, always_on_vpn", "name": "android:logcat"}, {"channel": "Task switch from browser/custom tab to handler immediately after OAuth return", "name": "android:logcat"}, {"channel": "ACTION_OPEN_DOCUMENT_TREE / ACTION_OPEN_DOCUMENT invoked without user gesture or repeatedly in background", "name": "android:logcat"}, {"channel": "None", "name": "Application Log"}, {"channel": "smtpd$.*$: .*from=[.*@internaldomain.com](mailto:.*@internaldomain.com) to=[.*@internaldomain.com](mailto:.*@internaldomain.com)", "name": "Application:Mail"}, {"channel": "Inbound messages with anomalous headers, spoofed SPF/DKIM failures", "name": "Application:Mail"}, {"channel": "Inbound emails containing hyperlinks from suspicious sources", "name": "Application:Mail"}, {"channel": "Inbound email attachments logged from MTAs with suspicious metadata", "name": "Application:Mail"}, {"channel": "Mismatch between authenticated username and From header in email", "name": "Application:Mail"}, {"channel": "High-frequency inbound mail activity to a specific recipient address", "name": "Application:Mail"}, {"channel": "Docker/Kubernetes API access from external sources", "name": "ApplicationLog:API"}, {"channel": "Outbound or inbound calls to high-risk or blocklisted numbers", "name": "ApplicationLog:CallRecords"}, {"channel": "DeviceRegistration events", "name": "ApplicationLog:EntraIDPortal"}, {"channel": "IIS W3C logs in C:\\inetpub\\logs\\LogFiles\\W3SVC* (spikes in 5xx, RCE/SQLi/path traversal/JNDI patterns)", "name": "ApplicationLog:IIS"}, {"channel": "Kubernetes NGINX/Envoy ingress controller logs with anomalous payloads and 5xx spikes", "name": "ApplicationLog:Ingress"}, {"channel": "Enrollment events (e.g., MDMDeviceRegistration)", "name": "ApplicationLog:Intune/MDM Logs"}, {"channel": "Unexpected additions of sieve rules or filtering directives", "name": "ApplicationLog:MailServer"}, {"channel": "Outlook client-level rule creation actions not consistent with normal user activity", "name": "ApplicationLog:Outlook"}, {"channel": "/var/log/httpd/access_log, /var/log/apache2/access.log, /var/log/nginx/access.log with exploit indicators and burst errors", "name": "ApplicationLog:WebServer"}, {"channel": "SendEmail", "name": "AWS:CloudTrail"}, {"channel": "InvokeModel", "name": "AWS:CloudTrail"}, {"channel": "InvokeFunction: Unexpected or repeated invocation of functions not tied to known workflows", "name": "AWS:CloudTrail"}, {"channel": "CreateUser|AttachRolePolicy|CreateAccessKey|UpdateAssumeRolePolicy|CreateLoginProfile", "name": "AWS:CloudTrail"}, {"channel": "StopLogging, DeleteTrail, UpdateTrail: API calls that disable or modify logging services", "name": "AWS:CloudTrail"}, {"channel": "Repeated crash pattern within container or instance logs", "name": "AWS:CloudWatch"}, {"channel": "Elevated 5xx response rates in application logs or gateway layer", "name": "AWS:CloudWatch"}, {"channel": "Add role assignment / ElevateAccess / Create service principal", "name": "azure:activity"}, {"channel": "App registrations or consent grants by abnormal users or at unusual times", "name": "azure:audit"}, {"channel": "ConsentGrant: Suspicious consent grants to non-approved or unknown applications", "name": "azure:signinlogs"}, {"channel": "Modify Conditional Access Policy", "name": "azure:signinlogs"}, {"channel": "Register PTA Agent or Modify AD FS trust", "name": "azure:signinlogs"}, {"channel": "Resource access initiated using application credentials, not user accounts", "name": "azure:signinlogs"}, {"channel": "container_create,container_start", "name": "docker:daemon"}, {"channel": "Container exited with non-zero code repeatedly in short period", "name": "docker:events"}, {"channel": "execution of cloud CLI tool (e.g., aws, az) inside container", "name": "docker:runtime"}, {"channel": "ThreatDetected, QuarantineLog", "name": "EDR:detection"}, {"channel": "ThreatLog", "name": "EDR:detection"}, {"channel": "/var/log/esxupdate.log contains VIB installed with `--force` or `--no-sig-check` and non-standard acceptance levels", "name": "esxi:esxupdate"}, {"channel": "/var/log/hostd.log anomalies (faults, crashes, restarts) around inbound connections", "name": "esxi:hostd"}, {"channel": "Keywords: ''Backtrace'',''Signal 11'',''PANIC'',''hostd restarted'',''assert'' or ''Service terminated unexpectedly'' in /var/log/hostd.log, /var/log/vmkernel.log, /var/log/syslog.log.", "name": "esxi:hostd"}, {"channel": "unexpected script/command invocations via hostd", "name": "esxi:hostd"}, {"channel": "Guest Operations API invocation: StartProgramInGuest, ListProcessesInGuest, ListFileInGuest, InitiateFileTransferFromGuest", "name": "esxi:hostd"}, {"channel": "unexpected script invocations producing long encoded strings", "name": "esxi:hostd"}, {"channel": "Host daemon command log entries related to vib enumeration", "name": "esxi:hostd"}, {"channel": "New extension/module install with unknown vendor ID", "name": "esxi:hostd"}, {"channel": "vmkernel / OpenSLP logs for malformed requests", "name": "esxi:vmkernel"}, {"channel": "Symmetric crypto routines triggered for external session", "name": "esxi:vpxd"}, {"channel": "ESXi process initiating asymmetric handshake with external host", "name": "esxi:vpxd"}, {"channel": "SendAs: Outbound messages with alias identities that differ from primary account", "name": "gcp:workspaceaudit"}, {"channel": "Repeated or large UIPasteboard reads; background pasteboard access shortly before packaging", "name": "iOS:unifiedlog"}, {"channel": "UIPasteboard read (general/string/data) by ; repeated reads or background access", "name": "iOS:unifiedlog"}, {"channel": "UIWindow/UIView events indicating secure text entry focus, editingChanged bursts, unexpected firstResponder cycling", "name": "iOS:unifiedlog"}, {"channel": "Secure text entry focus and editingChanged bursts not typical for the app", "name": "iOS:unifiedlog"}, {"channel": "Presentation of credential-like view (UIAlertController with text fields / custom modal) not backed by system auth controller; frequent editingChanged in secureTextEntry fields", "name": "iOS:unifiedlog"}, {"channel": "Repeated canOpenURL checks across diverse schemes (≥N within short window)", "name": "iOS:unifiedlog"}, {"channel": "UIDocumentPickerViewController presented repeatedly without foreground interaction or with short dwell time", "name": "iOS:unifiedlog"}, {"channel": "repeated sandbox denials related to restricted process/system interfaces consistent with process-table querying attempts", "name": "iOS:unifiedlog"}, {"channel": "security-relevant kernel log messages indicating restricted system interface access attempts by app process (device-dependent visibility)", "name": "iOS:unifiedlog"}, {"channel": "Segfault or crash log entry associated with specific application binary", "name": "journald:Application"}, {"channel": "Repeated service restart attempts or unit failures", "name": "journald:systemd"}, {"channel": "Access to orchestrator logs containing credentials (Docker/Kubernetes logs)", "name": "kubernetes:orchestrator"}, {"channel": "cleared or truncated .bash_history", "name": "linux:cli"}, {"channel": "usb * new|thunderbolt|pci .* added|block.*: new .* device", "name": "linux:syslog"}, {"channel": "Inbound messages from webmail services containing attachments or URLs", "name": "linux:syslog"}, {"channel": "kernel|systemd messages indicating ''segmentation fault''|''core dumped''|''service terminated unexpectedly'' for sshd, smbd, vsftpd, mysqld, httpd, etc.", "name": "linux:syslog"}, {"channel": "System daemons initiating encrypted sessions with unexpected destinations", "name": "linux:syslog"}, {"channel": "milter configuration updated, transport rule initialized, unexpected script execution", "name": "linux:syslog"}, {"channel": "Repetitive HTTP 408, 500, or 503 errors logged within short timeframe", "name": "linux:syslog"}, {"channel": "Application or browser logs (webview errors, plugin enumerations) indicating suspicious script evaluation or plugin loads", "name": "linux:syslog"}, {"channel": "processes binding to non-standard ports or sshd configured on unexpected port", "name": "linux:syslog"}, {"channel": "system daemons initiating TLS sessions outside expected services", "name": "linux:syslog"}, {"channel": "browser/office crash, segfault, abnormal termination", "name": "linux:syslog"}, {"channel": "Error/warning logs from services indicating load spike or worker exhaustion", "name": "linux:syslog"}, {"channel": "SPF fail OR DKIM fail OR DMARC fail OR mismatched from_domain vs return_path_domain", "name": "linux:syslog"}, {"channel": "suspicious DHCP lease assignment with unexpected DNS or gateway", "name": "linux:syslog"}, {"channel": "opened document|clicked link|segfault|abnormal termination|sandbox", "name": "linux:syslog"}, {"channel": "Authentication attempts into finance-related servers from unusual IPs or times", "name": "linux:syslog"}, {"channel": "sshd sessions with unusual port forwarding parameters", "name": "linux:syslog"}, {"channel": "Non-standard processes negotiating SSL/TLS key exchanges", "name": "linux:syslog"}, {"channel": "Module registration or stacktrace logs indicating segmentation faults or unknown module errors", "name": "linux:syslog"}, {"channel": "Segfaults, kernel oops, or crashes in security software processes", "name": "linux:syslog"}, {"channel": "Emails containing cleartext secrets (password=, api_key=, token=) shared across internal/external domains", "name": "m365:exchange"}, {"channel": "Transport Rule Modi