VALUES ('doc-09-mitre-attack-p0-4045', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-20T15:05:19.274Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Summarized network packet data that captures session-level details such as source/destination IPs, ports, protocol types, timestamps, and data volume, without storing full packet payloads. This is commonly used for traffic analysis, anomaly detection, and network performance monitoring.", "external_references": [{"external_id": "DC0078", "source_name": "mitre-attack", "url": "https://attack.mitre.org/datacomponents/DC0078"}], "id": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a", "modified": "2026-05-12T15:12:00.777Z", "name": "Network Traffic Flow", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-data-component", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["ics-attack", "mobile-attack", "enterprise-attack"], "x_mitre_log_sources": [{"channel": "None", "name": "Network Traffic"}, {"channel": "socket_events", "name": "macos:osquery"}, {"channel": "Unexpected flows between segmented networks or prohibited ports", "name": "NSM:Flow"}, {"channel": "Configuration change traps or policy enforcement failures", "name": "snmp:config"}, {"channel": "First-time outbound connections to package registries or unknown hosts immediately after restore/build", "name": "NSM:Flow"}, {"channel": "First-time egress to new registries/CDNs post-install/build", "name": "NSM:Flow"}, {"channel": "First-time egress to non-approved registries after dependency install", "name": "NSM:Flow"}, {"channel": "Outbound connections to TCP 139,445 and HTTP/HTTPS to WebDAV endpoints from workstation subnets", "name": "NSM:Flow"}, {"channel": "large outbound data flows or long-duration connections", "name": "NSM:Flow"}, {"channel": "egress > 90th percentile or frequent connection reuse", "name": "AWS:VPCFlowLogs"}, {"channel": "conn.log", "name": "NSM:Flow"}, {"channel": "socket/connect", "name": "auditd:SYSCALL"}, {"channel": "esxcli network vswitch or DNS resolver configuration updates", "name": "esxi:syslog"}, {"channel": "Network Events", "name": "esxi:vobd"}, {"channel": "TCP connections", "name": "iptables:LOG"}, {"channel": "connection metadata", "name": "NSM:Flow"}, {"channel": "DHCP Lease Granted", "name": "wineventlog:dhcp"}, {"channel": "LEASE_GRANTED", "name": "NSM:Flow"}, {"channel": "MAC not in allow-list acquiring IP (DHCP)", "name": "NSM:Flow"}, {"channel": "SMB over high port", "name": "Windows Firewall Log"}, {"channel": "Internal connection logging", "name": "NSM:Connections"}, {"channel": "pf firewall logs", "name": "NSM:Flow"}, {"channel": "/var/log/vmkernel.log", "name": "esxi:vmkernel"}, {"channel": "Inter-segment traffic", "name": "NSM:Flow"}, {"channel": "None", "name": "NSM:Flow"}, {"channel": "Long-lived or hijacked SSH sessions maintained with no active user activity", "name": "NSM:Flow"}, {"channel": "VPC/NSG flow logs for pod/instance egress to Internet or metadata", "name": "AWS:VPCFlowLogs"}, {"channel": "Suspicious outbound traffic from browser binary to non-standard domains", "name": "macos:unifiedlog"}, {"channel": "Abnormal browser traffic volume or destination", "name": "NSM:Flow"}, {"channel": "Outbound requests to domains not previously resolved or associated with phishing campaigns", "name": "NSM:Flow"}, {"channel": "Outbound traffic to domains/IPs not previously resolved, occurring shortly after attachment download or link click", "name": "NSM:Flow"}, {"channel": "NetworkConnection: bytes_sent >> bytes_received anomaly", "name": "M365Defender:DeviceNetworkEvents"}, {"channel": "outbound flows with bytes_out >> bytes_in", "name": "PF:Logs"}, {"channel": "network_flow: bytes_out >> bytes_in to external", "name": "NSX:FlowLogs"}, {"channel": "NetFlow/Zeek conn.log", "name": "NSM:Flow"}, {"channel": "Outbound data flows", "name": "AWS:VPCFlowLogs"}, {"channel": "Flow records with entropy signatures resembling symmetric encryption", "name": "NSM:Flow"}, {"channel": "flow records", "name": "NSM:Flow"}, {"channel": "flow records", "name": "networkdevice:syslog"}, {"channel": "HTTPS POST to known webhook URLs", "name": "macos:unifiedlog"}, {"channel": "Webhook registrations or repeated POST activity", "name": "saas:api"}, {"channel": "Source/destination IP translation inconsistent with intended policy", "name": "NSM:Flow"}, {"channel": "Unexpected NAT translation statistics or rule insertion events", "name": "SNMP:DeviceLogs"}, {"channel": "Sudden spike in incoming flows to web service ports from single/multiple IPs", "name": "NSM:Flow"}, {"channel": "Unusual volume of inbound packets from single source across short time interval", "name": "AWS:VPCFlowLogs"}, {"channel": "port 5900 inbound", "name": "NSM:Flow"}, {"channel": "TCP port 5900 open", "name": "NSM:Flow"}, {"channel": "inbound connection to port 5900", "name": "NSM:firewall"}, {"channel": "Outbound connections to 139/445 to multiple destinations", "name": "NSM:Firewall"}, {"channel": "High volume internal traffic with low entropy indicating looped or malicious DoS script", "name": "VPCFlowLogs:All"}, {"channel": "NetFlow/sFlow/PCAP", "name": "NSM:Flow"}, {"channel": "Outbound Network Flow", "name": "NSM:Flow"}, {"channel": "com.apple.network", "name": "macos:unifiedlog"}, {"channel": "Device-to-Device Deployment Flows", "name": "NSM:Flow"}, {"channel": "socket/connect syscalls", "name": "auditd:SYSCALL"}, {"channel": "outbound TCP/UDP traffic over unexpected port", "name": "macos:unifiedlog"}, {"channel": "ESXi service connections on unexpected ports", "name": "esxi:vpxd"}, {"channel": "OUTBOUND", "name": "iptables:LOG"}, {"channel": "tcp/udp", "name": "macos:unifiedlog"}, {"channel": "CLI network calls", "name": "esxi:hostd"}, {"channel": "Outbound traffic from suspicious new pr