VALUES ('doc-09-mitre-attack-p0-4056', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-20T15:05:19.272Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Contextual data about a pod and activity around it such as name, ID, namespace, or status", "external_references": [{"external_id": "DC0121", "source_name": "mitre-attack", "url": "https://attack.mitre.org/datacomponents/DC0121"}], "id": "x-mitre-data-component--c0edd522-0aef-46b3-8efa-2bd334ce4242", "modified": "2025-11-12T22:03:39.105Z", "name": "Pod Metadata", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-data-component", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": true, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-4056', 0, 53, '09-mitre-attack', 'retrieved', '672E160124C18A544E0B68B0C5EAAEE5E0F7F9C962826943DACF219FE5905B4E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
