VALUES ('doc-09-mitre-attack-p0-4058', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-20T15:05:19.275Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "\"Domain Name: Passive DNS\" captures logged historical and real-time domain name system (DNS) data. This includes records of domain-to-IP address resolutions over time, enabling analysts to track the evolution of domain infrastructure, uncover historical patterns of use, and detect malicious activities tied to domains and their associated IP addresses. Examples: \n\n- Historical Resolutions\n- Shared IP Usage\n- Temporal Patterns\n- Malicious Domain Clustering\n- Historical Lookback\n\nThis data component can be collected through the following measures:\n\n- Passive DNS Platforms: Use platforms that specialize in passive DNS collection and analysis:\n - Tools: Farsight DNSDB, RiskIQ PassiveTotal, PassiveDNS.\n- Threat Intelligence Feeds: Integrate passive DNS data from commercial or open-source threat intelligence providers.\n- Custom DNS Collectors: Deploy custom tools to capture DNS traffic at the network level for analysis.\n- Cloud DNS Services: Leverage cloud DNS services (e.g., AWS Route 53, Azure DNS) that maintain DNS query logs.", "external_references": [{"external_id": "DC0096", "source_name": "mitre-attack", "url": "https://attack.mitre.org/datacomponents/DC0096"}], "id": "x-mitre-data-component--cc150ad8-ecfa-4340-9aaa-d21165873bd4", "modified": "2025-10-21T15:10:28.402Z", "name": "Passive DNS", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-data-component", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_sources": [{"channel": "None", "name": "Domain Name"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-4058', 0, 183, '09-mitre-attack', 'retrieved', '3884DEBFB2D0E62713D5DC4484373E8E3213CC28D9692F98102CF62B42030F23', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
