VALUES ('doc-09-mitre-attack-p0-4067', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-20T15:05:19.274Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Contextual data about a container and activity around it such as name, ID, image, or status", "external_references": [{"external_id": "DC0122", "source_name": "mitre-attack", "url": "https://attack.mitre.org/datacomponents/DC0122"}], "id": "x-mitre-data-component--df508a43-65f5-453f-8b8f-4b5d64e60a21", "modified": "2025-11-12T22:03:39.105Z", "name": "Container Metadata", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-data-component", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": true, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-4067', 0, 53, '09-mitre-attack', 'retrieved', 'FAE260C16AEA9F46A81892F465D44BF3293AC89E18E97731C94FBD94FEC3FE98', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
