VALUES ('doc-09-mitre-attack-p0-4074', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-20T15:05:19.272Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Contextual data about a running process, which may include information such as environment variables, image name, user/owner, etc.", "external_references": [{"external_id": "DC0034", "source_name": "mitre-attack", "url": "https://attack.mitre.org/datacomponents/DC0034"}], "id": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1", "modified": "2026-05-12T15:12:00.778Z", "name": "Process Metadata", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-data-component", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["ics-attack", "mobile-attack", "enterprise-attack"], "x_mitre_log_sources": [{"channel": "None", "name": "Process"}, {"channel": "subsystem=com.apple.process", "name": "macos:unifiedlog"}, {"channel": "CodeIntegrity/WDAC events indicating unsigned/invalid DLL loads", "name": "WinEventLog:Microsoft-Windows-CodeIntegrity/Operational"}, {"channel": "sudo or service accounts invoking loaders with suspicious env vars", "name": "linux:syslog"}, {"channel": "Process Context", "name": "macos:osquery"}, {"channel": "user session", "name": "esxi:auth"}, {"channel": "Admin activity", "name": "networkdevice:syslog"}, {"channel": "execve call for sudo where euid != uid", "name": "auditd:SYSCALL"}, {"channel": "subsystem=com.apple.TCC", "name": "macos:unifiedlog"}, {"channel": "exec of binary with setuid/setgid and EUID != UID", "name": "macos:unifiedlog"}, {"channel": "process", "name": "macos:unifiedlog"}, {"channel": "Use of fork/exec with DISPLAY unset or redirected", "name": "auditd:SYSCALL"}, {"channel": "Process lineage and API usage enrichment (GetSystemTime, GetTimeZoneInformation, NtQuerySystemTime)", "name": "EDR:Tele