VALUES ('doc-09-mitre-attack-p0-4077', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-20T15:05:19.275Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Opening a network share, which makes the contents available to the requestor (ex: Windows EID 5140 or 5145)", "external_references": [{"external_id": "DC0102", "source_name": "mitre-attack", "url": "https://attack.mitre.org/datacomponents/DC0102"}], "id": "x-mitre-data-component--f5468e67-51c7-4756-9b4f-65707708e7fa", "modified": "2025-11-12T22:03:39.105Z", "name": "Network Share Access", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-data-component", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["ics-attack", "enterprise-attack"], "x_mitre_log_sources": [{"channel": "None", "name": "Network Share"}, {"channel": "EventCode=31001", "name": "WinEventLog:Microsoft-Windows-SMBClient/Security"}, {"channel": "EventCode=5140", "name": "WinEventLog:Security"}, {"channel": "EventCode=5145", "name": "WinEventLog:Security"}, {"channel": "Access to SYSVOL share from non-admin user or unusual endpoints", "name": "WinEventLog:Microsoft-Windows-SMBServer"}, {"channel": "smb_files.log", "name": "NSM:Flow"}, {"channel": "FileUploaded, FileAccessed", "name": "m365:unified"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-4077', 0, 97, '09-mitre-attack', 'retrieved', '759205A71FF5CDDFEB885F0510AB496620ABD3AE43F70E23A69EF1FC3011E3C3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
