INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-4084', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-20T15:05:19.275Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "\"Domain Name: Domain Registration\" data component captures information about the assignment, ownership, and metadata of domain names. This information is often sourced from registries like WHOIS and includes details such as registrant names, contact information, registration dates, expiration dates, and registrar details. This data is invaluable for tracking domain ownership, detecting malicious domain registrations, and identifying trends in adversary behavior. Examples: \n\n- Registrant Information: WHOIS lookup of example.com \n- Registration and Expiration Dates: A domain registered a week before being used in phishing attacks.\n- Domain Status: Status codes like clientTransferProhibited or serverHold indicate domain restrictions or potential hijacking activity.\n- Name Server Information: Name servers point to a public DNS provider often associated with malicious campaigns.\n- Privacy Protection: A domain uses WHOIS privacy protection to hide registrant details.\n\nThis data component can be collected through the following measures:\n\n- WHOIS Services: Use tools or services to perform WHOIS lookups:\n- WHOIS APIs: Automate domain registration lookups with APIs:\n- Registrar Platforms: Directly query domain registrars (e.g., GoDaddy, Namecheap) for detailed registration data.\n- Threat Intelligence Platforms: Integrate domain registration data from services like Recorded Future, RiskIQ, or PassiveTotal for enriched analysis.", "external_references": [{"external_id": "DC0101", "source_name": "mitre-attack", "url": "https://attack.mitre.org/datacomponents/DC0101"}], "id": "x-mitre-data-component--ff9b665a-598b-4bcb-8b2a-a87566aa1256", "modified": "2025-10-21T15:14:40.288Z", "name": "Domain Registration", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-data-component", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_sources": [{"channel": "None", "name": "Domain Name"}, {"channel": "Excessive lookups for domains with suspicious WHOIS or short TTL values", "name": "dns:query"}, {"channel": "DNS lookups resolving to domains with rapid changes in registration metadata", "name": "esxi:vmkernel"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-4084', 0, 256, '09-mitre-attack', 'retrieved', '3291AD31D9235A7BA7D0DF3C70B638BC1735693C0E2973002E207EABF9133EB4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
