VALUES ('doc-09-mitre-attack-p0-4085', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-20T15:05:19.273Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The process of listing or retrieving metadata about existing snapshots in a cloud environment.\n\n*Data Collection Measures:*\n\n- AWS CloudTrail\n - Logs API calls such as `DescribeSnapshots`, `ListSnapshots`, and `GetSnapshotAttributes`.\n- Azure Monitor Logs\n - Tracks snapshot enumeration via `Microsoft.Compute/snapshots/read`.\n- Google Cloud Logging\n - Detects snapshot listing through `compute.disks.listSnapshots`.\n", "external_references": [{"external_id": "DC0047", "source_name": "mitre-attack", "url": "https://attack.mitre.org/datacomponents/DC0047"}], "id": "x-mitre-data-component--ffd73905-2e51-4f2d-8549-e72fb0eb6c38", "modified": "2025-10-21T15:10:28.402Z", "name": "Snapshot Enumeration", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-data-component", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-4085', 0, 83, '09-mitre-attack', 'retrieved', '1BC48FE1D018333CF00E9E0FAD52297A5AC04D3A7AB7345A1FD9EEB107D9F318', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
